#Requires -Version 5.1
<#
    WinTaller - Revisa, repara, optimiza y protege Windows
    ------------------------------------------------------
    Interfaz gráfica para:
      * Ver los servicios de Windows y cuáles están en ejecución (en rojo).
      * Marcar servicios con casillas y finalizarlos.
      * Detener y deshabilitar servicios de forma permanente.
      * Reactivar servicios (tipo de inicio Manual).
      * Aplicar tareas habituales de optimización y limpieza.
      * Escanear los puertos abiertos y la telemetría del equipo.

    Uso:
      powershell -NoProfile -ExecutionPolicy Bypass -STA -File .\WinTaller.ps1

    Aviso: detener o deshabilitar servicios del sistema puede afectar al
    funcionamiento de Windows. El programa bloquea los servicios críticos,
    pero aun así revisa siempre lo que vas a detener.
#>

[CmdletBinding()]
param(
    [switch]$SelfTest,
    [switch]$UiSmokeTest
)

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.Data

try {
    $cultura = [System.Globalization.CultureInfo]::GetCultureInfo('es-ES')
    [System.Threading.Thread]::CurrentThread.CurrentCulture = $cultura
    [System.Threading.Thread]::CurrentThread.CurrentUICulture = $cultura
    [System.Globalization.CultureInfo]::DefaultThreadCurrentCulture = $cultura
    [System.Globalization.CultureInfo]::DefaultThreadCurrentUICulture = $cultura
} catch { }

try {
    [System.Windows.Forms.Application]::EnableVisualStyles()
    [System.Windows.Forms.Application]::SetCompatibleTextRenderingDefault($false)
} catch { }

$script:AppName    = 'WinTaller'
$script:AppVersion = '2.1.1'
$script:IsAdmin    = $false
$script:busy       = $false
$script:optCancel  = $false
$script:optProcess = $null
$script:optSnapshotFile = $null
$script:optRestorePointVerified = $false
$script:optTaskSkipped = $false

# Servicios que NUNCA se detienen ni deshabilitan desde esta herramienta.
$script:CriticalServices = @(
    'RpcSs','RpcEptMapper','DcomLaunch','LSM','SamSs','EventLog','Schedule',
    'ProfSvc','UserManager','Power','PlugPlay','nsi','Dhcp','Dnscache',
    'LanmanWorkstation','LanmanServer','Winmgmt','CryptSvc','TrustedInstaller',
    'gpsvc','BrokerInfrastructure','SystemEventsBroker','StateRepository',
    'Wcmsvc','mpssvc','BFE','WinDefend','SecurityHealthService','WdNisSvc',
    'Sense','KeyIso','Netlogon','NlaSvc','netprofm','Themes','Audiosrv',
    'AudioEndpointBuilder','ShellHWDetection','WlanSvc','WwanSvc',
    'Appinfo','AppXSvc','ClipSVC','TokenBroker','seclogon','Winlogon'
)

# Servicios habitualmente prescindibles: se etiquetan como riesgo "Bajo".
$script:SafeToStop = @(
    'DiagTrack','dmwappushservice','MapsBroker','RetailDemo','RemoteRegistry',
    'Fax','XblAuthManager','XblGameSave','XboxGipSvc','XboxNetApiSvc',
    'WMPNetworkSvc','Wisvc','PhoneSvc','PrintNotify','WpcMonSvc','TrkWks'
)
# defragsvc (TRIM / Optimize-Volume) y DsmSvc (instalación de drivers de
# dispositivos nuevos) ya no se consideran de riesgo bajo: las pestañas
# Optimización, Equipo y Drivers dependen de ellos.

$script:uiFont   = $null

# Icono de WinTaller (archivo .ico con 16 a 256 px) incrustado para que el
# programa siga siendo un único archivo.
$script:AppIconBase64 = ''
$script:AppIcon = $null
function Get-AppIcon {
    if ($script:AppIcon) { return $script:AppIcon }
    try {
        $bytes = [Convert]::FromBase64String($script:AppIconBase64)
        $flujo = New-Object System.IO.MemoryStream(,$bytes)
        $script:AppIcon = New-Object System.Drawing.Icon($flujo)
    } catch {
        $script:AppIcon = [System.Drawing.SystemIcons]::Shield
    }
    return $script:AppIcon
}
$script:boldFont = $null

# ---------------------------------------------------------------------------
# Funciones auxiliares
# ---------------------------------------------------------------------------

function Test-IsAdmin {
    try {
        $identity  = [System.Security.Principal.WindowsIdentity]::GetCurrent()
        $principal = New-Object System.Security.Principal.WindowsPrincipal($identity)
        return $principal.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch {
        return $false
    }
}

# Abre una página web o un documento con la sesión normal del usuario.
# explorer.exe entrega la orden al Explorador que ya está abierto, que no tiene
# permisos de administrador: así el navegador no arranca elevado.
function Open-AsDesktopUser {
    param([Parameter(Mandatory = $true)][string]$Target)
    $explorador = Join-Path $env:SystemRoot 'explorer.exe'
    if ($script:IsAdmin -and (Test-Path -LiteralPath $explorador)) {
        Start-Process -FilePath $explorador -ArgumentList ('"{0}"' -f $Target) | Out-Null
    } else {
        Start-Process -FilePath $Target | Out-Null
    }
}

# Usuario que tiene abierta la sesión de Windows (dueño del Explorador de esta
# sesión) frente al usuario con el que se ejecuta el programa. Si alguien eleva
# con la cuenta de otro administrador, los ajustes de usuario (HKCU) se aplican
# a esa otra cuenta.
function Get-SessionUserInfo {
    $proceso = ''
    try { $proceso = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name } catch { }
    $sesion = ''
    try {
        $idSesion = [System.Diagnostics.Process]::GetCurrentProcess().SessionId
        $explorador = Get-CimInstance -ClassName Win32_Process -Filter ("Name='explorer.exe' AND SessionId={0}" -f $idSesion) -ErrorAction Stop | Select-Object -First 1
        if ($explorador) {
            $duenio = Invoke-CimMethod -InputObject $explorador -MethodName GetOwner -ErrorAction Stop
            if ($duenio.ReturnValue -eq 0 -and $duenio.User) { $sesion = ('{0}\{1}' -f $duenio.Domain, $duenio.User) }
        }
    } catch { }
    return [pscustomobject]@{
        Process  = $proceso
        Session  = $sesion
        Mismatch = [bool]($sesion -and $proceso -and -not [string]::Equals($sesion, $proceso, [System.StringComparison]::OrdinalIgnoreCase))
    }
}

# Registro de diagnóstico (se escribe junto al script; si no se puede, en TEMP)
$script:BaseDir = $PSScriptRoot
if (-not $script:BaseDir) { $script:BaseDir = (Get-Location).Path }
$script:DiagFile = Join-Path $script:BaseDir 'diagnostico.log'
$script:DiagFallback = Join-Path $env:TEMP 'WinTaller_diagnostico.log'

# Al pasar de 1 MB se guarda como ".anterior.log" (sustituye al anterior) y se
# empieza uno nuevo, para que el registro no crezca sin límite.
foreach ($registro in @($script:DiagFile, $script:DiagFallback)) {
    try {
        $infoRegistro = Get-Item -LiteralPath $registro -Force -ErrorAction Stop
        if ($infoRegistro.Length -gt 1MB) {
            $anterior = [System.IO.Path]::ChangeExtension($registro, '.anterior.log')
            Move-Item -LiteralPath $registro -Destination $anterior -Force -ErrorAction Stop
        }
    } catch { }
}

function Write-Diag {
    param([string]$Message)
    $line = '{0}  {1}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff'), $Message
    try {
        Add-Content -LiteralPath $script:DiagFile -Value $line -Encoding UTF8 -ErrorAction Stop
    } catch {
        try {
            Add-Content -LiteralPath $script:DiagFallback -Value $line -Encoding UTF8 -ErrorAction SilentlyContinue
        } catch { }
    }
}

function Show-FatalError {
    param([string]$Message, [string]$Detail)
    Write-Diag ('ERROR FATAL: ' + $Detail)
    try {
        [void][System.Windows.Forms.MessageBox]::Show(
            ("La aplicación ha encontrado un error.`n`n{0}`n`nSe ha guardado el detalle en:`n{1}`n`nSi el archivo no existe, busca:`n{2}" -f $Message, $script:DiagFile, $script:DiagFallback),
            "$script:AppName - error", 'OK', 'Error')
    } catch { }
}

Write-Diag '============================================================'
Write-Diag ('Inicio. PowerShell {0}; 64 bits: {1}; usuario: {2}; admin: {3}' -f $PSVersionTable.PSVersion, [Environment]::Is64BitProcess, $env:USERNAME, (Test-IsAdmin))
Write-Diag ('Script: {0}' -f $PSCommandPath)
Write-Diag ('Directorio actual: {0}' -f (Get-Location).Path)
try { Write-Diag ('ExecutionPolicy: {0}' -f (Get-ExecutionPolicy)) } catch { }

try {
    [System.Windows.Forms.Application]::add_ThreadException({
        param($sender, $eventArgs)
        $detail = $eventArgs.Exception.ToString()
        Write-Diag ('EXCEPCION EN LA INTERFAZ: ' + $detail)
        try {
            [void][System.Windows.Forms.MessageBox]::Show(
                ("Se ha producido un error en la interfaz:`n`n{0}`n`nDetalle en: {1}" -f $eventArgs.Exception.Message, $script:DiagFile),
                "$script:AppName - error", 'OK', 'Error')
        } catch { }
    })
} catch { }

try {
    [AppDomain]::CurrentDomain.add_UnhandledException({
        param($sender, $eventArgs)
        Write-Diag ('EXCEPCION NO CONTROLADA: ' + $eventArgs.ExceptionObject.ToString())
    })
} catch { }

function Restart-Elevated {
    # Se libera el bloqueo de instancia única para que la ventana elevada pueda abrirse.
    if ($script:instanceMutex) {
        try { $script:instanceMutex.ReleaseMutex() } catch { }
        try { $script:instanceMutex.Dispose() } catch { }
        $script:instanceMutex = $null
    }
    try {
        $arguments = "-NoProfile -ExecutionPolicy Bypass -STA -File `"$PSCommandPath`""
        Start-Process -FilePath (Join-Path $PSHOME 'powershell.exe') -ArgumentList $arguments -Verb RunAs | Out-Null
        return $true
    } catch {
        return $false
    }
}

function Assert-Admin {
    if ($script:IsAdmin) { return $true }
    $answer = [System.Windows.Forms.MessageBox]::Show(
        "Esta acción necesita permisos de administrador.`n`nQuieres reiniciar la aplicación con permisos elevados?",
        $script:AppName, 'YesNo', 'Warning')
    if ($answer -eq 'Yes' -and (Restart-Elevated)) {
        if ($script:form) { $script:form.Close() }
    }
    return $false
}

# ---------------------------------------------------------------------------
# Seguridad: borrado sin seguir enlaces y carpetas de trabajo protegidas
# ---------------------------------------------------------------------------

# Borra un archivo o carpeta SIN entrar en enlaces (junctions / symlinks).
# Remove-Item -Recurse de PowerShell 5.1 sigue los enlaces de carpeta y borra
# el contenido del destino: con permisos de administrador eso permitiría
# vaciar carpetas del sistema plantando un enlace en TEMP o en una caché.
function Remove-FileSystemInfoSafe {
    param([Parameter(Mandatory = $true)][System.IO.FileSystemInfo]$Info)
    $reparse = [System.IO.FileAttributes]::ReparsePoint
    if ($Info -is [System.IO.DirectoryInfo]) {
        if (($Info.Attributes -band $reparse) -eq $reparse) {
            # Solo se quita el enlace; el destino no se toca.
            [System.IO.Directory]::Delete($Info.FullName, $false)
            return
        }
        foreach ($hijo in $Info.EnumerateFileSystemInfos()) {
            try { Remove-FileSystemInfoSafe -Info $hijo } catch { }
        }
        $Info.Attributes = [System.IO.FileAttributes]::Directory
        [System.IO.Directory]::Delete($Info.FullName, $false)
    } else {
        $soloLectura = [System.IO.FileAttributes]::ReadOnly
        if (($Info.Attributes -band $soloLectura) -eq $soloLectura) {
            $Info.Attributes = $Info.Attributes -bxor $soloLectura
        }
        $Info.Delete()
    }
}

function Remove-ItemSafe {
    param([Parameter(Mandatory = $true)][string]$Path)
    $info = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    Remove-FileSystemInfoSafe -Info $info
}

$script:TrustedOwnerSids = @('S-1-5-18', 'S-1-5-32-544')   # SYSTEM, Administradores

function New-ProtectedDirectorySecurity {
    $acl = New-Object System.Security.AccessControl.DirectorySecurity
    $acl.SetAccessRuleProtection($true, $false)
    foreach ($sid in $script:TrustedOwnerSids) {
        $id = New-Object System.Security.Principal.SecurityIdentifier($sid)
        $regla = New-Object System.Security.AccessControl.FileSystemAccessRule(
            $id, 'FullControl', 'ContainerInherit,ObjectInherit', 'None', 'Allow')
        $acl.AddAccessRule($regla)
    }
    $acl.SetOwner((New-Object System.Security.Principal.SecurityIdentifier('S-1-5-32-544')))
    return $acl
}

# Crea (o valida) una carpeta a la que solo tienen acceso SYSTEM y Administradores.
# Si ya existe pero es un enlace o su propietario no es de confianza, se aparta
# y se crea una nueva: así un proceso sin privilegios no puede prepararla antes.
function Initialize-SecureDirectory {
    param([Parameter(Mandatory = $true)][string]$Path)
    if (Test-Path -LiteralPath $Path) {
        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        $reparse = [System.IO.FileAttributes]::ReparsePoint
        $esEnlace = (($item.Attributes -band $reparse) -eq $reparse)
        $propietario = ''
        try { $propietario = (Get-Acl -LiteralPath $Path).GetOwner([System.Security.Principal.SecurityIdentifier]).Value } catch { }
        if ($esEnlace -or -not $item.PSIsContainer -or ($script:TrustedOwnerSids -notcontains $propietario)) {
            $aparte = '{0}.no-fiable-{1}' -f $Path, (Get-Date -Format 'yyyyMMddHHmmss')
            Write-Diag ('Carpeta de trabajo no fiable ({0}); se aparta a {1}' -f $Path, $aparte)
            if ($esEnlace) {
                [System.IO.Directory]::Delete($Path, $false)
            } else {
                Move-Item -LiteralPath $Path -Destination $aparte -Force -ErrorAction Stop
            }
        }
    }
    if (-not (Test-Path -LiteralPath $Path)) {
        [void][System.IO.Directory]::CreateDirectory($Path, (New-ProtectedDirectorySecurity))
    } else {
        Set-Acl -LiteralPath $Path -AclObject (New-ProtectedDirectorySecurity) -ErrorAction Stop
    }
    return $Path
}

# Carpeta raíz de datos protegidos (snapshots y archivos temporales elevados).
function Get-SecureDataRoot {
    return (Initialize-SecureDirectory -Path (Join-Path $env:ProgramData 'WinTaller'))
}

# Carpeta para los scripts hijo, descargas y registros temporales.
# Con permisos de administrador se usa la carpeta protegida; sin ellos, TEMP
# (el proceso hijo tampoco se eleva, así que no hay escalada posible).
function Get-WorkDir {
    if (-not $script:IsAdmin) { return $env:TEMP }
    try {
        [void](Get-SecureDataRoot)
        return (Initialize-SecureDirectory -Path (Join-Path $env:ProgramData 'WinTaller\tmp'))
    } catch {
        Write-Diag ('No se pudo preparar la carpeta protegida: ' + $_.Exception.Message)
        throw 'no se pudo preparar una carpeta de trabajo segura'
    }
}

function Write-Log {
    param(
        [Parameter(Mandatory = $true)][string]$Message,
        [ValidateSet('INFO','OK','WARN','ERROR','STEP')][string]$Level = 'INFO'
    )
    if (-not $script:logBox) { return }
    $timestamp = Get-Date -Format 'HH:mm:ss'
    switch ($Level) {
        'OK'    { $prefix = '[ OK ]';  $color = [System.Drawing.Color]::FromArgb(130, 220, 130) }
        'WARN'  { $prefix = '[AVISO]'; $color = [System.Drawing.Color]::FromArgb(240, 200, 100) }
        'ERROR' { $prefix = '[ERROR]'; $color = [System.Drawing.Color]::FromArgb(255, 120, 120) }
        'STEP'  { $prefix = '[TAREA]'; $color = [System.Drawing.Color]::FromArgb(120, 200, 255) }
        default { $prefix = '[INFO]';  $color = [System.Drawing.Color]::FromArgb(200, 200, 200) }
    }
    try {
        $script:logBox.SelectionStart  = $script:logBox.TextLength
        $script:logBox.SelectionLength = 0
        $script:logBox.SelectionColor  = $color
        $script:logBox.AppendText(('{0} {1} ' -f $timestamp, $prefix))
        $script:logBox.SelectionColor = [System.Drawing.Color]::FromArgb(225, 225, 225)
        $script:logBox.AppendText(('{0}{1}' -f $Message, [Environment]::NewLine))
        $script:logBox.SelectionStart = $script:logBox.TextLength
        $script:logBox.ScrollToCaret()
        [System.Windows.Forms.Application]::DoEvents()
    } catch { }
}

function Get-SystemInfoText {
    try {
        $os   = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        $cs   = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
        $cpu  = (Get-CimInstance -ClassName Win32_Processor -ErrorAction SilentlyContinue | Select-Object -First 1).Name
        $driveLetter = $env:SystemDrive.TrimEnd(':')
        $drive = Get-PSDrive -Name $driveLetter -ErrorAction SilentlyContinue
        $ram   = [math]::Round($cs.TotalPhysicalMemory / 1GB, 1)
        if ($drive) {
            $free  = [math]::Round($drive.Free / 1GB, 1)
            $total = [math]::Round(($drive.Used + $drive.Free) / 1GB, 1)
            $disk = ('{0} {1} GB libres de {2} GB' -f $env:SystemDrive, $free, $total)
        } else {
            $disk = 'disco no disponible'
        }
        if ($cpu) {
            $cpu = $cpu.Trim()
            $cpu = $cpu -replace '\s*\(R\)', '' -replace '\s*\(TM\)', ''
            $cpu = $cpu -replace '\s+CPU\s+@.*$', '' -replace '\s+CPU$', ''
            $cpu = $cpu.Trim()
        } else {
            $cpu = 'CPU desconocida'
        }
        $sistema = [string]$os.Caption
        $sistema = $sistema -replace '^Microsoft\s+', ''
        return ('Equipo: {0}  |  {1}  |  {2}  |  RAM {3} GB  |  {4}' -f $env:COMPUTERNAME, $sistema, $cpu, $ram, $disk)
    } catch {
        return 'No se pudo obtener la información del equipo.'
    }
}

function Get-FreeSpaceGB {
    try {
        $drive = Get-PSDrive -Name $env:SystemDrive.TrimEnd(':') -ErrorAction Stop
        return [math]::Round($drive.Free / 1GB, 2)
    } catch {
        return $null
    }
}

function Get-ServiceSnapshot {
    $items = @()
    try {
        $rows = Get-CimInstance -ClassName Win32_Service -Property Name,DisplayName,State,StartMode,ProcessId,Description,PathName -ErrorAction Stop
        foreach ($svc in $rows) {
            if ($svc.State -eq 'Running') { $state = 'En ejecución' } else { $state = 'Detenido' }
            $mode = switch ($svc.StartMode) {
                'Auto'     { 'Automático' }
                'Manual'   { 'Manual' }
                'Disabled' { 'Deshabilitado' }
                default    { [string]$svc.StartMode }
            }
            $desc = ''
            if ($svc.Description) {
                $desc = ($svc.Description -replace '\s+', ' ').Trim()
            }
            $items += [pscustomobject]@{
                Name        = [string]$svc.Name
                DisplayName = [string]$svc.DisplayName
                State       = $state
                StartMode   = $mode
                ProcessId   = [int]$svc.ProcessId
                Description = $desc
                PathName    = [string]$svc.PathName
            }
        }
    } catch {
        foreach ($svc in (Get-Service -ErrorAction SilentlyContinue)) {
            if ($svc.Status -eq 'Running') { $state = 'En ejecución' } else { $state = 'Detenido' }
            $mode = switch ([string]$svc.StartType) {
                'Automatic' { 'Automático' }
                'Manual'    { 'Manual' }
                'Disabled'  { 'Deshabilitado' }
                default     { [string]$svc.StartType }
            }
            $items += [pscustomobject]@{
                Name        = [string]$svc.Name
                DisplayName = [string]$svc.DisplayName
                State       = $state
                StartMode   = $mode
                ProcessId   = 0
                Description = ''
                PathName    = ''
            }
        }
    }
    return $items
}

function Get-ServiceRisk {
    param([string]$Name)
    if ($script:CriticalServices -contains $Name) { return 'Crítico' }
    if ($script:SafeToStop -contains $Name)      { return 'Bajo' }
    return 'Medio'
}

# ---------------------------------------------------------------------------
# Base de conocimiento: que ocurre al detener o deshabilitar cada servicio
#   Consejo:
#     Quitar    -> se puede deshabilitar sin perder nada importante
#     Opcional  -> solo si no usas la función que da ese servicio
#     No tocar  -> Windows lo necesita; no lo deshabilites
# ---------------------------------------------------------------------------

$script:ServiceKnowledge = @{}

# Servicios de Windows que conviene dejar como están aunque no sean "críticos"
$script:KeepServices = @(
    'wuauserv','bits','UsoSvc','WaaSMedicSvc','sppsvc','VSS','SDRSVC','swprv',
    'msiserver','TrustedInstaller','StorSvc','W32Time','tzautoupdate','EventSystem',
    'COMSysApp','UserDataSvc','UnistoreSvc','camsvc','FontCache','hidserv',
    'AppReadiness','FrameServer','DeviceAssociationService'
)

function Add-ServiceKnowledge {
    param(
        [string]$Name,
        [string]$Consejo,
        [string]$Impacto,
        [string]$Uso = ''
    )
    $script:ServiceKnowledge[$Name] = [pscustomobject]@{
        Consejo = $Consejo
        Impacto = $Impacto
        Uso     = $Uso
    }
}

