# ---------------------------------------------------------------------------
# Consejo para un servicio concreto
# ---------------------------------------------------------------------------

function Get-ServiceAdvice {
    param($Service)

    $name = [string]$Service.Name
    if ($script:ServiceKnowledge.ContainsKey($name)) {
        $k = $script:ServiceKnowledge[$name]
        return [pscustomobject]@{ Consejo = $k.Consejo; Impacto = $k.Impacto; Uso = $k.Uso }
    }

    if ($script:CriticalServices -contains $name) {
        return [pscustomobject]@{
            Consejo = 'No tocar'
            Impacto = 'Es un servicio esencial de Windows. Si se detiene o se deshabilita, el equipo puede quedar inestable, sin red, sin inicio de sesión o sin arrancar correctamente. Esta herramienta no permite tocarlo.'
            Uso     = 'Siempre: Windows lo necesita para funcionar.'
        }
    }

    if ($script:KeepServices -contains $name) {
        return [pscustomobject]@{
            Consejo = 'No tocar'
            Impacto = 'Windows lo usa para funciones basicas (actualizaciones, activación, instalación de programas, hora del sistema o aplicaciones modernas). Deshabilitarlo puede romper esas funciones.'
            Uso     = 'Uso normal del equipo.'
        }
    }

    if ($script:SafeToStop -contains $name) {
        return [pscustomobject]@{
            Consejo = 'Quitar'
            Impacto = 'Es un servicio prescindible en la mayoría de equipos. Al deshabilitarlo deja de ocupar memoria y se reduce la superficie de ataque; reactivalo si echas de menos su función.'
            Uso     = 'Solo para funciones secundarias.'
        }
    }

    $path = [string]$Service.PathName
    $esDeWindows = ($path -match '(?i)\\Windows\\(System32|SysWOW64|servicing|WinSxS)\\')
    if ($path -and -not $esDeWindows) {
        $exe = ''
        try { $exe = Split-Path -Leaf ($path.Trim('"')) } catch { }
        return [pscustomobject]@{
            Consejo = 'Opcional'
            Impacto = ('Pertenece a un programa instalado en el equipo ({0}). Si deshabilitas el servicio, ese programa puede dejar de actualizarse, de arrancar solo o de funcionar hasta que lo reactives. No afecta a Windows.' -f $exe)
            Uso     = 'Solo si usas ese programa.'
        }
    }

    return [pscustomobject]@{
        Consejo = 'Opcional'
        Impacto = 'Servicio de Windows sin ficha propia. Si lo detienes, la función concreta que describe su nombre deja de estar disponible; el resto del sistema suele seguir igual. Si algo deja de funcionar, reactivalo.'
        Uso     = 'Depende de la función que use el servicio.'
    }
}

function Get-ServiceRelations {
    param([string]$Name)
    $dependents = @()
    $dependsOn  = @()
    try {
        $svc = Get-Service -Name $Name -ErrorAction Stop
        foreach ($d in $svc.DependentServices) {
            $st = 'detenido'
            if ($d.Status -eq 'Running') { $st = 'en ejecución' }
            $dependents += ('{0} [{1}]' -f $d.DisplayName, $st)
        }
        foreach ($d in $svc.ServicesDependedOn) {
            $st = 'detenido'
            if ($d.Status -eq 'Running') { $st = 'en ejecución' }
            $dependsOn += ('{0} [{1}]' -f $d.DisplayName, $st)
        }
    } catch { }
    return [pscustomobject]@{ Dependents = $dependents; DependsOn = $dependsOn }
}

function New-ServiceInfoText {
    param(
        [string]$Name,
        [string]$DisplayName,
        [string]$State,
        [string]$StartMode,
        [int]$ProcessId,
        [string]$Risk,
        [string]$Description,
        $Advice
    )

    $relations = Get-ServiceRelations -Name $Name
    $lines = New-Object System.Collections.Generic.List[string]

    $lines.Add('SERVICIO')
    $lines.Add(('  Nombre interno : {0}' -f $Name))
    $lines.Add(('  Nombre visible : {0}' -f $DisplayName))
    if ($ProcessId -gt 0) {
        $lines.Add(('  Estado ahora   : {0} (PID {1})' -f $State, $ProcessId))
    } else {
        $lines.Add(('  Estado ahora   : {0}' -f $State))
    }
    $lines.Add(('  Tipo de inicio : {0}' -f $StartMode))
    $lines.Add(('  Riesgo         : {0}' -f $Risk))
    $lines.Add('')

    $lines.Add('QUE ES')
    if ($Description) {
        $lines.Add(('  {0}' -f $Description))
    } else {
        $lines.Add('  Windows no ofrece una descripción para este servicio.')
    }
    $lines.Add('')

    $lines.Add('QUE PASA SI LO DETENGO')
    if ($State -eq 'En ejecución') {
        $lines.Add('  - El servicio se detiene en este momento.')
    } else {
        $lines.Add('  - Ahora mismo ya está detenido, así que no cambia nada de inmediato.')
    }
    if ($StartMode -eq 'Automático') {
        $lines.Add('  - Como su inicio es Automático, volverá a arrancar al reiniciar el equipo.')
    } elseif ($StartMode -eq 'Manual') {
        $lines.Add('  - Su inicio es Manual: solo arranca cuando Windows o un programa lo piden.')
    } elseif ($StartMode -eq 'Deshabilitado') {
        $lines.Add('  - Ya está deshabilitado: no arrancara aunque Windows lo necesite.')
    }
    $lines.Add(('  - {0}' -f $Advice.Impacto))
    if ($relations.Dependents.Count -gt 0) {
        $lista = ($relations.Dependents | Select-Object -First 6) -join ', '
        if ($relations.Dependents.Count -gt 6) { $lista += ', ...' }
        $lines.Add(('  - ATENCIÓN: estos servicios dependen de el y también se detendrán: {0}' -f $lista))
    }
    $lines.Add('')

    $lines.Add('QUE PASA SI LO DESHABILITO')
    $lines.Add('  - No volverá a arrancar al reiniciar. Es la forma de quitarlo de forma permanente.')
    $lines.Add(('  - {0}' -f $Advice.Impacto))
    $lines.Add('  - Puedes revertirlo cuando quieras con el botón "Reactivar" (lo deja en inicio Manual).')
    $lines.Add('')

    $lines.Add('RECOMENDACION')
    switch ($Advice.Consejo) {
        'Quitar' {
            $lines.Add('  SE PUEDE QUITAR. No es necesario para el funcionamiento normal de Windows.')
        }
        'Opcional' {
            $lines.Add('  OPCIONAL. Solo lo necesitas si usas la función que da este servicio.')
        }
        default {
            $lines.Add('  NO TOCAR. Windows lo necesita; deshabilitarlo puede romper el sistema.')
        }
    }
    if ($Risk -eq 'Crítico') {
        $lines.Add('  Además está marcado como CRÍTICO: la herramienta no permite detenerlo ni deshabilitarlo.')
    }
    $lines.Add('')

    $lines.Add('CUANDO LO NECESITAS')
    if ($Advice.Uso) {
        $lines.Add(('  {0}' -f $Advice.Uso))
    } else {
        $lines.Add('  Depende de la función que use el servicio.')
    }
    $lines.Add('')

    $lines.Add('SERVICIOS RELACIONADOS')
    if ($relations.Dependents.Count -gt 0) {
        $lines.Add(('  Dependen de este : {0}' -f (($relations.Dependents | Select-Object -First 8) -join ', ')))
    } else {
        $lines.Add('  Dependen de este : ninguno.')
    }
    if ($relations.DependsOn.Count -gt 0) {
        $lines.Add(('  Este depende de  : {0}' -f (($relations.DependsOn | Select-Object -First 8) -join ', ')))
    } else {
        $lines.Add('  Este depende de  : ninguno.')
    }
    $lines.Add('')
    $lines.Add('Nota: la ficha es orientativa. Si después de quitarlo algo deja de funcionar,')
    $lines.Add('reactiva el servicio con el botón "Reactivar".')

    return ($lines -join "`r`n")
}

function New-ServiceInfoDialog {
    param($Row)

    if (-not $Row -or $Row.IsNewRow) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'Selecciona primero un servicio de la lista y vuelve a pulsar el botón.',
            $script:AppName, 'OK', 'Information')
        return $null
    }

    $name      = [string]$Row.Cells['Nombre'].Value
    $disp      = [string]$Row.Cells['Mostrar'].Value
    $state     = [string]$Row.Cells['Estado'].Value
    $startMode = [string]$Row.Cells['Inicio'].Value
    $risk      = [string]$Row.Cells['Riesgo'].Value
    $desc      = [string]$Row.Cells['Descripcion'].Value
    $pidValue  = 0
    try { $pidValue = [int]$Row.Cells['PID'].Value } catch { }
    $path = ''
    try { $path = [string]$Row.Cells['Ruta'].Value } catch { }

    $advice = Get-ServiceAdvice ([pscustomobject]@{ Name = $name; Description = $desc; PathName = $path })
    $text   = New-ServiceInfoText -Name $name -DisplayName $disp -State $state -StartMode $startMode `
                                  -ProcessId $pidValue -Risk $risk -Description $desc -Advice $advice

    $verdictColor = [System.Drawing.Color]::FromArgb(150, 100, 0)
    $verdict = 'OPCIONAL: solo si no usas esa función'
    if ($advice.Consejo -eq 'Quitar') {
        $verdictColor = [System.Drawing.Color]::FromArgb(0, 120, 0)
        $verdict = 'SE PUEDE QUITAR'
    } elseif ($advice.Consejo -eq 'No tocar') {
        $verdictColor = [System.Drawing.Color]::FromArgb(170, 0, 0)
        $verdict = 'NO TOCAR: Windows lo necesita'
    }

    $dlg = New-Object System.Windows.Forms.Form
    try { $dlg.Icon = Get-AppIcon } catch { }
    $dlg.Text = ('Que pasa si quito "{0}"' -f $disp)
    $dlg.StartPosition = 'CenterParent'
    $dlg.Size = New-Object System.Drawing.Size(760, 640)
    $dlg.MinimumSize = New-Object System.Drawing.Size(560, 420)
    $dlg.MaximizeBox = $false
    $dlg.MinimizeBox = $false
    $dlg.ShowInTaskbar = $false
    $dlg.Font = $script:uiFont

    $layout = New-Object System.Windows.Forms.TableLayoutPanel
    $layout.Dock = 'Fill'
    $layout.ColumnCount = 1
    $layout.RowCount = 3
    [void]$layout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute, 84)))
    [void]$layout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Percent, 100)))
    [void]$layout.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute, 50)))
    $layout.Padding = New-Object System.Windows.Forms.Padding(10, 8, 10, 8)
    $dlg.Controls.Add($layout)

    $header = New-Object System.Windows.Forms.TableLayoutPanel
    $header.Dock = 'Fill'
    $header.ColumnCount = 1
    $header.RowCount = 3
    [void]$header.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute, 30)))
    [void]$header.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute, 22)))
    [void]$header.RowStyles.Add((New-Object System.Windows.Forms.RowStyle([System.Windows.Forms.SizeType]::Absolute, 28)))
    $layout.Controls.Add($header, 0, 0)

    $lblTitle = New-Object System.Windows.Forms.Label
    $lblTitle.Dock = 'Fill'
    $lblTitle.TextAlign = 'MiddleLeft'
    $lblTitle.Font = New-Object System.Drawing.Font('Segoe UI', 12, [System.Drawing.FontStyle]::Bold)
    $lblTitle.Text = $disp
    $header.Controls.Add($lblTitle, 0, 0)

    $lblSub = New-Object System.Windows.Forms.Label
    $lblSub.Dock = 'Fill'
    $lblSub.TextAlign = 'MiddleLeft'
    $lblSub.ForeColor = [System.Drawing.Color]::FromArgb(90, 90, 90)
    $lblSub.Text = ('Servicio: {0}   |   Estado: {1}   |   Inicio: {2}   |   Riesgo: {3}' -f $name, $state, $startMode, $risk)
    $header.Controls.Add($lblSub, 0, 1)

    $lblVerdict = New-Object System.Windows.Forms.Label
    $lblVerdict.Dock = 'Fill'
    $lblVerdict.TextAlign = 'MiddleLeft'
    $lblVerdict.Font = $script:boldFont
    $lblVerdict.ForeColor = $verdictColor
    $lblVerdict.Text = $verdict
    $header.Controls.Add($lblVerdict, 0, 2)

    $txt = New-Object System.Windows.Forms.TextBox
    $txt.Dock = 'Fill'
    $txt.Multiline = $true
    $txt.ReadOnly = $true
    $txt.WordWrap = $true
    $txt.ScrollBars = 'Vertical'
    $txt.BorderStyle = 'FixedSingle'
    $txt.BackColor = [System.Drawing.Color]::White
    $txt.Font = New-Object System.Drawing.Font('Segoe UI', 9.5)
    $txt.Text = $text
