    $txt.SelectionLength = 0
    $layout.Controls.Add($txt, 0, 1)

    $buttons = New-Object System.Windows.Forms.FlowLayoutPanel
    $buttons.Dock = 'Fill'
    $buttons.FlowDirection = 'RightToLeft'
    $buttons.WrapContents = $false
    $buttons.Padding = New-Object System.Windows.Forms.Padding(0, 6, 0, 0)
    $layout.Controls.Add($buttons, 0, 2)

    $btnClose = New-Object System.Windows.Forms.Button
    $btnClose.Text = 'Cerrar'
    $btnClose.AutoSize = $true
    $btnClose.MinimumSize = New-Object System.Drawing.Size(90, 30)
    $btnClose.DialogResult = 'Cancel'
    $btnClose.Margin = New-Object System.Windows.Forms.Padding(4, 0, 0, 0)
    $buttons.Controls.Add($btnClose)

    $btnMark = New-Object System.Windows.Forms.Button
