        } catch { }
        try { $sender.FindForm().Close() } catch { }
    })
    $btnMark.Tag = $Row

    $dlg.AcceptButton = $btnMark
    $dlg.CancelButton = $btnClose
    return $dlg
}

function Show-ServiceInfo {
