    try {
        [void]$dlg.ShowDialog($script:form)
    } finally {
        $dlg.Dispose()
    }
}

function Show-InfoForCurrentRow {
    $row = $null
    if ($script:grid) { $row = $script:grid.CurrentRow }
    Show-ServiceInfo $row
}

