function New-LogView {
    $box = New-Object System.Windows.Forms.RichTextBox
    $box.Dock = 'Fill'
    $box.ReadOnly = $true
    $box.BorderStyle = 'FixedSingle'
    $box.BackColor = [System.Drawing.Color]::FromArgb(32, 34, 38)
    $box.ForeColor = [System.Drawing.Color]::FromArgb(225, 225, 225)
    $box.Font = New-Object System.Drawing.Font('Consolas', 9)
    $box.WordWrap = $true
    $box.HideSelection = $false
    $box.DetectUrls = $false
    return $box
}

function Add-TabLog {
    param($Box, [string]$Text, [string]$Kind = 'INFO')
    if (-not $Box) { return }
    $color  = [System.Drawing.Color]::FromArgb(225, 225, 225)
    $prefix = '     '
    switch ($Kind) {
        'OK'    { $color = [System.Drawing.Color]::FromArgb(120, 220, 120); $prefix = '[OK] ' }
        'WARN'  { $color = [System.Drawing.Color]::FromArgb(240, 190, 90);  $prefix = '[!]  ' }
        'ERROR' { $color = [System.Drawing.Color]::FromArgb(240, 110, 110); $prefix = '[X]  ' }
        'STEP'  { $color = [System.Drawing.Color]::FromArgb(120, 190, 255); $prefix = '>>   ' }
    }
    $stamp = (Get-Date).ToString('HH:mm:ss')
    try {
        $Box.SelectionStart = $Box.TextLength
        $Box.SelectionLength = 0
        $Box.SelectionColor = [System.Drawing.Color]::FromArgb(150, 150, 150)
        $Box.AppendText(('{0} ' -f $stamp))
        $Box.SelectionColor = $color
        $Box.AppendText(('{0}{1}' -f $prefix, $Text))
        $Box.SelectionColor = [System.Drawing.Color]::FromArgb(225, 225, 225)
        $Box.AppendText([Environment]::NewLine)
        $Box.SelectionStart = $Box.TextLength
        $Box.ScrollToCaret()
    } catch { }
    try { Add-Content -LiteralPath $script:DiagFile -Value ('{0}  [{1}] {2}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff'), $Kind, $Text) -Encoding UTF8 -ErrorAction SilentlyContinue } catch { }
}

function Save-LogBox {
    param($Box, [string]$DefaultName = 'registro')
    if (-not $Box -or $Box.TextLength -eq 0) {
        [void][System.Windows.Forms.MessageBox]::Show('No hay nada que guardar todavía.', $script:AppName, 'OK', 'Information')
        return
    }
    $dialog = New-Object System.Windows.Forms.SaveFileDialog
    $dialog.Filter   = 'Archivo de texto (*.txt)|*.txt'
    $dialog.FileName = ('{0}_{1}.txt' -f $DefaultName, (Get-Date -Format 'yyyyMMdd_HHmmss'))
    if ($dialog.ShowDialog() -eq 'OK') {
        try {
            Set-Content -LiteralPath $dialog.FileName -Value $Box.Text -Encoding UTF8
            [void][System.Windows.Forms.MessageBox]::Show(("Registro guardado en:`n{0}" -f $dialog.FileName), $script:AppName, 'OK', 'Information')
        } catch {
            [void][System.Windows.Forms.MessageBox]::Show(('No se pudo guardar: {0}' -f $_.Exception.Message), $script:AppName, 'OK', 'Error')
        }
    }
}

function Set-RegValue {
    param([string]$Path, [string]$Name, $Value, [string]$Type = 'DWord')
    if (-not (Test-Path -LiteralPath $Path)) {
        New-Item -Path $Path -Force -ErrorAction Stop | Out-Null
    }
    New-ItemProperty -Path $Path -Name $Name -Value $Value -PropertyType $Type -Force -ErrorAction Stop | Out-Null
}

# Borra un valor del registro si existe (vuelve al comportamiento por defecto).
function Remove-RegValue {
    param([string]$Path, [string]$Name)
    if (-not (Test-Path -LiteralPath $Path)) { return }
    if ($null -eq (Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction SilentlyContinue)) { return }
    Remove-ItemProperty -LiteralPath $Path -Name $Name -Force -ErrorAction Stop
}

function Update-ExplorerSettings {
    try {
        if (-not ('WinTaller.Avisos' -as [type])) {
            $code = '[DllImport("user32.dll", CharSet = CharSet.Auto)] public static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint Msg, UIntPtr wParam, string lParam, uint fuFlags, uint uTimeout, out UIntPtr lpdwResult);'
            Add-Type -MemberDefinition $code -Name 'Avisos' -Namespace 'WinTaller' -ErrorAction Stop
        }
        $resultado = [UIntPtr]::Zero
        [void][WinTaller.Avisos]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, 'ImmersiveColorSet', 2, 2000, [ref]$resultado)
        [void][WinTaller.Avisos]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, 'Environment', 2, 2000, [ref]$resultado)
    } catch { }
}

# ---------------------------------------------------------------------------
# winget: instalación de programas
# ---------------------------------------------------------------------------

# Se busca winget en rutas fijas en lugar de en el PATH: con permisos de
# administrador, un winget.exe colocado en una carpeta del PATH del usuario
# se ejecutaría elevado.
function Get-WingetPath {
    $alias = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
    # Sin elevación no hay riesgo: el alias del usuario es lo más fiable.
    if (-not $script:IsAdmin -and (Test-Path -LiteralPath $alias)) { return $alias }
    try {
        $paquete = Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction Stop |
            Sort-Object Version -Descending | Select-Object -First 1
        if ($paquete -and $paquete.InstallLocation) {
            $exe = Join-Path $paquete.InstallLocation 'winget.exe'
            if (Test-Path -LiteralPath $exe) { return $exe }
        }
    } catch { }
    if (Test-Path -LiteralPath $alias) { return $alias }
    return $null
}

function Test-Winget {
    $script:wingetPath    = Get-WingetPath
    $script:wingetReady   = $false
    $script:wingetVersion = ''
    if (-not $script:wingetPath) { return $false }
    try {
        $salida = & $script:wingetPath --version 2>&1
        if ($LASTEXITCODE -eq 0) {
            $script:wingetVersion = ([string]($salida | Select-Object -First 1)).Trim()
            $script:wingetReady = $true
        }
    } catch { }
    return $script:wingetReady
}

function Get-WingetInstalledIds {
    $ids = @{}
    if (-not $script:wingetPath) { return $ids }
    $tmp = $null
    try {
        $tmp = Join-Path (Get-WorkDir) ('winget_export_{0}.json' -f ([guid]::NewGuid().ToString('N')))
        $proc = Start-Process -FilePath $script:wingetPath `
            -ArgumentList @('export', '--output', ('"' + $tmp + '"'), '--accept-source-agreements', '--disable-interactivity') `
            -PassThru -WindowStyle Hidden
        if (-not $proc.WaitForExit(60000)) {
            try { $proc.Kill() } catch { }
        }
        if (Test-Path -LiteralPath $tmp) {
            $raw  = Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop
            $json = $raw | ConvertFrom-Json
            foreach ($src in $json.Sources) {
                foreach ($pkg in $src.Packages) {
                    if ($pkg.PackageIdentifier) { $ids[[string]$pkg.PackageIdentifier] = $true }
                }
            }
        }
    } catch {
        Write-Diag ('No se pudo leer la lista de programas instalados: ' + $_.Exception.Message)
    } finally {
        if ($tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
    }
    return $ids
}

function Set-AppItemState {
    param($Item, [string]$State)
    try {
        while ($Item.SubItems.Count -lt 4) { [void]$Item.SubItems.Add('') }
        $Item.SubItems[3].Text = $State
        if ($State -eq 'Instalado') {
            $Item.ForeColor = [System.Drawing.Color]::FromArgb(0, 120, 0)
        } elseif ($State -eq 'Error' -or $State -eq 'Aviso') {
            $Item.ForeColor = [System.Drawing.Color]::FromArgb(170, 60, 0)
        } elseif ($State -eq 'Instalando...') {
            $Item.ForeColor = [System.Drawing.Color]::FromArgb(0, 80, 160)
        } else {
            $Item.ForeColor = [System.Drawing.Color]::Black
        }
        if ($Item.Tag -and $script:appStateById) {
            $script:appStateById[[string]$Item.Tag.Id] = $State
        }
    } catch { }
}

function Start-WingetQueue {
    param($Items)

    $necesitaWinget = @($Items | Where-Object { -not $_.Tag -or $_.Tag.Kind -ne 'msi' }).Count -gt 0
    if ($necesitaWinget -and -not (Test-Winget)) {
        [void][System.Windows.Forms.MessageBox]::Show(
            "winget no está disponible en este equipo.`n`nAbre Microsoft Store, instala 'Instalador de aplicaciones' (App Installer) y vuelve a intentarlo.`n`nTambién puedes ejecutar en PowerShell: winget --version",
            "$script:AppName - winget", 'OK', 'Warning')
        return
    }

    $script:wingetQueue.Clear()
    foreach ($item in $Items) { $script:wingetQueue.Enqueue($item) }
    $script:wingetTotal  = $Items.Count
    $script:wingetDone   = 0
    $script:wingetErrors = 0
    $script:wingetKind   = 'winget'

    if ($necesitaWinget) {
        Add-TabLog $script:prgLog ('=== Instalación de {0} programas (winget {1}) ===' -f $Items.Count, $script:wingetVersion) 'STEP'
    } else {
        Add-TabLog $script:prgLog ('=== Instalación de {0} programas desde su web oficial ===' -f $Items.Count) 'STEP'
    }
    $btnProgramsInstall.Enabled = $false
    $btnProgramsStop.Enabled    = $true
    if ($script:txtPrgSearch) { $script:txtPrgSearch.Enabled = $false }
    $script:statusLabel.Text = 'Instalando programas...'
    Start-NextWinget
}

# Comprueba un instalador descargado antes de ejecutarlo como administrador.
# Devuelve '' si es correcto o el motivo del rechazo.
#   - Firma Authenticode obligatoria y válida.
#   - Si la entrada del catálogo define Signer, el certificado debe contenerlo.
#   - Si define Sha256, el hash debe coincidir exactamente.
function Test-DownloadedInstaller {
    param([string]$Path, $App)
    try {
        if ($App.Sha256) {
            $hash = (Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash
            if ($hash -ne ([string]$App.Sha256).ToUpperInvariant()) {
                return ('el hash SHA256 no coincide (esperado {0}, obtenido {1})' -f $App.Sha256, $hash)
            }
        }
        $firma = Get-AuthenticodeSignature -LiteralPath $Path -ErrorAction Stop
        if ($firma.Status -ne 'Valid') {
            return ('la firma digital no es válida ({0})' -f $firma.Status)
        }
        $sujeto = ''
        if ($firma.SignerCertificate) { $sujeto = [string]$firma.SignerCertificate.Subject }
        if ($App.Signer -and $sujeto -notlike ('*' + [string]$App.Signer + '*')) {
            return ('el firmante no es el esperado ({0})' -f $sujeto)
        }
        Add-TabLog $script:prgLog ('{0}: firma digital válida. Firmante: {1}' -f $App.Name, $sujeto) 'OK'
        return ''
    } catch {
        return ('no se pudo comprobar el archivo ({0})' -f $_.Exception.Message)
    }
}

function Start-MsiAppInstall {
    param($Item, $App)

    $script:wingetKind = 'msi'
    $script:wingetOutFile = $null
    $script:wingetErrFile = $null

    if (-not $script:IsAdmin) {
        Set-AppItemState $Item 'Aviso'
        $script:wingetErrors++
        $script:wingetDone++
        Add-TabLog $script:prgLog ('{0}: para instalar este programa hay que abrir la herramienta como administrador (Iniciar.bat).' -f $App.Name) 'ERROR'
        Start-NextWinget
        return
    }
    if (-not $App.Url) {
        Set-AppItemState $Item 'Aviso'
        $script:wingetErrors++
        $script:wingetDone++
        Add-TabLog $script:prgLog ('{0}: no tiene direccion de descarga configurada.' -f $App.Name) 'ERROR'
        Start-NextWinget
        return
    }

    $archivo = $null
    $script:statusLabel.Text = ('Descargando {0}...' -f $App.Name)
    $script:form.UseWaitCursor = $true
    [System.Windows.Forms.Application]::DoEvents()
    try {
        if (-not ([string]$App.Url).StartsWith('https://', [System.StringComparison]::OrdinalIgnoreCase)) {
            throw 'la dirección de descarga no usa HTTPS'
        }
        # Carpeta protegida: un proceso sin privilegios no puede cambiar el MSI
        # entre la descarga y la instalación con permisos de administrador.
        $archivo = Join-Path (Get-WorkDir) ('wintaller_app_{0}.msi' -f ([guid]::NewGuid().ToString('N')))
        $script:wingetMsiFile = $archivo
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
        Invoke-WebRequest -Uri $App.Url -OutFile $archivo -UseBasicParsing -TimeoutSec 300 -ErrorAction Stop
    } catch {
        Set-AppItemState $Item 'Aviso'
        $script:wingetErrors++
        $script:wingetDone++
        Add-TabLog $script:prgLog ('{0}: no se pudo descargar desde su web oficial ({1}).' -f $App.Name, $_.Exception.Message) 'ERROR'
        try { Remove-Item -LiteralPath $archivo -Force -ErrorAction SilentlyContinue } catch { }
        $script:wingetMsiFile = $null
        Start-NextWinget
        return
    } finally {
        $script:form.UseWaitCursor = $false
    }

    if (-not (Test-Path -LiteralPath $archivo)) {
        Set-AppItemState $Item 'Aviso'
        $script:wingetErrors++
        $script:wingetDone++
        Add-TabLog $script:prgLog ('{0}: la descarga no genero ningún archivo.' -f $App.Name) 'ERROR'
        $script:wingetMsiFile = $null
        Start-NextWinget
        return
    }

    $motivoRechazo = Test-DownloadedInstaller -Path $archivo -App $App
    if ($motivoRechazo) {
        Set-AppItemState $Item 'Aviso'
        $script:wingetErrors++
        $script:wingetDone++
        Add-TabLog $script:prgLog ('{0}: el instalador descargado NO se ha ejecutado: {1}.' -f $App.Name, $motivoRechazo) 'ERROR'
        try { Remove-Item -LiteralPath $archivo -Force -ErrorAction SilentlyContinue } catch { }
        $script:wingetMsiFile = $null
        Start-NextWinget
        return
    }

    Add-TabLog $script:prgLog ('{0}: descargado y verificado. Instalando en silencio...' -f $App.Name) 'OK'
    $extra = '/qn /norestart'
    if ($App.MsiArgs) { $extra = [string]$App.MsiArgs }
    $argumentos = @('/i', ('"' + $archivo + '"')) + @($extra -split '\s+' | Where-Object { $_ })
    try {
        $script:wingetProcess = Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\msiexec.exe') -ArgumentList $argumentos -PassThru -WindowStyle Hidden
        $script:wingetProcess.EnableRaisingEvents = $true
        $script:wingetStarted = Get-Date
        $script:wingetTimer.Start()
    } catch {
        Set-AppItemState $Item 'Aviso'
        $script:wingetErrors++
        $script:wingetDone++
        Add-TabLog $script:prgLog ('{0}: no se pudo iniciar el instalador ({1}).' -f $App.Name, $_.Exception.Message) 'ERROR'
        try { Remove-Item -LiteralPath $archivo -Force -ErrorAction SilentlyContinue } catch { }
        $script:wingetMsiFile = $null
        $script:wingetProcess = $null
        Start-NextWinget
    }
}

function Start-NextWinget {
    if ($script:wingetQueue.Count -eq 0) {
        $script:wingetTimer.Stop()
        $btnProgramsInstall.Enabled = $true
        $btnProgramsStop.Enabled    = $false
        if ($script:txtPrgSearch) { $script:txtPrgSearch.Enabled = $true }
        Add-TabLog $script:prgLog ('=== Fin: {0} correctos, {1} con avisos o errores ===' -f ($script:wingetDone - $script:wingetErrors), $script:wingetErrors) 'STEP'
        $script:statusLabel.Text = 'Instalación de programas terminada'
        if (-not $UiSmokeTest) {
            [void][System.Windows.Forms.MessageBox]::Show(
                ("Instalación terminada.`n`nCorrectos: {0}`nCon avisos o errores: {1}`n`nRevisa el registro para ver el detalle." -f ($script:wingetDone - $script:wingetErrors), $script:wingetErrors),
                $script:AppName, 'OK', 'Information')
        }
        return
    }

    $item = $script:wingetQueue.Dequeue()
    $app  = $item.Tag
    $script:wingetCurrentItem = $item
    Set-AppItemState $item 'Instalando...'
    try { $script:appList.EnsureVisible($item.Index) } catch { }

    if ($app.Kind -eq 'msi') {
        Add-TabLog $script:prgLog ('Instalando {0} desde su web oficial...' -f $app.Name) 'STEP'
        $script:statusLabel.Text = ('Descargando {0}...' -f $app.Name)
        Start-MsiAppInstall $item $app
        return
    }

    $script:wingetKind = 'winget'
    Add-TabLog $script:prgLog ('Instalando {0} ({1})...' -f $app.Name, $app.Id) 'STEP'
    $script:statusLabel.Text = ('Instalando {0}...' -f $app.Name)

    try {
        $script:wingetOutFile = Join-Path (Get-WorkDir) ('winget_out_{0}.txt' -f ([guid]::NewGuid().ToString('N')))
    } catch {
        $script:wingetOutFile = Join-Path $env:TEMP ('winget_out_{0}.txt' -f ([guid]::NewGuid().ToString('N')))
    }
    $script:wingetErrFile = $script:wingetOutFile + '.err'

    $argumentos = @(
        'install', '--id', $app.Id, '--exact', '--silent',
        '--accept-package-agreements', '--accept-source-agreements',
        '--disable-interactivity', '--source', 'winget'
    )

    try {
        $script:wingetProcess = Start-Process -FilePath $script:wingetPath `
            -ArgumentList $argumentos -PassThru -WindowStyle Hidden `
            -RedirectStandardOutput $script:wingetOutFile `
            -RedirectStandardError  $script:wingetErrFile
        # Con redireccion, Start-Process cierra el handle del proceso y ExitCode queda vacio.
        # Habilitar los eventos conserva el handle y permite leer el código de salida al terminar.
        $script:wingetProcess.EnableRaisingEvents = $true
        $script:wingetStarted = Get-Date
        $script:wingetTimer.Start()
    } catch {
        Add-TabLog $script:prgLog ('No se pudo iniciar winget: {0}' -f $_.Exception.Message) 'ERROR'
        Set-AppItemState $item 'Error'
        $script:wingetErrors++
        $script:wingetDone++
        $script:wingetProcess = $null
        Start-NextWinget
    }
}

function Get-WingetCodeText {
    param([int]$Code)
    switch ($Code) {
        -1978335212 { return 'el paquete no existe en winget o el identificador esta mal escrito' }
        -1978335189 { return 'winget no encontró un instalador aplicable para este equipo' }
        -1978334969 { return 'la instalación se canceló o el instalador pidió permisos que no se concedieron' }
        1602        { return 'el usuario canceló la instalación' }
        1603        { return 'error fatal del instalador (revisa permisos o cierra otros instaladores)' }
        1618        { return 'ya hay otra instalación en curso; espera y vuelve a intentarlo' }
        1625        { return 'la instalación está bloqueada por una directiva del sistema' }
        1633        { return 'el paquete no es compatible con este equipo' }
        1638        { return 'ya hay otra versión de este programa instalada' }
        1641        { return 'instalado; Windows ha iniciado el reinicio' }
        3010        { return 'instalado, pero Windows necesita reiniciar' }
    }
    return ''
}

function Stop-WingetProcess {
    $proc = $script:wingetProcess
    if (-not $proc) { return }
    try {
        if (-not $proc.HasExited) {
            & "$env:SystemRoot\System32\taskkill.exe" /PID $proc.Id /T /F 2>&1 | Out-Null
        }
    } catch {
        try { $proc.Kill() } catch { }
    }
    try { $proc.Dispose() } catch { }
}

function Step-WingetQueue {
    $proc = $script:wingetProcess
    if (-not $proc) { return }
    $terminado = $false
    try { $terminado = $proc.HasExited } catch { $terminado = $true }
    if (-not $terminado) {
        # Red de seguridad: si un instalador se queda colgado, no bloquear la cola para siempre.
        if ($script:wingetStarted -and ((Get-Date) - $script:wingetStarted).TotalMinutes -gt 60) {
            $colgado = $script:wingetCurrentItem
            Stop-WingetProcess
            if ($colgado) { Set-AppItemState $colgado 'Aviso' }
            $script:wingetErrors++
            $script:wingetDone++
            Add-TabLog $script:prgLog ('{0}: la instalación superó 60 minutos y se ha cancelado.' -f $colgado.Tag.Name) 'WARN'
            $script:wingetProcess = $null
            $script:wingetCurrentItem = $null
            if ($script:wingetMsiFile) {
                Remove-Item -LiteralPath $script:wingetMsiFile -Force -ErrorAction SilentlyContinue
                $script:wingetMsiFile = $null
            }
            foreach ($f in @($script:wingetOutFile, $script:wingetErrFile)) {
                if ($f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
            }
            $script:wingetOutFile = $null
            $script:wingetErrFile = $null
            Start-NextWinget
        }
        return
    }

    $codigo = -1
    try { $codigo = [int]$proc.ExitCode } catch { }

    $detalle = ''
    try {
        $lineas = @()
        foreach ($f in @($script:wingetOutFile, $script:wingetErrFile)) {
            if ($f -and (Test-Path -LiteralPath $f)) {
                $lineas += @(Get-Content -LiteralPath $f -ErrorAction SilentlyContinue)
            }
        }
        $limpias = @($lineas | ForEach-Object { ([string]$_ -replace "`r", ' ').Trim() } | Where-Object { $_ -and $_ -notmatch '^[-\\|/ ]+$' })
        $detalle = (($limpias | Select-Object -Last 4) -join ' | ')
    } catch { }

    $item = $script:wingetCurrentItem
    if ($script:wingetKind -eq 'msi') {
        if ($codigo -eq 0 -or $codigo -eq 3010 -or $codigo -eq 1641) {
            Set-AppItemState $item 'Instalado'
            if ($codigo -eq 3010 -or $codigo -eq 1641) {
                Add-TabLog $script:prgLog ('{0}: instalado. Windows pedira reiniciar.' -f $item.Tag.Name) 'OK'
            } else {
                Add-TabLog $script:prgLog ('{0}: instalado correctamente.' -f $item.Tag.Name) 'OK'
            }
        } else {
            Set-AppItemState $item 'Aviso'
            $script:wingetErrors++
            $explicacionMsi = Get-WingetCodeText $codigo
            if ($explicacionMsi) {
                Add-TabLog $script:prgLog ('{0}: {1} (código {2}).' -f $item.Tag.Name, $explicacionMsi, $codigo) 'WARN'
            } else {
                Add-TabLog $script:prgLog ('{0}: el instalador terminó con código {1}.' -f $item.Tag.Name, $codigo) 'WARN'
            }
        }
    } else {
        $explicacion = Get-WingetCodeText $codigo
        if ($codigo -eq 0 -or $codigo -eq 3010) {
            Set-AppItemState $item 'Instalado'
            if ($codigo -eq 3010) {
                Add-TabLog $script:prgLog ('{0}: instalado. Windows pedira reiniciar.' -f $item.Tag.Name) 'OK'
            } else {
                Add-TabLog $script:prgLog ('{0}: instalado correctamente.' -f $item.Tag.Name) 'OK'
            }
        } else {
            Set-AppItemState $item 'Aviso'
            $script:wingetErrors++
            if ($explicacion) {
                Add-TabLog $script:prgLog ('{0}: {1} (código {2}).' -f $item.Tag.Name, $explicacion, $codigo) 'WARN'
            } elseif ($detalle) {
                Add-TabLog $script:prgLog ('{0}: winget terminó con código {1}. {2}' -f $item.Tag.Name, $codigo, $detalle) 'WARN'
            } else {
                Add-TabLog $script:prgLog ('{0}: winget terminó con código {1}.' -f $item.Tag.Name, $codigo) 'WARN'
            }
        }
    }

    $script:wingetDone++
    $script:wingetProcess = $null
    $script:wingetCurrentItem = $null
    try { $proc.Dispose() } catch { }
    if ($script:wingetMsiFile) {
        Remove-Item -LiteralPath $script:wingetMsiFile -Force -ErrorAction SilentlyContinue
        $script:wingetMsiFile = $null
    }
    foreach ($f in @($script:wingetOutFile, $script:wingetErrFile)) {
        if ($f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
    }
    $script:wingetOutFile = $null
    $script:wingetErrFile = $null
    Start-NextWinget
}

function Stop-WingetQueue {
    $script:wingetQueue.Clear()
    if ($script:wingetProcess) {
        Stop-WingetProcess
        if ($script:wingetCurrentItem) { Set-AppItemState $script:wingetCurrentItem 'Cancelado' }
        Add-TabLog $script:prgLog 'Instalación detenida por el usuario.' 'WARN'
    }
    $script:wingetProcess = $null
    $script:wingetCurrentItem = $null
    $script:wingetTimer.Stop()
    foreach ($f in @($script:wingetOutFile, $script:wingetErrFile)) {
        if ($f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
    }
    $script:wingetOutFile = $null
    $script:wingetErrFile = $null
    if ($script:wingetMsiFile) {
        Remove-Item -LiteralPath $script:wingetMsiFile -Force -ErrorAction SilentlyContinue
        $script:wingetMsiFile = $null
    }
    $btnProgramsInstall.Enabled = $true
    $btnProgramsStop.Enabled    = $false
    if ($script:txtPrgSearch) { $script:txtPrgSearch.Enabled = $true }
    $script:statusLabel.Text = 'Instalación detenida'
}

# ---------------------------------------------------------------------------
# Detección del equipo (sobremesa o portátil)
# ---------------------------------------------------------------------------

function Get-HardwareProfile {
    $perfil = [pscustomobject]@{
        IsLaptop   = $false
        HasBattery = $false
        Chassis    = ''
        DiskKind   = 'Desconocido'
        Cpu        = ''
        RamGB      = 0
        Gpu        = ''
        Os         = ''
    }

    try {
        $equipo = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
        $perfil.RamGB = [math]::Round(($equipo.TotalPhysicalMemory / 1GB), 1)
        if ($equipo.PCSystemType -eq 2) { $perfil.IsLaptop = $true }
    } catch { }

    try {
        $so = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        $perfil.Os = ('{0} {1}' -f $so.Caption, $so.Version).Trim()
    } catch { }

    try {
        $cpu = Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop | Select-Object -First 1
        $perfil.Cpu = ([string]$cpu.Name).Trim()
    } catch { }

    try {
        $gpus = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop | ForEach-Object { $_.Name })
        $perfil.Gpu = ($gpus | Where-Object { $_ } | Select-Object -First 2) -join ' + '
    } catch { }

    try {
        $baterias = @(Get-CimInstance -ClassName Win32_Battery -ErrorAction Stop)
        if ($baterias.Count -gt 0) {
            $perfil.HasBattery = $true
            $perfil.IsLaptop   = $true
        }
    } catch { }

    try {
        $cajas = @(Get-CimInstance -ClassName Win32_SystemEnclosure -Property ChassisTypes -ErrorAction Stop)
        $tipos = @()
        foreach ($c in $cajas) {
            foreach ($t in @($c.ChassisTypes)) { $tipos += [int]$t }
        }
        $portatiles = @(8, 9, 10, 11, 12, 14, 18, 21, 30, 31, 32)
        $encontrados = @($tipos | Where-Object { $portatiles -contains $_ })
        if ($encontrados.Count -gt 0) {
            $perfil.IsLaptop = $true
            $perfil.Chassis  = 'Portátil'
        } elseif ($tipos.Count -gt 0) {
            $perfil.Chassis = 'Sobremesa'
        }
    } catch { }

    if (-not $perfil.Chassis) {
        if ($perfil.IsLaptop) { $perfil.Chassis = 'Portátil' } else { $perfil.Chassis = 'Sobremesa' }
    }

    try {
        $discos = @(Get-PhysicalDisk -ErrorAction Stop)
        $clases = @()
        foreach ($d in $discos) {
            $tipo = [string]$d.MediaType
            if ($tipo -eq 'SSD') { $clases += 'SSD' }
            elseif ($tipo -eq 'HDD') { $clases += 'HDD' }
            elseif ([int]$d.BusType -eq 17) { $clases += 'SSD' }
            else { $clases += 'Desconocido' }
        }
        if (($clases -contains 'SSD') -and ($clases -contains 'HDD')) { $perfil.DiskKind = 'Mixto' }
        elseif ($clases -contains 'SSD') { $perfil.DiskKind = 'SSD' }
        elseif ($clases -contains 'HDD') { $perfil.DiskKind = 'HDD' }
    } catch { }

    return $perfil
}

function Get-HardwareSummary {
    param($Perfil)
    if (-not $Perfil) { return 'Detectando el equipo...' }
    $tipo = 'Sobremesa'
    if ($Perfil.IsLaptop) { $tipo = 'Portátil' }
    $bateria = 'no detectada'
    if ($Perfil.HasBattery) { $bateria = 'sí' }
    return ('{0}  |  Disco: {1}  |  RAM: {2} GB  |  Batería: {3}{4}{5}' -f `
        $tipo, $Perfil.DiskKind, $Perfil.RamGB, $bateria, `
        $(if ($Perfil.Cpu) { '  |  ' + $Perfil.Cpu } else { '' }), `
        $(if ($Perfil.Gpu) { '  |  ' + $Perfil.Gpu } else { '' }))
}


function Update-ServiceGrid {
    if (-not $script:serviceTable) { return }
    $snapshot = @(Get-ServiceSnapshot)
    $script:grid.SuspendLayout()
    try {
        $script:serviceTable.Rows.Clear()
        foreach ($svc in $snapshot) {
            $row = $script:serviceTable.NewRow()
            $row['Sel']         = $false
            $row['Nombre']      = $svc.Name
            $row['Mostrar']     = $svc.DisplayName
            $row['Estado']      = $svc.State
            $row['Inicio']      = $svc.StartMode
            $row['PID']         = $svc.ProcessId
            $row['Riesgo']      = Get-ServiceRisk $svc.Name
            $row['Consejo']     = (Get-ServiceAdvice $svc).Consejo
            $row['Descripcion'] = $svc.Description
            $row['Ruta']        = $svc.PathName
            [void]$script:serviceTable.Rows.Add($row)
        }
    } finally {
        $script:grid.ResumeLayout()
    }
    Apply-ServiceFilter
}

function Apply-ServiceFilter {
    if (-not $script:serviceView) { return }
    $filters = @()
    if ($script:chkOnlyRunning -and $script:chkOnlyRunning.Checked) {
        $filters += "Estado = 'En ejecución'"
    }
    if ($script:chkRemovable -and $script:chkRemovable.Checked) {
        $filters += "Consejo = 'Quitar'"
    }
    $text = ''
    if ($script:txtSearch) { $text = $script:txtSearch.Text.Trim() }
    if ($text) {
        $safe = $text.Replace("'", "''")
        $filters += "(Nombre LIKE '%$safe%' OR Mostrar LIKE '%$safe%' OR Descripcion LIKE '%$safe%' OR Consejo LIKE '%$safe%' OR Riesgo LIKE '%$safe%')"
    }
    try {
        $script:serviceView.RowFilter = ($filters -join ' AND ')
    } catch {
        $script:serviceView.RowFilter = ''
    }
    Update-ServiceCounts
}

function Update-ServiceCounts {
    if (-not $script:serviceTable -or -not $script:lblCounts) { return }
    $total   = $script:serviceTable.Rows.Count
    $running = 0
    try {
        $running = @($script:serviceTable.Select("Estado = 'En ejecución'")).Count
    } catch { }
    $visible = 0
    if ($script:grid) { $visible = $script:grid.Rows.Count }
    $removable = 0
    try {
        $removable = @($script:serviceTable.Select("Consejo = 'Quitar'")).Count
    } catch { }
    $script:lblCounts.Text = ('Mostrando {0} de {1} servicios  -  {2} en ejecución  -  {3} se pueden quitar' -f $visible, $total, $running, $removable)
}

function Get-CheckedRows {
    $checked = @()
    if (-not $script:grid) { return ,$checked }
    foreach ($row in $script:grid.Rows) {
        if ($row.IsNewRow) { continue }
        $cell = $row.Cells['Sel']
        if ($null -ne $cell.Value -and [bool]$cell.Value) { $checked += $row }
    }
    return ,$checked
}

function Set-VisibleSelection {
    param([bool]$Value)
    foreach ($row in $script:grid.Rows) {
        if (-not $row.IsNewRow) { $row.Cells['Sel'].Value = $Value }
    }
}

function Update-SystemInfoLabel {
    if ($script:lblSystemInfo) { $script:lblSystemInfo.Text = Get-SystemInfoText }
}

function Invoke-ServiceAction {
    param([ValidateSet('Stop','Disable','Enable')][string]$Action)

    if ($script:busy) {
        [void][System.Windows.Forms.MessageBox]::Show('Ya hay una operación en curso. Espera a que termine.', $script:AppName, 'OK', 'Information')
        return
    }
    $rows = @(Get-CheckedRows)
    if ($rows.Count -eq 0) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'Marca al menos un servicio con la casilla de la primera columna.',
            $script:AppName, 'OK', 'Information')
        return
    }
    if (-not (Assert-Admin)) { return }

    $names   = @($rows | ForEach-Object { [string]$_.Cells['Nombre'].Value })
    $blocked = @($names | Where-Object { $script:CriticalServices -contains $_ })
    $allowed = @($names | Where-Object { $script:CriticalServices -notcontains $_ })

    if ($blocked.Count -gt 0) {
        [void][System.Windows.Forms.MessageBox]::Show(
            ("Se ignoran estos servicios críticos del sistema:`n`n{0}`n`nDetenerlos puede dejar Windows inestable o sin arrancar." -f ($blocked -join "`n")),
            $script:AppName, 'OK', 'Warning')
    }
    if ($allowed.Count -eq 0) { return }

    # Stop-Service -Force detiene también los servicios que dependen del marcado.
    # Si alguno de esos es crítico, el servicio marcado no se toca.
    if ($Action -eq 'Stop' -or $Action -eq 'Disable') {
        $porDependencias = @()
        foreach ($name in $allowed) {
            try {
                $dependientes = @((Get-Service -Name $name -ErrorAction Stop).DependentServices |
                    Where-Object { $_.Status -eq 'Running' -and $script:CriticalServices -contains $_.Name } |
                    ForEach-Object { $_.Name })
                if ($dependientes.Count -gt 0) {
                    $porDependencias += ('{0} (lo necesitan: {1})' -f $name, ($dependientes -join ', '))
                }
            } catch { }
        }
        if ($porDependencias.Count -gt 0) {
            $bloqueadosDep = @($porDependencias | ForEach-Object { ($_ -split ' ')[0] })
            $allowed = @($allowed | Where-Object { $bloqueadosDep -notcontains $_ })
            [void][System.Windows.Forms.MessageBox]::Show(
                ("Se ignoran estos servicios porque detenerlos pararía también servicios críticos:`n`n{0}" -f ($porDependencias -join "`n")),
                $script:AppName, 'OK', 'Warning')
            if ($allowed.Count -eq 0) { return }
        }

        # Servicios que Windows necesita aunque no estén en la lista de críticos:
        # se permite, pero con una confirmación aparte y explícita.
        $delicados = @($allowed | Where-Object { $script:KeepServices -contains $_ })
        if ($delicados.Count -gt 0) {
            $avisoKeep = ("Estos servicios están marcados como 'No tocar' (Windows Update, copias de sombra, instalador, etc.):`n`n{0}`n`nDetenerlos o deshabilitarlos puede impedir actualizar Windows, instalar programas o restaurar copias.`n`n¿Seguro que quieres incluirlos?" -f ($delicados -join "`n"))
            if ([System.Windows.Forms.MessageBox]::Show($avisoKeep, "$script:AppName - servicios delicados", 'YesNo', 'Warning', 'Button2') -ne 'Yes') {
                $allowed = @($allowed | Where-Object { $script:KeepServices -notcontains $_ })
                if ($allowed.Count -eq 0) { return }
            }
        }
    }

    $list = $allowed -join "`n"
    switch ($Action) {
        'Stop' {
            $question = "Se van a DETENER estos servicios:`n`n$list`n`nTambién se detendrán sus dependencias. Volverán a iniciarse al reiniciar si su tipo de inicio es Automático.`n`nContinuar?"
            $icon = 'Warning'
        }
        'Disable' {
            $question = "Se van a DETENER y DESHABILITAR de forma PERMANENTE estos servicios:`n`n$list`n`nNo volverán a iniciarse al reiniciar el equipo. Usalo solo si sabes lo que haces.`n`nContinuar?"
            $icon = 'Warning'
        }
        default {
            $question = "Se van a REACTIVAR estos servicios (tipo de inicio Manual):`n`n$list`n`nPodrás iniciarlos cuando quieras. Continuar?"
            $icon = 'Question'
        }
    }
    if ([System.Windows.Forms.MessageBox]::Show($question, $script:AppName, 'YesNo', $icon) -ne 'Yes') { return }

    $ok = 0
    $fail = @()
    $script:busy = $true
    $script:form.UseWaitCursor = $true
    try {
        foreach ($name in $allowed) {
            $script:statusLabel.Text = "Procesando $name ..."
            [System.Windows.Forms.Application]::DoEvents()
            try {
                $svc = Get-Service -Name $name -ErrorAction Stop
                if ($Action -eq 'Stop' -or $Action -eq 'Disable') {
                    if ($svc.Status -eq 'Running') {
                        Stop-Service -Name $name -Force -ErrorAction Stop
                    }
                    if ($Action -eq 'Disable') {
                        Set-Service -Name $name -StartupType Disabled -ErrorAction Stop
                    }
                } else {
                    Set-Service -Name $name -StartupType Manual -ErrorAction Stop
                }
                $ok++
            } catch {
                $fail += ('{0}: {1}' -f $name, $_.Exception.Message)
            }
        }
    } finally {
        $script:form.UseWaitCursor = $false
        $script:busy = $false
    }

    Update-ServiceGrid
    Apply-ServiceFilter

    $actionText = switch ($Action) {
        'Stop'    { 'detenidos' }
        'Disable' { 'detenidos y deshabilitados' }
        default   { 'reactivados' }
    }
    $summary = "Servicios $actionText correctamente: $ok de $($allowed.Count)."
    if ($fail.Count -gt 0) {
        $summary += "`n`nNo se pudieron procesar:`n" + ($fail -join "`n")
    }
    $script:statusLabel.Text = ($summary -split "`n")[0]
    [void][System.Windows.Forms.MessageBox]::Show($summary, $script:AppName, 'OK', 'Information')
}

function Save-ActivityLog {
    if (-not $script:logBox) { return }
    $dialog = New-Object System.Windows.Forms.SaveFileDialog
    $dialog.Filter   = 'Archivo de texto (*.txt)|*.txt'
    $dialog.FileName = ('WinTaller_{0}.txt' -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
    if ($dialog.ShowDialog() -eq 'OK') {
        try {
            Set-Content -LiteralPath $dialog.FileName -Value $script:logBox.Text -Encoding UTF8
            Write-Log ('Registro guardado en {0}' -f $dialog.FileName) 'OK'
        } catch {
            Write-Log ('No se pudo guardar el registro: {0}' -f $_.Exception.Message) 'ERROR'
        }
    }
}

function New-ActionButton {
    param([string]$Text, $BackColor, $ForeColor)
    if (-not $PSBoundParameters.ContainsKey('BackColor')) {
        $BackColor = [System.Drawing.Color]::FromArgb(245, 245, 245)
    }
    if (-not $PSBoundParameters.ContainsKey('ForeColor')) {
        $ForeColor = [System.Drawing.Color]::FromArgb(30, 30, 30)
    }
    $button = New-Object System.Windows.Forms.Button
    $button.Text      = $Text
    $button.AutoSize  = $true
    $button.MinimumSize = New-Object System.Drawing.Size(0, 30)
    $button.Padding   = New-Object System.Windows.Forms.Padding(10, 0, 10, 0)
    $button.FlatStyle = 'Flat'
    $button.BackColor = $BackColor
    $button.ForeColor = $ForeColor
    $button.FlatAppearance.BorderColor = [System.Drawing.Color]::FromArgb(180, 180, 180)
    $button.Margin    = New-Object System.Windows.Forms.Padding(4, 6, 4, 6)
    return $button
}

# ---------------------------------------------------------------------------
# Tareas de optimización
# ---------------------------------------------------------------------------

$script:tasks = @(
    [pscustomobject]@{
        Name        = 'Crear punto de restauración'
        Description = 'Crea un punto de restauración del sistema antes de tocar nada. Es lo primero que deberías ejecutar. Puede fallar si la protección del sistema está desactivada.'
        Recommended = $true
        Confirm     = $null
        Run         = {
            Write-Log 'Comprobando la protección del sistema y los puntos de restauración...'
            $srKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore'
            $antes = 0
            try {
                $puntosAntes = @(Get-ComputerRestorePoint -ErrorAction SilentlyContinue | Sort-Object SequenceNumber)
                if ($puntosAntes.Count -gt 0) { $antes = [int]$puntosAntes[-1].SequenceNumber }
            } catch { }
            try { Enable-ComputerRestore -Drive "$env:SystemDrive\" -ErrorAction SilentlyContinue } catch { }
            # Se quita temporalmente el límite de un punto cada 24 h y después se
            # deja el valor como estaba (antes se quedaba a 0 para siempre).
            $frecuenciaAnterior = $null
            $frecuenciaCambiada = $false
            try {
                if (Test-Path $srKey) {
                    $frecuenciaAnterior = (Get-ItemProperty -Path $srKey -Name 'SystemRestorePointCreationFrequency' -ErrorAction SilentlyContinue).SystemRestorePointCreationFrequency
                    New-ItemProperty -Path $srKey -Name 'SystemRestorePointCreationFrequency' -Value 0 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
                    $frecuenciaCambiada = $true
                }
                Checkpoint-Computer -Description 'Antes de WinTaller' -RestorePointType 'MODIFY_SETTINGS' -ErrorAction Stop
                Start-Sleep -Seconds 2
                $puntosDespues = @(Get-ComputerRestorePoint -ErrorAction SilentlyContinue | Sort-Object SequenceNumber)
                $nuevo = $false
                if ($puntosDespues.Count -gt 0) {
                    if ([int]$puntosDespues[-1].SequenceNumber -ne $antes) { $nuevo = $true }
                }
                if ($nuevo) {
                    $script:optRestorePointVerified = $true
                    Write-Log ('Punto de restauración creado y verificado: {0}' -f $puntosDespues[-1].Description) 'OK'
                } else {
                    $script:optRestorePointVerified = $false
                    Write-Log 'Windows no ha creado un punto nuevo. No des por hecho que existe una copia de seguridad.' 'WARN'
                    Write-Log 'Abre "Crear un punto de restauración" y comprueba que la protección del sistema está activada en la unidad C:.' 'WARN'
                }
            } catch {
                $script:optRestorePointVerified = $false
                Write-Log ('No se pudo crear el punto de restauración: {0}' -f $_.Exception.Message) 'WARN'
                Write-Log 'Puede que la protección del sistema este desactivada o que ya se creará un punto en las últimas 24 horas.' 'WARN'
            } finally {
                if ($frecuenciaCambiada) {
                    try {
                        if ($null -eq $frecuenciaAnterior) {
                            Remove-ItemProperty -Path $srKey -Name 'SystemRestorePointCreationFrequency' -ErrorAction SilentlyContinue
                        } else {
                            Set-ItemProperty -Path $srKey -Name 'SystemRestorePointCreationFrequency' -Value ([int]$frecuenciaAnterior) -ErrorAction SilentlyContinue
                        }
                    } catch { }
                }
            }
        }
    },
    [pscustomobject]@{
        Name        = 'Limpiar archivos temporales'
        Description = 'Elimina el contenido de las carpetas TEMP del usuario y de Windows. Libera espacio y no afecta a programas instalados; algunos archivos en uso no se podrán borrar.'
        Recommended = $true
        Confirm     = $null
        Run         = {
            $targets = @($env:TEMP, (Join-Path $env:SystemRoot 'Temp'))
            $total = 0
            foreach ($path in ($targets | Select-Object -Unique)) {
                if (-not (Test-Path -LiteralPath $path)) { continue }
                $count = 0
                Get-ChildItem -LiteralPath $path -Force -ErrorAction SilentlyContinue | ForEach-Object {
                    try {
                        Remove-FileSystemInfoSafe -Info $_
                        $count++
                    } catch { }
                }
                $total += $count
                Write-Log ('{0}: {1} elemento(s) eliminado(s).' -f $path, $count)
            }
            Write-Log ('Archivos temporales eliminados: {0}' -f $total) 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Vaciar la papelera de reciclaje'
        Description = 'Elimina definitivamente todo el contenido de la papelera de reciclaje del sistema.'
        Recommended = $true
        Confirm     = $null
        Run         = {
            try {
                Clear-RecycleBin -Force -ErrorAction Stop
                Write-Log 'Papelera de reciclaje vaciada.' 'OK'
            } catch {
                Write-Log ('No se pudo vaciar la papelera (puede que ya estuviera vacia): {0}' -f $_.Exception.Message) 'WARN'
            }
        }
    },
    [pscustomobject]@{
        Name        = 'Limpiar cache DNS'
        Description = 'Vacia la cache DNS y vuelve a registrar los nombres del equipo. Útil si hay problemas para resolver dominios o navegar.'
        Recommended = $true
        Confirm     = $null
        Run         = {
            & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 | Out-Null
            & "$env:SystemRoot\System32\ipconfig.exe" /registerdns 2>&1 | Out-Null
            Write-Log 'Cache DNS vaciada y nombres DNS registrados de nuevo.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Desactivar telemetría de Windows'
        Description = 'Detiene y deshabilita DiagTrack y dmwappushservice, y desactiva las tareas programadas de telemetría y experiencia del cliente. Recomendado en equipos personales.'
        Recommended = $true
        Confirm     = $null
        Run         = {
            foreach ($name in @('DiagTrack','dmwappushservice')) {
                $svc = Get-Service -Name $name -ErrorAction SilentlyContinue
                if (-not $svc) { Write-Log "El servicio $name no existe en este equipo."; continue }
                try {
                    if ($svc.Status -eq 'Running') { Stop-Service -Name $name -Force -ErrorAction Stop }
                    Set-Service -Name $name -StartupType Disabled -ErrorAction Stop
                    Write-Log "$name detenido y deshabilitado." 'OK'
                } catch {
                    Write-Log ('No se pudo deshabilitar {0}: {1}' -f $name, $_.Exception.Message) 'WARN'
                }
            }
            $folders = @(
                '\Microsoft\Windows\Application Experience\',
                '\Microsoft\Windows\Customer Experience Improvement Program\',
                '\Microsoft\Windows\Feedback\Siuf\'
            )
            $disabled = 0
            foreach ($folder in $folders) {
                try {
                    $found = @(Get-ScheduledTask -TaskPath $folder -ErrorAction Stop)
                    foreach ($task in $found) {
                        try {
                            Disable-ScheduledTask -TaskName $task.TaskName -TaskPath $task.TaskPath -ErrorAction Stop | Out-Null
                            $disabled++
                        } catch { }
                    }
                } catch { }
            }
            Write-Log ('Tareas programadas de telemetría deshabilitadas: {0}' -f $disabled) 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Deshabilitar servicios innecesarios'
        Description = 'Muestra la lista exacta de servicios prescindibles que existen en este equipo (Xbox, Fax, RemoteRegistry, MapsBroker, WMPNetworkSvc...) y pide confirmación antes de deshabilitarlos. No toca servicios críticos.'
        Recommended = $false
        Confirm     = $null
        Run         = {
            $optional = @('MapsBroker','RetailDemo','RemoteRegistry','Fax','XblAuthManager','XblGameSave','XboxGipSvc','XboxNetApiSvc','WMPNetworkSvc','Wisvc','PhoneSvc')
            $existentes = @()
            foreach ($name in $optional) {
                $svc = Get-Service -Name $name -ErrorAction SilentlyContinue
                if ($svc) {
                    $existentes += [pscustomobject]@{
                        Name    = $name
                        Display = [string]$svc.DisplayName
                        Status  = [string]$svc.Status
                    }
                }
            }
            if ($existentes.Count -eq 0) {
                Write-Log 'No existe ninguno de los servicios opcionales en este equipo. No hay nada que cambiar.' 'OK'
                $script:optTaskSkipped = $true
                return
            }
            $detalle = ($existentes | ForEach-Object { ' - {0} ({1}) [{2}]' -f $_.Display, $_.Name, $_.Status }) -join [Environment]::NewLine
            $pregunta = "Se van a DETENER y DESHABILITAR estos servicios:`n`n{0}`n`nSi usas impresora, Xbox, Bluetooth o escritorio remoto, revisa que ninguno te haga falta.`n`nQuieres continuar?" -f $detalle
            if ([System.Windows.Forms.MessageBox]::Show($pregunta, "$script:AppName - servicios opcionales", 'YesNo', 'Warning') -ne 'Yes') {
                Write-Log 'Tarea omitida por el usuario: no se ha deshabilitado ningún servicio.' 'WARN'
                $script:optTaskSkipped = $true
                return
            }
            $done = 0
            foreach ($item in $existentes) {
                $name = $item.Name
                try {
                    $svc = Get-Service -Name $name -ErrorAction Stop
                    if ($svc.Status -eq 'Running') { Stop-Service -Name $name -Force -ErrorAction Stop }
                    Set-Service -Name $name -StartupType Disabled -ErrorAction Stop
                    $done++
                    Write-Log ('{0} ({1}) deshabilitado.' -f $item.Display, $name) 'OK'
                } catch {
                    Write-Log ('No se pudo deshabilitar {0}: {1}' -f $name, $_.Exception.Message) 'WARN'
                }
            }
            Write-Log ('Servicios innecesarios deshabilitados: {0} de {1}' -f $done, $existentes.Count) 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Deshabilitar el indice de búsqueda (WSearch)'
        Description = 'Detiene y deshabilita Windows Search. Reduce el uso de disco en segundo plano, pero la búsqueda del menú Inicio, del Explorador y de Outlook deja de encontrar resultados al instante. Si usas Outlook o buscas archivos a menudo, no la marques.'
        Recommended = $false
        Confirm     = 'Se deshabilitará WSearch. La búsqueda del menú Inicio, del Explorador y de Outlook dejara de funcionar al instante. Continuar?'
        Run         = {
            $svc = Get-Service -Name 'WSearch' -ErrorAction SilentlyContinue
            if (-not $svc) { Write-Log 'El servicio WSearch no existe en este equipo.'; return }
            try {
                if ($svc.Status -eq 'Running') { Stop-Service -Name 'WSearch' -Force -ErrorAction Stop }
                Set-Service -Name 'WSearch' -StartupType Disabled -ErrorAction Stop
                Write-Log 'WSearch detenido y deshabilitado.' 'OK'
            } catch {
                Write-Log ('No se pudo deshabilitar WSearch: {0}' -f $_.Exception.Message) 'WARN'
            }
        }
    },
    [pscustomobject]@{
        Name        = 'Optimizar el disco del sistema (TRIM/desfragmentar)'
        Description = 'Ejecuta Optimize-Volume en la unidad del sistema. En SSD aplica TRIM y en discos mecanicos desfragmenta. Puede tardar varios minutos.'
        Recommended = $true
        Confirm     = $null
        Run         = {
            $letter = $env:SystemDrive.TrimEnd(':')
            Write-Log ("Optimizando la unidad {0} con Optimize-Volume..." -f $letter)
            $comandoOptimizar = "Optimize-Volume -DriveLetter '{0}' -ErrorAction Stop" -f $letter
            $codigo = Invoke-OptCancelableProcess -File (Join-Path $PSHOME 'powershell.exe') -Arguments @('-NoProfile','-ExecutionPolicy','Bypass','-Command',$comandoOptimizar) -Label 'Optimize-Volume'
            if ($script:optCancel) {
                Write-Log 'Optimización del disco cancelada por el usuario.' 'WARN'
                return
            }
            if ($codigo -eq 0) {
                Write-Log 'Optimización del disco completada.' 'OK'
            } else {
                Write-Log ('No se pudo optimizar el disco (código {0}).' -f $codigo) 'WARN'
            }
        }
    },
    [pscustomobject]@{
        Name        = 'Reparar archivos del sistema (DISM + SFC)'
        Description = 'Primero ejecuta DISM /Online /Cleanup-Image /RestoreHealth (repara la imagen de Windows) y despues sfc /scannow (repara los archivos del sistema). Ese es el orden correcto. Es la tarea mas lenta: puede tardar entre 15 y 40 minutos.'
        Recommended = $false
        Confirm     = 'La reparación con DISM y SFC puede tardar entre 15 y 40 minutos. Se puede cancelar con el botón Cancelar, pero es mejor dejarla terminar. Continuar?'
        Run         = {
            Write-Log 'Paso 1 de 2: DISM /Online /Cleanup-Image /RestoreHealth (puede tardar bastante)...'
            $dismPath = Join-Path $env:SystemRoot 'System32\Dism.exe'
            $codigoDism = Invoke-OptCancelableProcess -File $dismPath -Arguments @('/Online','/Cleanup-Image','/RestoreHealth') -Label 'DISM'
            if ($script:optCancel) {
                Write-Log 'DISM cancelado por el usuario. No se ejecutara SFC.' 'WARN'
                return
            }
            if ($codigoDism -eq 0 -or $codigoDism -eq 3010) {
                Write-Log ('DISM terminó correctamente (código {0}).' -f $codigoDism) 'OK'
            } else {
                Write-Log ('DISM terminó con código {0}. Se intentará SFC de todos modos.' -f $codigoDism) 'WARN'
            }

            if ($script:optCancel) { return }
            Write-Log 'Paso 2 de 2: SFC /scannow (puede tardar bastante)...'
            $sfcPath = Join-Path $env:SystemRoot 'System32\sfc.exe'
            $codigoSfc = Invoke-OptCancelableProcess -File $sfcPath -Arguments @('/scannow') -Label 'SFC'
            if ($script:optCancel) {
                Write-Log 'SFC cancelado por el usuario.' 'WARN'
                return
            }
            if ($codigoSfc -eq 0) {
                Write-Log ('SFC terminó correctamente (código {0}).' -f $codigoSfc) 'OK'
            } else {
                Write-Log ('SFC terminó con código {0}. Revisa el registro de CBS si el problema continúa.' -f $codigoSfc) 'WARN'
            }
        }
    },
    [pscustomobject]@{
        Name        = 'Limpiar componentes de Windows (WinSxS)'
        Description = 'Ejecuta DISM /Online /Cleanup-Image /StartComponentCleanup. Compacta la carpeta WinSxS y elimina versiones antiguas de componentes. Libera espacio sin tocar tus programas. Puede tardar entre 5 y 20 minutos.'
        Recommended = $false
        Confirm     = 'La limpieza de WinSxS puede tardar entre 5 y 20 minutos. Continuar?'
        Run         = {
            Write-Log 'Limpiando componentes antiguos de Windows (WinSxS)...'
            $dismPath = Join-Path $env:SystemRoot 'System32\Dism.exe'
            $codigo = Invoke-OptCancelableProcess -File $dismPath -Arguments @('/Online','/Cleanup-Image','/StartComponentCleanup') -Label 'WinSxS'
            if ($script:optCancel) {
                Write-Log 'Limpieza de WinSxS cancelada por el usuario.' 'WARN'
                return
            }
            if ($codigo -eq 0 -or $codigo -eq 3010) {
                Write-Log ('Componentes de Windows limpiados (código {0}).' -f $codigo) 'OK'
            } else {
                Write-Log ('DISM terminó con código {0} al limpiar WinSxS.' -f $codigo) 'WARN'
            }
        }
    },
    [pscustomobject]@{
        Name        = 'Vaciar cache de Windows Update'
        Description = 'Detiene temporalmente los servicios de Windows Update y BITS, borra los archivos descargados en SoftwareDistribution\Download y vuelve a iniciarlos. No elimina las actualizaciones ya instaladas.'
        Recommended = $false
        Confirm     = $null
        Run         = {
            $ruta = Join-Path $env:SystemRoot 'SoftwareDistribution\Download'
            $liberado = 0
            try {
                $suma = (Get-ChildItem -LiteralPath $ruta -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
                if ($suma) { $liberado = [math]::Round($suma / 1MB, 1) }
            } catch { }
            foreach ($svc in @('wuauserv','BITS')) {
                try { Stop-Service -Name $svc -Force -ErrorAction SilentlyContinue } catch { }
            }
            Start-Sleep -Seconds 2
            try {
                Get-ChildItem -LiteralPath $ruta -Force -ErrorAction SilentlyContinue | ForEach-Object {
                    try { Remove-FileSystemInfoSafe -Info $_ } catch { }
                }
            } catch { }
            foreach ($svc in @('wuauserv','BITS')) {
                try { Start-Service -Name $svc -ErrorAction SilentlyContinue } catch { }
            }
            Write-Log ('Cache de Windows Update vaciada. Espacio liberado aproximado: {0} MB.' -f $liberado) 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Limpiar cache de Optimización de entrega'
