            if (Get-Command Delete-DeliveryOptimizationCache -ErrorAction SilentlyContinue) {
                try {
                    Delete-DeliveryOptimizationCache -Force -ErrorAction Stop
                    $hecho = $true
                    Write-Log 'Cache de Optimización de entrega eliminada.' 'OK'
                } catch {
                    Write-Log ('No se pudo usar Delete-DeliveryOptimizationCache: {0}' -f $_.Exception.Message) 'WARN'
                }
            }
            if (-not $hecho) {
                try {
                    Stop-Service -Name 'DoSvc' -Force -ErrorAction SilentlyContinue
                    $ruta = Join-Path $env:SystemRoot 'SoftwareDistribution\DeliveryOptimization'
                    if (Test-Path -LiteralPath $ruta) {
                        Get-ChildItem -LiteralPath $ruta -Force -ErrorAction SilentlyContinue | ForEach-Object {
                            try { Remove-FileSystemInfoSafe -Info $_ } catch { }
                        }
                    }
                    Start-Service -Name 'DoSvc' -ErrorAction SilentlyContinue
                    Write-Log 'Cache de Optimización de entrega limpiada manualmente.' 'OK'
                } catch {
                    Write-Log ('No se pudo limpiar la cache de Optimización de entrega: {0}' -f $_.Exception.Message) 'WARN'
                }
            }
