    [pscustomobject]@{
        Name        = 'Eliminar volcados de memoria'
        Description = 'Borra MEMORY.DMP, los minivolcados de C:\Windows\Minidump y los informes de fallos del usuario. Los volcados solo sirven para analizar errores antiguos.'
        Recommended = $true
        Confirm     = $null
        Run         = {
            $total = 0
            $rutas = @(
                (Join-Path $env:SystemRoot 'MEMORY.DMP'),
                (Join-Path $env:SystemRoot 'Minidump'),
                (Join-Path $env:LOCALAPPDATA 'CrashDumps')
            )
            foreach ($ruta in $rutas) {
                if (-not (Test-Path -LiteralPath $ruta)) { continue }
                $suma = 0
                try {
                    $item = Get-Item -LiteralPath $ruta -Force -ErrorAction Stop
                    if ($item.PSIsContainer) {
                        $suma = (Get-ChildItem -LiteralPath $ruta -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
                        Get-ChildItem -LiteralPath $ruta -Force -ErrorAction SilentlyContinue | ForEach-Object {
                            try { Remove-FileSystemInfoSafe -Info $_ } catch { }
                        }
                    } else {
                        $suma = $item.Length
                        Remove-Item -LiteralPath $ruta -Force -ErrorAction Stop
                    }
                } catch { }
                if ($suma) { $total += $suma }
            }
            Write-Log ('Volcados de memoria eliminados: {0} MB.' -f [math]::Round($total / 1MB, 1)) 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Limpiar cache de miniaturas e iconos'
        Description = 'Elimina las miniaturas y los iconos guardados en cache. Windows los vuelve a generar cuando hacen falta. Si el Explorador los tiene bloqueados, se omiten sin dar error.'
        Recommended = $true
        Confirm     = $null
        Run         = {
            $carpeta = Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Explorer'
            $borrados = 0
            foreach ($patron in @('thumbcache_*.db','iconcache_*.db')) {
                Get-ChildItem -LiteralPath $carpeta -Filter $patron -Force -ErrorAction SilentlyContinue | ForEach-Object {
                    try { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction Stop; $borrados++ } catch { }
                }
            }
            try { & ie4uinit.exe -show 2>&1 | Out-Null } catch { }
            Write-Log ('Archivos de cache de miniaturas e iconos eliminados: {0}.' -f $borrados) 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Limpiar cache de navegadores'
        Description = 'Borra las caches de Chrome, Edge y Firefox (no las contraseñas, el historial ni las pestañas). Cierra antes los navegadores para que la limpieza funcione del todo.'
        Recommended = $false
        Confirm     = 'Cierra Chrome, Edge y Firefox antes de continuar. Se borraran solo archivos de cache, no el historial ni las contraseñas. Continuar?'
        Run         = {
            $rutas = @()
            $baseChrome = Join-Path $env:LOCALAPPDATA 'Google\Chrome\User Data'
            $baseEdge   = Join-Path $env:LOCALAPPDATA 'Microsoft\Edge\User Data'
            foreach ($base in @($baseChrome, $baseEdge)) {
                if (-not (Test-Path -LiteralPath $base)) { continue }
                Get-ChildItem -LiteralPath $base -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                    foreach ($sub in @('Cache','Code Cache','GPUCache')) {
                        $ruta = Join-Path $_.FullName $sub
                        if (Test-Path -LiteralPath $ruta) { $rutas += $ruta }
                    }
                }
            }
            $baseFirefox = Join-Path $env:LOCALAPPDATA 'Mozilla\Firefox\Profiles'
            if (Test-Path -LiteralPath $baseFirefox) {
                Get-ChildItem -LiteralPath $baseFirefox -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                    $ruta = Join-Path $_.FullName 'cache2'
                    if (Test-Path -LiteralPath $ruta) { $rutas += $ruta }
                }
            }
            $total = 0
            foreach ($ruta in ($rutas | Select-Object -Unique)) {
                try {
                    $suma = (Get-ChildItem -LiteralPath $ruta -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
                    if ($suma) { $total += $suma }
                    Get-ChildItem -LiteralPath $ruta -Force -ErrorAction SilentlyContinue | ForEach-Object {
                        try { Remove-FileSystemInfoSafe -Info $_ } catch { }
                    }
                } catch { }
            }
            Write-Log ('Cache de navegadores limpiada: {0} MB en {1} carpetas.' -f [math]::Round($total / 1MB, 1), $rutas.Count) 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Quitar Copilot, Recall, widgets y sugerencias'
        Description = 'Desactiva Copilot, Recall, el botón de widgets, las sugerencias y anuncios de Inicio, y la búsqueda web de Bing en el menú Inicio. Son ajustes de privacidad; no borran programas.'
        Recommended = $false
        Confirm     = 'Se cambiaran ajustes de privacidad de Windows 11. Algunos requieren cerrar sesión o reiniciar para aplicarse. Continuar?'
        Run         = {
            $cambios = 0
            try {
                Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'ShowCopilotButton' 0
                Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'TaskbarDa' 0
                Set-RegValue 'HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot' 'TurnOffWindowsCopilot' 1
                Set-RegValue 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI' 'DisableAIDataAnalysis' 1
                Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search' 'BingSearchEnabled' 0
                Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search' 'CortanaConsent' 0
                $cdm = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'
                foreach ($nombre in @('SubscribedContent-338388Enabled','SubscribedContent-338389Enabled','SubscribedContent-338387Enabled','SystemPaneSuggestionsEnabled','SilentInstalledAppsEnabled','PreInstalledAppsEnabled')) {
                    Set-RegValue $cdm $nombre 0
                }
                Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'ShowSyncProviderNotifications' 0
                $cambios = 10
                Write-Log ('Ajustes de privacidad aplicados: {0}.' -f $cambios) 'OK'
                Write-Log 'Cierra sesión o reinicia para que algunos cambios se vean del todo.' 'WARN'
            } catch {
                Write-Log ('No se pudieron aplicar todos los ajustes de privacidad: {0}' -f $_.Exception.Message) 'WARN'
            }
        }
    },
    [pscustomobject]@{
        Name        = 'Restablecer la red (Winsock e IP)'
        Description = 'Ejecuta netsh winsock reset y netsh int ip reset para reparar problemas de conexión. Requiere reiniciar el equipo. Úsalo solo si hay fallos de red; no es una tarea de mantenimiento habitual.'
        Recommended = $false
        Confirm     = 'Se restablecerá la configuración de red y habrá que REINICIAR. Si tienes VPN o reglas de red especiales, se perderan. Continuar?'
        Run         = {
            Write-Log 'Restableciendo Winsock...'
            try { & "$env:SystemRoot\System32\netsh.exe" winsock reset 2>&1 | Out-Null } catch { }
            Write-Log 'Restableciendo la pila IP...'
            try { & "$env:SystemRoot\System32\netsh.exe" int ip reset 2>&1 | Out-Null } catch { }
            try { & "$env:SystemRoot\System32\ipconfig.exe" /flushdns 2>&1 | Out-Null } catch { }
            Write-Log 'Red restablecida. Reinicia el equipo para terminar.' 'OK'
        }
    }
)

function Invoke-OptCancelableProcess {
    param(
        [string]$File,
        [string[]]$Arguments,
        [string]$Label = ''
    )
    $script:optProcess = Start-Process -FilePath $File -ArgumentList $Arguments -PassThru -WindowStyle Hidden
    while ($true) {
        $terminado = $false
        try { $terminado = $script:optProcess.HasExited } catch { $terminado = $true }
        if ($terminado) { break }
        if ($script:optCancel) {
            try { & "$env:SystemRoot\System32\taskkill.exe" /PID $script:optProcess.Id /T /F 2>&1 | Out-Null } catch { }
            Start-Sleep -Milliseconds 600
            break
        }
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 300
    }
    $codigo = -1
    if ($script:optProcess) {
        try { if ($script:optProcess.HasExited) { $codigo = [int]$script:optProcess.ExitCode } } catch { }
        try { $script:optProcess.Dispose() } catch { }
    }
    $script:optProcess = $null
    return $codigo
}

# Los snapshots se guardan en ProgramData\WinTaller\snapshots con permisos
# solo para SYSTEM y Administradores. Antes estaban junto al script (Documentos),
# donde cualquier proceso del usuario podía cambiar los .reg que luego se
# importan con permisos de administrador.
function Get-OptimizationSnapshotDir {
    [void](Get-SecureDataRoot)
    return (Initialize-SecureDirectory -Path (Join-Path $env:ProgramData 'WinTaller\snapshots'))
}

# Claves que se pueden restaurar desde un snapshot (lista blanca).
$script:SnapshotRegistryKeys = @(
    [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'; File = 'HKCU_ExplorerAdvanced.reg' },
    [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'; File = 'HKCU_ContentDeliveryManager.reg' },
    [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search'; File = 'HKCU_Search.reg' },
    [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects'; File = 'HKCU_VisualEffects.reg' },
    [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize'; File = 'HKCU_Personalize.reg' },
    [pscustomobject]@{ Path = 'HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot'; File = 'HKCU_WindowsCopilot.reg' },
    [pscustomobject]@{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI'; File = 'HKLM_WindowsAI.reg' },
    # Claves que cambia la pestaña Rendimiento
    [pscustomobject]@{ Path = 'HKCU:\Control Panel\Desktop'; File = 'HKCU_Desktop.reg' },
    [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\GameBar'; File = 'HKCU_GameBar.reg' },
    [pscustomobject]@{ Path = 'HKCU:\System\GameConfigStore'; File = 'HKCU_GameConfigStore.reg' },
    [pscustomobject]@{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications'; File = 'HKCU_BackgroundAccess.reg' },
    [pscustomobject]@{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR'; File = 'HKLM_GameDVR.reg' },
    [pscustomobject]@{ Path = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power'; File = 'HKLM_SessionPower.reg' }
)

function ConvertTo-RegExportPath {
    param([string]$Path)
    return ($Path -replace '^HKCU:', 'HKEY_CURRENT_USER' -replace '^HKLM:', 'HKEY_LOCAL_MACHINE')
}

# Comprueba que un .reg del snapshot está en su carpeta, tiene un nombre de la
# lista blanca y solo contiene claves de la clave permitida para ese archivo.
function Test-SnapshotRegFile {
    param([string]$File, [string]$SnapshotDir)
    try {
        $completo = [System.IO.Path]::GetFullPath($File)
        $sep = [System.IO.Path]::DirectorySeparatorChar
        $base = [System.IO.Path]::GetFullPath($SnapshotDir).TrimEnd($sep) + $sep
        if (-not $completo.StartsWith($base, [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
        $nombre = [System.IO.Path]::GetFileName($completo)
        $entrada = $script:SnapshotRegistryKeys | Where-Object { $_.File -eq $nombre } | Select-Object -First 1
        if (-not $entrada) { return $false }
        $raiz = (ConvertTo-RegExportPath $entrada.Path).ToUpperInvariant()
        foreach ($linea in [System.IO.File]::ReadAllLines($completo)) {
            $t = $linea.Trim()
            if ($t -match '^\[-?(.+)\]$') {
                $clave = $Matches[1].ToUpperInvariant()
                if ($clave -ne $raiz -and -not $clave.StartsWith($raiz + '\')) { return $false }
            }
        }
        return $true
    } catch {
        return $false
    }
}

function Save-OptimizationSnapshot {
    try {
        $dir = Get-OptimizationSnapshotDir
        if (-not $dir) { return }
        $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
        $json = Join-Path $dir ('snapshot_{0}.json' -f $stamp)
        $regDir = Join-Path $dir ('registro_{0}' -f $stamp)
        New-Item -ItemType Directory -Path $regDir -Force -ErrorAction SilentlyContinue | Out-Null

        $archivosReg = @()
        foreach ($clave in $script:SnapshotRegistryKeys) {
            if (-not (Test-Path -LiteralPath $clave.Path)) { continue }
            $destino = Join-Path $regDir $clave.File
            $rutaReg = ConvertTo-RegExportPath $clave.Path
            try {
                & "$env:SystemRoot\System32\reg.exe" export $rutaReg $destino /y 2>&1 | Out-Null
                if (Test-Path -LiteralPath $destino) { $archivosReg += $destino }
            } catch { }
        }

        $servicios = @()
        try {
            $servicios = @(Get-CimInstance -ClassName Win32_Service -ErrorAction Stop |
                Select-Object Name, StartMode, State, DelayedAutoStart)
        } catch { }

        $tareas = @()
        try {
            $tareas = @(Get-ScheduledTask -ErrorAction SilentlyContinue | Select-Object TaskPath, TaskName, State)
        } catch { }

        $esquema = ''
        try {
            $salida = (& "$env:SystemRoot\System32\powercfg.exe" /getactivescheme 2>&1 | Out-String)
            $m = [regex]::Match($salida, '\{[0-9a-fA-F-]{36}\}')
            if ($m.Success) { $esquema = $m.Value }
        } catch { }

        $datos = [pscustomobject]@{
            Created     = (Get-Date).ToString('s')
            Computer    = $env:COMPUTERNAME
            FreeGB      = Get-FreeSpaceGB
            PowerScheme = $esquema
            Services    = $servicios
            Tasks       = $tareas
            Registry    = $archivosReg
        }
        $datos | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $json -Encoding UTF8
        $script:optSnapshotFile = $json
        Write-Log ('Copia de ajustes guardada antes de optimizar: {0}' -f $json) 'OK'
        Write-Log ('Servicios guardados: {0} | tareas programadas: {1} | claves de registro: {2}' -f $servicios.Count, $tareas.Count, $archivosReg.Count)
    } catch {
        Write-Log ('No se pudo guardar la copia de ajustes: {0}' -f $_.Exception.Message) 'WARN'
    }
}

function Revert-Optimization {
    if ($script:busy) {
        [void][System.Windows.Forms.MessageBox]::Show('Ya hay una operación en curso. Espera a que termine.', $script:AppName, 'OK', 'Information')
        return
    }
    if (-not (Assert-Admin)) { return }

    $dir = Get-OptimizationSnapshotDir
    $archivos = @()
    try { $archivos = @(Get-ChildItem -LiteralPath $dir -Filter 'snapshot_*.json' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending) } catch { }
    if ($archivos.Count -eq 0) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'No hay ninguna copia de ajustes guardada. La herramienta la crea automáticamente cuando ejecutas una optimización.',
            "$script:AppName - revertir", 'OK', 'Information')
        return
    }

    $ultimo = $archivos[0]
    $confirmar = [System.Windows.Forms.MessageBox]::Show(
        ("Se van a restaurar los servicios, las tareas programadas, el plan de energía y las claves de registro guardadas el {0}.`n`nEsta acción deshace los cambios de la última optimización, pero no reinstala programas ni borra archivos.`n`nQuieres continuar?" -f $ultimo.LastWriteTime.ToString('dd/MM/yyyy HH:mm')),
        "$script:AppName - revertir cambios", 'YesNo', 'Warning')
    if ($confirmar -ne 'Yes') { return }

    $script:busy = $true
    $script:btnRun.Enabled = $false
    $script:btnRevert.Enabled = $false
    $script:form.UseWaitCursor = $true
    $script:statusLabel.Text = 'Revirtiendo cambios...'
    [System.Windows.Forms.Application]::DoEvents()

    $cambios = 0
    $errores = 0
    try {
        $datos = Get-Content -LiteralPath $ultimo.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
        Write-Log ('=== Revirtiendo cambios desde {0} ===' -f $ultimo.Name) 'STEP'

        # Solo se tocan los servicios cuyo tipo de inicio ha cambiado desde el
        # snapshot. Se conserva el "Automático (inicio retrasado)" con sc.exe.
        $actuales = @{}
        try {
            foreach ($s in @(Get-CimInstance -ClassName Win32_Service -ErrorAction Stop)) { $actuales[[string]$s.Name] = $s }
        } catch { }
        foreach ($servicio in @($datos.Services)) {
            if (-not $servicio -or -not $servicio.Name) { continue }
            $nombreSvc = [string]$servicio.Name
            $modo = [string]$servicio.StartMode
            if ($modo -notin @('Auto', 'Manual', 'Disabled')) { continue }   # Boot/System: no se tocan
            $actual = $actuales[$nombreSvc]
            if (-not $actual) { continue }
            $retrasadoAntes = [bool]$servicio.DelayedAutoStart
            $retrasadoAhora = [bool]$actual.DelayedAutoStart
            if ([string]$actual.StartMode -eq $modo -and ($modo -ne 'Auto' -or $retrasadoAntes -eq $retrasadoAhora)) { continue }
            try {
                $valorSc = switch ($modo) {
                    'Auto'     { if ($retrasadoAntes) { 'delayed-auto' } else { 'auto' } }
                    'Manual'   { 'demand' }
                    'Disabled' { 'disabled' }
                }
                $salidaSc = & "$env:SystemRoot\System32\sc.exe" config $nombreSvc start= $valorSc 2>&1 | Out-String
                if ($LASTEXITCODE -ne 0) { throw $salidaSc.Trim() }
                if ([string]$servicio.State -eq 'Running' -and [string]$actual.State -ne 'Running' -and $modo -ne 'Disabled') {
                    Start-Service -Name $nombreSvc -ErrorAction SilentlyContinue
                }
                Write-Log ('Servicio {0}: tipo de inicio restaurado a {1}.' -f $nombreSvc, $valorSc)
                $cambios++
            } catch {
                Write-Log ('No se pudo restaurar el servicio {0}: {1}' -f $nombreSvc, $_.Exception.Message) 'WARN'
                $errores++
            }
        }
        Write-Log ('Servicios restaurados: {0}' -f $cambios) 'OK'

        $tareasOk = 0
        $estadoTareas = @{}
        try {
            foreach ($t in @(Get-ScheduledTask -ErrorAction SilentlyContinue)) {
                $estadoTareas[([string]$t.TaskPath + [string]$t.TaskName)] = ([string]$t.State -eq 'Disabled')
            }
        } catch { }
        foreach ($tarea in @($datos.Tasks)) {
            if (-not $tarea -or -not $tarea.TaskName) { continue }
            $claveTarea = [string]$tarea.TaskPath + [string]$tarea.TaskName
            if (-not $estadoTareas.ContainsKey($claveTarea)) { continue }
            # El State se guarda como número (enum) o texto según la versión: 1 = Disabled.
            $deshabilitadaAntes = ([string]$tarea.State -eq 'Disabled' -or [string]$tarea.State -eq '1')
            if ($estadoTareas[$claveTarea] -eq $deshabilitadaAntes) { continue }
            try {
                if ($deshabilitadaAntes) {
                    Disable-ScheduledTask -TaskName ([string]$tarea.TaskName) -TaskPath ([string]$tarea.TaskPath) -ErrorAction SilentlyContinue | Out-Null
                } else {
                    Enable-ScheduledTask -TaskName ([string]$tarea.TaskName) -TaskPath ([string]$tarea.TaskPath) -ErrorAction SilentlyContinue | Out-Null
                }
                $tareasOk++
            } catch { }
        }
        Write-Log ('Tareas programadas revisadas: {0}' -f $tareasOk) 'OK'

        $regOk = 0
        $carpetaSnapshots = Get-OptimizationSnapshotDir
        foreach ($archivo in @($datos.Registry)) {
            if (-not $archivo -or -not (Test-Path -LiteralPath $archivo)) { continue }
            if (-not (Test-SnapshotRegFile -File ([string]$archivo) -SnapshotDir $carpetaSnapshots)) {
                Write-Log ('Se ignora un archivo de registro no válido o fuera de la lista permitida: {0}' -f $archivo) 'WARN'
                $errores++
                continue
            }
            try {
                & "$env:SystemRoot\System32\reg.exe" import $archivo 2>&1 | Out-Null
                $regOk++
            } catch { $errores++ }
        }
        Write-Log ('Claves de registro restauradas: {0}' -f $regOk) 'OK'

        if ($datos.PowerScheme) {
            try {
                & "$env:SystemRoot\System32\powercfg.exe" /setactive ([string]$datos.PowerScheme) 2>&1 | Out-Null
                Write-Log ('Plan de energía restaurado: {0}' -f $datos.PowerScheme) 'OK'
            } catch { $errores++ }
        }

        Write-Log ('=== Reversión terminada: {0} cambios, {1} errores ===' -f $cambios, $errores) 'STEP'
        [void][System.Windows.Forms.MessageBox]::Show(
            ("Cambios revertidos.`n`nServicios revisados: {0}`nErrores: {1}`n`nReinicia el equipo para aplicar algunos ajustes." -f $cambios, $errores),
            "$script:AppName - revertir", 'OK', 'Information')
    } catch {
        Write-Log ('No se pudo revertir: {0}' -f $_.Exception.Message) 'ERROR'
        [void][System.Windows.Forms.MessageBox]::Show(
            ('No se pudo revertir la optimización: {0}' -f $_.Exception.Message), "$script:AppName - error", 'OK', 'Error')
    } finally {
        $script:busy = $false
        $script:btnRun.Enabled = $true
        $script:btnRevert.Enabled = $true
        $script:form.UseWaitCursor = $false
        $script:statusLabel.Text = 'Listo'
    }
}

function Invoke-Optimization {
    if ($script:busy) {
        [void][System.Windows.Forms.MessageBox]::Show('Ya hay una operación en curso. Espera a que termine.', $script:AppName, 'OK', 'Information')
        return
    }
    $selected = @()
    for ($i = 0; $i -lt $script:taskList.Items.Count; $i++) {
        if ($script:taskList.GetItemChecked($i)) { $selected += $script:tasks[$i] }
    }
    if ($selected.Count -eq 0) {
        [void][System.Windows.Forms.MessageBox]::Show('Marca al menos una tarea de la lista.', $script:AppName, 'OK', 'Information')
        return
    }
    if (-not (Assert-Admin)) { return }

    $names = ($selected | ForEach-Object { ' - ' + $_.Name }) -join "`n"
    $question = "Se van a ejecutar estas tareas:`n`n$names`n`nAlgunas pueden tardar varios minutos. Continuar?"
    if ([System.Windows.Forms.MessageBox]::Show($question, $script:AppName, 'YesNo', 'Question') -ne 'Yes') { return }

    $tieneRestauracion = @($selected | Where-Object { $_.Name -eq 'Crear punto de restauración' }).Count -gt 0
    $riesgosas = @($selected | Where-Object { $_.Name -match 'Deshabilitar|WSearch|Reparar|WinSxS|Restablecer la red' })
    if (-not $tieneRestauracion -and $riesgosas.Count -gt 0) {
        $aviso = "No has marcado la tarea 'Crear punto de restauración'.`n`nSi algo sale mal, no habrá un punto al que volver. Puedes usar el botón 'Revertir cambios' para restaurar los ajustes guardados, pero no sustituye a un punto de restauración.`n`nQuieres continuar igualmente?"
        if ([System.Windows.Forms.MessageBox]::Show($aviso, "$script:AppName - sin punto de restauración", 'YesNo', 'Warning') -ne 'Yes') { return }
    }

    $script:optCancel = $false
    $script:optRestorePointVerified = $false
    $script:optTaskSkipped = $false
    $script:btnRun.Enabled = $false
    $script:btnOptCancel.Enabled = $true
    $script:btnRevert.Enabled = $false
    $script:busy = $true
    $script:form.UseWaitCursor = $true
    $freeBefore = Get-FreeSpaceGB
    $started    = Get-Date
    $executed   = 0
    $skipped    = 0
    $indice     = 0
    $script:optProgress.Maximum = [math]::Max(1, $selected.Count)
    $script:optProgress.Value = 0
    try {
        Write-Log ('Espacio libre antes de optimizar: {0} GB' -f $freeBefore)
        Save-OptimizationSnapshot
        foreach ($task in $selected) {
            if ($script:optCancel) {
                Write-Log 'Optimización cancelada por el usuario.' 'WARN'
                break
            }
            if ($task.Confirm) {
                if ([System.Windows.Forms.MessageBox]::Show($task.Confirm, $script:AppName, 'YesNo', 'Warning') -ne 'Yes') {
                    Write-Log ('Tarea omitida por el usuario: {0}' -f $task.Name) 'WARN'
                    $skipped++
                    $indice++
                    try { $script:optProgress.Value = [math]::Min($indice, $script:optProgress.Maximum) } catch { }
                    continue
                }
            }
            Write-Log ('=== {0} ===' -f $task.Name) 'STEP'
            $script:statusLabel.Text = ('Ejecutando: {0}' -f $task.Name)
            $script:optTaskSkipped = $false
            try {
                & $task.Run
                if ($script:optTaskSkipped) { $skipped++ } else { $executed++ }
            } catch {
                Write-Log ('Error en "{0}": {1}' -f $task.Name, $_.Exception.Message) 'ERROR'
                $skipped++
            }
            if ($task.Name -eq 'Crear punto de restauración' -and -not $script:optRestorePointVerified) {
                $respuesta = [System.Windows.Forms.MessageBox]::Show(
                    "No se ha podido verificar que exista un punto de restauración nuevo.`n`nSi continuas, los cambios no tendrán una copia de seguridad del sistema.`n`nQuieres continuar con las demás tareas?",
                    "$script:AppName - punto de restauración", 'YesNo', 'Warning')
                if ($respuesta -ne 'Yes') {
                    $script:optCancel = $true
                    Write-Log 'Optimización detenida: no hay punto de restauración verificado.' 'WARN'
                    break
                }
            }
            $indice++
            try { $script:optProgress.Value = [math]::Min($indice, $script:optProgress.Maximum) } catch { }
            [System.Windows.Forms.Application]::DoEvents()
        }
    } finally {
        $script:form.UseWaitCursor = $false
        $script:btnRun.Enabled = $true
        $script:btnOptCancel.Enabled = $false
        $script:btnRevert.Enabled = $true
        $script:optProcess = $null
        $script:busy = $false
    }

    $cancelado = $script:optCancel
    $freeAfter = Get-FreeSpaceGB
    $elapsed   = (Get-Date) - $started
    Write-Log ('Tareas ejecutadas: {0}  |  omitidas: {1}  |  tiempo: {2:mm\:ss}' -f $executed, $skipped, $elapsed) 'OK'
    if ($null -ne $freeBefore -and $null -ne $freeAfter) {
        $diff = [math]::Round($freeAfter - $freeBefore, 2)
        Write-Log ('Espacio libre después: {0} GB (diferencia: {1} GB)' -f $freeAfter, $diff) 'OK'
    }

    Update-SystemInfoLabel
    Update-ServiceGrid
    if ($cancelado) {
        $script:statusLabel.Text = 'Optimización cancelada'
        [void][System.Windows.Forms.MessageBox]::Show(
            ("Optimización cancelada.`n`nTareas ejecutadas: {0}`nTareas omitidas: {1}`nTiempo: {2:mm\:ss}`n`nPuedes usar 'Revertir cambios' para restaurar los ajustes guardados." -f $executed, $skipped, $elapsed),
            $script:AppName, 'OK', 'Warning')
    } else {
        $script:statusLabel.Text = 'Optimización finalizada'
        [void][System.Windows.Forms.MessageBox]::Show(
            ("Optimización finalizada.`n`nTareas ejecutadas: {0}`nTareas omitidas: {1}`nTiempo: {2:mm\:ss}`n`nRevisa el registro para ver el detalle." -f $executed, $skipped, $elapsed),
            $script:AppName, 'OK', 'Information')
    }
}

# ---------------------------------------------------------------------------
# Autocomprobacion sin interfaz
# ---------------------------------------------------------------------------

if ($SelfTest) {
    $snap = @(Get-ServiceSnapshot)
    Write-Host ("Servicios encontrados: {0}" -f $snap.Count)
    Write-Host ("En ejecución: {0}" -f @($snap | Where-Object { $_.State -eq 'En ejecución' }).Count)
    Write-Host ("Críticos: {0}" -f @($snap | Where-Object { $script:CriticalServices -contains $_.Name }).Count)
    Write-Host ("Tareas de optimización definidas: {0}" -f $script:tasks.Count)
    $adviceList = @($snap | ForEach-Object { (Get-ServiceAdvice $_).Consejo })
    Write-Host ("Consejo - se puede quitar: {0} | opcional: {1} | no tocar: {2}" -f `
        @($adviceList | Where-Object { $_ -eq 'Quitar' }).Count, `
        @($adviceList | Where-Object { $_ -eq 'Opcional' }).Count, `
        @($adviceList | Where-Object { $_ -eq 'No tocar' }).Count)
    $ejemplo = $snap | Where-Object { $_.Name -eq 'DiagTrack' } | Select-Object -First 1
    if ($ejemplo) {
        $adv = Get-ServiceAdvice $ejemplo
        $info = New-ServiceInfoText -Name $ejemplo.Name -DisplayName $ejemplo.DisplayName `
            -State $ejemplo.State -StartMode $ejemplo.StartMode -ProcessId $ejemplo.ProcessId `
            -Risk (Get-ServiceRisk $ejemplo.Name) -Description $ejemplo.Description -Advice $adv
        Write-Host ''
        Write-Host '--- Ejemplo de ficha (DiagTrack) ---'
        ($info -split "`r`n" | Select-Object -First 18) | ForEach-Object { Write-Host $_ }
        Write-Host ('--- Fin del ejemplo ({0} caracteres, consejo: {1}) ---' -f $info.Length, $adv.Consejo)
    }
    $snap | Select-Object -First 5 Name, DisplayName, State, StartMode, ProcessId | Format-Table -AutoSize | Out-String | Write-Host

    Write-Host ''
    Write-Host '--- Copias de seguridad ---'
    $robo = Get-Command (Join-Path $env:SystemRoot 'System32\robocopy.exe') -ErrorAction SilentlyContinue
    $wb   = Get-Command (Join-Path $env:SystemRoot 'System32\wbadmin.exe') -ErrorAction SilentlyContinue
    if ($robo) { Write-Host ('robocopy: {0}' -f $robo.Source) } else { Write-Host 'robocopy: NO disponible' }
    if ($wb) { Write-Host ('wbadmin: {0}' -f $wb.Source) } else { Write-Host 'wbadmin: NO disponible' }
    $conocidas = @(
        [Environment]::GetFolderPath('MyDocuments'),
        [Environment]::GetFolderPath('Desktop'),
        [Environment]::GetFolderPath('MyPictures'),
        [Environment]::GetFolderPath('MyMusic'),
        [Environment]::GetFolderPath('MyVideos'),
        (Join-Path $env:USERPROFILE 'Downloads'),
        [Environment]::GetFolderPath('Favorites')
    )
    $existentes = @($conocidas | Where-Object { $_ -and (Test-Path -LiteralPath $_) })
    Write-Host ('Carpetas habituales existentes: {0} de {1}' -f $existentes.Count, $conocidas.Count)
    $otrasUnidades = @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction SilentlyContinue | Where-Object { $_.DeviceID -ne $env:SystemDrive })
    Write-Host ('Unidades para la imagen distintas de {0}: {1}' -f $env:SystemDrive, $otrasUnidades.Count)
    Write-Host ('Espacio libre en {0}: {1} GB' -f $env:SystemDrive, (Get-FreeSpaceGB))
    exit 0
}

# ---------------------------------------------------------------------------
# Arranque
# ---------------------------------------------------------------------------

$script:IsAdmin = Test-IsAdmin
Write-Diag ('Permisos comprobados. Administrador: {0}' -f $script:IsAdmin)
if (-not $script:IsAdmin -and -not $SelfTest -and -not $UiSmokeTest) {
    $answer = [System.Windows.Forms.MessageBox]::Show(
        "Este programa puede mostrar los servicios sin permisos especiales, pero para detenerlos, deshabilitarlos u optimizar el equipo necesita permisos de administrador.`n`nQuieres reiniciarlo como administrador?",
        "$script:AppName - permisos", 'YesNo', 'Question')
    if ($answer -eq 'Yes' -and (Restart-Elevated)) { exit 0 }
}

# Una sola instancia: dos ventanas a la vez podrían pisarse las colas de
# instalación, drivers o copias.
$script:instanceMutex = $null
if (-not $SelfTest -and -not $UiSmokeTest) {
    $creado = $false
    try {
        $script:instanceMutex = New-Object System.Threading.Mutex($true, 'Local\WinTaller_SylredComputers', [ref]$creado)
    } catch { $creado = $true }
    if (-not $creado) {
        Write-Diag 'Ya hay otra ventana abierta. Saliendo.'
        [void][System.Windows.Forms.MessageBox]::Show(
            'El programa ya está abierto. Usa la ventana que tienes abierta.',
            $script:AppName, 'OK', 'Information')
        exit 0
    }
}

# Elevación con la cuenta de otro administrador: los ajustes de usuario
# (Rendimiento, Privacidad, Inicio del usuario) irían a esa otra cuenta.
$script:SessionUser = $null
if ($script:IsAdmin -and -not $SelfTest) {
    $script:SessionUser = Get-SessionUserInfo
    Write-Diag ('Usuario del programa: {0} | usuario de la sesión: {1}' -f $script:SessionUser.Process, $script:SessionUser.Session)
    if ($script:SessionUser.Mismatch -and -not $UiSmokeTest) {
        [void][System.Windows.Forms.MessageBox]::Show(
            ("WinTaller se está ejecutando con la cuenta de administrador «{0}», pero la sesión abierta es de «{1}».`n`nLos ajustes de usuario (pestañas Rendimiento y Privacidad, y programas de Inicio del usuario) se aplicarán a «{0}», no a «{1}».`n`nPara aplicarlos a «{1}», esa cuenta tiene que ser administradora y abrir WinTaller ella misma." -f $script:SessionUser.Process, $script:SessionUser.Session),
            "$script:AppName - cuenta distinta", 'OK', 'Warning')
    }
}

