$script:form.add_FormClosing({
    param($sender, $eventArgs)
    if ($script:busy) {
        $eventArgs.Cancel = $true
        if ($script:statusLabel) {
            $script:statusLabel.Text = 'Espera a que termine la operación en curso...'
        }
        return
    }
    if ($script:wingetProcess) {
        $respuesta = [System.Windows.Forms.MessageBox]::Show(
            "Hay una instalación de programas en curso.`n`nSi cierras ahora se cancelará. Cerrar igualmente?",
            "$script:AppName - confirmar", 'YesNo', 'Question')
        if ($respuesta -ne 'Yes') {
            $eventArgs.Cancel = $true
            return
        }
        try { Stop-WingetProcess } catch { }
        try { $script:wingetTimer.Stop() } catch { }
    }
    if ($script:drvProcess) {
        $respuesta = [System.Windows.Forms.MessageBox]::Show(
            "Hay una instalación de drivers en curso.`n`nSi cierras ahora se cancelará y el driver podría quedar a medias. Cerrar igualmente?",
            "$script:AppName - confirmar", 'YesNo', 'Question')
        if ($respuesta -ne 'Yes') {
            $eventArgs.Cancel = $true
            return
        }
        try { Stop-DriverQueue } catch { }
    }
    if ($script:bkProcess) {
        $respuesta = [System.Windows.Forms.MessageBox]::Show(
            "Hay una copia de seguridad en curso.`n`nSi cierras ahora se cancelará, aunque lo ya copiado se conserva. Cerrar igualmente?",
            "$script:AppName - confirmar", 'YesNo', 'Question')
        if ($respuesta -ne 'Yes') {
            $eventArgs.Cancel = $true
            return
        }
        try { Stop-BackupJob } catch { }
    }
    if ($script:uninstProcess) {
        $respuesta = [System.Windows.Forms.MessageBox]::Show(
            "Hay una desinstalación en curso.`n`nSi cierras ahora se cancelará y el programa podría quedar a medias. Cerrar igualmente?",
            "$script:AppName - confirmar", 'YesNo', 'Question')
        if ($respuesta -ne 'Yes') {
            $eventArgs.Cancel = $true
            return
        }
        try { Stop-UninstallQueue } catch { }
    }
    if ($script:secProcess) {
        $respuesta = [System.Windows.Forms.MessageBox]::Show(
            "Hay un análisis o una actualización de Defender en curso.`n`nSi cierras ahora se cancelará. Cerrar igualmente?",
            "$script:AppName - confirmar", 'YesNo', 'Question')
        if ($respuesta -ne 'Yes') {
            $eventArgs.Cancel = $true
            return
        }
        try { Stop-SecurityJob -Silent } catch { }
    }
})

