# Cuatro pestañas principales; cada una contiene sus subpestañas.
#   Sistema       -> Servicios, Inicio, Drivers
#   Optimización  -> Limpieza y mantenimiento, Rendimiento
#   Programas     -> Instalar, Desinstalar
#   Protección    -> Seguridad, Puertos, Privacidad, Copias
function New-MainTab {
    param([string]$Text)
    $pagina = New-Object System.Windows.Forms.TabPage
    $pagina.Text = $Text
    $pagina.Padding = New-Object System.Windows.Forms.Padding(4)
    $pagina.UseVisualStyleBackColor = $true
    $sub = New-Object System.Windows.Forms.TabControl
    $sub.Dock = 'Fill'
    $sub.Padding = New-Object System.Drawing.Point(12, 4)
    $sub.Font = $script:uiFont
    $pagina.Controls.Add($sub)
    $pagina.Tag = $sub
    [void]$script:tabs.TabPages.Add($pagina)
    return $sub
}

$script:subSistema    = New-MainTab 'Sistema'
$script:subOptim      = New-MainTab 'Optimización'
$script:subProgramas  = New-MainTab 'Programas'
$script:subProteccion = New-MainTab 'Protección'
$script:tabSwitching  = $false

# Muestra una subpestaña concreta (selecciona también su pestaña principal).
function Select-AppTab {
    param($Page)
    foreach ($principal in $script:tabs.TabPages) {
        $sub = $principal.Tag
        if ($sub -and $sub.TabPages.Contains($Page)) {
            $script:tabSwitching = $true
            try {
                $script:tabs.SelectedTab = $principal
                $sub.SelectedTab = $Page
            } finally {
                $script:tabSwitching = $false
            }
            [System.Windows.Forms.Application]::DoEvents()
            Invoke-TabActivated $Page
            return
        }
    }
}

function Get-CurrentSubTab {
    $principal = $script:tabs.SelectedTab
    if ($principal -and $principal.Tag) { return $principal.Tag.SelectedTab }
    return $null
}

