# Colores y comportamiento de la tabla
$script:grid.add_CellFormatting({
    param($sender, $e)
    if ($e.RowIndex -lt 0) { return }
    try {
        $state = [string]$sender.Rows[$e.RowIndex].Cells['Estado'].Value
        $risk  = [string]$sender.Rows[$e.RowIndex].Cells['Riesgo'].Value
        if ($state -eq 'En ejecución') {
            $e.CellStyle.ForeColor = [System.Drawing.Color]::FromArgb(190, 20, 20)
        }
        if ($risk -eq 'Crítico') {
            $e.CellStyle.Font = $script:boldFont
        }
        if ($e.ColumnIndex -eq $sender.Columns['Riesgo'].Index) {
            if ($risk -eq 'Crítico') {
                $e.CellStyle.ForeColor = [System.Drawing.Color]::FromArgb(150, 0, 0)
            } elseif ($risk -eq 'Bajo') {
                $e.CellStyle.ForeColor = [System.Drawing.Color]::FromArgb(0, 120, 0)
            } else {
                $e.CellStyle.ForeColor = [System.Drawing.Color]::FromArgb(150, 100, 0)
            }
        }
        if ($e.ColumnIndex -eq $sender.Columns['Consejo'].Index) {
            $advice = [string]$sender.Rows[$e.RowIndex].Cells['Consejo'].Value
            $e.CellStyle.Font = $script:uiFont
            if ($advice -eq 'Quitar') {
                $e.CellStyle.ForeColor = [System.Drawing.Color]::FromArgb(0, 120, 0)
                $e.CellStyle.Font = $script:boldFont
            } elseif ($advice -eq 'No tocar') {
                $e.CellStyle.ForeColor = [System.Drawing.Color]::FromArgb(170, 0, 0)
            } else {
                $e.CellStyle.ForeColor = [System.Drawing.Color]::FromArgb(150, 100, 0)
            }
        }
    } catch { }
})

$script:grid.add_CurrentCellDirtyStateChanged({
    if ($script:grid.IsCurrentCellDirty -and $script:grid.CurrentCell -is [System.Windows.Forms.DataGridViewCheckBoxCell]) {
        $script:grid.CommitEdit([System.Windows.Forms.DataGridViewDataErrorContexts]::Commit)
    }
})

$script:grid.add_DataError({
    param($sender, $e)
    $e.ThrowException = $false
})

$script:grid.add_CellDoubleClick({
    param($sender, $e)
    if ($e.RowIndex -lt 0) { return }
    if ($e.ColumnIndex -eq $sender.Columns['Sel'].Index) {
        $cell = $sender.Rows[$e.RowIndex].Cells['Sel']
        $cell.Value = -not [bool]$cell.Value
    } else {
        Show-ServiceInfo $sender.Rows[$e.RowIndex]
    }
})

$script:grid.add_CellMouseDown({
    param($sender, $e)
    if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Right -and $e.RowIndex -ge 0) {
        try { $sender.CurrentCell = $sender.Rows[$e.RowIndex].Cells['Nombre'] } catch { }
    }
})

$script:grid.add_KeyDown({
    param($sender, $e)
    if ($e.KeyCode -eq [System.Windows.Forms.Keys]::F1) {
        Show-InfoForCurrentRow
        $e.Handled = $true
    }
})

