# ---------------------------------------------------------------------------
# Eventos
# ---------------------------------------------------------------------------

$script:txtSearch.add_TextChanged({ Apply-ServiceFilter })
$script:chkOnlyRunning.add_CheckedChanged({ Apply-ServiceFilter })
$script:chkRemovable.add_CheckedChanged({
    if ($script:chkRemovable.Checked -and $script:chkOnlyRunning.Checked) {
        $script:chkOnlyRunning.Checked = $false
    }
    Apply-ServiceFilter
})

$btnRefresh.add_Click({
    $script:statusLabel.Text = 'Actualizando lista de servicios...'
    $script:form.UseWaitCursor = $true
    try { Update-ServiceGrid } finally { $script:form.UseWaitCursor = $false }
    $script:statusLabel.Text = 'Lista de servicios actualizada'
})

$script:btnStop.add_Click({ Invoke-ServiceAction -Action 'Stop' })
$btnDisable.add_Click({ Invoke-ServiceAction -Action 'Disable' })
$btnEnable.add_Click({ Invoke-ServiceAction -Action 'Enable' })

$script:btnRun.add_Click({ Invoke-Optimization })

$btnRecommended.add_Click({
    for ($i = 0; $i -lt $script:taskList.Items.Count; $i++) {
        $script:taskList.SetItemChecked($i, [bool]$script:tasks[$i].Recommended)
    }
    $script:statusLabel.Text = 'Tareas recomendadas marcadas'
})

$btnUncheck.add_Click({
    for ($i = 0; $i -lt $script:taskList.Items.Count; $i++) {
        $script:taskList.SetItemChecked($i, $false)
    }
    $script:statusLabel.Text = 'Tareas desmarcadas'
})

$script:btnOptCancel.add_Click({
    if (-not $script:busy) { return }
    $respuesta = [System.Windows.Forms.MessageBox]::Show(
        "Se cancelará la tarea que este en curso.`n`nSi se esta reparando Windows (DISM/SFC) o comprobando el disco, es mejor dejarla terminar.`n`nQuieres cancelar?",
        "$script:AppName - cancelar optimización", 'YesNo', 'Warning')
    if ($respuesta -ne 'Yes') { return }
    $script:optCancel = $true
    $script:btnOptCancel.Enabled = $false
    $script:statusLabel.Text = 'Cancelando...'
    if ($script:optProcess) {
        try { & "$env:SystemRoot\System32\taskkill.exe" /PID $script:optProcess.Id /T /F 2>&1 | Out-Null } catch { }
    }
})

$script:btnRevert.add_Click({ Revert-Optimization })

$script:taskList.add_SelectedIndexChanged({
    $index = $script:taskList.SelectedIndex
    if ($index -ge 0 -and $index -lt $script:tasks.Count) {
        $script:lblTaskInfo.Text = $script:tasks[$index].Description
    }
})

$btnSaveLog.add_Click({ Save-ActivityLog })

$btnClearLog.add_Click({
    $script:logBox.Clear()
    $script:statusLabel.Text = 'Registro limpiado'
})

$btnRefreshInfo.add_Click({
    Update-SystemInfoLabel
    Write-Log ('Información actualizada: {0}' -f $script:lblSystemInfo.Text)
})

$btnStartup.add_Click({ Select-AppTab $tabInicio })

# ---------------------------------------------------------------------------
# Pestaña: Programas (instalador tipo Ninite con winget)
# ---------------------------------------------------------------------------

function New-AppEntry {
    param(
        [string]$Name,
        [string]$Category,
        [string]$Id,
        [string]$Note,
        [bool]$Recommended = $false,
        [string]$Kind = 'winget',
        [string]$Url = '',
        [string]$MsiArgs = '',
        [string]$Signer = '',
        [string]$Sha256 = ''
    )
    return [pscustomobject]@{
        Name        = $Name
        Category    = $Category
        Id          = $Id
        Note        = $Note
        Recommended = $Recommended
        Kind        = $Kind
        Url         = $Url
        MsiArgs     = $MsiArgs
        Signer      = $Signer
        Sha256      = $Sha256
    }
}

