function Get-UninstallRiskRank {
    param([string]$Risk)
    switch ($Risk) {
        'Sistema' { return 0 }
        'Alto'    { return 1 }
        'Medio'   { return 2 }
        default   { return 3 }
    }
}

function Get-UninstallAssessment {
    param(
        [string]$Name,
        [string]$Publisher,
        $InstallDate,
        $OsDate,
        [bool]$HasUninstall,
        [int]$NoRemove,
        [string]$Source = 'Registro'
    )

    $texto = ('{0} {1}' -f $Name, $Publisher)
    $protected = $false
    $risk = 'Bajo'
    $reason = 'Programa instalado por el usuario o por otro programa.'

    $patronesProtegidos = @(
        '^Microsoft Edge($| )',
        'Microsoft Edge WebView2 Runtime',
        '^Microsoft Visual C\+\+',
        '^Microsoft \.NET',
        '^Microsoft ASP\.NET',
        '^Microsoft Windows Desktop Runtime',
        '^Microsoft Windows App Runtime',
        '^Windows App Runtime',
        '^Windows Software Development Kit',
        '^Microsoft Update Health Tools',
        '^Microsoft GameInput',
        '^Microsoft XNA',
        '^Microsoft SQL Server .*(Native Client|ODBC|OLEDB)',
        '^Microsoft ODBC Driver',
        '^Microsoft OLE DB Driver'
    )
    foreach ($patron in $patronesProtegidos) {
        if ($Name -match $patron) {
            $protected = $true
            $risk = 'Sistema'
            $reason = 'Componente necesario para Windows o para otros programas. No se recomienda quitarlo.'
            break
        }
    }

    if ($NoRemove -eq 1 -and -not $protected) {
        $protected = $true
        $risk = 'Sistema'
        $reason = 'El propio programa indica que Windows no debe permitir su desinstalación.'
    }
    if (-not $HasUninstall -and -not $protected) {
        $protected = $true
        $risk = 'Sistema'
        $reason = 'No tiene un desinstalador registrado. Windows lo considera parte del sistema.'
    }

    if (-not $protected) {
        if ($Source -eq 'Appx') {
            if ($Name -match 'Microsoft\.(WindowsStore|Windows\.ShellExperienceHost|Windows\.StartMenuExperienceHost|Windows\.Search|AAD\.BrokerPlugin|AccountsControl|Windows\.CloudExperienceHost|Windows\.ContentDeliveryManager|UI\.Xaml|VCLibs|NET\.Native|Services\.Store)') {
                $protected = $true
                $risk = 'Sistema'
                $reason = 'Aplicación base de Windows o dependencia de la Tienda. No se debe quitar.'
            } elseif ($Publisher -match 'Microsoft') {
                $risk = 'Medio'
                $reason = 'Aplicación incluida en Windows. Se puede reinstalar desde Microsoft Store.'
            } else {
                $risk = 'Bajo'
                $reason = 'Aplicación de la Tienda instalada por el usuario.'
            }
        } else {
            if ($texto -match 'Defender|Antivirus|Malwarebytes|Kaspersky|Norton|McAfee|Avast|AVG|Bitdefender|ESET|Sophos|Panda|Trend Micro|Webroot|TinyWall|Firewall') {
                $risk = 'Alto'
                $reason = 'Software de seguridad. Si lo quitas, el equipo puede quedarse sin protección.'
            } elseif ($texto -match 'Runtime|Redistributable|Java|DirectX|Visual C\+\+') {
                $risk = 'Alto'
                $reason = 'Libreria compartida por varios programas. Quitarla puede romper aplicaciones.'
            } elseif ($texto -match 'Driver|Controlador|Chipset|Audio|Realtek|Intel|AMD|NVIDIA|Synaptics|Touchpad|Bluetooth|Dell|HP |Lenovo') {
                $risk = 'Alto'
                $reason = 'Controlador o utilidad del fabricante. El hardware puede dejar de funcionar bien.'
            } elseif ($Publisher -match 'Microsoft') {
                $risk = 'Alto'
                $reason = 'Programa de Microsoft. Comprueba que no lo necesitas antes de quitarlo.'
            }

            if ($risk -eq 'Bajo' -and $Publisher -notmatch 'Microsoft' -and $InstallDate -and $OsDate) {
                if ($InstallDate -gt $OsDate.AddDays(30)) {
                    $reason = 'Parece instalado por el usuario después de instalar Windows.'
                } else {
                    $risk = 'Medio'
                    $reason = 'No esta claro si lo instalaste tu o vino con el equipo. Revisa su nombre.'
                }
            }
        }
    }

    return [pscustomobject]@{
        Risk      = $risk
        Protected = $protected
        Reason    = $reason
    }
}

function Get-InstalledPrograms {
    param([switch]$IncludeStoreApps)

    $apps = New-Object System.Collections.ArrayList
    $vistos = @{}
    $osDate = $null
    try { $osDate = [datetime](Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop).InstallDate } catch { }

    $rutas = @(
        'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKCU:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    )

    foreach ($ruta in $rutas) {
        $rama = 'HKLM'
        if ($ruta.StartsWith('HKCU', [System.StringComparison]::OrdinalIgnoreCase)) { $rama = 'HKCU' }
        try {
            $claves = @(Get-ItemProperty -Path $ruta -ErrorAction SilentlyContinue)
        } catch { $claves = @() }
        foreach ($clave in $claves) {
            if (-not $clave -or -not $clave.DisplayName) { continue }
            if ([int]$clave.SystemComponent -eq 1) { continue }
            if ($clave.ParentKeyName) { continue }
            $tipo = [string]$clave.ReleaseType
            if ($tipo -match 'Update|Hotfix|Security Update|ServicePack|Patch') { continue }
            $nombre = ([string]$clave.DisplayName).Trim()
            if (-not $nombre) { continue }
            if ($nombre -match '^(KB\d{6,}|Update for |Security Update for |Hotfix for |Definition Update for )') { continue }

            $fabricante = ''
            if ($clave.Publisher) { $fabricante = ([string]$clave.Publisher).Trim() }
            $version = ''
            if ($clave.DisplayVersion) { $version = ([string]$clave.DisplayVersion).Trim() }
            $fecha = $null
            if (([string]$clave.InstallDate) -match '^\d{8}$') {
                try { $fecha = [datetime]::ParseExact([string]$clave.InstallDate, 'yyyyMMdd', $null) } catch { }
            }
            $tamano = 0
            try { if ($clave.EstimatedSize) { $tamano = [math]::Round(([double]$clave.EstimatedSize / 1024), 1) } } catch { }
            $desinstalar = ''
            if ($clave.UninstallString) { $desinstalar = [string]$clave.UninstallString }
            $silencioso = ''
            if ($clave.QuietUninstallString) { $silencioso = [string]$clave.QuietUninstallString }
            $noQuitar = 0
            try { if ($null -ne $clave.NoRemove) { $noQuitar = [int]$clave.NoRemove } } catch { }

            $id = ('{0}|{1}|{2}' -f $nombre, $fabricante, $version).ToLowerInvariant()
            if ($vistos.ContainsKey($id)) { continue }
            $vistos[$id] = $true

            $eval = Get-UninstallAssessment -Name $nombre -Publisher $fabricante -InstallDate $fecha `
                -OsDate $osDate -HasUninstall ([bool]($desinstalar -or $silencioso)) -NoRemove $noQuitar -Source 'Registro'

            [void]$apps.Add([pscustomobject]@{
                Id             = $id
                Name           = $nombre
                Publisher      = $fabricante
                Version        = $version
                InstallDate    = $fecha
                SizeMB         = $tamano
                Uninstall      = $desinstalar
                QuietUninstall = $silencioso
                Key            = [string]$clave.PSChildName
                Hive           = $rama
                Source         = 'Registro'
                Risk           = $eval.Risk
                Protected      = $eval.Protected
                Reason         = $eval.Reason
            })
        }
    }

    if ($IncludeStoreApps) {
        try {
            $paquetes = @(Get-AppxPackage -ErrorAction SilentlyContinue)
        } catch { $paquetes = @() }
        foreach ($paquete in $paquetes) {
            if (-not $paquete -or -not $paquete.Name) { continue }
            if ($paquete.IsFramework) { continue }
            try { if ($paquete.NonRemovable) { continue } } catch { }
            if ([string]$paquete.Name -match '\.Resources_') { continue }
            $nombre = [string]$paquete.Name
            $fabricante = [string]$paquete.PublisherDisplayName
            if (-not $fabricante) { $fabricante = [string]$paquete.Publisher }
            $version = [string]$paquete.Version
            $id = ('appx|{0}' -f $paquete.PackageFullName).ToLowerInvariant()
            if ($vistos.ContainsKey($id)) { continue }
            $vistos[$id] = $true
            $eval = Get-UninstallAssessment -Name $nombre -Publisher $fabricante -InstallDate $null `
                -OsDate $osDate -HasUninstall $true -NoRemove 0 -Source 'Appx'
            [void]$apps.Add([pscustomobject]@{
                Id             = $id
                Name           = $nombre
                Publisher      = $fabricante
                Version        = $version
                InstallDate    = $null
                SizeMB         = 0
                Uninstall      = ''
                QuietUninstall = ''
                Key            = [string]$paquete.PackageFullName
                Hive           = ''
                Source         = 'Appx'
                Risk           = $eval.Risk
                Protected      = $eval.Protected
                Reason         = $eval.Reason
            })
        }
    }

    return @($apps.ToArray() | Sort-Object @{ Expression = { Get-UninstallRiskRank $_.Risk } }, Name)
}

function Get-UninstallCommand {
    param($App)
    if (-not $App) { return $null }

    if ($App.Source -eq 'Appx') {
        $full = ([string]$App.Key) -replace "'", "''"
        return [pscustomobject]@{
            File   = (Join-Path $PSHOME 'powershell.exe')
            Args   = @('-NoProfile', '-NonInteractive', '-Command', ("Remove-AppxPackage -Package '{0}'" -f $full))
            Hidden = $true
        }
    }

    $silencioso = [string]$App.QuietUninstall
    $normal = [string]$App.Uninstall
    $usarSilencioso = [bool]$silencioso
    $comando = $normal
    if ($silencioso) { $comando = $silencioso }
    if (-not $comando) { return $null }

    if ($comando -match '(?i)msiexec') {
        $guid = ''
        $m = [regex]::Match($comando, '\{[0-9A-Fa-f-]{36}\}')
        if ($m.Success) { $guid = $m.Value }
        if ($guid) {
            return [pscustomobject]@{
                File   = (Join-Path $env:SystemRoot 'System32\msiexec.exe')
                Args   = @('/x', $guid, '/qn', '/norestart')
                Hidden = $true
            }
        }
    }

    $exe = ''
    $argumentos = ''
    if ($comando -match '^\s*"([^"]+)"\s*(.*)$') {
        $exe = $Matches[1]
        $argumentos = $Matches[2]
    } elseif ($comando -match '^\s*([^\s]+\.exe)\s*(.*)$') {
        $exe = $Matches[1]
        $argumentos = $Matches[2]
    } else {
        $exe = Join-Path $env:SystemRoot 'System32\cmd.exe'
        $argumentos = '/c ' + $comando
    }
    if (-not $exe) { return $null }
    # Un ejecutable sin ruta (rundll32.exe, por ejemplo) se busca en System32 y
    # no en la carpeta actual ni en el PATH.
    if ($exe -notmatch '[\\/]') {
        $enSistema = Join-Path $env:SystemRoot ('System32\' + $exe)
        if (Test-Path -LiteralPath $enSistema) { $exe = $enSistema }
    }
    return [pscustomobject]@{
        File   = $exe
        Args   = @($argumentos)
        Hidden = $usarSilencioso
    }
}

function Update-UninstallDetail {
    if (-not $script:uninstDetail) { return }
    if ($script:uninstList.SelectedItems.Count -eq 0) {
        $script:uninstDetail.Text = 'Selecciona un programa de la lista para ver su información y el riesgo de desinstalarlo.'
        return
    }
    $app = $script:uninstList.SelectedItems[0].Tag
    if (-not $app) { return }
    $lineas = @()
    $lineas += ('Programa: {0}' -f $app.Name)
    if ($app.Publisher) { $lineas += ('Fabricante: {0}' -f $app.Publisher) }
    if ($app.Version) { $lineas += ('Versión: {0}' -f $app.Version) }
    if ($app.InstallDate) { $lineas += ('Instalado: {0:dd/MM/yyyy}' -f $app.InstallDate) }
    if ($app.SizeMB -gt 0) { $lineas += ('Tamaño aproximado: {0} MB' -f $app.SizeMB) }
    $lineas += ('Origen: {0}' -f $(if ($app.Source -eq 'Appx') { 'Aplicación de la Tienda' } else { 'Programas y características de Windows' }))
    $lineas += ('Riesgo: {0}{1}' -f $app.Risk, $(if ($app.Protected) { ' (protegido)' } else { '' }))
    $lineas += ''
    $lineas += $app.Reason
    if ($app.Protected) {
        $lineas += ''
        $lineas += 'Esta entrada no se puede desinstalar desde esta herramienta porque Windows la necesita.'
    } elseif ($app.Risk -eq 'Alto') {
        $lineas += ''
        $lineas += 'Aviso: si no estas seguro de para que sirve, no lo desinstales.'
    }
    $script:uninstDetail.Text = ($lineas -join [Environment]::NewLine)
}

function Update-UninstallButtons {
    $marcados = 0
    try { $marcados = @($script:uninstList.CheckedItems).Count } catch { }
    $script:btnUninstRun.Enabled = (($marcados -gt 0) -and (-not $script:uninstProcess))
    $script:btnUninstStop.Enabled = [bool]$script:uninstProcess
    $script:btnUninstAll.Enabled = (-not $script:uninstProcess)
    $script:btnUninstRefresh.Enabled = (-not $script:uninstProcess)
}

function Update-UninstallList {
    param([switch]$Reload)

    if (-not $script:uninstList) { return }

    if ($Reload -or -not $script:uninstLoaded) {
        $script:statusLabel.Text = 'Leyendo los programas instalados...'
        $script:form.UseWaitCursor = $true
        [System.Windows.Forms.Application]::DoEvents()
        try {
            $incluirTienda = $false
            if ($script:chkUninstAppx) { $incluirTienda = [bool]$script:chkUninstAppx.Checked }
            $script:uninstApps = @(Get-InstalledPrograms -IncludeStoreApps:$incluirTienda)
            $script:uninstLoaded = $true
        } catch {
            $script:uninstApps = @()
            Add-TabLog $script:uninstLog ('No se pudo leer la lista de programas: {0}' -f $_.Exception.Message) 'ERROR'
        } finally {
            $script:form.UseWaitCursor = $false
        }
    }

    $filtro = ''
    if ($script:txtUninstSearch) { $filtro = $script:txtUninstSearch.Text.Trim().ToLowerInvariant() }
    $modo = 0
    if ($script:cmbUninstFilter) { $modo = $script:cmbUninstFilter.SelectedIndex }

    $mostrados = 0
    $script:uninstUpdating = $true
    $script:uninstList.BeginUpdate()
    try {
        $script:uninstList.Items.Clear()
        foreach ($app in $script:uninstApps) {
            if ($modo -eq 1 -and ($app.Protected -or $app.Risk -eq 'Alto' -or $app.Risk -eq 'Sistema')) { continue }
            if ($modo -eq 2 -and -not ($app.Protected -or $app.Risk -eq 'Alto' -or $app.Risk -eq 'Sistema')) { continue }
            if ($filtro) {
                $texto = ('{0} {1} {2}' -f $app.Name, $app.Publisher, $app.Version).ToLowerInvariant()
                if (-not $texto.Contains($filtro)) { continue }
            }

            $item = New-Object System.Windows.Forms.ListViewItem($app.Name)
            [void]$item.SubItems.Add($app.Publisher)
            [void]$item.SubItems.Add($app.Version)
            if ($app.SizeMB -gt 0) { [void]$item.SubItems.Add(('{0} MB' -f $app.SizeMB)) } else { [void]$item.SubItems.Add('') }
            if ($app.InstallDate) { [void]$item.SubItems.Add(('{0:dd/MM/yyyy}' -f $app.InstallDate)) } else { [void]$item.SubItems.Add('') }
            [void]$item.SubItems.Add($app.Risk)
            $item.Tag = $app

            if ($app.Protected) {
                $item.ForeColor = [System.Drawing.Color]::FromArgb(190, 0, 0)
                $item.Font = New-Object System.Drawing.Font($script:uiFont, [System.Drawing.FontStyle]::Bold)
            } elseif ($app.Risk -eq 'Alto') {
                $item.ForeColor = [System.Drawing.Color]::FromArgb(170, 70, 0)
            } elseif ($app.Risk -eq 'Medio') {
                $item.ForeColor = [System.Drawing.Color]::FromArgb(150, 100, 0)
            } else {
                $item.ForeColor = [System.Drawing.Color]::Black
            }

            $marcado = $false
            if ($script:uninstChecked.ContainsKey($app.Id)) { $marcado = [bool]$script:uninstChecked[$app.Id] }
            if ($app.Protected) { $marcado = $false }
            $item.Checked = $marcado

            [void]$script:uninstList.Items.Add($item)
            $mostrados++
        }
    } finally {
        $script:uninstList.EndUpdate()
        $script:uninstUpdating = $false
    }

    if ($script:grpUninstList) {
        $script:grpUninstList.Text = ('Programas instalados ({0} visibles de {1})' -f $mostrados, $script:uninstApps.Count)
    }
    Update-UninstallButtons
}

function Show-UninstallDangerInfo {
    $texto = @()
    $texto += 'NO se recomienda desinstalar estos tipos de programas:'
    $texto += ''
    $texto += '- Componentes de Windows: Microsoft Edge, WebView2, Visual C++, .NET, Windows App Runtime, SDK.'
    $texto += '- Controladores y utilidades del fabricante: audio, chipset, Wi-Fi, Bluetooth, touchpad.'
    $texto += '- Antivirus y cortafuegos: Defender, Malwarebytes, TinyWall, Kaspersky, Norton, etc.'
    $texto += '- Librerias compartidas: Java, runtimes, redistribuibles, DirectX.'
    $texto += ''
    $texto += 'En la lista aparecen en ROJO o NARANJA. Los que están en rojo y negrita están protegidos: la herramienta no los desinstala.'
    $texto += ''
    $texto += 'Antes de quitar algo, comprueba que no lo uses. Si no sabes para que sirve, no lo desinstales.'
    [void][System.Windows.Forms.MessageBox]::Show(
        ($texto -join [Environment]::NewLine), "$script:AppName - que no debo quitar", 'OK', 'Information')
}

function Finish-UninstallQueue {
    $script:uninstTimer.Stop()
    $script:uninstProcess = $null
    $script:uninstCurrent = $null
    $script:uninstCancelItem = $false
    $script:uninstStarted = $null
    Update-UninstallButtons
    if ($script:uninstCancelled) {
        $script:statusLabel.Text = 'Desinstalación detenida'
    } else {
        $script:statusLabel.Text = 'Desinstalación finalizada'
        Add-TabLog $script:uninstLog ('=== Fin: {0} correctos, {1} con avisos o errores ===' -f ($script:uninstDone - $script:uninstErrors), $script:uninstErrors) 'STEP'
        [void][System.Windows.Forms.MessageBox]::Show(
            ("Desinstalación finalizada.`n`nCorrectos: {0}`nCon avisos o errores: {1}`n`nRevisa el registro para ver el detalle." -f ($script:uninstDone - $script:uninstErrors), $script:uninstErrors),
            $script:AppName, 'OK', 'Information')
    }
    Start-Sleep -Milliseconds 800
    $script:uninstLoaded = $false
    Update-UninstallList -Reload
}

function Start-NextUninstall {
    if ($script:uninstQueue.Count -eq 0) {
        Finish-UninstallQueue
        return
    }

    $item = $script:uninstQueue.Dequeue()
    $app = $item.Tag
    $script:uninstCurrent = $item
    $script:statusLabel.Text = ('Desinstalando: {0}' -f $app.Name)
    Add-TabLog $script:uninstLog ('Desinstalando {0}...' -f $app.Name) 'STEP'

    $cmd = Get-UninstallCommand $app
    if (-not $cmd) {
        Add-TabLog $script:uninstLog ('{0}: no se encontró un comando de desinstalación.' -f $app.Name) 'ERROR'
        $script:uninstErrors++
        $script:uninstDone++
        Start-NextUninstall
        return
    }

    # Las entradas de HKCU las puede escribir cualquier programa del usuario sin
    # permisos de administrador. Si la herramienta está elevada, su comando se
    # ejecutaría como administrador: se muestra completo, se pide confirmación
    # y nunca se lanza oculto.
    if ($app.Hive -eq 'HKCU' -and $script:IsAdmin) {
        $cmd.Hidden = $false
        $textoCmd = ('{0} {1}' -f $cmd.File, (@($cmd.Args) -join ' ')).Trim()
        $aviso = ("'{0}' está registrado solo para tu usuario (HKCU) y su desinstalador se ejecutaría con permisos de administrador.`n`nComando:`n{1}`n`nEjecútalo solo si reconoces el programa y la ruta. ¿Continuar?" -f $app.Name, $textoCmd)
        if ([System.Windows.Forms.MessageBox]::Show($aviso, "$script:AppName - desinstalar", 'YesNo', 'Warning') -ne 'Yes') {
            Add-TabLog $script:uninstLog ('{0}: omitido por el usuario (entrada de HKCU).' -f $app.Name) 'WARN'
            $script:uninstErrors++
            $script:uninstDone++
            $script:uninstCurrent = $null
            Start-NextUninstall
            return
        }
    }

    try {
        $estilo = 'Normal'
        if ($cmd.Hidden) { $estilo = 'Hidden' }
        $script:uninstProcess = Start-Process -FilePath $cmd.File -ArgumentList $cmd.Args -PassThru -WindowStyle $estilo
        $script:uninstStarted = Get-Date
        $script:uninstTimer.Start()
    } catch {
        Add-TabLog $script:uninstLog ('{0}: no se pudo iniciar el desinstalador ({1}).' -f $app.Name, $_.Exception.Message) 'ERROR'
        $script:uninstErrors++
        $script:uninstDone++
        $script:uninstProcess = $null
        $script:uninstCurrent = $null
        Start-NextUninstall
    }
}

function Step-UninstallQueue {
    $proc = $script:uninstProcess
    if (-not $proc) { return }
    $terminado = $false
    try { $terminado = $proc.HasExited } catch { $terminado = $true }

    if (-not $terminado) {
        if ($script:uninstStarted -and ((Get-Date) - $script:uninstStarted).TotalMinutes -gt 45) {
            $colgado = $script:uninstCurrent
            try { & "$env:SystemRoot\System32\taskkill.exe" /PID $proc.Id /T /F 2>&1 | Out-Null } catch { }
            Add-TabLog $script:uninstLog ('{0}: el desinstalador superó 45 minutos y se ha cancelado.' -f $colgado.Tag.Name) 'WARN'
            $script:uninstErrors++
            $script:uninstDone++
            $script:uninstProcess = $null
            $script:uninstCurrent = $null
            try { $proc.Dispose() } catch { }
            Start-NextUninstall
        }
        return
    }

    $codigo = -1
    try { $codigo = [int]$proc.ExitCode } catch { }
    $item = $script:uninstCurrent
    $nombre = ''
    if ($item) { $nombre = [string]$item.Tag.Name }

    if ($script:uninstCancelItem) {
        Add-TabLog $script:uninstLog ('{0}: desinstalación cancelada por el usuario.' -f $nombre) 'WARN'
    } elseif ($codigo -eq 0 -or $codigo -eq 3010 -or $codigo -eq 1641) {
        Add-TabLog $script:uninstLog ('{0}: desinstalado correctamente.' -f $nombre) 'OK'
    } elseif ($codigo -eq 1605) {
        Add-TabLog $script:uninstLog ('{0}: Windows ya no lo tenia instalado.' -f $nombre) 'OK'
    } else {
        Add-TabLog $script:uninstLog ('{0}: el desinstalador terminó con código {1}.' -f $nombre, $codigo) 'WARN'
        $script:uninstErrors++
    }

    $script:uninstDone++
    $script:uninstProcess = $null
    $script:uninstCurrent = $null
    $script:uninstCancelItem = $false
    try { $proc.Dispose() } catch { }
    Start-NextUninstall
}

function Start-UninstallQueue {
    param($Items)

    if ($script:uninstProcess) { return }

    $seleccion = @()
    foreach ($item in @($Items)) {
        if ($item -and $item.Tag -and -not $item.Tag.Protected) { $seleccion += $item }
    }
    if ($seleccion.Count -eq 0) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'Marca primero uno o varios programas. Los componentes protegidos no se pueden desinstalar desde aquí.',
            $script:AppName, 'OK', 'Information')
        return
    }

    $lista = ($seleccion | ForEach-Object { ' - ' + $_.Tag.Name }) -join [Environment]::NewLine
    $riesgo = @($seleccion | Where-Object { $_.Tag.Risk -ne 'Bajo' })
    $texto = "Se van a desinstalar {0} programas:`n`n{1}`n" -f $seleccion.Count, $lista
    if ($riesgo.Count -gt 0) {
        $texto += "`nAVISO: estos programas no son recomendables de quitar:`n"
        foreach ($item in $riesgo) {
            $texto += (' - {0} ({1}): {2}' -f $item.Tag.Name, $item.Tag.Risk, $item.Tag.Reason) + [Environment]::NewLine
        }
        $texto += "`nSi el equipo deja de funcionar bien, tendras que volver a instalarlos.`n"
    }
    $texto += "`nQuieres continuar?"
    if ([System.Windows.Forms.MessageBox]::Show($texto, "$script:AppName - confirmar desinstalación", 'OKCancel', 'Warning') -ne 'OK') { return }

    $script:uninstQueue.Clear()
    foreach ($item in $seleccion) { $script:uninstQueue.Enqueue($item) }
    $script:uninstTotal = $seleccion.Count
    $script:uninstDone = 0
    $script:uninstErrors = 0
    $script:uninstCancelled = $false
    $script:uninstCancelItem = $false
    $script:uninstUpdating = $true
    foreach ($item in $seleccion) {
        if ($item.Tag) { $script:uninstChecked[[string]$item.Tag.Id] = $false }
        $item.Checked = $false
    }
    $script:uninstUpdating = $false
    Update-UninstallButtons
    Add-TabLog $script:uninstLog ('=== Desinstalando {0} programas ===' -f $seleccion.Count) 'STEP'
    Start-NextUninstall
}

function Stop-UninstallQueue {
    $script:uninstCancelled = $true
    $script:uninstQueue.Clear()
    if ($script:uninstProcess) {
        $script:uninstCancelItem = $true
        try { & "$env:SystemRoot\System32\taskkill.exe" /PID $script:uninstProcess.Id /T /F 2>&1 | Out-Null } catch { }
        Add-TabLog $script:uninstLog 'Desinstalación detenida por el usuario.' 'WARN'
    } else {
        Finish-UninstallQueue
    }
}

