$script:uninstList.add_ItemChecked({
    param($sender, $e)
    if ($script:uninstUpdating) { return }
    if (-not $e.Item -or -not $e.Item.Tag) { return }
    if ($e.Item.Checked -and $e.Item.Tag.Protected) {
        $script:uninstUpdating = $true
        $e.Item.Checked = $false
        $script:uninstUpdating = $false
        $clave = [string]$e.Item.Tag.Id
        if (-not $script:uninstWarned.ContainsKey($clave)) {
            $script:uninstWarned[$clave] = $true
            [void][System.Windows.Forms.MessageBox]::Show(
                ("{0}`n`n{1}`n`nEsta entrada está protegida y no se puede desinstalar desde esta herramienta." -f $e.Item.Tag.Name, $e.Item.Tag.Reason),
                "$script:AppName - componente protegido", 'OK', 'Warning')
        }
        return
    }
    $script:uninstChecked[[string]$e.Item.Tag.Id] = [bool]$e.Item.Checked
    Update-UninstallButtons
})

