$script:btnUninstAll.add_Click({
    if ($script:uninstProcess) { return }
    $marcar = $true
    $visibles = @($script:uninstList.Items | Where-Object { $_.Tag -and -not $_.Tag.Protected })
    $marcados = @($visibles | Where-Object { $_.Checked }).Count
    if ($visibles.Count -gt 0 -and $marcados -eq $visibles.Count) { $marcar = $false }
    $script:uninstUpdating = $true
    $script:uninstList.BeginUpdate()
    try {
        foreach ($item in $visibles) {
            $item.Checked = $marcar
            $script:uninstChecked[[string]$item.Tag.Id] = $marcar
        }
    } finally {
        $script:uninstList.EndUpdate()
        $script:uninstUpdating = $false
    }
    Update-UninstallButtons
})

