# ---------------------------------------------------------------------------
# Pestaña: Rendimiento (antes "Equipo": ajustes según sea sobremesa o portátil)
# ---------------------------------------------------------------------------
# Cada ajuste muestra su estado actual en este equipo, para saber qué va a
# cambiar antes de aplicarlo. Los ajustes ya aplicados aparecen en verde y
# sin marcar. El diagnóstico (discos, pantallazos, memoria, informes) está en
# botones aparte y no cambia nada.

$script:GuidPattern = '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}'
$script:ReportBrand = 'WinTaller'

# Compilación de Windows (22000 o superior = Windows 11). Algunos ajustes solo
# existen a partir de una compilación concreta.
$script:WinBuild = 0
try { $script:WinBuild = [int][Environment]::OSVersion.Version.Build } catch { }

function Get-RegValueSafe {
    param([string]$Path, [string]$Name)
    try {
        return (Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction Stop).$Name
    } catch {
        return $null
    }
}

function New-EquipoState {
    param([string]$Text, [bool]$Applied = $false)
    return [pscustomobject]@{ Text = $Text; Applied = $Applied }
}

function Get-ActivePowerScheme {
    $salida = (& "$env:SystemRoot\System32\powercfg.exe" /getactivescheme 2>&1 | Out-String)
    $guid = ''
    $nombre = ''
    $m = [regex]::Match($salida, ('({0})\s*\(([^)]+)\)' -f $script:GuidPattern))
    if ($m.Success) {
        $guid = $m.Groups[1].Value.ToLowerInvariant()
        $nombre = $m.Groups[2].Value.Trim()
    } else {
        $m = [regex]::Match($salida, $script:GuidPattern)
        if ($m.Success) { $guid = $m.Value.ToLowerInvariant() }
    }
    return [pscustomobject]@{ Guid = $guid; Name = $nombre }
}

# Planes de energía estándar de Windows. Names: nombres con los que aparece
# el plan (también las copias creadas con /duplicatescheme).
$script:PowerPlans = @{
    'Alto'        = [pscustomobject]@{ Guid = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'; Label = 'Alto rendimiento'; Names = @('Alto rendimiento', 'High performance') }
    'Equilibrado' = [pscustomobject]@{ Guid = '381b4222-f694-41f0-9685-ff5bb260df2e'; Label = 'Equilibrado'; Names = @('Equilibrado', 'Balanced') }
    'Economia'    = [pscustomobject]@{ Guid = 'a1841308-3541-4fab-bc81-f71556f20b4a'; Label = 'Economizador'; Names = @('Economizador', 'Ahorro de energía', 'Power saver') }
}

function Test-PowerPlanActive {
    param([string]$Key)
    $plan = $script:PowerPlans[$Key]
    $activo = Get-ActivePowerScheme
    return ($activo.Guid -eq $plan.Guid -or ($activo.Name -and $plan.Names -contains $activo.Name))
}

function Get-PowerPlanState {
    param([string]$Key)
    if (Test-PowerPlanActive $Key) { return (New-EquipoState 'Activo' $true) }
    $activo = Get-ActivePowerScheme
    $nombre = $activo.Name
    if (-not $nombre) { $nombre = 'otro plan' }
    return (New-EquipoState ('No (ahora: {0})' -f $nombre) $false)
}

# Activa un plan estándar. En muchos portátiles modernos Windows oculta el plan
# Alto rendimiento: en ese caso se reutiliza una copia existente o se crea una.
function Set-PowerPlan {
    param([string]$Key)
    $plan = $script:PowerPlans[$Key]
    & "$env:SystemRoot\System32\powercfg.exe" /setactive $plan.Guid 2>&1 | Out-Null
    if ($LASTEXITCODE -eq 0) { return }

    $lista = (& "$env:SystemRoot\System32\powercfg.exe" /list 2>&1 | Out-String) -split "`r?`n"
    foreach ($linea in $lista) {
        $m = [regex]::Match($linea, ('({0})\s*\(([^)]+)\)' -f $script:GuidPattern))
        if ($m.Success -and $plan.Names -contains $m.Groups[2].Value.Trim()) {
            & "$env:SystemRoot\System32\powercfg.exe" /setactive $m.Groups[1].Value 2>&1 | Out-Null
            if ($LASTEXITCODE -eq 0) { return }
        }
    }

    $salida = (& "$env:SystemRoot\System32\powercfg.exe" /duplicatescheme $plan.Guid 2>&1 | Out-String)
    $m = [regex]::Match($salida, $script:GuidPattern)
    if (-not $m.Success) { throw ('El plan "{0}" no está disponible en este equipo.' -f $plan.Label) }
    & "$env:SystemRoot\System32\powercfg.exe" /setactive $m.Value 2>&1 | Out-Null
    if ($LASTEXITCODE -ne 0) { throw ('No se pudo activar el plan "{0}" (código {1}).' -f $plan.Label, $LASTEXITCODE) }
}

function Get-HibernationState {
    $hiber = Join-Path $env:SystemDrive 'hiberfil.sys'
    $tamano = 0
    try { $tamano = (Get-Item -LiteralPath $hiber -Force -ErrorAction Stop).Length } catch { }
    $valor = Get-RegValueSafe 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' 'HibernateEnabled'
    $activa = ($tamano -gt 0) -or ($valor -eq 1)
    if ($activa) {
        if ($tamano -gt 0) { return (New-EquipoState ('Activada (ocupa {0:N1} GB)' -f ($tamano / 1GB)) $false) }
        return (New-EquipoState 'Activada' $false)
    }
    return (New-EquipoState 'Desactivada' $true)
}

function Get-FastStartupState {
    $hib = Get-HibernationState
    if ($hib.Applied) { return (New-EquipoState 'Desactivado (sin hibernación)' $true) }
    $valor = Get-RegValueSafe 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' 'HiberbootEnabled'
    if ($valor -eq 0) { return (New-EquipoState 'Desactivado' $true) }
    return (New-EquipoState 'Activado' $false)
}

function Get-TrimState {
    if (-not $script:IsAdmin) { return (New-EquipoState 'Sin comprobar (requiere administrador)' $false) }
    $salida = (& "$env:SystemRoot\System32\fsutil.exe" behavior query DisableDeleteNotify 2>&1 | Out-String)
    $m = [regex]::Match($salida, 'DisableDeleteNotify\s*=\s*(\d)')
    if (-not $m.Success) { return (New-EquipoState 'Desconocido' $false) }
    if ($m.Groups[1].Value -eq '0') { return (New-EquipoState 'Activado' $true) }
    return (New-EquipoState 'DESACTIVADO' $false)
}

$script:equipoActions = @(
    [pscustomobject]@{
        Name        = 'Plan de energía: Alto rendimiento'
        Group       = 'Energía'
        Exclusive   = 'Plan'
        NeedsAdmin  = $false
        Description = 'La CPU no baja de frecuencia y el disco y la red no se suspenden. Es el recomendado en sobremesa. En portátil consume bastante más batería. Solo puede haber un plan activo: al marcar uno se desmarcan los otros.'
        Target      = 'Todos'
        RecDesktop  = $true
        RecLaptop   = $false
        State       = { Get-PowerPlanState 'Alto' }
        Run         = {
            Set-PowerPlan 'Alto'
            Add-TabLog $script:eqLog 'Plan de energía cambiado a ALTO RENDIMIENTO.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Plan de energía: Equilibrado'
        Group       = 'Energía'
        Exclusive   = 'Plan'
        NeedsAdmin  = $false
        Description = 'El plan por defecto de Windows: buen rendimiento y consumo razonable. Es el recomendado en portátiles. En sobremesa también es correcto si prefieres menos consumo y ruido.'
        Target      = 'Todos'
        RecDesktop  = $false
        RecLaptop   = $true
        State       = { Get-PowerPlanState 'Equilibrado' }
        Run         = {
            Set-PowerPlan 'Equilibrado'
            Add-TabLog $script:eqLog 'Plan de energía cambiado a EQUILIBRADO.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Plan de energía: Economizador'
        Group       = 'Energía'
        Exclusive   = 'Plan'
        NeedsAdmin  = $false
        Description = 'Máxima autonomía en portátiles: baja el rendimiento para que la batería dure más. No lo uses si vas a jugar o editar vídeo.'
        Target      = 'Portatil'
        RecDesktop  = $false
        RecLaptop   = $false
        State       = { Get-PowerPlanState 'Economia' }
        Run         = {
            Set-PowerPlan 'Economia'
            Add-TabLog $script:eqLog 'Plan de energía cambiado a ECONOMIZADOR.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Desactivar hibernación (libera disco)'
        Group       = 'Energía'
        Exclusive   = ''
        NeedsAdmin  = $true
        Description = 'Elimina el archivo hiberfil.sys, que suele ocupar entre 4 y 16 GB, y desactiva también el Inicio rápido. En portátiles perderás la opción de hibernar; si la usas, no marques esta acción. Se revierte con: powercfg /hibernate on'
        Target      = 'Todos'
        RecDesktop  = $true
        RecLaptop   = $false
        State       = { Get-HibernationState }
        Run         = {
            & "$env:SystemRoot\System32\powercfg.exe" /hibernate off 2>&1 | Out-Null
            if ($LASTEXITCODE -ne 0) { throw ('powercfg devolvió el código {0}' -f $LASTEXITCODE) }
            Add-TabLog $script:eqLog 'Hibernación desactivada y archivo hiberfil.sys eliminado.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Desactivar Inicio rápido'
        Group       = 'Energía'
        Exclusive   = ''
        NeedsAdmin  = $true
        Description = 'El Inicio rápido acelera el arranque pero deja el sistema en un estado mixto que provoca fallos raros al apagar, en actualizaciones y con arranque dual. Desactivarlo hace los apagados más limpios.'
        Target      = 'Todos'
        RecDesktop  = $false
        RecLaptop   = $false
        State       = { Get-FastStartupState }
        Run         = {
            Set-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' 'HiberbootEnabled' 0
            Add-TabLog $script:eqLog 'Inicio rápido desactivado. Se aplica en el próximo apagado.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Efectos visuales: máximo rendimiento'
        Group       = 'Rendimiento y aspecto'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'Quita animaciones, sombras y efectos de ventanas. La interfaz se ve más simple pero responde más rápido, sobre todo con poca memoria o gráfica integrada. Se aplica del todo al cerrar sesión.'
        Target      = 'Todos'
        RecDesktop  = $true
        RecLaptop   = $true
        State       = {
            $v = Get-RegValueSafe 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' 'VisualFXSetting'
            switch ($v) {
                2       { New-EquipoState 'Máximo rendimiento' $true }
                1       { New-EquipoState 'Máxima apariencia' $false }
                3       { New-EquipoState 'Personalizado' $false }
                default { New-EquipoState 'Automático (Windows decide)' $false }
            }
        }
        Run         = {
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' 'VisualFXSetting' 2
            Add-TabLog $script:eqLog 'Efectos visuales en máximo rendimiento. Cierra sesión para aplicarlo del todo.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Quitar transparencias y animaciones'
        Group       = 'Rendimiento y aspecto'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'Desactiva la transparencia del menú Inicio y la barra de tareas, las animaciones de la barra y el retardo de los menús. Se nota mucho en equipos modestos.'
        Target      = 'Todos'
        RecDesktop  = $true
        RecLaptop   = $true
        State       = {
            $t = Get-RegValueSafe 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' 'EnableTransparency'
            $a = Get-RegValueSafe 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'TaskbarAnimations'
            if ($t -eq 0 -and $a -eq 0) { New-EquipoState 'Quitadas' $true }
            elseif ($t -eq 0) { New-EquipoState 'Sin transparencia, con animaciones' $false }
            else { New-EquipoState 'Activadas' $false }
        }
        Run         = {
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' 'EnableTransparency' 0
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'TaskbarAnimations' 0
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'ListviewAlphaSelect' 0
            Set-RegValue 'HKCU:\Control Panel\Desktop' 'DragFullWindows' '0' 'String'
            Set-RegValue 'HKCU:\Control Panel\Desktop' 'MenuShowDelay' '0' 'String'
            Set-RegValue 'HKCU:\Control Panel\Desktop\WindowMetrics' 'MinAnimate' '0' 'String'
            Update-ExplorerSettings
            Add-TabLog $script:eqLog 'Transparencias y animaciones desactivadas.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Desactivar apps en segundo plano'
        Group       = 'Rendimiento y aspecto'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'Impide que las aplicaciones de la Store se ejecuten en segundo plano. Ahorra RAM y batería, pero algunas dejarán de avisar (correo, mensajes, notificaciones).'
        Target      = 'Todos'
        RecDesktop  = $false
        RecLaptop   = $false
        State       = {
            $v = Get-RegValueSafe 'HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications' 'GlobalUserDisabled'
            if ($v -eq 1) { New-EquipoState 'Desactivadas' $true } else { New-EquipoState 'Permitidas' $false }
        }
        Run         = {
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications' 'GlobalUserDisabled' 1
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search' 'BackgroundAppGlobalToggle' 0
            Add-TabLog $script:eqLog 'Aplicaciones en segundo plano desactivadas para este usuario.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Activar TRIM en el SSD'
        Group       = 'Disco'
        Exclusive   = ''
        NeedsAdmin  = $true
        Description = 'Avisa al SSD de los bloques que ya no se usan para que los libere. Mantiene la velocidad del disco con el tiempo. Windows lo activa por defecto; si aparece desactivado, conviene activarlo.'
        Target      = 'SSD'
        RecDesktop  = $true
        RecLaptop   = $true
        State       = { Get-TrimState }
        Run         = {
            $salida = & "$env:SystemRoot\System32\fsutil.exe" behavior set DisableDeleteNotify 0 2>&1
            if ($LASTEXITCODE -ne 0) { throw ($salida -join ' ') }
            Add-TabLog $script:eqLog 'TRIM activado en las unidades SSD.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Activar modo juego'
        Group       = 'Juegos'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'Windows da prioridad a los juegos y evita que otras tareas roben recursos mientras juegas. No afecta al trabajo normal. Viene activado por defecto.'
        Target      = 'Todos'
        RecDesktop  = $true
        RecLaptop   = $true
        State       = {
            $v = Get-RegValueSafe 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled'
            if ($v -eq 0) { New-EquipoState 'Desactivado' $false } else { New-EquipoState 'Activado' $true }
        }
        Run         = {
            Set-RegValue 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled' 1
            Set-RegValue 'HKCU:\Software\Microsoft\GameBar' 'AllowAutoGameMode' 1
            Add-TabLog $script:eqLog 'Modo juego activado.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Desactivar Game DVR (grabación en segundo plano)'
        Group       = 'Juegos'
        Exclusive   = ''
        NeedsAdmin  = $true
        Description = 'Desactiva la grabación de clips en segundo plano de la Barra de juegos. Libera CPU, GPU y disco al jugar. Puedes seguir grabando a mano con Win+G.'
        Target      = 'Todos'
        RecDesktop  = $true
        RecLaptop   = $true
        State       = {
            $v = Get-RegValueSafe 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled'
            if ($v -eq 0) { New-EquipoState 'Desactivado' $true } else { New-EquipoState 'Activado' $false }
        }
        Run         = {
            Set-RegValue 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 0
            Set-RegValue 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR' 'AllowGameDVR' 0
            Add-TabLog $script:eqLog 'Game DVR desactivado.' 'OK'
        }
    },
    # --- Windows más ágil: opciones útiles que Windows trae desactivadas -------
    # Estos ajustes tienen además un bloque Undo: el botón "Deshacer" devuelve
    # el valor que trae Windows de fábrica.
    [pscustomobject]@{
        Name        = 'Activar "Finalizar tarea" en la barra de tareas'
        Group       = 'Windows más ágil'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'Añade "Finalizar tarea" al menú del botón derecho de cada programa en la barra de tareas. Permite cerrar un programa colgado sin abrir el Administrador de tareas. Windows 11 lo trae desactivado (Configuración > Sistema > Para desarrolladores). Se aplica al momento.'
        Target      = 'Win11'
        MinBuild    = 22631
        RecDesktop  = $true
        RecLaptop   = $true
        State       = {
            $v = Get-RegValueSafe 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced\TaskbarDeveloperSettings' 'TaskbarEndTask'
            if ($v -eq 1) { New-EquipoState 'Activado' $true } else { New-EquipoState 'Desactivado' $false }
        }
        Run         = {
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced\TaskbarDeveloperSettings' 'TaskbarEndTask' 1
            Add-TabLog $script:eqLog '"Finalizar tarea" activado en el botón derecho de la barra de tareas.' 'OK'
        }
        Undo        = {
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced\TaskbarDeveloperSettings' 'TaskbarEndTask' 0
            Add-TabLog $script:eqLog '"Finalizar tarea" desactivado (valor de Windows).' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Menú contextual clásico al hacer clic derecho'
        Group       = 'Windows más ágil'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'El botón derecho vuelve a mostrar el menú completo de siempre, sin tener que pulsar "Mostrar más opciones". Ahorra un clic cada vez. Solo afecta a tu usuario. Se aplica al cerrar sesión o al reiniciar el Explorador de Windows.'
        Target      = 'Win11'
        RecDesktop  = $false
        RecLaptop   = $false
        State       = {
            $v = [Microsoft.Win32.Registry]::GetValue('HKEY_CURRENT_USER\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32', '', $null)
            if ($null -ne $v -and [string]$v -eq '') { New-EquipoState 'Menú clásico' $true } else { New-EquipoState 'Menú de Windows 11' $false }
        }
        Run         = {
            [Microsoft.Win32.Registry]::SetValue('HKEY_CURRENT_USER\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32', '', '', [Microsoft.Win32.RegistryValueKind]::String)
            Add-TabLog $script:eqLog 'Menú contextual clásico activado. Cierra sesión o reinicia el Explorador para verlo.' 'OK'
        }
        Undo        = {
            $clave = 'HKCU:\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}'
            if (Test-Path -LiteralPath $clave) { Remove-Item -LiteralPath $clave -Recurse -Force -ErrorAction Stop }
            Add-TabLog $script:eqLog 'Menú contextual de Windows 11 restaurado. Cierra sesión o reinicia el Explorador para verlo.' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Mostrar las extensiones de los archivos'
        Group       = 'Windows más ágil'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'El Explorador muestra el nombre completo (factura.pdf, foto.jpg). Además de ahorrar tiempo es una medida de seguridad: deja a la vista los archivos del tipo "factura.pdf.exe". Windows las oculta por defecto.'
        Target      = 'Todos'
        RecDesktop  = $true
        RecLaptop   = $true
        State       = {
            $v = Get-RegValueSafe 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'HideFileExt'
            if ($v -eq 0) { New-EquipoState 'Visibles' $true } else { New-EquipoState 'Ocultas' $false }
        }
        Run         = {
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'HideFileExt' 0
            Update-ExplorerSettings
            Add-TabLog $script:eqLog 'Extensiones de archivo visibles. Si no se ven aún, pulsa F5 en el Explorador.' 'OK'
        }
        Undo        = {
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'HideFileExt' 1
            Update-ExplorerSettings
            Add-TabLog $script:eqLog 'Extensiones de archivo ocultas (valor de Windows).' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Abrir el Explorador en "Este equipo"'
        Group       = 'Windows más ágil'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'El Explorador de archivos se abre directamente en "Este equipo" (discos y unidades) en lugar de en Inicio / Acceso rápido, que tarda más en cargar porque calcula los archivos recientes.'
        Target      = 'Todos'
        RecDesktop  = $false
        RecLaptop   = $false
        State       = {
            $v = Get-RegValueSafe 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'LaunchTo'
            if ($v -eq 1) { New-EquipoState 'Este equipo' $true } else { New-EquipoState 'Inicio / Acceso rápido' $false }
        }
        Run         = {
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'LaunchTo' 1
            Add-TabLog $script:eqLog 'El Explorador se abrirá en "Este equipo".' 'OK'
        }
        Undo        = {
            Set-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' 'LaunchTo' 2
            Add-TabLog $script:eqLog 'El Explorador vuelve a abrirse en Inicio / Acceso rápido (valor de Windows).' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Activar el historial del portapapeles (Win+V)'
        Group       = 'Windows más ágil'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'Con Win+V puedes pegar cualquiera de las últimas cosas copiadas, no solo la última. El historial se guarda en este equipo y se borra al reiniciar. Ten en cuenta que también guarda lo que copies de un gestor de contraseñas; por eso no se marca como recomendado.'
        Target      = 'Todos'
        RecDesktop  = $false
        RecLaptop   = $false
        State       = {
            $v = Get-RegValueSafe 'HKCU:\Software\Microsoft\Clipboard' 'EnableClipboardHistory'
            if ($v -eq 1) { New-EquipoState 'Activado' $true } else { New-EquipoState 'Desactivado' $false }
        }
        Run         = {
            Set-RegValue 'HKCU:\Software\Microsoft\Clipboard' 'EnableClipboardHistory' 1
            Add-TabLog $script:eqLog 'Historial del portapapeles activado. Úsalo con Win+V.' 'OK'
        }
        Undo        = {
            Set-RegValue 'HKCU:\Software\Microsoft\Clipboard' 'EnableClipboardHistory' 0
            Add-TabLog $script:eqLog 'Historial del portapapeles desactivado (valor de Windows).' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Activar rutas largas (más de 260 caracteres)'
        Group       = 'Windows más ágil'
        Exclusive   = ''
        NeedsAdmin  = $true
        Description = 'Quita el límite histórico de 260 caracteres en las rutas de archivo. Evita errores al copiar, descomprimir o hacer copias de seguridad de carpetas muy anidadas. Solo lo aprovechan los programas preparados para ello; no afecta al resto. Windows lo trae desactivado.'
        Target      = 'Todos'
        RecDesktop  = $true
        RecLaptop   = $true
        State       = {
            $v = Get-RegValueSafe 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'LongPathsEnabled'
            if ($v -eq 1) { New-EquipoState 'Activadas' $true } else { New-EquipoState 'Desactivadas' $false }
        }
        Run         = {
            Set-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'LongPathsEnabled' 1
            Add-TabLog $script:eqLog 'Rutas largas activadas. Los programas lo notan al volver a abrirse.' 'OK'
        }
        Undo        = {
            Set-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'LongPathsEnabled' 0
            Add-TabLog $script:eqLog 'Rutas largas desactivadas (valor de Windows).' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Cerrar antes los programas colgados al apagar'
        Group       = 'Windows más ágil'
        Exclusive   = ''
        NeedsAdmin  = $false
        Description = 'Al apagar, reiniciar o cerrar sesión, Windows cierra por su cuenta los programas que no responden en lugar de quedarse esperando en la pantalla "Esta aplicación impide el apagado". Apaga más rápido, pero un programa con cambios sin guardar se cerrará sin preguntar: guarda antes de apagar.'
        Target      = 'Todos'
        RecDesktop  = $false
        RecLaptop   = $false
        State       = {
            $v = Get-RegValueSafe 'HKCU:\Control Panel\Desktop' 'AutoEndTasks'
            if ([string]$v -eq '1') { New-EquipoState 'Activado' $true } else { New-EquipoState 'Desactivado (Windows espera)' $false }
        }
        Run         = {
            Set-RegValue 'HKCU:\Control Panel\Desktop' 'AutoEndTasks' '1' 'String'
            Set-RegValue 'HKCU:\Control Panel\Desktop' 'HungAppTimeout' '3000' 'String'
            Set-RegValue 'HKCU:\Control Panel\Desktop' 'WaitToKillAppTimeout' '5000' 'String'
            Add-TabLog $script:eqLog 'Cierre automático de programas colgados al apagar activado. Se aplica al iniciar sesión de nuevo.' 'OK'
        }
        Undo        = {
            foreach ($nombre in @('AutoEndTasks', 'HungAppTimeout', 'WaitToKillAppTimeout')) {
                Remove-RegValue 'HKCU:\Control Panel\Desktop' $nombre
            }
            Add-TabLog $script:eqLog 'Windows vuelve a esperar a los programas al apagar (valor de Windows).' 'OK'
        }
    },
    [pscustomobject]@{
        Name        = 'Mensajes detallados al arrancar y al apagar'
        Group       = 'Windows más ágil'
        Exclusive   = ''
        NeedsAdmin  = $true
        Description = 'En lugar de "Espere un momento", Windows indica qué está haciendo en cada paso del arranque, el apagado y el inicio de sesión. No acelera nada, pero permite ver de un vistazo qué servicio o directiva está retrasando el equipo. Pensado para diagnóstico en taller.'
        Target      = 'Todos'
        RecDesktop  = $false
        RecLaptop   = $false
        State       = {
            $v = Get-RegValueSafe 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'VerboseStatus'
            if ($v -eq 1) { New-EquipoState 'Activados' $true } else { New-EquipoState 'Desactivados' $false }
        }
        Run         = {
            Set-RegValue 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'VerboseStatus' 1
            Add-TabLog $script:eqLog 'Mensajes detallados de arranque y apagado activados.' 'OK'
        }
        Undo        = {
            Remove-RegValue 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' 'VerboseStatus'
            Add-TabLog $script:eqLog 'Mensajes detallados de arranque y apagado desactivados (valor de Windows).' 'OK'
        }
    }
)

