function Test-EquipoRecommended {
    param($Accion)
    if ($script:hardware -and $script:hardware.IsLaptop) { return [bool]$Accion.RecLaptop }
    return [bool]$Accion.RecDesktop
}

function Get-EquipoActionState {
    param($Accion)
    try {
        $estado = & $Accion.State
        if ($estado) { return $estado }
    } catch {
        Write-Diag ('Estado de "{0}": {1}' -f $Accion.Name, $_.Exception.Message)
    }
    return (New-EquipoState 'Desconocido' $false)
}

# Rellena la lista con el estado actual de cada ajuste. Los recomendados que
# todavía no están aplicados quedan marcados.
function Update-EquipoList {
    $script:eqSyncing = $true
    $script:eqList.BeginUpdate()
    try {
        $script:eqList.Items.Clear()
        $script:eqList.Groups.Clear()
        $grupos = @{}
        foreach ($nombre in @('Energía', 'Rendimiento y aspecto', 'Windows más ágil', 'Disco', 'Juegos')) {
            $g = New-Object System.Windows.Forms.ListViewGroup($nombre, $nombre)
            [void]$script:eqList.Groups.Add($g)
            $grupos[$nombre] = $g
        }
        $pendientes = 0
        $aplicados = 0
        foreach ($accion in $script:equipoList) {
            $estado = Get-EquipoActionState $accion
            $recomendada = Test-EquipoRecommended $accion
            $item = New-Object System.Windows.Forms.ListViewItem([string]$accion.Name)
            $textoEstado = [string]$estado.Text
            if ($estado.Applied) { $textoEstado = [char]0x2713 + ' ' + $textoEstado }
            [void]$item.SubItems.Add($textoEstado)
            [void]$item.SubItems.Add($(if ($recomendada) { 'Sí' } else { '' }))
            $item.Tag = [pscustomobject]@{ Action = $accion; State = $estado; Recommended = $recomendada }
            $item.ToolTipText = [string]$accion.Description
            if ($grupos.ContainsKey([string]$accion.Group)) { $item.Group = $grupos[[string]$accion.Group] }
            if ($estado.Applied) {
                $item.ForeColor = [System.Drawing.Color]::FromArgb(0, 120, 0)
                $aplicados++
            } elseif ($recomendada) {
                $item.Checked = $true
                $item.Font = $script:boldFont
                $pendientes++
            }
            [void]$script:eqList.Items.Add($item)
        }
        $grpEqActions.Text = ('Ajustes para este equipo ({0} ya aplicados, {1} recomendados pendientes)' -f $aplicados, $pendientes)
    } finally {
        $script:eqList.EndUpdate()
        $script:eqSyncing = $false
    }
    if ($script:btnEqUndo) { $script:btnEqUndo.Enabled = $false }
}

function Update-EquipoTab {
    $script:hardware = Get-HardwareProfile
    $script:equipoDetected = $true
    $tipo = 'Sobremesa'
    if ($script:hardware.IsLaptop) { $tipo = 'Portátil' }
    $script:lblEquipoTipo.Text = ('{0}  ·  disco {1}  ·  {2} GB de RAM' -f $tipo, $script:hardware.DiskKind, $script:hardware.RamGB)
    $script:lblEquipoDetalle.Text = (Get-HardwareSummary -Perfil $script:hardware)
    $script:btnEqBattery.Enabled = [bool]$script:hardware.HasBattery

    $script:equipoList = @($script:equipoActions | Where-Object {
        (-not $_.MinBuild) -or ($script:WinBuild -ge [int]$_.MinBuild)
    } | Where-Object {
        ($_.Target -eq 'Todos') -or
        ($_.Target -eq 'Win11' -and $script:WinBuild -ge 22000) -or
        ($_.Target -eq 'Portatil' -and $script:hardware.IsLaptop) -or
        ($_.Target -eq 'Sobremesa' -and -not $script:hardware.IsLaptop) -or
        ($_.Target -eq 'SSD' -and ($script:hardware.DiskKind -eq 'SSD' -or $script:hardware.DiskKind -eq 'Mixto')) -or
        ($_.Target -eq 'HDD' -and ($script:hardware.DiskKind -eq 'HDD' -or $script:hardware.DiskKind -eq 'Mixto'))
    })
    Update-EquipoList

    Add-TabLog $script:eqLog ('Equipo detectado: {0}' -f (Get-HardwareSummary -Perfil $script:hardware)) 'STEP'
    $pend = @($script:eqList.Items | Where-Object { $_.Checked }).Count
    if ($pend -gt 0) {
        Add-TabLog $script:eqLog ('Hay {0} ajuste(s) recomendado(s) sin aplicar; ya están marcados. Revísalos y pulsa "Aplicar marcados".' -f $pend)
    } else {
        Add-TabLog $script:eqLog 'Todos los ajustes recomendados para este equipo ya están aplicados.' 'OK'
    }
    Write-Diag ('Equipo: ' + (Get-HardwareSummary -Perfil $script:hardware))
}

function Show-EquipoDetail {
    if ($script:eqList.SelectedItems.Count -eq 0) { return }
    $info = $script:eqList.SelectedItems[0].Tag
    if (-not $info) { return }
    $accion = $info.Action
    $lineas = @(
        ('{0}   [estado actual: {1}]' -f $accion.Name, $info.State.Text),
        '',
        $accion.Description
    )
    $extra = @()
    if ($info.Recommended) { $extra += 'Recomendado para este equipo.' }
    if ($accion.NeedsAdmin) { $extra += 'Necesita permisos de administrador.' }
    if ($accion.Undo) { $extra += 'Se puede deshacer con el botón "Deshacer".' }
    if ($extra.Count -gt 0) { $lineas += ''; $lineas += ($extra -join ' ') }
    $script:eqDetail.Text = ($lineas -join "`r`n")
}

# Devuelve al valor de fábrica de Windows el ajuste seleccionado (solo los
# ajustes que definen un bloque Undo, es decir, el grupo "Windows más ágil").
function Update-EquipoUndoButton {
    $puede = $false
    if ($script:eqList.SelectedItems.Count -gt 0) {
        $info = $script:eqList.SelectedItems[0].Tag
        if ($info -and $info.Action.Undo -and $info.State.Applied) { $puede = $true }
    }
    $script:btnEqUndo.Enabled = $puede
}

function Invoke-EquipoUndo {
    if ($script:eqList.SelectedItems.Count -eq 0) { return }
    $info = $script:eqList.SelectedItems[0].Tag
    if (-not $info -or -not $info.Action.Undo) { return }
    $accion = $info.Action
    if ($accion.NeedsAdmin -and -not (Assert-Admin)) { return }
    if (-not $UiSmokeTest) {
        $respuesta = [System.Windows.Forms.MessageBox]::Show(
            ("Se va a deshacer este ajuste y dejarlo como viene en Windows:`n`n - {0}   (ahora: {1})`n`n¿Continuar?" -f $accion.Name, $info.State.Text),
            "$script:AppName - deshacer ajuste", 'YesNo', 'Question')
        if ($respuesta -ne 'Yes') { return }
    }
    $script:busy = $true
    $script:form.UseWaitCursor = $true
    try {
        Add-TabLog $script:eqLog ('Deshacer: {0}' -f $accion.Name) 'STEP'
        & $accion.Undo
        $script:statusLabel.Text = 'Ajuste deshecho'
    } catch {
        Add-TabLog $script:eqLog ('Error al deshacer: {0}' -f $_.Exception.Message) 'ERROR'
        Write-Diag ('Rendimiento, deshacer "{0}": {1}' -f $accion.Name, $_.Exception.ToString())
    } finally {
        $script:form.UseWaitCursor = $false
        $script:busy = $false
    }
    Update-EquipoList
    Update-EquipoUndoButton
}

function Set-EquipoChecked {
    param([bool]$Value, [switch]$OnlyRecommended)
    $script:eqSyncing = $true
    try {
        foreach ($item in $script:eqList.Items) {
            $info = $item.Tag
            if ($OnlyRecommended) {
                $item.Checked = ($info.Recommended -and -not $info.State.Applied)
            } else {
                $item.Checked = $Value
            }
        }
    } finally {
        $script:eqSyncing = $false
    }
}

function Invoke-EquipoActions {
    $marcados = @($script:eqList.Items | Where-Object { $_.Checked })
    if ($marcados.Count -eq 0) {
        [void][System.Windows.Forms.MessageBox]::Show('Marca al menos un ajuste de la lista.', $script:AppName, 'OK', 'Information')
        return
    }
    $seleccionadas = @($marcados | ForEach-Object { $_.Tag.Action })
    $necesitaAdmin = @($seleccionadas | Where-Object { $_.NeedsAdmin }).Count -gt 0
    if ($necesitaAdmin -and -not (Assert-Admin)) { return }

    $lineas = foreach ($item in $marcados) {
        ' - {0}   (ahora: {1})' -f $item.Tag.Action.Name, $item.Tag.State.Text
    }
    $respuesta = [System.Windows.Forms.MessageBox]::Show(
        ("Se van a aplicar {0} cambios en este equipo:`n`n{1}`n`nAntes se guarda una copia de los ajustes: se puede deshacer con 'Revertir cambios' en la pestaña Optimización.`nAlgunos cambios necesitan cerrar sesión o reiniciar para notarse.`n`n¿Continuar?" -f $seleccionadas.Count, ($lineas -join "`n")),
        "$script:AppName - confirmar", 'YesNo', 'Question')
    if ($respuesta -ne 'Yes') { return }

    $script:busy = $true
    $script:btnEqApply.Enabled = $false
    $script:form.UseWaitCursor = $true
    $okCount = 0
    $errCount = 0
    try {
        if ($script:IsAdmin) {
            Save-OptimizationSnapshot
            if ($script:optSnapshotFile) {
                Add-TabLog $script:eqLog ('Copia de los ajustes guardada antes de aplicar: {0}' -f (Split-Path -Leaf $script:optSnapshotFile)) 'OK'
            }
        } else {
            Add-TabLog $script:eqLog 'Sin permisos de administrador no se guarda la copia para revertir.' 'WARN'
        }
        Add-TabLog $script:eqLog ('=== Aplicando {0} ajustes ===' -f $seleccionadas.Count) 'STEP'
        foreach ($accion in $seleccionadas) {
            Add-TabLog $script:eqLog $accion.Name 'STEP'
            $script:statusLabel.Text = ('Aplicando: {0}' -f $accion.Name)
            [System.Windows.Forms.Application]::DoEvents()
            try {
                & $accion.Run
                $okCount++
            } catch {
                $errCount++
                Add-TabLog $script:eqLog ('Error: {0}' -f $_.Exception.Message) 'ERROR'
                Write-Diag ('Rendimiento, ajuste "{0}": {1}' -f $accion.Name, $_.Exception.ToString())
            }
        }
    } finally {
        $script:btnEqApply.Enabled = $true
        $script:form.UseWaitCursor = $false
        $script:busy = $false
    }

    $script:statusLabel.Text = 'Ajustes aplicados'
    Add-TabLog $script:eqLog ('=== Fin: {0} correctos, {1} con error ===' -f $okCount, $errCount) 'STEP'
    Update-EquipoList
    [void][System.Windows.Forms.MessageBox]::Show(
        ("Ajustes aplicados: {0}`nCon error: {1}`n`nLa columna 'Estado actual' ya muestra cómo queda el equipo. Reinicia para que todos los cambios surtan efecto." -f $okCount, $errCount),
        $script:AppName, 'OK', 'Information')
}

# ---------------------------------------------------------------------------
# Diagnóstico de la pestaña Rendimiento (solo lectura)
# ---------------------------------------------------------------------------

function Get-DiskHealthText {
    param([string]$Health)
    switch ($Health) {
        'Healthy'   { return 'correcta' }
        'Warning'   { return 'con avisos' }
        'Unhealthy' { return 'MALA' }
        ''          { return 'desconocida' }
    }
    return $Health
}

# Salud de los discos con los contadores SMART que expone Windows.
function Get-DiskHealthInfo {
    $resultado = @()
    $discos = @(Get-PhysicalDisk -ErrorAction Stop | Sort-Object DeviceId)
    foreach ($d in $discos) {
        $r = $null
        if ($script:IsAdmin) {
            try { $r = $d | Get-StorageReliabilityCounter -ErrorAction Stop } catch { }
        }
        $avisos = @()
        $salud = [string]$d.HealthStatus
        if ($salud -and $salud -ne 'Healthy') { $avisos += ('salud {0}' -f (Get-DiskHealthText $salud)) }
        $temp = $null; $desgaste = $null; $horas = $null; $errLectura = $null; $errEscritura = $null
        if ($r) {
            if ($r.Temperature -gt 0) { $temp = [int]$r.Temperature }
            if ($null -ne $r.Wear) { $desgaste = [int]$r.Wear }
            if ($r.PowerOnHours -gt 0) { $horas = [int64]$r.PowerOnHours }
            if ($null -ne $r.ReadErrorsUncorrected) { $errLectura = [int64]$r.ReadErrorsUncorrected }
            if ($null -ne $r.WriteErrorsUncorrected) { $errEscritura = [int64]$r.WriteErrorsUncorrected }
        }
        if ($temp -and $temp -ge 60) { $avisos += ('temperatura alta ({0} °C)' -f $temp) }
        if ($null -ne $desgaste -and $desgaste -ge 80) { $avisos += ('desgaste del {0} %' -f $desgaste) }
        if ($errLectura -gt 0) { $avisos += ('{0} errores de lectura sin corregir' -f $errLectura) }
        if ($errEscritura -gt 0) { $avisos += ('{0} errores de escritura sin corregir' -f $errEscritura) }
        $resultado += [pscustomobject]@{
            Name        = [string]$d.FriendlyName
            Media       = [string]$d.MediaType
            Bus         = [string]$d.BusType
            SizeGB      = [math]::Round(($d.Size / 1GB), 0)
            Health      = $salud
            Temperature = $temp
            Wear        = $desgaste
            Hours       = $horas
            ReadErrors  = $errLectura
            WriteErrors = $errEscritura
            Warnings    = $avisos
            HasCounters = [bool]$r
        }
    }
    return $resultado
}

function Show-DiskHealth {
    $script:form.UseWaitCursor = $true
    [System.Windows.Forms.Application]::DoEvents()
    try {
        Add-TabLog $script:eqLog 'Salud de los discos' 'STEP'
        $discos = @(Get-DiskHealthInfo)
        foreach ($d in $discos) {
            $partes = @(('{0} GB' -f $d.SizeGB), $d.Media, $d.Bus, ('salud: {0}' -f (Get-DiskHealthText $d.Health)))
            if ($d.Temperature) { $partes += ('{0} °C' -f $d.Temperature) }
            if ($null -ne $d.Wear) { $partes += ('desgaste {0} %' -f $d.Wear) }
            if ($d.Hours) { $partes += ('{0:N0} h encendido' -f $d.Hours) }
            $nivel = 'OK'
            if ($d.Warnings.Count -gt 0) { $nivel = 'WARN' }
            if ($d.Health -and $d.Health -ne 'Healthy') { $nivel = 'ERROR' }
            Add-TabLog $script:eqLog ('{0}: {1}' -f $d.Name, ($partes -join ' | ')) $nivel
            foreach ($a in $d.Warnings) { Add-TabLog $script:eqLog ('   ' + $a) $(if ($nivel -eq 'ERROR') { 'ERROR' } else { 'WARN' }) }
            if (-not $d.HasCounters) {
                if ($script:IsAdmin) { Add-TabLog $script:eqLog '   El disco no informa de temperatura ni desgaste (habitual en USB y algunos controladores).' }
                else { Add-TabLog $script:eqLog '   Temperatura, desgaste y errores: abre el programa como administrador para verlos.' }
            }
        }
        if ($discos.Count -eq 0) { Add-TabLog $script:eqLog 'No se ha encontrado ningún disco.' 'WARN' }
        foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' -and $_.Size -gt 0 } | Sort-Object DriveLetter)) {
            $libre = [math]::Round(($v.SizeRemaining / 1GB), 1)
            $pct = [math]::Round(($v.SizeRemaining / $v.Size) * 100, 0)
            $nivelV = 'INFO'
            if ($pct -lt 10) { $nivelV = 'WARN' }
            Add-TabLog $script:eqLog ('Unidad {0}: {1} GB libres de {2} GB ({3} % libre)' -f $v.DriveLetter, $libre, [math]::Round(($v.Size / 1GB), 1), $pct) $nivelV
        }
    } catch {
        Add-TabLog $script:eqLog ('No se pudo leer el estado de los discos: {0}' -f $_.Exception.Message) 'ERROR'
    } finally {
        $script:form.UseWaitCursor = $false
    }
}

# Pantallazos azules (BugCheck) y apagados inesperados de los últimos días.
function Get-CrashEvents {
    param([int]$Days = 60)
    $desde = (Get-Date).AddDays(-$Days)
    $eventos = @()
    $filtros = @(
        @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WER-SystemErrorReporting'; Id = 1001; StartTime = $desde },
        @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-Kernel-Power'; Id = 41; StartTime = $desde },
        @{ LogName = 'System'; ProviderName = 'EventLog'; Id = 6008; StartTime = $desde }
    )
    foreach ($f in $filtros) {
        try {
            foreach ($e in @(Get-WinEvent -FilterHashtable $f -MaxEvents 50 -ErrorAction Stop)) {
                $tipo = 'Apagado inesperado'
                $detalle = ''
                if ($e.Id -eq 1001) {
                    $tipo = 'Pantallazo azul'
                    $m = [regex]::Match([string]$e.Message, '0x[0-9a-fA-F]{8}')
                    if ($m.Success) { $detalle = 'código ' + $m.Value }
                } elseif ($e.Id -eq 41) {
                    $tipo = 'Reinicio sin apagado correcto'
                    try {
                        $codigo = [int64]($e.Properties[0].Value)
                        if ($codigo -ne 0) { $detalle = ('código 0x{0:X}' -f $codigo) }
                    } catch { }
                }
                $eventos += [pscustomobject]@{ Time = $e.TimeCreated; Kind = $tipo; Detail = $detalle; Id = $e.Id }
            }
        } catch { }
    }
    return @($eventos | Sort-Object Time -Descending)
}

function Show-CrashHistory {
    $script:form.UseWaitCursor = $true
    [System.Windows.Forms.Application]::DoEvents()
    try {
        Add-TabLog $script:eqLog 'Pantallazos azules y apagados inesperados (últimos 60 días)' 'STEP'
        $eventos = @(Get-CrashEvents -Days 60)
        if ($eventos.Count -eq 0) {
            Add-TabLog $script:eqLog 'No hay pantallazos azules ni apagados inesperados en los últimos 60 días.' 'OK'
        } else {
            foreach ($e in @($eventos | Select-Object -First 25)) {
                $texto = ('{0:dd/MM/yyyy HH:mm}  {1}' -f $e.Time, $e.Kind)
                if ($e.Detail) { $texto += ('  ({0})' -f $e.Detail) }
                Add-TabLog $script:eqLog $texto $(if ($e.Id -eq 1001) { 'ERROR' } else { 'WARN' })
            }
            $azules = @($eventos | Where-Object { $_.Id -eq 1001 }).Count
            Add-TabLog $script:eqLog ('Total: {0} pantallazo(s) azul(es) y {1} apagado(s) o reinicio(s) inesperado(s).' -f $azules, ($eventos.Count - $azules))
            Add-TabLog $script:eqLog 'Un "reinicio sin apagado correcto" aislado suele ser un corte de luz o haber mantenido pulsado el botón de encendido. Si se repiten, revisa fuente de alimentación, temperaturas y drivers.'
        }
        $minidump = Join-Path $env:SystemRoot 'Minidump'
        $volcados = @(Get-ChildItem -LiteralPath $minidump -Filter '*.dmp' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending)
        if ($volcados.Count -gt 0) {
            Add-TabLog $script:eqLog ('Minivolcados en {0}: {1} (el último del {2:dd/MM/yyyy}). Se pueden analizar con WinDbg o BlueScreenView.' -f $minidump, $volcados.Count, $volcados[0].LastWriteTime)
        }
    } catch {
        Add-TabLog $script:eqLog ('No se pudo leer el registro de eventos: {0}' -f $_.Exception.Message) 'ERROR'
    } finally {
        $script:form.UseWaitCursor = $false
    }
}

function Start-MemoryDiagnostic {
    $r = [System.Windows.Forms.MessageBox]::Show(
        "Se abrirá el Diagnóstico de memoria de Windows.`n`nTe dará a elegir entre reiniciar ahora o hacer la prueba la próxima vez que arranques. La prueba tarda entre 10 y 30 minutos y el resultado aparece al volver a entrar en Windows (y en el Visor de eventos, origen MemoryDiagnostics-Results).`n`n¿Abrirlo?",
        "$script:AppName - test de memoria", 'YesNo', 'Question')
    if ($r -ne 'Yes') { return }
    try {
        Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\mdsched.exe') | Out-Null
        Add-TabLog $script:eqLog 'Diagnóstico de memoria de Windows abierto. Elige cuándo reiniciar en su ventana.' 'OK'
    } catch {
        Add-TabLog $script:eqLog ('No se pudo abrir el diagnóstico de memoria: {0}' -f $_.Exception.Message) 'ERROR'
    }
}

function New-BatteryReport {
    $destino = Join-Path ([Environment]::GetFolderPath('Desktop')) ('informe-bateria-{0:yyyyMMdd-HHmm}.html' -f (Get-Date))
    try {
        & "$env:SystemRoot\System32\powercfg.exe" /batteryreport /output $destino 2>&1 | Out-Null
        if (-not (Test-Path -LiteralPath $destino)) { throw 'powercfg no ha generado el informe.' }
        Add-TabLog $script:eqLog ('Informe de batería creado: {0}' -f $destino) 'OK'
        Open-AsDesktopUser $destino
    } catch {
        Add-TabLog $script:eqLog ('No se pudo crear el informe de batería: {0}' -f $_.Exception.Message) 'ERROR'
    }
}

# Salud de la batería: capacidad actual frente a la de fábrica.
function Get-BatteryHealth {
    try {
        $diseno = @(Get-CimInstance -Namespace 'root/wmi' -ClassName 'BatteryStaticData' -ErrorAction Stop)[0].DesignedCapacity
        $actual = @(Get-CimInstance -Namespace 'root/wmi' -ClassName 'BatteryFullChargedCapacity' -ErrorAction Stop)[0].FullChargedCapacity
        if ($diseno -gt 0 -and $actual -gt 0) {
            return [pscustomobject]@{ Design = [int64]$diseno; Full = [int64]$actual; Percent = [math]::Round(($actual / $diseno) * 100, 0) }
        }
    } catch { }
    return $null
}

function ConvertTo-HtmlText {
    param($Value)
    return [System.Net.WebUtility]::HtmlEncode([string]$Value)
}

# Informe HTML del equipo, pensado para guardarlo o entregarlo al cliente.
function New-EquipoReport {
    $script:form.UseWaitCursor = $true
    $script:statusLabel.Text = 'Creando el informe del equipo...'
    [System.Windows.Forms.Application]::DoEvents()
    try {
        if (-not $script:hardware) { $script:hardware = Get-HardwareProfile }
        $cs = $null; $bios = $null; $os = $null; $cpu = $null
        try { $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop } catch { }
        try { $bios = Get-CimInstance Win32_BIOS -ErrorAction Stop } catch { }
        try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } catch { }
        try { $cpu = Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1 } catch { }
        $modulos = @()
        try { $modulos = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop) } catch { }
        $gpus = @()
        try { $gpus = @(Get-CimInstance Win32_VideoController -ErrorAction Stop | Where-Object { $_.Name }) } catch { }

        $filas = New-Object System.Collections.ArrayList
        function Add-Fila { param($Seccion, $Campo, $Valor, $Nivel = '') [void]$filas.Add([pscustomobject]@{ S = $Seccion; C = $Campo; V = $Valor; N = $Nivel }) }

        if ($cs) {
            Add-Fila 'Equipo' 'Nombre del equipo' $cs.Name
            Add-Fila 'Equipo' 'Fabricante y modelo' (('{0} {1}' -f $cs.Manufacturer, $cs.Model).Trim())
        }
        Add-Fila 'Equipo' 'Tipo' $(if ($script:hardware.IsLaptop) { 'Portátil' } else { 'Sobremesa' })
        if ($bios) {
            Add-Fila 'Equipo' 'Número de serie' ([string]$bios.SerialNumber).Trim()
            $fechaBios = ''
            if ($bios.ReleaseDate) { $fechaBios = ' (' + ([datetime]$bios.ReleaseDate).ToString('dd/MM/yyyy') + ')' }
            Add-Fila 'Equipo' 'BIOS / UEFI' (([string]$bios.SMBIOSBIOSVersion).Trim() + $fechaBios)
        }
        if ($os) {
            Add-Fila 'Windows' 'Sistema' ('{0} (compilación {1})' -f $os.Caption, $os.BuildNumber)
            try {
                $dv = Get-RegValueSafe 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' 'DisplayVersion'
                if ($dv) { Add-Fila 'Windows' 'Versión' $dv }
            } catch { }
            if ($os.InstallDate) { Add-Fila 'Windows' 'Instalado el' ([datetime]$os.InstallDate).ToString('dd/MM/yyyy') }
            if ($os.LastBootUpTime) {
                $encendido = (Get-Date) - [datetime]$os.LastBootUpTime
                Add-Fila 'Windows' 'Encendido desde' ('{0:dd/MM/yyyy HH:mm} ({1} días y {2} h)' -f [datetime]$os.LastBootUpTime, $encendido.Days, $encendido.Hours)
            }
        }
        if ($cpu) { Add-Fila 'Hardware' 'Procesador' ('{0} ({1} núcleos, {2} hilos)' -f ([string]$cpu.Name).Trim(), $cpu.NumberOfCores, $cpu.NumberOfLogicalProcessors) }
        $detalleRam = ''
        if ($modulos.Count -gt 0) {
            $detalleRam = ' en ' + (($modulos | ForEach-Object { '{0} GB{1}' -f [math]::Round($_.Capacity / 1GB), $(if ($_.Speed) { ' ' + $_.Speed + ' MHz' } else { '' }) }) -join ' + ')
        }
        Add-Fila 'Hardware' 'Memoria RAM' ('{0} GB{1}' -f $script:hardware.RamGB, $detalleRam)
        foreach ($g in $gpus) { Add-Fila 'Hardware' 'Gráfica' $g.Name }

        try {
            foreach ($d in @(Get-DiskHealthInfo)) {
                $texto = ('{0} · {1} GB · {2} {3} · salud: {4}' -f $d.Name, $d.SizeGB, $d.Media, $d.Bus, (Get-DiskHealthText $d.Health))
                if ($d.Temperature) { $texto += (' · {0} °C' -f $d.Temperature) }
                if ($null -ne $d.Wear) { $texto += (' · desgaste {0} %' -f $d.Wear) }
                if ($d.Hours) { $texto += (' · {0:N0} h' -f $d.Hours) }
                $nivel = 'OK'
                if ($d.Warnings.Count -gt 0) { $nivel = 'WARN'; $texto += (' · ' + ($d.Warnings -join ', ')) }
                if ($d.Health -and $d.Health -ne 'Healthy') { $nivel = 'BAD' }
                Add-Fila 'Discos' 'Disco' $texto $nivel
            }
        } catch { }
        foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' -and $_.Size -gt 0 } | Sort-Object DriveLetter)) {
            $pct = [math]::Round(($v.SizeRemaining / $v.Size) * 100, 0)
            Add-Fila 'Discos' ('Unidad {0}:' -f $v.DriveLetter) ('{0} GB libres de {1} GB ({2} %)' -f [math]::Round($v.SizeRemaining / 1GB, 1), [math]::Round($v.Size / 1GB, 1), $pct) $(if ($pct -lt 10) { 'WARN' } else { 'OK' })
        }

        if ($script:hardware.HasBattery) {
            $bat = Get-BatteryHealth
            if ($bat) {
                $nivelBat = 'OK'
                if ($bat.Percent -lt 60) { $nivelBat = 'BAD' } elseif ($bat.Percent -lt 80) { $nivelBat = 'WARN' }
                Add-Fila 'Batería' 'Capacidad actual' ('{0} % de la original ({1:N0} de {2:N0} mWh)' -f $bat.Percent, $bat.Full, $bat.Design) $nivelBat
            } else {
                Add-Fila 'Batería' 'Capacidad actual' 'No disponible (abre el programa como administrador)'
            }
        }

        try {
            $problemas = @(Get-CimInstance Win32_PnPEntity -ErrorAction Stop | Where-Object { $_.ConfigManagerErrorCode -and $_.ConfigManagerErrorCode -ne 0 -and $_.ConfigManagerErrorCode -ne 22 })
            if ($problemas.Count -eq 0) {
                Add-Fila 'Drivers' 'Componentes con problemas' 'Ninguno' 'OK'
            } else {
                foreach ($p in $problemas) { Add-Fila 'Drivers' 'Componente con problemas' ('{0} (código {1})' -f $p.Name, $p.ConfigManagerErrorCode) 'WARN' }
            }
        } catch { }

        $eventos = @(Get-CrashEvents -Days 60)
        $azules = @($eventos | Where-Object { $_.Id -eq 1001 }).Count
        Add-Fila 'Estabilidad' 'Pantallazos azules (60 días)' $azules $(if ($azules -gt 0) { 'BAD' } else { 'OK' })
        Add-Fila 'Estabilidad' 'Apagados inesperados (60 días)' ($eventos.Count - $azules) $(if (($eventos.Count - $azules) -gt 2) { 'WARN' } else { 'OK' })

        try {
            foreach ($chk in @(Get-SecurityChecks)) { Add-Fila ('Seguridad · ' + $chk.Group) $chk.Name $chk.Value $chk.Level }
        } catch { }

        $nombreEquipo = $env:COMPUTERNAME
        $fecha = Get-Date
        $html = New-Object System.Text.StringBuilder
        [void]$html.AppendLine('<!DOCTYPE html><html lang="es"><head><meta charset="utf-8">')
        [void]$html.AppendLine(('<title>Informe del equipo {0}</title>' -f (ConvertTo-HtmlText $nombreEquipo)))
        [void]$html.AppendLine('<style>body{font-family:"Segoe UI",Arial,sans-serif;color:#222;margin:32px auto;max-width:960px;padding:0 16px}header{border-bottom:3px solid #0078d7;margin-bottom:20px;padding-bottom:10px}h1{margin:0;font-size:24px}.sub{color:#666;font-size:13px}h2{font-size:16px;margin:26px 0 6px;color:#0078d7}table{border-collapse:collapse;width:100%;font-size:13.5px}td{border-bottom:1px solid #e5e5e5;padding:6px 8px;vertical-align:top}td.c{width:32%;color:#555}tr.OK td.v{color:#107c10}tr.WARN td.v{color:#b06000;font-weight:600}tr.BAD td.v{color:#c42b1c;font-weight:700}.res{display:flex;gap:12px;margin:10px 0 4px}.res div{flex:1;border-radius:6px;padding:10px 12px;font-size:13px}.r1{background:#e7f4e7}.r2{background:#fff3e0}.r3{background:#fde7e7}.res b{font-size:20px;display:block}footer{margin-top:28px;color:#888;font-size:12px;border-top:1px solid #ddd;padding-top:8px}@media print{body{margin:0}}</style></head><body>')
        [void]$html.AppendLine(('<header><h1>Informe del equipo {0}</h1><div class="sub">{1} · Generado el {2:dd/MM/yyyy} a las {2:HH:mm}</div></header>' -f (ConvertTo-HtmlText $nombreEquipo), (ConvertTo-HtmlText $script:ReportBrand), $fecha))
        $nOk = @($filas | Where-Object { $_.N -eq 'OK' }).Count
        $nWarn = @($filas | Where-Object { $_.N -eq 'WARN' }).Count
        $nBad = @($filas | Where-Object { $_.N -eq 'BAD' }).Count
        [void]$html.AppendLine(('<div class="res"><div class="r1"><b>{0}</b>comprobaciones correctas</div><div class="r2"><b>{1}</b>avisos</div><div class="r3"><b>{2}</b>problemas</div></div>' -f $nOk, $nWarn, $nBad))
        $seccionActual = ''
        foreach ($f in $filas) {
            if ($f.S -ne $seccionActual) {
                if ($seccionActual) { [void]$html.AppendLine('</table>') }
                [void]$html.AppendLine(('<h2>{0}</h2><table>' -f (ConvertTo-HtmlText $f.S)))
                $seccionActual = $f.S
            }
            [void]$html.AppendLine(('<tr class="{0}"><td class="c">{1}</td><td class="v">{2}</td></tr>' -f $f.N, (ConvertTo-HtmlText $f.C), (ConvertTo-HtmlText $f.V)))
        }
        if ($seccionActual) { [void]$html.AppendLine('</table>') }
        [void]$html.AppendLine(('<footer>{0} {1} · desarrollado por Sylred Computers. Este informe solo recoge información: no se ha modificado nada en el equipo al generarlo. Contiene datos de este equipo (hardware, seguridad y cuentas): trátalo como confidencial y compártelo solo con quien lo necesite.</footer></body></html>' -f (ConvertTo-HtmlText $script:AppName), $script:AppVersion))

        $carpeta = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'WinTaller\Informes'
        [void](New-Item -ItemType Directory -Path $carpeta -Force -ErrorAction Stop)
        $nombreSeguro = ($nombreEquipo -replace '[^A-Za-z0-9_-]', '_')
        $archivo = Join-Path $carpeta ('Informe-{0}-{1:yyyyMMdd-HHmm}.html' -f $nombreSeguro, $fecha)
        [System.IO.File]::WriteAllText($archivo, $html.ToString(), (New-Object System.Text.UTF8Encoding($true)))
        Add-TabLog $script:eqLog ('Informe del equipo creado: {0} ({1} correctos, {2} avisos, {3} problemas)' -f $archivo, $nOk, $nWarn, $nBad) 'OK'
        if (-not $UiSmokeTest) { Open-AsDesktopUser $archivo }
        return $archivo
    } catch {
        Add-TabLog $script:eqLog ('No se pudo crear el informe: {0}' -f $_.Exception.Message) 'ERROR'
        Write-Diag ('Informe del equipo: ' + $_.Exception.ToString())
    } finally {
        $script:form.UseWaitCursor = $false
        $script:statusLabel.Text = 'Listo'
    }
}

