# Script hijo que descarga e instala los drivers en un proceso aparte, para que
# la ventana siga respondiendo y se pueda cancelar.
$script:drvChildScript = @'
param(
    [Parameter(Mandatory=$true)][string]$OutFile,
    [string]$Ids = '',
    [switch]$Search
)

$ErrorActionPreference = 'Stop'

function Write-Evento {
    param([hashtable]$Datos)
    try {
        Add-Content -LiteralPath $OutFile -Value ($Datos | ConvertTo-Json -Compress) -Encoding UTF8
    } catch { }
}

function Get-Texto {
    param([int]$Codigo)
    switch ($Codigo) {
        0 { return 'sin iniciar' }
        1 { return 'en curso' }
        2 { return 'correcto' }
        3 { return 'correcto con errores' }
        4 { return 'fallido' }
        5 { return 'cancelado' }
    }
    return ('codigo ' + $Codigo)
}

try {
    $admin = $false
    try {
        $identidad = [Security.Principal.WindowsIdentity]::GetCurrent()
        $principal = New-Object Security.Principal.WindowsPrincipal($identidad)
        $admin = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch { }

    # Solo se aceptan identificadores con formato GUID (se usan en el criterio de búsqueda).
    $deseados = @($Ids -split ',' | ForEach-Object { $_.Trim() } |
        Where-Object { $_ -match '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$' })
    $sesion = New-Object -ComObject 'Microsoft.Update.Session'
    $sesion.ClientApplicationID = 'WinTaller'
    $buscador = $sesion.CreateUpdateSearcher()
    $buscador.Online = $true

    $mapa = @{}
    $resultado = $null
    if ($Search) {
        $resultado = $buscador.Search("IsInstalled=0 and Type='Driver'")
    } else {
        # Se busca cada driver por su UpdateID: repetir la búsqueda general
        # puede devolver una lista distinta y dar "ya no está disponible".
        foreach ($id in $deseados) {
            try {
                $r = $buscador.Search(("UpdateID='{0}'" -f $id))
                foreach ($u in $r.Updates) { $mapa[[string]$u.Identity.UpdateID] = $u }
            } catch { }
        }
        if (@($deseados | Where-Object { -not $mapa.ContainsKey($_) }).Count -gt 0) {
            try {
                $r = $buscador.Search("IsInstalled=0 and Type='Driver'")
                foreach ($u in $r.Updates) {
                    $clave = [string]$u.Identity.UpdateID
                    if (-not $mapa.ContainsKey($clave)) { $mapa[$clave] = $u }
                }
            } catch { }
        }
    }

    if ($Search) {
        foreach ($u in $resultado.Updates) {
            $fecha = ''
            try { if ($u.DriverVerDate) { $fecha = ([datetime]$u.DriverVerDate).ToString('yyyy-MM-dd') } } catch { }
            $mb = 0
            try { $mb = [math]::Round(($u.MaxDownloadSize / 1MB), 1) } catch { }
            $hw = ''
            try { $hw = [string]$u.DriverHardwareID } catch { }
            Write-Evento @{
                t         = 'driver'
                id        = [string]$u.Identity.UpdateID
                titulo    = [string]$u.Title
                proveedor = [string]$u.DriverProvider
                clase     = [string]$u.DriverClass
                fecha     = $fecha
                mb        = $mb
                hwid      = $hw
            }
        }
        Write-Evento @{ t = 'fin' }
        return
    }

    foreach ($id in $deseados) {
        if (-not $mapa.ContainsKey($id)) {
            Write-Evento @{ t = 'falta'; id = $id }
            continue
        }
        $u = $mapa[$id]
        $titulo = [string]$u.Title
        if ($u.IsInstalled) {
            Write-Evento @{ t = 'resultado'; id = $id; titulo = $titulo; ok = $true; codigo = 2; texto = 'ya estaba instalado'; reinicio = $false }
            continue
        }
        Write-Evento @{ t = 'inicio'; id = $id; titulo = $titulo }
        if (-not $admin) {
            Write-Evento @{ t = 'resultado'; id = $id; titulo = $titulo; ok = $false; codigo = -2; texto = 'hacen falta permisos de administrador'; reinicio = $false }
            continue
        }
        try {
            if (-not $u.EulaAccepted) { [void]$u.AcceptEula() }
            $coleccion = New-Object -ComObject 'Microsoft.Update.UpdateColl'
            [void]$coleccion.Add($u)

            $descargador = $sesion.CreateUpdateDownloader()
            $descargador.Updates = $coleccion
            $descarga = $descargador.Download()
            if ([int]$descarga.ResultCode -ne 2) {
                Write-Evento @{ t = 'resultado'; id = $id; titulo = $titulo; ok = $false; codigo = [int]$descarga.ResultCode; texto = ('descarga ' + (Get-Texto ([int]$descarga.ResultCode))); reinicio = $false }
                continue
            }

            Write-Evento @{ t = 'descargado'; id = $id; titulo = $titulo }

            $instalador = $sesion.CreateUpdateInstaller()
            $instalador.Updates = $coleccion
            $instalacion = $instalador.Install()
            $codigo = [int]$instalacion.ResultCode
            $ok = ($codigo -eq 2 -or $codigo -eq 3)
            if ($codigo -eq 3) {
                $texto = 'instalado, pero Windows informa de algun error'
            } else {
                $texto = Get-Texto $codigo
            }
            Write-Evento @{ t = 'resultado'; id = $id; titulo = $titulo; ok = $ok; codigo = $codigo; texto = $texto; reinicio = [bool]$instalacion.RebootRequired }
        } catch {
            Write-Evento @{ t = 'resultado'; id = $id; titulo = $titulo; ok = $false; codigo = -1; texto = $_.Exception.Message; reinicio = $false }
        }
    }
    Write-Evento @{ t = 'fin' }
} catch {
    Write-Evento @{ t = 'fatal'; mensaje = $_.Exception.Message }
}
'@

