function Get-AppSelection {
    $lista = @()
    $porId = @{}
    foreach ($item in $script:appList.Items) {
        if ($item.Tag) { $porId[[string]$item.Tag.Id] = $item }
    }
    foreach ($app in $script:appCatalog) {
        if (-not $script:appCheckedById.ContainsKey($app.Id)) { continue }
        if (-not [bool]$script:appCheckedById[$app.Id]) { continue }
        if ($script:appStateById.ContainsKey($app.Id) -and [string]$script:appStateById[$app.Id] -eq 'Instalado') { continue }
        if ($porId.ContainsKey($app.Id)) { $lista += $porId[$app.Id] }
    }
    return $lista
}

function Update-AppList {
    if (-not $script:appList) { return }
    $filtro = ''
    if ($script:txtPrgSearch) { $filtro = $script:txtPrgSearch.Text.Trim().ToLowerInvariant() }
    $mostrados = 0
    $script:appList.BeginUpdate()
    try {
        $script:appList.Items.Clear()
        foreach ($app in $script:appCatalog) {
            if ($filtro) {
                $texto = ('{0} {1} {2} {3}' -f $app.Name, $app.Category, $app.Note, $app.Id).ToLowerInvariant()
                if (-not $texto.Contains($filtro)) { continue }
            }
            $item = New-Object System.Windows.Forms.ListViewItem($app.Name)
            [void]$item.SubItems.Add($app.Category)
            [void]$item.SubItems.Add($app.Note)
            [void]$item.SubItems.Add('')
            $item.Tag = $app
            $estado = ''
            if ($script:appStateById.ContainsKey($app.Id)) { $estado = [string]$script:appStateById[$app.Id] }
            if ($estado) { Set-AppItemState $item $estado }
            $marcado = $false
            if ($script:appCheckedById.ContainsKey($app.Id)) { $marcado = [bool]$script:appCheckedById[$app.Id] }
            if ($estado -eq 'Instalado') { $marcado = $false }
            $item.Checked = $marcado
            [void]$script:appList.Items.Add($item)
            $mostrados++
        }
    } finally {
        $script:appList.EndUpdate()
    }
    if ($script:grpPrograms) {
        if ($filtro) {
            $script:grpPrograms.Text = ('Programas disponibles ({0} de {1})' -f $mostrados, $script:appCatalog.Count)
        } else {
            $script:grpPrograms.Text = ('Programas disponibles ({0})' -f $mostrados)
        }
    }
}

function Set-AllAppsChecked {
    param([bool]$Value, [switch]$OnlyRecommended)
    foreach ($app in $script:appCatalog) {
        $instalado = ($script:appStateById.ContainsKey($app.Id) -and [string]$script:appStateById[$app.Id] -eq 'Instalado')
        if ($OnlyRecommended -and -not $app.Recommended) {
            $script:appCheckedById[$app.Id] = $false
            continue
        }
        if ($instalado) {
            $script:appCheckedById[$app.Id] = $false
            continue
        }
        $script:appCheckedById[$app.Id] = $Value
    }
    Update-AppList
}

function Update-WingetLabel {
    if (-not $script:lblWinget) { return }
    if ($script:wingetReady) {
        $script:lblWinget.Text = ('winget {0} disponible' -f $script:wingetVersion)
        $script:lblWinget.ForeColor = [System.Drawing.Color]::FromArgb(0, 120, 0)
    } else {
        $script:lblWinget.Text = 'winget no disponible: instala "Instalador de aplicaciones" desde la Store'
        $script:lblWinget.ForeColor = [System.Drawing.Color]::FromArgb(180, 60, 0)
    }
}

function Update-InstalledApps {
    if (-not (Test-Winget)) {
        Update-WingetLabel
        return
    }
    Update-WingetLabel
    $script:statusLabel.Text = 'Comprobando programas instalados...'
    $script:form.UseWaitCursor = $true
    [System.Windows.Forms.Application]::DoEvents()
    try {
        $ids = Get-WingetInstalledIds
        $instalados = 0
        foreach ($app in $script:appCatalog) {
            $estado = ''
            if ($script:appStateById.ContainsKey($app.Id)) { $estado = [string]$script:appStateById[$app.Id] }
            $instalado = $ids.ContainsKey($app.Id)
            if (-not $instalado -and $app.Kind -eq 'msi') {
                try {
                    $clave = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue |
                        Where-Object { $_.DisplayName -and $_.DisplayName -like ('*' + $app.Name + '*') } |
                        Select-Object -First 1
                    if ($clave) { $instalado = $true }
                } catch { }
            }
            if ($instalado) {
                $script:appStateById[$app.Id] = 'Instalado'
                $script:appCheckedById[$app.Id] = $false
                $instalados++
            } elseif ($estado -eq 'Instalado') {
                $script:appStateById[$app.Id] = ''
            }
        }
        Update-AppList
        Add-TabLog $script:prgLog ('Programas ya instalados detectados: {0} de {1}' -f $instalados, $script:appCatalog.Count) 'OK'
        $script:statusLabel.Text = 'Listo'
    } catch {
        Add-TabLog $script:prgLog ('No se pudo comprobar lo instalado: {0}' -f $_.Exception.Message) 'WARN'
        $script:statusLabel.Text = 'Listo'
    } finally {
        $script:form.UseWaitCursor = $false
    }
}

$script:btnProgramsInstall.add_Click({
    if ($script:busy) { return }
    if ($script:txtPrgSearch -and $script:txtPrgSearch.Text.Trim()) {
        $script:txtPrgSearch.Text = ''
        Update-AppList
    }
    $seleccion = @(Get-AppSelection)
    if ($seleccion.Count -eq 0) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'Marca primero los programas que quieras instalar.', $script:AppName, 'OK', 'Information')
        return
    }
    $necesitaWinget = @($seleccion | Where-Object { -not $_.Tag -or $_.Tag.Kind -ne 'msi' }).Count -gt 0
    if ($necesitaWinget -and -not (Test-Winget)) {
        Update-WingetLabel
        [void][System.Windows.Forms.MessageBox]::Show(
            "winget no está disponible en este equipo.`n`nPulsa 'Abrir Store', instala 'Instalador de aplicaciones' (App Installer) y vuelve a intentarlo.",
            "$script:AppName - winget", 'OK', 'Warning')
        return
    }
    Update-WingetLabel
    $nombres = ($seleccion | ForEach-Object { ' - ' + $_.Tag.Name }) -join "`n"
    $texto = "Vas a realizar una instalación desde la página oficial del programa.`n`n"
    $texto += ("Programas seleccionados ({0}):`n{1}`n`n" -f $seleccion.Count, $nombres)
    $texto += "Se descargan de Internet y se instalan sin preguntar. Este proceso puede tardar varios minutos.`n`n"
    $texto += "Quieres continuar?"
    $respuesta = [System.Windows.Forms.MessageBox]::Show(
        $texto, "$script:AppName - confirmar", 'OKCancel', 'Question')
    if ($respuesta -ne 'OK') { return }
    Start-WingetQueue $seleccion
})

$script:btnProgramsStop.add_Click({
    $respuesta = [System.Windows.Forms.MessageBox]::Show(
        'Se detendrá la instalación en curso y se cancelarán los programas pendientes. Continuar?',
        "$script:AppName - confirmar", 'YesNo', 'Question')
    if ($respuesta -eq 'Yes') { Stop-WingetQueue }
})

