# Solo puede haber un plan de energía marcado: al marcar uno se desmarcan los demás.
$script:eqList.add_ItemChecked({
    param($sender, $e)
    if ($script:eqSyncing) { return }
    $item = $e.Item
    if (-not $item.Checked -or -not $item.Tag) { return }
    $grupo = [string]$item.Tag.Action.Exclusive
    if (-not $grupo) { return }
    $script:eqSyncing = $true
    try {
        foreach ($otro in $script:eqList.Items) {
            if ($otro -ne $item -and $otro.Checked -and $otro.Tag -and [string]$otro.Tag.Action.Exclusive -eq $grupo) {
                $otro.Checked = $false
            }
        }
    } finally {
        $script:eqSyncing = $false
    }
})

