function Get-DeviceClassText {
    param([string]$Code)
    if (-not $Code) { return 'Desconocido' }
    switch ($Code.ToUpperInvariant()) {
        'NET'             { return 'Red' }
        'DISPLAY'         { return 'Pantalla' }
        'MEDIA'           { return 'Sonido' }
        'AUDIOENDPOINT'   { return 'Audio' }
        'HIDCLASS'        { return 'Entrada' }
        'USB'             { return 'USB' }
        'BLUETOOTH'       { return 'Bluetooth' }
        'SCSIADAPTER'     { return 'Almacenamiento' }
        'DISKDRIVE'       { return 'Disco' }
        'VOLUME'          { return 'Volumen' }
        'KEYBOARD'        { return 'Teclado' }
        'MOUSE'           { return 'Ratón' }
        'PRINTER'         { return 'Impresora' }
        'PRINTQUEUE'      { return 'Cola de impresión' }
        'FIRMWARE'        { return 'Firmware' }
        'SYSTEM'          { return 'Sistema' }
        'PROCESSOR'       { return 'Procesador' }
        'CAMERA'          { return 'Cámara' }
        'IMAGE'           { return 'Imagen' }
        'BATTERY'         { return 'Batería' }
        'MONITOR'         { return 'Monitor' }
        'SMARTCARDREADER' { return 'Lector de tarjetas' }
        'SECURITYDEVICES' { return 'Seguridad' }
        'SOFTWAREDEVICE'  { return 'Dispositivo virtual' }
        'COMPUTER'        { return 'Equipo' }
    }
    return $Code
}

function Update-DeviceInventory {
    param([switch]$Force)
    if ($script:drvLoaded -and -not $Force) { return }

    $conductores = @{}
    try {
        foreach ($c in @(Get-CimInstance -ClassName Win32_PnPSignedDriver -ErrorAction SilentlyContinue)) {
            if (-not $c.DeviceID) { continue }
            $conductores[([string]$c.DeviceID).ToUpperInvariant()] = $c
        }
    } catch { }

    $lista = New-Object System.Collections.ArrayList
    $conPnp = $false
    try { $conPnp = [bool](Get-Command Get-PnpDevice -ErrorAction SilentlyContinue) } catch { }

    if ($conPnp) {
        foreach ($d in @(Get-PnpDevice -PresentOnly -ErrorAction SilentlyContinue)) {
            $id = [string]$d.InstanceId
            if (-not $id) { continue }
            $con = $conductores[$id.ToUpperInvariant()]
            $estado = [string]$d.Status
            $problema = ($estado -eq 'Error' -or $estado -eq 'Degraded')
            $texto = ''
            try { $texto = [string]$d.ProblemDescription } catch { }
            $clase = [string]$d.Class
            if (-not $clase) { try { $clase = [string]$d.PNPClass } catch { } }
            $nombre = [string]$d.FriendlyName
            if (-not $nombre) { $nombre = [string]$d.Description }
            if (-not $nombre) { $nombre = $clase }
            $version = ''
            $fecha = $null
            $proveedor = ''
            $inf = ''
            if ($con) {
                $version = [string]$con.DriverVersion
                if ($con.DriverDate) { try { $fecha = [datetime]$con.DriverDate } catch { } }
                $proveedor = [string]$con.Manufacturer
                $inf = [string]$con.InfName
                if (-not $clase) { $clase = [string]$con.DeviceClass }
            }
            if (-not $proveedor) { try { $proveedor = [string]$d.Manufacturer } catch { } }
            $hw = @()
            foreach ($h in @($d.HardwareID)) { if ($h) { $hw += [string]$h } }
            [void]$lista.Add([pscustomobject]@{
                Name        = $nombre
                Class       = $clase
                ClassText   = (Get-DeviceClassText $clase)
                Status      = $estado
                ProblemText = $texto
                InstanceId  = $id
                Version     = $version
                Date        = $fecha
                Provider    = $proveedor
                InfName     = $inf
                HardwareIds = $hw
                Service     = [string]$d.Service
                IsProblem   = $problema
            })
        }
    } else {
        foreach ($d in @(Get-CimInstance -ClassName Win32_PnPEntity -ErrorAction SilentlyContinue)) {
            $id = [string]$d.PNPDeviceID
            if (-not $id) { continue }
            $con = $conductores[$id.ToUpperInvariant()]
            $codigoError = [string]$d.ConfigManagerErrorCode
            $problema = ($codigoError -and $codigoError -ne '0' -and $codigoError -ne 'CM_PROB_NONE')
            $estado = 'OK'
            if ($problema) { $estado = 'Error' }
            $nombre = [string]$d.Name
            if (-not $nombre) { $nombre = [string]$d.Description }
            $version = ''
            $fecha = $null
            $proveedor = [string]$d.Manufacturer
            $inf = ''
            if ($con) {
                $version = [string]$con.DriverVersion
                if ($con.DriverDate) { try { $fecha = [datetime]$con.DriverDate } catch { } }
                if (-not $proveedor) { $proveedor = [string]$con.Manufacturer }
                $inf = [string]$con.InfName
            }
            $hw = @()
            foreach ($h in @($d.HardwareID)) { if ($h) { $hw += [string]$h } }
            [void]$lista.Add([pscustomobject]@{
                Name        = $nombre
                Class       = [string]$d.PNPClass
                ClassText   = (Get-DeviceClassText ([string]$d.PNPClass))
                Status      = $estado
                ProblemText = ''
                InstanceId  = $id
                Version     = $version
                Date        = $fecha
                Provider    = $proveedor
                InfName     = $inf
                HardwareIds = $hw
                Service     = [string]$d.Service
                IsProblem   = $problema
            })
        }
    }

    $script:drvDevices = @($lista | Sort-Object @{ Expression = { if ($_.IsProblem) { 0 } else { 1 } } }, @{ Expression = { $_.Name } })
    $script:drvLoaded = $true
}

function Get-ProblemDeviceForHardwareId {
    param([string]$HardwareId)
    if (-not $HardwareId) { return $null }
    $aguja = $HardwareId.ToLowerInvariant().TrimStart('*').Trim()
    if (-not $aguja) { return $null }
    foreach ($d in $script:drvDevices) {
        if (-not $d.IsProblem) { continue }
        foreach ($h in @($d.HardwareIds)) {
            if (-not $h) { continue }
            if (([string]$h).ToLowerInvariant().StartsWith($aguja)) { return $d }
        }
    }
    return $null
}

function Set-DriverItemState {
    param($Item, [string]$Text, $Color)
    if (-not $Item) { return }
    try {
        $Item.SubItems[2].Text = $Text
        if ($Color) { $Item.ForeColor = $Color }
    } catch { }
}

function Update-DriverSelectAll {
    if (-not $script:chkDrvAll) { return }
    $total = 0
    $marcados = 0
    if ($script:drvMode -eq 'Drivers') {
        foreach ($item in $script:drvList.Items) {
            if (-not $item.Tag) { continue }
            if ($item.Tag.Installed) { continue }
            $total++
            if ($item.Checked) { $marcados++ }
        }
    }
    $script:drvAllUpdating = $true
    try {
        $script:chkDrvAll.Enabled = (($script:drvMode -eq 'Drivers') -and ($total -gt 0) -and (-not $script:drvProcess))
        $script:chkDrvAll.Checked = ($total -gt 0 -and $marcados -eq $total)
    } finally {
        $script:drvAllUpdating = $false
    }
}

function Update-DriverButtons {
    $marcados = 0
    try { $marcados = @($script:drvList.CheckedItems).Count } catch { }
    $script:btnDrvInstall.Enabled = (($script:drvMode -eq 'Drivers') -and ($marcados -gt 0) -and (-not $script:drvProcess))
    $script:btnDrvStop.Enabled = [bool]$script:drvProcess
    Update-DriverSelectAll
}

function Update-DriverList {
    $script:drvList.BeginUpdate()
    try {
        $script:drvList.Items.Clear()
        $script:drvItemById = @{}
        if ($script:drvMode -eq 'Drivers') {
            $script:drvList.CheckBoxes = $true
            foreach ($u in $script:drvUpdates) {
                $item = New-Object System.Windows.Forms.ListViewItem($u.Title)
                [void]$item.SubItems.Add((Get-DeviceClassText $u.Class))
                [void]$item.SubItems.Add('')
                [void]$item.SubItems.Add('')
                $item.Tag = $u
                if ($u.Matched) {
                    $item.Font = New-Object System.Drawing.Font($script:uiFont, [System.Drawing.FontStyle]::Bold)
                    $item.Checked = $true
                    $item.SubItems[2].Text = 'Para tu equipo'
                }
                if ($u.Installed) {
                    Set-DriverItemState $item 'Instalado' ([System.Drawing.Color]::FromArgb(0, 120, 0))
                    $item.Checked = $false
                }
                [void]$script:drvList.Items.Add($item)
                if ($u.Id) { $script:drvItemById[[string]$u.Id] = $item }
            }
        } else {
            $script:drvList.CheckBoxes = $false
            foreach ($d in $script:drvDevices) {
                if ($script:drvMode -eq 'Problemas' -and -not $d.IsProblem) { continue }
                $item = New-Object System.Windows.Forms.ListViewItem($d.Name)
                [void]$item.SubItems.Add($d.ClassText)
                if ($d.IsProblem) {
                    [void]$item.SubItems.Add('Con problema')
                } else {
                    [void]$item.SubItems.Add('Correcto')
                }
                [void]$item.SubItems.Add($d.Version)
                $item.Tag = $d
                if ($d.IsProblem) {
                    $item.ForeColor = [System.Drawing.Color]::FromArgb(180, 30, 30)
                    $item.Font = New-Object System.Drawing.Font($script:uiFont, [System.Drawing.FontStyle]::Bold)
                }
                [void]$script:drvList.Items.Add($item)
            }
        }
    } finally {
        $script:drvList.EndUpdate()
    }

    foreach ($i in @($script:drvList.SelectedItems)) { $i.Selected = $false }
    if ($script:drvList.Items.Count -gt 0) {
        $script:drvList.Items[0].Selected = $true
        Show-DriverDetail
    } elseif ($script:drvMode -eq 'Problemas') {
        $script:drvDetail.Text = 'Ningún componente tiene problemas: todos los drivers están instalados.' + "`r`n`r`n" + 'Puedes cambiar la lista a "Todos los dispositivos" o buscar drivers nuevos en Windows Update.'
    } elseif ($script:drvMode -eq 'Drivers') {
        $script:drvDetail.Text = 'Windows Update no ofrece drivers nuevos para este equipo.' + "`r`n`r`n" + 'Si acabas de instalar un componente, pulsa "Buscar en Windows Update" otra vez.'
    } else {
        $script:drvDetail.Text = 'No hay componentes que mostrar.'
    }
    Update-DriverButtons
}

function Update-DriverTab {
    if (-not $script:drvLoaded) {
        $script:form.UseWaitCursor = $true
        $script:statusLabel.Text = 'Analizando los componentes del equipo...'
        [System.Windows.Forms.Application]::DoEvents()
        try {
            Update-DeviceInventory -Force
            try {
                $equipo = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
                if ($equipo) {
                    Add-TabLog $script:drvLog ('Fabricante y modelo: {0} {1}.' -f $equipo.Manufacturer, $equipo.Model)
                }
            } catch { }
            Add-TabLog $script:drvLog ('Componentes detectados: {0}.' -f $script:drvDevices.Count)
            $conProblemas = @($script:drvDevices | Where-Object { $_.IsProblem }).Count
            if ($conProblemas -gt 0) {
                Add-TabLog $script:drvLog ('Componentes con problemas: {0}. Pulsa "Buscar en Windows Update" para ver si hay driver disponible.' -f $conProblemas) 'WARN'
            } else {
                Add-TabLog $script:drvLog 'Todos los componentes tienen driver y funcionan correctamente.' 'OK'
            }
        } catch {
            Add-TabLog $script:drvLog ('No se pudo analizar el equipo: {0}' -f $_.Exception.Message) 'ERROR'
            Write-Diag ('ERROR analizando dispositivos: ' + $_.Exception.ToString())
        } finally {
            $script:form.UseWaitCursor = $false
            $script:statusLabel.Text = 'Listo'
        }
    }

    $conProblemas = @($script:drvDevices | Where-Object { $_.IsProblem }).Count
    $script:lblDrvEstado.Text = ('{0} componentes  |  {1} con problemas' -f $script:drvDevices.Count, $conProblemas)

    if ($script:drvMode -ne 'Drivers') {
        if ($conProblemas -eq 0 -and $script:drvMode -eq 'Problemas') {
            $script:drvMode = 'Todos'
            $script:drvView.SelectedIndex = 1
        }
        Update-DriverList
    }
}

function Start-DriverChild {
    param([string[]]$Ids, [switch]$Search)

    $script:drvReadPos = 0
    $script:drvOutFile = $null
    $script:drvScript  = $null

    try {
        $dirTrabajo = Get-WorkDir
        $script:drvOutFile = Join-Path $dirTrabajo ('wintaller_drivers_{0}.log' -f ([guid]::NewGuid().ToString('N')))
        $script:drvScript  = Join-Path $dirTrabajo ('wintaller_drivers_{0}.ps1' -f ([guid]::NewGuid().ToString('N')))
        [System.IO.File]::WriteAllText($script:drvScript, $script:drvChildScript, (New-Object System.Text.UTF8Encoding($true)))
    } catch {
        Add-TabLog $script:drvLog ('No se pudo preparar la operación: {0}' -f $_.Exception.Message) 'ERROR'
        Clear-DriverTempFiles
        return $false
    }

    $argumentos = @(
        '-NoProfile', '-ExecutionPolicy', 'Bypass', '-STA',
        '-File', ('"' + $script:drvScript + '"'),
        '-OutFile', ('"' + $script:drvOutFile + '"')
    )
    if ($Search) {
        $argumentos += '-Search'
    } else {
        $argumentos += @('-Ids', ('"' + ($Ids -join ',') + '"'))
    }

    try {
        $script:drvProcess = Start-Process -FilePath (Join-Path $PSHOME 'powershell.exe') -ArgumentList $argumentos -PassThru -WindowStyle Hidden
        $script:drvProcess.EnableRaisingEvents = $true
        $script:drvStarted = Get-Date
        $script:drvTimer.Start()
        return $true
    } catch {
        Add-TabLog $script:drvLog ('No se pudo iniciar la operación: {0}' -f $_.Exception.Message) 'ERROR'
        $script:drvProcess = $null
        Clear-DriverTempFiles
        return $false
    }
}

function Start-DriverSearch {
    if ($script:drvProcess) { return }
    $script:drvSearching   = $true
    $script:drvSearchItems = New-Object System.Collections.ArrayList
    $script:drvDone        = 0
    $script:drvErrors      = 0
    Add-TabLog $script:drvLog 'Consultando Windows Update (puede tardar hasta un minuto)...' 'STEP'
    $script:btnDrvSearch.Enabled  = $false
    $script:btnDrvInstall.Enabled = $false
    $script:btnDrvStop.Enabled    = $true
    $btnDrvRefresh.Enabled        = $false
    $script:statusLabel.Text      = 'Buscando drivers en Windows Update...'
    if (-not (Start-DriverChild -Search)) {
        $script:drvSearching          = $false
        $script:btnDrvSearch.Enabled  = $true
        $script:btnDrvStop.Enabled    = $false
        $btnDrvRefresh.Enabled        = $true
        $script:statusLabel.Text      = 'No se pudo buscar'
    }
}

function Complete-DriverSearch {
    $lista = New-Object System.Collections.ArrayList
    foreach ($e in @($script:drvSearchItems)) {
        $fecha = $null
        if ($e.fecha) {
            try { $fecha = [datetime]::ParseExact([string]$e.fecha, 'yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture) } catch { }
        }
        $mb = 0
        try { $mb = [double]$e.mb } catch { }
        [void]$lista.Add([pscustomobject]@{
            Id         = [string]$e.id
            Title      = [string]$e.titulo
            Provider   = [string]$e.proveedor
            Class      = [string]$e.clase
            Date       = $fecha
            SizeMB     = $mb
            HardwareId = [string]$e.hwid
            Matched    = $null
            Installed  = $false
            Update     = $null
        })
    }

    $script:drvUpdates = @($lista)
    $coinciden = 0
    foreach ($u in $script:drvUpdates) {
        $u.Matched = Get-ProblemDeviceForHardwareId $u.HardwareId
        if ($u.Matched) { $coinciden++ }
    }
    $script:drvUpdates = @($script:drvUpdates | Sort-Object @{ Expression = { if ($_.Matched) { 0 } else { 1 } } }, @{ Expression = { $_.Date }; Descending = $true })

    if ($script:drvUpdates.Count -eq 0) {
        Add-TabLog $script:drvLog 'Windows Update no ofrece drivers nuevos para este equipo.' 'OK'
    } else {
        Add-TabLog $script:drvLog ('Drivers disponibles en Windows Update: {0} ({1} para componentes con problemas).' -f $script:drvUpdates.Count, $coinciden) 'OK'
        if ($coinciden -gt 0) {
            Add-TabLog $script:drvLog 'Los que corresponden a componentes con problemas ya vienen marcados.' 'STEP'
        }
    }

    $script:drvMode = 'Drivers'
    if ($script:drvView.SelectedIndex -ne 2) { $script:drvView.SelectedIndex = 2 }
    else { Update-DriverList }

    $conProblemas = @($script:drvDevices | Where-Object { $_.IsProblem }).Count
    $script:lblDrvEstado.Text = ('{0} componentes  |  {1} con problemas  |  {2} drivers' -f $script:drvDevices.Count, $conProblemas, $script:drvUpdates.Count)
    $script:statusLabel.Text = 'Listo'
}

function Read-DriverEvents {
    if (-not $script:drvOutFile) { return }
    if (-not (Test-Path -LiteralPath $script:drvOutFile)) { return }
    try {
        $lineas = @(Get-Content -LiteralPath $script:drvOutFile -Encoding UTF8 -ErrorAction SilentlyContinue)
        while ($script:drvReadPos -lt $lineas.Count) {
            $linea = [string]$lineas[$script:drvReadPos]
            $script:drvReadPos++
            if (-not $linea.Trim()) { continue }
            $evt = $null
            try { $evt = $linea | ConvertFrom-Json } catch { continue }
            if (-not $evt) { continue }
            $item = $null
            if ($evt.id) { $item = $script:drvItemById[[string]$evt.id] }
            switch ([string]$evt.t) {
                'driver' {
                    if ($null -ne $script:drvSearchItems) { [void]$script:drvSearchItems.Add($evt) }
                }
                'inicio' {
                    if ($item) { Set-DriverItemState $item 'Descargando...' ([System.Drawing.Color]::FromArgb(0, 80, 160)) }
                    Add-TabLog $script:drvLog ('Descargando: {0}' -f $evt.titulo) 'STEP'
                }
                'descargado' {
                    if ($item) { Set-DriverItemState $item 'Instalando...' ([System.Drawing.Color]::FromArgb(0, 80, 160)) }
                }
                'falta' {
                    if ($item) { Set-DriverItemState $item 'No disponible' ([System.Drawing.Color]::FromArgb(170, 60, 0)) }
                    $script:drvDone++
                    $script:drvErrors++
                    Add-TabLog $script:drvLog 'Un driver ya no está disponible en Windows Update. Vuelve a buscar.' 'WARN'
                }
                'resultado' {
                    $correcto = [bool]$evt.ok
                    if ($correcto) {
                        if ($item) {
                            Set-DriverItemState $item 'Instalado' ([System.Drawing.Color]::FromArgb(0, 120, 0))
                            $item.Checked = $false
                        }
                        foreach ($u in $script:drvUpdates) {
                            if ($u.Id -eq [string]$evt.id) { $u.Installed = $true }
                        }
                        Add-TabLog $script:drvLog ('{0}: instalado ({1}).' -f $evt.titulo, $evt.texto) 'OK'
                    } else {
                        if ($item) { Set-DriverItemState $item 'Error' ([System.Drawing.Color]::FromArgb(180, 40, 40)) }
                        Add-TabLog $script:drvLog ('{0}: {1} (código {2}).' -f $evt.titulo, $evt.texto, $evt.codigo) 'WARN'
                    }
                    if ($evt.reinicio) { $script:drvReboot = $true }
                    $script:drvDone++
                    if (-not $correcto) { $script:drvErrors++ }
                }
                'fatal' {
                    $script:drvErrors++
                    Add-TabLog $script:drvLog ('Error en la operación con Windows Update: {0}' -f $evt.mensaje) 'ERROR'
                }
            }
        }
        if (-not $script:drvSearching) { Update-DriverButtons }
    } catch { }
}

function Start-DriverQueue {
    param([string[]]$Ids, [switch]$Testing)
    if (-not $Ids -or $Ids.Count -eq 0) { return }
    if (-not $Testing -and -not $script:IsAdmin) {
        [void][System.Windows.Forms.MessageBox]::Show(
            "Instalar drivers necesita permisos de administrador.`n`nCierra el programa y abrelo con Iniciar.bat (pide UAC).",
            "$script:AppName - permisos", 'OK', 'Warning')
        return
    }

    $script:drvSearching = $false
    $script:drvTotal     = $Ids.Count
    $script:drvDone      = 0
    $script:drvErrors    = 0
    $script:drvReboot    = $false

    Add-TabLog $script:drvLog ('=== Instalando {0} drivers desde Windows Update ===' -f $Ids.Count) 'STEP'
    $script:btnDrvSearch.Enabled  = $false
    $script:btnDrvInstall.Enabled = $false
    $script:btnDrvStop.Enabled    = $true
    $btnDrvRefresh.Enabled        = $false
    $script:statusLabel.Text      = 'Instalando drivers...'

    if (-not (Start-DriverChild -Ids $Ids)) {
        $script:btnDrvSearch.Enabled  = $true
        $script:btnDrvInstall.Enabled = $false
        $script:btnDrvStop.Enabled    = $false
        $btnDrvRefresh.Enabled        = $true
        $script:statusLabel.Text      = 'No se pudo instalar'
    }
}

function Clear-DriverTempFiles {
    foreach ($f in @($script:drvOutFile, $script:drvScript)) {
        if ($f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
    }
    $script:drvOutFile = $null
    $script:drvScript  = $null
}

function Cancel-PendingDriverItems {
    foreach ($item in $script:drvList.Items) {
        if ($item.SubItems[2].Text -eq 'Descargando...' -or $item.SubItems[2].Text -eq 'Instalando...') {
            Set-DriverItemState $item 'Cancelado' ([System.Drawing.Color]::FromArgb(120, 120, 120))
        }
    }
}

function Step-DriverQueue {
    $proc = $script:drvProcess
    if (-not $proc) { return }

    Read-DriverEvents

    $terminado = $false
    try { $terminado = $proc.HasExited } catch { $terminado = $true }

    if (-not $terminado) {
        $limite = 90
        if ($script:drvSearching) { $limite = 10 }
        if ($script:drvStarted -and ((Get-Date) - $script:drvStarted).TotalMinutes -gt $limite) {
            try { & "$env:SystemRoot\System32\taskkill.exe" /PID $proc.Id /T /F 2>&1 | Out-Null } catch { }
            try { $proc.Dispose() } catch { }
            $script:drvProcess = $null
            $script:drvTimer.Stop()
            Clear-DriverTempFiles
            if ($script:drvSearching) {
                $script:drvSearching = $false
                Add-TabLog $script:drvLog 'La consulta a Windows Update tardo demasiado y se canceló.' 'WARN'
                $script:statusLabel.Text = 'Búsqueda cancelada'
            } else {
                Add-TabLog $script:drvLog 'La instalación superó 90 minutos y se ha cancelado.' 'WARN'
                Cancel-PendingDriverItems
                $script:statusLabel.Text = 'Instalación de drivers cancelada'
            }
            $script:btnDrvSearch.Enabled  = $true
            $script:btnDrvInstall.Enabled = $false
            $script:btnDrvStop.Enabled    = $false
            $btnDrvRefresh.Enabled        = $true
        }
        return
    }

    Read-DriverEvents
    $codigo = -1
    try { $codigo = [int]$proc.ExitCode } catch { }
    try { $proc.Dispose() } catch { }
    $script:drvProcess = $null
    $script:drvTimer.Stop()
    $eraBusqueda = [bool]$script:drvSearching
    $script:drvSearching = $false
    Clear-DriverTempFiles

    $script:btnDrvSearch.Enabled  = $true
    $script:btnDrvInstall.Enabled = $false
    $script:btnDrvStop.Enabled    = $false
    $btnDrvRefresh.Enabled        = $true

    if ($eraBusqueda) {
        if ($script:drvSearchItems.Count -eq 0) {
            Add-TabLog $script:drvLog ('Windows Update no devolvió resultados (código {0}). Comprueba la conexión a Internet.' -f $codigo) 'WARN'
            $script:statusLabel.Text = 'Sin resultados de Windows Update'
        } else {
            Complete-DriverSearch
        }
        return
    }

    if ($script:drvDone -eq 0) {
        Add-TabLog $script:drvLog ('El proceso de instalación terminó sin resultados (código {0}).' -f $codigo) 'ERROR'
    }

    $correctos = $script:drvDone - $script:drvErrors
    Add-TabLog $script:drvLog ('=== Fin: {0} correctos, {1} con error ===' -f $correctos, $script:drvErrors) 'STEP'
    if ($script:drvReboot) {
        Add-TabLog $script:drvLog 'Windows necesita reiniciar para terminar de aplicar los drivers.' 'WARN'
    }

    try { Update-DeviceInventory -Force } catch { }

    $script:statusLabel.Text = 'Instalación de drivers terminada'

    if (-not $UiSmokeTest) {
        $texto = ("Instalación de drivers terminada.`n`nCorrectos: {0}`nCon error: {1}" -f $correctos, $script:drvErrors)
        if ($script:drvReboot) { $texto += "`n`nReinicia el equipo para terminar de aplicar los cambios." }
        [void][System.Windows.Forms.MessageBox]::Show($texto, $script:AppName, 'OK', 'Information')
    }
}

function Stop-DriverQueue {
    $eraBusqueda = [bool]$script:drvSearching
    if ($script:drvProcess) {
        try {
            if (-not $script:drvProcess.HasExited) { & "$env:SystemRoot\System32\taskkill.exe" /PID $script:drvProcess.Id /T /F 2>&1 | Out-Null }
        } catch {
            try { $script:drvProcess.Kill() } catch { }
        }
        try { $script:drvProcess.Dispose() } catch { }
        if ($eraBusqueda) {
            Add-TabLog $script:drvLog 'Consulta a Windows Update cancelada por el usuario.' 'WARN'
        } else {
            Add-TabLog $script:drvLog 'Instalación de drivers detenida por el usuario.' 'WARN'
        }
    }
    $script:drvProcess = $null
    $script:drvSearching = $false
    $script:drvTimer.Stop()
    if (-not $eraBusqueda) { Cancel-PendingDriverItems }
    Clear-DriverTempFiles
    $script:statusLabel.Text      = 'Operación de drivers detenida'
    $script:btnDrvSearch.Enabled  = $true
    $script:btnDrvInstall.Enabled = $false
    $script:btnDrvStop.Enabled    = $false
    $btnDrvRefresh.Enabled        = $true
}

function Backup-DriverPackages {
    if (-not $script:IsAdmin) {
        [void][System.Windows.Forms.MessageBox]::Show(
            "Guardar una copia de los drivers necesita permisos de administrador.`n`nAbre el programa con Iniciar.bat.",
            "$script:AppName - permisos", 'OK', 'Warning')
        return
    }

    $destino = Join-Path ([Environment]::GetFolderPath('MyDocuments')) ('WinTaller\Drivers-{0}' -f (Get-Date -Format 'yyyyMMdd-HHmmss'))
    Add-TabLog $script:drvLog ('Guardando copia de los drivers en {0} ...' -f $destino) 'STEP'
    $script:form.UseWaitCursor = $true
    $script:statusLabel.Text = 'Copiando drivers...'
    [System.Windows.Forms.Application]::DoEvents()
    try {
        [void](New-Item -ItemType Directory -Path $destino -Force -ErrorAction Stop)
        $salida = & "$env:SystemRoot\System32\pnputil.exe" /export-driver * $destino 2>&1 | Out-String
        $codigo = $LASTEXITCODE
        $archivos = @(Get-ChildItem -LiteralPath $destino -Filter '*.inf' -Recurse -ErrorAction SilentlyContinue)
        if ($codigo -eq 0) {
            Add-TabLog $script:drvLog ('Copia guardada: {0} paquetes de driver.' -f $archivos.Count) 'OK'
            Add-TabLog $script:drvLog ('Carpeta: {0}' -f $destino)
            [void][System.Windows.Forms.MessageBox]::Show(
                ("Copia de seguridad creada.`n`nPaquetes de driver: {0}`nCarpeta:`n{1}`n`nPara recuperarlos, usa 'Instalar .inf...' o el Administrador de dispositivos." -f $archivos.Count, $destino),
                "$script:AppName - copia de drivers", 'OK', 'Information')
            try { Start-Process -FilePath (Join-Path $env:SystemRoot 'explorer.exe') -ArgumentList ('"{0}"' -f $destino) } catch { }
        } else {
            throw ('pnputil devolvió el código {0}: {1}' -f $codigo, $salida.Trim())
        }
    } catch {
        Add-TabLog $script:drvLog ('No se pudo guardar la copia: {0}' -f $_.Exception.Message) 'ERROR'
        [void][System.Windows.Forms.MessageBox]::Show(
            ('No se pudo guardar la copia de los drivers.' + "`n`n" + $_.Exception.Message),
            "$script:AppName - copia de drivers", 'OK', 'Warning')
    } finally {
        $script:form.UseWaitCursor = $false
        $script:statusLabel.Text = 'Listo'
    }
}

function Install-DriverFromInf {
    if (-not $script:IsAdmin) {
        [void][System.Windows.Forms.MessageBox]::Show(
            "Instalar un driver necesita permisos de administrador.`n`nAbre el programa con Iniciar.bat.",
            "$script:AppName - permisos", 'OK', 'Warning')
        return
    }

    $dialogo = New-Object System.Windows.Forms.OpenFileDialog
    $dialogo.Title  = 'Selecciona el archivo .inf del driver'
    $dialogo.Filter = 'Paquetes de controlador (*.inf)|*.inf|Todos los archivos (*.*)|*.*'
    if ($dialogo.ShowDialog() -ne 'OK') { return }

    $archivo = $dialogo.FileName
    Add-TabLog $script:drvLog ('Instalando el driver {0} ...' -f $archivo) 'STEP'
    $script:form.UseWaitCursor = $true
    [System.Windows.Forms.Application]::DoEvents()
    try {
        $salida = & "$env:SystemRoot\System32\pnputil.exe" /add-driver $archivo /install 2>&1 | Out-String
        $codigo = $LASTEXITCODE
        if ($codigo -eq 0 -or $codigo -eq 3010) {
            Add-TabLog $script:drvLog 'Driver instalado correctamente.' 'OK'
            if ($codigo -eq 3010) { Add-TabLog $script:drvLog 'Windows pide reiniciar para terminar.' 'WARN' }
            try { Update-DeviceInventory -Force } catch { }
            [void][System.Windows.Forms.MessageBox]::Show(
                'Driver instalado. Reinicia el equipo si Windows lo pide.',
                "$script:AppName - drivers", 'OK', 'Information')
        } else {
            $lineas = @($salida -split "`r?`n" | Where-Object { $_.Trim() })
            $detalle = ($lineas | Select-Object -Last 2) -join ' '
            Add-TabLog $script:drvLog ('No se pudo instalar el driver (código {0}). {1}' -f $codigo, $detalle) 'ERROR'
            [void][System.Windows.Forms.MessageBox]::Show(
                ("No se pudo instalar el driver.`n`nCódigo: {0}`n{1}" -f $codigo, $detalle),
                "$script:AppName - drivers", 'OK', 'Warning')
        }
    } finally {
        $script:form.UseWaitCursor = $false
        $script:statusLabel.Text = 'Listo'
    }
}

function Open-ManufacturerSupport {
    $fabricante = ''
    $modelo = ''
    try {
        $equipo = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction SilentlyContinue
        if ($equipo) {
            $fabricante = [string]$equipo.Manufacturer
            $modelo = [string]$equipo.Model
        }
    } catch { }

    $url = ''
    switch -Regex ($fabricante.ToUpperInvariant()) {
        'LENOVO'              { $url = 'https://pcsupport.lenovo.com/' }
        'HP|HEWLETT'          { $url = 'https://support.hp.com/drivers' }
        'DELL'                { $url = 'https://www.dell.com/support/home' }
        'ASUS'                { $url = 'https://www.asus.com/support/download-center/' }
        'ACER'                { $url = 'https://www.acer.com/us-en/support/drivers-and-manuals' }
        'MSI'                 { $url = 'https://www.msi.com/support/download' }
        'SAMSUNG'             { $url = 'https://www.samsung.com/us/support/downloads/' }
        'MICROSOFT'           { $url = 'https://support.microsoft.com/surface' }
        'TOSHIBA|DYNABOOK'    { $url = 'https://support.dynabook.com/' }
        'FUJITSU'             { $url = 'https://support.ts.fujitsu.com/' }
        'GIGABYTE'            { $url = 'https://www.gigabyte.com/Support' }
        'ASROCK'              { $url = 'https://www.asrock.com/support/index.asp' }
        'HUAWEI'              { $url = 'https://consumer.huawei.com/en/support/' }
        'XIAOMI'              { $url = 'https://www.mi.com/global/support/' }
        'ALIENWARE'           { $url = 'https://www.dell.com/support/home' }
        'PACKARD'             { $url = 'https://www.acer.com/us-en/support/drivers-and-manuals' }
        'MEDION'              { $url = 'https://www.medion.com/service/' }
        'VAIO'                { $url = 'https://us.vaio.com/support' }
        'LG ELECTRONICS|^LG'  { $url = 'https://www.lg.com/us/support' }
        'RAZER'               { $url = 'https://www.razer.com/support' }
        'CHUWI'               { $url = 'https://www.chuwi.com/support.html' }
    }
    if (-not $url) {
        if ($fabricante) {
            $url = 'https://www.google.com/search?q=' + [uri]::EscapeDataString(($fabricante + ' ' + $modelo + ' drivers'))
        } else {
            $url = 'https://support.microsoft.com/windows'
        }
    }

    if ($modelo) {
        try { [System.Windows.Forms.Clipboard]::SetText($modelo) } catch { }
    }
    Add-TabLog $script:drvLog ('Abriendo el soporte del fabricante: {0}' -f $url) 'STEP'
    if ($modelo) { Add-TabLog $script:drvLog ('Modelo copiado al portapapeles: {0}' -f $modelo) }
    try {
        Open-AsDesktopUser $url
    } catch {
        Add-TabLog $script:drvLog ('No se pudo abrir el navegador: {0}' -f $_.Exception.Message) 'ERROR'
    }
}

function Show-DriverDetail {
    $item = $null
    if ($script:drvList.SelectedItems.Count -gt 0) { $item = $script:drvList.SelectedItems[0] }
    if (-not $item) {
        $script:drvDetail.Text = 'Selecciona un componente de la lista para ver sus datos.'
        return
    }

    if ($script:drvMode -eq 'Drivers') {
        $u = $item.Tag
        $fecha = 'desconocida'
        if ($u.Date) { $fecha = $u.Date.ToString('dd/MM/yyyy') }
        $lineas = @(
            $u.Title,
            '',
            ('Fabricante: {0}' -f $u.Provider),
            ('Tipo: {0}' -f (Get-DeviceClassText $u.Class)),
            ('Fecha del driver: {0}' -f $fecha),
            ('Descarga aproximada: {0} MB' -f $u.SizeMB)
        )
        if ($u.HardwareId) { $lineas += ('ID de hardware: {0}' -f $u.HardwareId) }
        if ($u.Matched) {
            $lineas += ''
            $lineas += ('Corresponde a: {0}' -f $u.Matched.Name)
        } else {
            $lineas += ''
            $lineas += 'No corresponde a ningún componente con problemas: puede ser de otro equipo o un driver antiguo. Marcalo solo si sabes lo que haces.'
        }
        if ($u.Installed) {
            $lineas += ''
            $lineas += 'Estado: ya instalado en esta sesión.'
        }
        $script:drvDetail.Text = ($lineas -join "`r`n")
        return
    }

    $d = $item.Tag
    $hw = @($d.HardwareIds)
    if ($hw.Count -eq 0) {
        try {
            $hw = @((Get-PnpDeviceProperty -InstanceId $d.InstanceId -KeyName 'DEVPKEY_Device_HardwareIds' -ErrorAction SilentlyContinue).Data)
        } catch { }
    }

    $lineas = @(
        $d.Name,
        '',
        ('Clase: {0}' -f $d.ClassText),
        ('Estado: {0}' -f $d.Status)
    )
    if ($d.ProblemText) { $lineas += ('Problema: {0}' -f $d.ProblemText) }
    if ($d.Provider)    { $lineas += ('Fabricante: {0}' -f $d.Provider) }
    if ($d.Version)     { $lineas += ('Versión del driver: {0}' -f $d.Version) }
    if ($d.Date)        { $lineas += ('Fecha del driver: {0}' -f $d.Date.ToString('dd/MM/yyyy')) }
    if ($d.InfName)     { $lineas += ('Archivo: {0}' -f $d.InfName) }
    $lineas += ('ID de instancia: {0}' -f $d.InstanceId)
    if ($hw.Count -gt 0) { $lineas += ('ID de hardware: {0}' -f (($hw | Where-Object { $_ }) -join ' | ')) }
    if ($d.IsProblem) {
        $lineas += ''
        $lineas += 'Este componente no tiene driver o no funciona bien. Pulsa "Buscar en Windows Update" para ver si hay driver para el.'
    }
    $script:drvDetail.Text = ($lineas -join "`r`n")
}

$script:drvView.add_SelectedIndexChanged({
    $indice = $script:drvView.SelectedIndex
    if ($indice -eq 2) { $script:drvMode = 'Drivers' }
    elseif ($indice -eq 1) { $script:drvMode = 'Todos' }
    else { $script:drvMode = 'Problemas' }
    Update-DriverList
})

$script:drvList.add_SelectedIndexChanged({ Show-DriverDetail })
$script:drvList.add_ItemChecked({ Update-DriverButtons })

$script:chkDrvAll.add_CheckedChanged({
    if ($script:drvAllUpdating) { return }
    if ($script:drvMode -ne 'Drivers') { return }
    $valor = [bool]$script:chkDrvAll.Checked
    $script:drvList.BeginUpdate()
    try {
        foreach ($item in $script:drvList.Items) {
            if (-not $item.Tag) { continue }
            if ($item.Tag.Installed) { continue }
            $item.Checked = $valor
        }
    } finally {
        $script:drvList.EndUpdate()
    }
    Update-DriverButtons
})

$script:btnDrvSearch.add_Click({
    if ($script:drvProcess) { return }
    Start-DriverSearch
})

$script:btnDrvInstall.add_Click({
    if ($script:drvProcess) { return }
    $ids = @()
    $nombres = @()
    foreach ($item in @($script:drvList.CheckedItems)) {
        if (-not $item.Tag) { continue }
        $u = $item.Tag
        if ($u.Installed) { continue }
        $ids += [string]$u.Id
        $nombres += (' - ' + $u.Title)
    }
    if ($ids.Count -eq 0) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'Marca primero uno o varios drivers de la lista.', $script:AppName, 'OK', 'Information')
        return
    }
    $respuesta = [System.Windows.Forms.MessageBox]::Show(
        ("Se van a descargar e instalar {0} drivers desde Windows Update:`n`n{1}`n`nLos drivers se descargan de los servidores de Microsoft. Algunos pediran reiniciar.`n`nContinuar?" -f $ids.Count, ($nombres -join "`n")),
        "$script:AppName - confirmar", 'YesNo', 'Question')
    if ($respuesta -ne 'Yes') { return }
    Start-DriverQueue -Ids $ids
})

$script:btnDrvStop.add_Click({
    $respuesta = [System.Windows.Forms.MessageBox]::Show(
        'Se detendrá la instalación en curso. Algunos drivers podrían quedar a medias. Continuar?',
        "$script:AppName - confirmar", 'YesNo', 'Question')
    if ($respuesta -eq 'Yes') { Stop-DriverQueue }
})

$btnDrvBackup.add_Click({ Backup-DriverPackages })
$btnDrvInf.add_Click({ Install-DriverFromInf })
$btnDrvSupport.add_Click({ Open-ManufacturerSupport })

$btnDrvRefresh.add_Click({
    if ($script:drvProcess) { return }
    $script:form.UseWaitCursor = $true
    $script:statusLabel.Text = 'Actualizando la lista de componentes...'
    [System.Windows.Forms.Application]::DoEvents()
