# ---------------------------------------------------------------------------
# Pestaña: Copias (carpetas concretas o imagen completa del sistema)
# ---------------------------------------------------------------------------

# Estado de la pestaña Copias
$script:bkMode          = 'files'
$script:bkProcess       = $null
$script:bkOutFile       = $null
$script:bkScript        = $null
$script:bkJobFile       = $null
$script:bkReadPos       = 0
$script:bkStarted       = $null
$script:bkTotalFiles    = 0
$script:bkProcessed     = 0
$script:bkErrors        = 0
$script:bkResultOk      = $false
$script:bkSawResult     = $false
$script:bkRunMode       = 'files'
$script:bkDestFinal     = ''
$script:bkOpenAfter     = $false
$script:bkChangingMode  = $false
$script:bkPathByName    = @{}

# Script hijo: copia con robocopy o crea la imagen con wbadmin en un proceso
# aparte, para que la ventana siga respondiendo y se pueda cancelar.
$script:bkChildScript = @'
param(
    [Parameter(Mandatory=$true)][string]$OutFile,
    [Parameter(Mandatory=$true)][string]$JobFile
)

$ErrorActionPreference = 'Continue'

function Write-Evento {
    param([hashtable]$Datos)
    try {
        Add-Content -LiteralPath $OutFile -Value ($Datos | ConvertTo-Json -Compress) -Encoding UTF8
    } catch { }
}

# Cuenta archivos y bytes sin cargar la lista entera en memoria y sin entrar en
# puntos de unión (igual que robocopy /XJ), para que los totales coincidan.
function Measure-Carpeta {
    param([string]$Path)
    $archivos = 0
    $bytes = [double]0
    $reparse = [System.IO.FileAttributes]::ReparsePoint
    $pila = New-Object System.Collections.Generic.Stack[System.IO.DirectoryInfo]
    $pila.Push((New-Object System.IO.DirectoryInfo($Path)))
    while ($pila.Count -gt 0) {
        $dir = $pila.Pop()
        try {
            foreach ($e in $dir.EnumerateFileSystemInfos()) {
                if ($e -is [System.IO.DirectoryInfo]) {
                    if (($e.Attributes -band $reparse) -ne $reparse) { $pila.Push($e) }
                } elseif (($e.Attributes -band $reparse) -ne $reparse) {
                    $archivos++
                    $bytes += [double]$e.Length
                }
            }
        } catch { }
    }
    return [pscustomobject]@{ Files = $archivos; Bytes = $bytes }
}

function Get-Tamano {
    param([double]$Bytes)
    if ($Bytes -ge 1GB) { return (([string][math]::Round($Bytes / 1GB, 2)) + ' GB') }
    if ($Bytes -ge 1MB) { return (([string][math]::Round($Bytes / 1MB, 1)) + ' MB') }
    if ($Bytes -ge 1KB) { return (([string][math]::Round($Bytes / 1KB, 0)) + ' KB') }
    return (([string][math]::Round($Bytes, 0)) + ' bytes')
}

try {
    $job = Get-Content -LiteralPath $JobFile -Raw -Encoding UTF8 | ConvertFrom-Json
    $modo = [string]$job.mode
    $destino = ([string]$job.dest).Trim()
    if (-not $destino) { throw 'no se indico el destino de la copia' }

    if ($modo -eq 'image') {
        $sistema = $env:SystemDrive
        if ($destino -match '^\s*([A-Za-z]):[\\/]*\s*$') {
            $letraDestino = $Matches[1].ToUpperInvariant() + ':'
        } else {
            throw 'para la imagen del sistema el destino debe ser la raiz de otra unidad (por ejemplo E:\)'
        }
        if ($letraDestino -eq $sistema.ToUpperInvariant()) {
            throw 'la imagen del sistema no se puede guardar en la misma unidad que Windows; usa un disco externo o una segunda unidad'
        }
        $disco = Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $letraDestino) -ErrorAction SilentlyContinue
        if (-not $disco) { throw ('la unidad {0} no existe o no esta disponible' -f $letraDestino) }
        if ([string]$disco.FileSystem -ne 'NTFS') {
            throw ('la unidad {0} debe estar formateada en NTFS (ahora es {1})' -f $letraDestino, $disco.FileSystem)
        }
        $sist = Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $sistema) -ErrorAction SilentlyContinue
        $usado = 0
        if ($sist) { $usado = [double]$sist.Size - [double]$sist.FreeSpace }
        $libre = [double]$disco.FreeSpace
        if ($libre -lt ($usado * 1.1)) {
            throw ('no hay espacio suficiente en {0}: libre {1}, se necesitan unos {2}' -f $letraDestino, (Get-Tamano $libre), (Get-Tamano ($usado * 1.1)))
        }

        Write-Evento @{ t = 'inicio'; modo = 'image'; destino = ($letraDestino + '\'); libre = (Get-Tamano $libre); necesario = (Get-Tamano ($usado * 1.1)) }
        $reloj = [System.Diagnostics.Stopwatch]::StartNew()
        $codigo = -1
        & "$env:SystemRoot\System32\wbadmin.exe" start backup ("-backupTarget:{0}" -f $letraDestino) ("-include:{0}" -f $sistema) -allCritical -quiet 2>&1 | ForEach-Object {
            $texto = ([string]$_).Trim()
            if ($texto) { Write-Evento @{ t = 'linea'; texto = $texto } }
        }
        $codigo = $LASTEXITCODE
        $ok = ($codigo -eq 0)
        $mensaje = 'imagen creada'
        if (-not $ok) { $mensaje = ('wbadmin devolvio el codigo ' + $codigo) }
        Write-Evento @{ t = 'resultado'; ok = $ok; codigo = $codigo; modo = 'image'; texto = $mensaje; destino = ($letraDestino + '\WindowsImageBackup'); segundos = [math]::Round($reloj.Elapsed.TotalSeconds, 1) }
        Write-Evento @{ t = 'fin' }
        return
    }

    if (-not (Test-Path -LiteralPath (Join-Path $env:SystemRoot 'System32\robocopy.exe'))) {
        throw 'robocopy no esta disponible en este equipo'
    }

    $fuentes = @($job.sources | Where-Object { $_ })
    if ($fuentes.Count -eq 0) { throw 'no hay carpetas seleccionadas' }

    Write-Evento @{ t = 'contando' }
    $plan = New-Object System.Collections.ArrayList
    $totalArchivos = 0
    $totalBytes = 0
    $nombres = @{}
    foreach ($fuente in $fuentes) {
        if (-not (Test-Path -LiteralPath $fuente)) {
            Write-Evento @{ t = 'aviso'; texto = ('la carpeta no existe y se omite: ' + $fuente) }
            continue
        }
        $nombre = [System.IO.Path]::GetFileName(([string]$fuente).TrimEnd('\'))
        if (-not $nombre) { $nombre = 'Copia' }
        $base = $nombre
        $n = 2
        while ($nombres.ContainsKey($nombre.ToLowerInvariant())) {
            $nombre = ('{0}_{1}' -f $base, $n)
            $n++
        }
        $nombres[$nombre.ToLowerInvariant()] = $true
        $sub = Join-Path $destino $nombre
        $medida = Measure-Carpeta -Path $fuente
        $totalArchivos += $medida.Files
        $totalBytes += $medida.Bytes
        [void]$plan.Add([pscustomobject]@{ Source = $fuente; Dest = $sub; Files = $medida.Files; Bytes = $medida.Bytes })
    }
    if ($plan.Count -eq 0) { throw 'ninguna de las carpetas seleccionadas existe' }

    $libre = 0
    try {
        $raizDestino = [System.IO.Path]::GetPathRoot($destino)
        $letraDestino = ''
        if ($raizDestino) { $letraDestino = $raizDestino.TrimEnd('\') }
        if ($letraDestino) {
            $disco = Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $letraDestino) -ErrorAction SilentlyContinue
            if ($disco) { $libre = [double]$disco.FreeSpace }
        }
    } catch { }
    if ($libre -gt 0 -and $libre -lt ($totalBytes * 1.02)) {
        throw ('no hay espacio suficiente en el destino: libre {0} para {1} de datos' -f (Get-Tamano $libre), (Get-Tamano $totalBytes))
    }

    [void](New-Item -ItemType Directory -Path $destino -Force -ErrorAction Stop)
    $logRobo = Join-Path $destino '_registro-copia.txt'
    Write-Evento @{ t = 'plan'; archivos = $totalArchivos; bytes = (Get-Tamano $totalBytes); libre = (Get-Tamano $libre); destino = $destino }

    $escribirRegistro = $true
    if ($null -ne $job.logFile) { $escribirRegistro = [bool]$job.logFile }
    $escritor = $null
    if ($escribirRegistro) {
        $escritor = New-Object System.IO.StreamWriter($logRobo, $true, (New-Object System.Text.UTF8Encoding($false)))
    }
    $procesados = 0
    $errores = 0
    $reloj = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        foreach ($p in $plan) {
            Write-Evento @{ t = 'carpeta'; estado = 'inicio'; origen = $p.Source; destino = $p.Dest; archivos = $p.Files; bytes = (Get-Tamano $p.Bytes) }
            try {
                if ($escritor) {
                    $escritor.WriteLine(('--- {0} -> {1} ({2} archivos, {3}) ---' -f $p.Source, $p.Dest, $p.Files, (Get-Tamano $p.Bytes)))
                    $escritor.Flush()
                }
            } catch { }
            $antesCarpeta = $procesados
            $argumentos = @(
                $p.Source, $p.Dest, '/E', '/R:2', '/W:2', '/XJ', '/V',
                '/NP', '/NDL', '/NJS', '/NJH', '/COPY:DAT', '/DCOPY:T'
            )
            & "$env:SystemRoot\System32\robocopy.exe" @argumentos 2>&1 | ForEach-Object {
                $linea = [string]$_
                if (-not $linea.Trim()) { return }
                try { if ($escritor) { $escritor.WriteLine($linea) } } catch { }
                if ($linea -match "`t\s*\d+`t") {
                    $procesados++
                    if (($procesados % 25) -eq 0) {
                        try { if ($escritor) { $escritor.Flush() } } catch { }
                        Write-Evento @{ t = 'progreso'; procesados = $procesados; total = $totalArchivos; segundos = [math]::Round($reloj.Elapsed.TotalSeconds, 1) }
                    }
                } elseif ($linea -match 'ERROR|denegado|denied') {
                    $errores++
                }
            }
            $codigo = $LASTEXITCODE
            $okCarpeta = ($codigo -lt 8)
            if (-not $okCarpeta) { $errores++ }
            try { if ($escritor) { $escritor.Flush() } } catch { }
            Write-Evento @{ t = 'carpeta'; estado = 'fin'; origen = $p.Source; codigo = $codigo; procesados = ($procesados - $antesCarpeta); ok = $okCarpeta }
        }

        if ([bool]$job.verify) {
            $fallos = 0
            foreach ($p in $plan) {
                if (-not (Test-Path -LiteralPath $p.Dest)) { $fallos++; continue }
                $medidaDest = Measure-Carpeta -Path $p.Dest
                $okV = ($medidaDest.Files -ge $p.Files -and $medidaDest.Bytes -ge $p.Bytes)
                if (-not $okV) { $fallos++ }
                Write-Evento @{ t = 'verificado'; origen = $p.Source; ok = $okV; archivos = $medidaDest.Files; esperados = $p.Files; bytes = (Get-Tamano $medidaDest.Bytes) }
            }
            if ($fallos -gt 0) { $errores++ }
        }

        Write-Evento @{ t = 'resultado'; ok = ($errores -eq 0); modo = 'files'; procesados = $procesados; archivos = $totalArchivos; errores = $errores; destino = $destino; segundos = [math]::Round($reloj.Elapsed.TotalSeconds, 1) }
        Write-Evento @{ t = 'fin' }
    } finally {
        try { if ($escritor) { $escritor.Flush(); $escritor.Close() } } catch { }
    }
} catch {
    Write-Evento @{ t = 'fatal'; mensaje = $_.Exception.Message }
    Write-Evento @{ t = 'fin' }
}
'@

function Get-BackupPresets {
    $lista = New-Object System.Collections.ArrayList
    $candidatos = @(
        @{ Name = 'Documentos'; Path = [Environment]::GetFolderPath('MyDocuments') },
        @{ Name = 'Escritorio'; Path = [Environment]::GetFolderPath('Desktop') },
        @{ Name = 'Imagenes';   Path = [Environment]::GetFolderPath('MyPictures') },
        @{ Name = 'Musica';     Path = [Environment]::GetFolderPath('MyMusic') },
        @{ Name = 'Videos';     Path = [Environment]::GetFolderPath('MyVideos') },
        @{ Name = 'Descargas';  Path = (Join-Path $env:USERPROFILE 'Downloads') },
        @{ Name = 'Favoritos';  Path = [Environment]::GetFolderPath('Favorites') }
    )
    $vistos = @{}
    foreach ($c in $candidatos) {
        if (-not $c.Path) { continue }
        if (-not (Test-Path -LiteralPath $c.Path)) { continue }
        $clave = $c.Path.ToLowerInvariant()
        if ($vistos.ContainsKey($clave)) { continue }
        $vistos[$clave] = $true
        [void]$lista.Add([pscustomobject]@{ Name = $c.Name; Path = $c.Path })
    }
    return @($lista)
}

function Get-BackupOtherDriveRoot {
    try {
        $d = Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction SilentlyContinue |
            Where-Object { $_.DeviceID -ne $env:SystemDrive } |
            Sort-Object FreeSpace -Descending |
            Select-Object -First 1
        if ($d) { return ([string]$d.DeviceID + '\') }
    } catch { }
    return ''
}

function Get-BackupFreeSpaceText {
    param([string]$Path)
    try {
        $raiz = [System.IO.Path]::GetPathRoot($Path)
        if (-not $raiz) { return '' }
        $letra = $raiz.TrimEnd('\')
        $d = Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $letra) -ErrorAction SilentlyContinue
        if ($d) {
            $libre = [math]::Round([double]$d.FreeSpace / 1GB, 1)
            $total = [math]::Round([double]$d.Size / 1GB, 1)
            return ('Libre en {0}: {1} GB de {2} GB' -f $letra, $libre, $total)
        }
    } catch { }
    return ''
}

function Get-BackupDiskNumber {
    param([string]$Path)
    try {
        $raiz = [System.IO.Path]::GetPathRoot($Path)
        if ($raiz -match '^([A-Za-z]):') {
            $p = Get-Partition -DriveLetter $Matches[1] -ErrorAction Stop
            if ($p) { return [int]$p.DiskNumber }
        }
    } catch { }
    return -1
}

function Update-BackupDestinationInfo {
    if (-not $script:bkDest) { return }
    $destino = $script:bkDest.Text.Trim()
    if (-not $destino) {
        $script:lblBkFree.Text = 'Elige una carpeta o unidad de destino.'
        $script:lblBkFree.ForeColor = [System.Drawing.Color]::FromArgb(90, 90, 90)
        return
    }
    $texto = Get-BackupFreeSpaceText $destino
    if (-not $texto) { $texto = 'No se pudo leer el espacio libre del destino.' }
    $color = [System.Drawing.Color]::FromArgb(90, 90, 90)
    $aviso = ''
    try {
        $raiz = [System.IO.Path]::GetPathRoot($destino)
        if ($raiz -and ($raiz.TrimEnd('\') -ieq $env:SystemDrive)) {
            if ($script:bkMode -eq 'image') {
                $aviso = '  |  Elige OTRA unidad: la imagen no puede ir en ' + $env:SystemDrive
                $color = [System.Drawing.Color]::FromArgb(180, 30, 30)
            } else {
                $aviso = '  |  Aviso: mismo disco que Windows'
                $color = [System.Drawing.Color]::FromArgb(170, 90, 0)
            }
        }
    } catch { }
    $script:lblBkFree.Text = $texto + $aviso
    $script:lblBkFree.ForeColor = $color
}

function Set-BackupMode {
    param([string]$Mode)
    if ($Mode -ne 'image') { $Mode = 'files' }
    $script:bkMode = $Mode
    $script:bkChangingMode = $true
    try {
        $esImagen = ($Mode -eq 'image')
        $script:rbBkFolders.Checked = -not $esImagen
        $script:rbBkImage.Checked = $esImagen
        if ($esImagen) {
            $otra = ''
            try { $otra = [System.IO.Path]::GetPathRoot($script:bkDest.Text.Trim()) } catch { }
            if ($otra -and ($otra.TrimEnd('\') -ine $env:SystemDrive)) {
                $script:bkDest.Text = $otra
            } else {
                $otra = Get-BackupOtherDriveRoot
                if ($otra) { $script:bkDest.Text = $otra }
            }
        }
    } finally {
        $script:bkChangingMode = $false
    }
    Update-BackupDestinationInfo
    Update-BackupButtons
}

function Update-BackupButtons {
    $busy = [bool]$script:bkProcess
    $esImagen = ($script:bkMode -eq 'image')
    $script:btnBkStart.Enabled = -not $busy
    $script:btnBkStop.Enabled = $busy
    $script:rbBkFolders.Enabled = -not $busy
    $script:rbBkImage.Enabled = -not $busy
    $script:btnBkBrowse.Enabled = -not $busy
    $script:bkDest.Enabled = -not $busy
    $script:bkList.Enabled = (-not $busy) -and (-not $esImagen)
    $script:btnBkAdd.Enabled = (-not $busy) -and (-not $esImagen)
    $script:btnBkRemove.Enabled = (-not $busy) -and (-not $esImagen)
    $script:btnBkCommon.Enabled = (-not $busy) -and (-not $esImagen)
    $script:btnBkNone.Enabled = (-not $busy) -and (-not $esImagen)
}

function Get-BackupSelectedPaths {
    $paths = @()
    foreach ($item in @($script:bkList.CheckedItems)) {
        $nombre = [string]$item
        if ($script:bkPathByName.ContainsKey($nombre)) { $paths += [string]$script:bkPathByName[$nombre] }
    }
    return @($paths)
}

function Add-BackupFolderItem {
    param([string]$Path)
    if (-not $Path) { return }
    $nombre = [System.IO.Path]::GetFileName(([string]$Path).TrimEnd('\'))
    if (-not $nombre) { $nombre = $Path }
    $base = $nombre
    $n = 2
    while ($script:bkPathByName.ContainsKey($nombre)) {
        $nombre = ('{0} ({1})' -f $base, $n)
        $n++
    }
    [void]$script:bkList.Items.Add($nombre)
    $script:bkPathByName[$nombre] = $Path
    $script:bkList.SetItemChecked($script:bkList.Items.Count - 1, $true)
}

function Initialize-BackupFolderList {
    $script:bkPathByName = @{}
    $script:bkList.Items.Clear()
    foreach ($p in (Get-BackupPresets)) {
        [void]$script:bkList.Items.Add($p.Name)
        $script:bkPathByName[$p.Name] = $p.Path
    }
    for ($i = 0; $i -lt $script:bkList.Items.Count; $i++) {
        $nombre = [string]$script:bkList.Items[$i]
        if ($nombre -eq 'Documentos' -or $nombre -eq 'Escritorio') {
            $script:bkList.SetItemChecked($i, $true)
        }
    }
}

function Start-BackupChild {
    param([string]$JobJson)

    $script:bkReadPos = 0
    $script:bkOutFile = $null
    $script:bkScript  = $null
    $script:bkJobFile = $null

    try {
        $dirTrabajo = Get-WorkDir
        $script:bkOutFile = Join-Path $dirTrabajo ('wintaller_copia_{0}.log' -f ([guid]::NewGuid().ToString('N')))
        $script:bkScript  = Join-Path $dirTrabajo ('wintaller_copia_{0}.ps1' -f ([guid]::NewGuid().ToString('N')))
        $script:bkJobFile = Join-Path $dirTrabajo ('wintaller_copia_{0}.json' -f ([guid]::NewGuid().ToString('N')))
        [System.IO.File]::WriteAllText($script:bkScript, $script:bkChildScript, (New-Object System.Text.UTF8Encoding($true)))
        [System.IO.File]::WriteAllText($script:bkJobFile, $JobJson, (New-Object System.Text.UTF8Encoding($true)))
    } catch {
        Add-TabLog $script:bkLog ('No se pudo preparar la copia: {0}' -f $_.Exception.Message) 'ERROR'
        Clear-BackupTempFiles
        return $false
    }

    $argumentos = @(
        '-NoProfile', '-ExecutionPolicy', 'Bypass', '-STA',
        '-File', ('"' + $script:bkScript + '"'),
        '-OutFile', ('"' + $script:bkOutFile + '"'),
        '-JobFile', ('"' + $script:bkJobFile + '"')
    )

    try {
        $script:bkProcess = Start-Process -FilePath (Join-Path $PSHOME 'powershell.exe') -ArgumentList $argumentos -PassThru -WindowStyle Hidden
        $script:bkProcess.EnableRaisingEvents = $true
        $script:bkStarted = Get-Date
        $script:bkTimer.Start()
        return $true
    } catch {
        Add-TabLog $script:bkLog ('No se pudo iniciar la copia: {0}' -f $_.Exception.Message) 'ERROR'
        $script:bkProcess = $null
        Clear-BackupTempFiles
        return $false
    }
}

function Start-BackupJob {
    param(
        [string[]]$Sources,
        [string]$Destination,
        [string]$Mode = 'files',
        [switch]$Testing
    )

    if ($script:bkProcess) { return }
    if ($Mode -ne 'image') { $Mode = 'files' }
    $script:bkRunMode = $Mode
    if (-not $Destination) { $Destination = $script:bkDest.Text.Trim() }
    if (-not $Sources -or $Sources.Count -eq 0) {
        if ($Mode -eq 'files') { $Sources = @(Get-BackupSelectedPaths) }
    }

    if (-not $Destination) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'Elige primero la carpeta o unidad de destino.', "$script:AppName - copias", 'OK', 'Information')
        return
    }

    if ($Mode -eq 'image') {
        if (-not (Test-Path -LiteralPath (Join-Path $env:SystemRoot 'System32\wbadmin.exe'))) {
            [void][System.Windows.Forms.MessageBox]::Show(
                "Este Windows no incluye wbadmin, la herramienta de imagen del sistema.`n`nPuedes usar la copia de carpetas.",
                "$script:AppName - copias", 'OK', 'Warning')
            return
        }
        if (-not $Testing -and -not $script:IsAdmin) {
            [void][System.Windows.Forms.MessageBox]::Show(
                "Crear una imagen del sistema necesita permisos de administrador.`n`nAbre el programa con Iniciar.bat (pide UAC).",
                "$script:AppName - permisos", 'OK', 'Warning')
            return
        }
        if ($Destination -notmatch '^[A-Za-z]:[\\/]*$') {
            [void][System.Windows.Forms.MessageBox]::Show(
                "Para la imagen del sistema el destino debe ser la raiz de otra unidad, por ejemplo E:\`n`nAhora es: $Destination",
                "$script:AppName - copias", 'OK', 'Warning')
            return
        }
        if ($Destination.Substring(0, 2) -ieq $env:SystemDrive) {
            [void][System.Windows.Forms.MessageBox]::Show(
                "La imagen del sistema no se puede guardar en la misma unidad que Windows.`n`nConecta un disco externo o usa otra unidad.",
                "$script:AppName - copias", 'OK', 'Warning')
            return
        }
        $discoDestino = Get-CimInstance Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $Destination.Substring(0, 2)) -ErrorAction SilentlyContinue
        if (-not $discoDestino) {
            [void][System.Windows.Forms.MessageBox]::Show(
                "La unidad $($Destination.Substring(0, 2)) no está disponible.", "$script:AppName - copias", 'OK', 'Warning')
            return
        }
        if ([string]$discoDestino.FileSystem -ne 'NTFS') {
            [void][System.Windows.Forms.MessageBox]::Show(
                "La unidad de destino debe estar formateada en NTFS.`n`nAhora es $($discoDestino.FileSystem).", "$script:AppName - copias", 'OK', 'Warning')
            return
        }
    } else {
        if ($Sources.Count -eq 0) {
            [void][System.Windows.Forms.MessageBox]::Show(
                'Marca al menos una carpeta para copiar.', "$script:AppName - copias", 'OK', 'Information')
            return
        }
        foreach ($s in $Sources) {
            if (-not (Test-Path -LiteralPath $s)) {
                [void][System.Windows.Forms.MessageBox]::Show(
                    ("La carpeta no existe:`n{0}" -f $s), "$script:AppName - copias", 'OK', 'Warning')
                return
            }
        }
        try {
            $destinoPlano = [System.IO.Path]::GetFullPath($Destination).TrimEnd('\') + '\'
            foreach ($s in $Sources) {
                $origenPlano = [System.IO.Path]::GetFullPath($s).TrimEnd('\') + '\'
                if ($destinoPlano.StartsWith($origenPlano, [System.StringComparison]::OrdinalIgnoreCase)) {
                    [void][System.Windows.Forms.MessageBox]::Show(
                        "El destino no puede estar dentro de una carpeta que se va a copiar.`n`nDestino: $Destination`nCarpeta: $s",
                        "$script:AppName - copias", 'OK', 'Warning')
                    return
                }
            }
        } catch { }
        try {
            [void](New-Item -ItemType Directory -Path $Destination -Force -ErrorAction Stop)
        } catch {
            [void][System.Windows.Forms.MessageBox]::Show(
                ("No se pudo crear o abrir el destino:`n{0}`n`n{1}" -f $Destination, $_.Exception.Message),
                "$script:AppName - copias", 'OK', 'Warning')
            return
        }
    }

    $mismoDisco = $false
    if ($Mode -eq 'image') {
        $d1 = Get-BackupDiskNumber $env:SystemDrive
        $d2 = Get-BackupDiskNumber $Destination
        if ($d1 -ge 0 -and $d1 -eq $d2) { $mismoDisco = $true }
    } else {
        $d1 = Get-BackupDiskNumber $Sources[0]
        $d2 = Get-BackupDiskNumber $Destination
        if ($d1 -ge 0 -and $d1 -eq $d2) { $mismoDisco = $true }
    }

    if (-not $Testing) {
        $lineas = @()
        if ($Mode -eq 'image') {
            $lineas += 'Se creará una imagen completa de Windows (volúmenes críticos).'
            $lineas += ''
            $lineas += ('Destino: {0}' -f $Destination)
            $lineas += 'Se guardara en la carpeta WindowsImageBackup.'
            $lineas += ''
            $lineas += 'Puede tardar entre 10 y 60 minutos y ocupar varios GB. No apagues el equipo.'
            if ($mismoDisco) {
                $lineas += ''
                $lineas += 'AVISO: el destino parece estar en el mismo disco físico que Windows. Si ese disco falla, perderas también la copia.'
            }
        } else {
            $lineas += ('Se copiaran {0} carpetas:' -f $Sources.Count)
            foreach ($s in $Sources) { $lineas += ('  - ' + $s) }
            $lineas += ''
            $lineas += ('Destino: {0}' -f $Destination)
            $lineas += ''
            $lineas += 'No se borra nada en el origen. Los archivos que ya son iguales no se copian otra vez.'
            if ($mismoDisco) {
                $lineas += ''
                $lineas += 'AVISO: el destino esta en el mismo disco físico que el origen. Si el disco falla, perderas también la copia.'
            }
        }
        $lineas += ''
        $lineas += 'Continuar?'
        $respuesta = [System.Windows.Forms.MessageBox]::Show(
            ($lineas -join "`r`n"), "$script:AppName - copias", 'YesNo', 'Question')
        if ($respuesta -ne 'Yes') { return }
    }

    $script:bkErrors      = 0
    $script:bkProcessed   = 0
    $script:bkTotalFiles  = 0
    $script:bkResultOk    = $false
    $script:bkSawResult   = $false
    $script:bkDestFinal   = $Destination
    $script:bkOpenAfter   = $false
    if (-not $Testing) { $script:bkOpenAfter = [bool]$chkBkOpen.Checked }

    $script:bkBar.Style = 'Blocks'
    $script:bkBar.Value = 0
    if ($Mode -eq 'image') {
        $script:bkBar.Style = 'Marquee'
        $script:bkBar.MarqueeAnimationSpeed = 40
        Add-TabLog $script:bkLog ('=== Imagen del sistema -> {0} ===' -f $Destination) 'STEP'
        Add-TabLog $script:bkLog 'Creando la imagen con wbadmin. Esto puede tardar bastante...'
        $script:statusLabel.Text = 'Creando imagen del sistema...'
    } else {
        Add-TabLog $script:bkLog ('=== Copia de {0} carpetas -> {1} ===' -f $Sources.Count, $Destination) 'STEP'
        Add-TabLog $script:bkLog 'Contando archivos y comprobando el espacio libre...'
        $script:statusLabel.Text = 'Preparando la copia...'
    }

    $job = @{
        mode    = $Mode
        dest    = $Destination
        sources = @($Sources)
        verify  = [bool]$chkBkVerify.Checked
        logFile = [bool]$chkBkLogFile.Checked
    }
    if ($Testing) { $job.verify = $true; $job.logFile = $true }
    $json = $job | ConvertTo-Json -Depth 4

    if (-not (Start-BackupChild -JobJson $json)) {
        $script:bkBar.Style = 'Blocks'
        $script:statusLabel.Text = 'No se pudo iniciar la copia'
        Update-BackupButtons
        return
    }
    Update-BackupButtons
}

function Read-BackupEvents {
    if (-not $script:bkOutFile) { return }
    if (-not (Test-Path -LiteralPath $script:bkOutFile)) { return }
    try {
        $lineas = @(Get-Content -LiteralPath $script:bkOutFile -Encoding UTF8 -ErrorAction SilentlyContinue)
        while ($script:bkReadPos -lt $lineas.Count) {
            $linea = [string]$lineas[$script:bkReadPos]
            $script:bkReadPos++
            if (-not $linea.Trim()) { continue }
            $evt = $null
            try { $evt = $linea | ConvertFrom-Json } catch { continue }
            if (-not $evt) { continue }
            switch ([string]$evt.t) {
                'contando' {
                    Add-TabLog $script:bkLog 'Contando archivos de las carpetas elegidas...'
                }
                'plan' {
                    $script:bkTotalFiles = [int]$evt.archivos
                    Add-TabLog $script:bkLog ('Archivos a procesar: {0} ({1}). Libre en destino: {2}.' -f $evt.archivos, $evt.bytes, $evt.libre)
                }
                'carpeta' {
                    if ([string]$evt.estado -eq 'inicio') {
                        Add-TabLog $script:bkLog ('Copiando {0} -> {1} ({2} archivos, {3})...' -f $evt.origen, $evt.destino, $evt.archivos, $evt.bytes) 'STEP'
                    } elseif ([bool]$evt.ok) {
                        Add-TabLog $script:bkLog ('{0}: terminada (código {1}, {2} archivos procesados).' -f $evt.origen, $evt.codigo, $evt.procesados) 'OK'
                    } else {
                        Add-TabLog $script:bkLog ('{0}: robocopy devolvió el código {1} y ha habido errores.' -f $evt.origen, $evt.codigo) 'WARN'
                    }
                }
                'progreso' {
                    $script:bkProcessed = [int]$evt.procesados
                    if ($script:bkTotalFiles -gt 0) {
                        $pct = [int](100 * $script:bkProcessed / $script:bkTotalFiles)
                        if ($pct -gt 99) { $pct = 99 }
                        if ($pct -lt 0) { $pct = 0 }
                        $script:bkBar.Style = 'Blocks'
                        $script:bkBar.Value = $pct
                        $script:statusLabel.Text = ('Copiando... {0}% ({1} de {2} archivos)' -f $pct, $script:bkProcessed, $script:bkTotalFiles)
                    } else {
                        $script:statusLabel.Text = ('Copiando... {0} archivos procesados' -f $script:bkProcessed)
                    }
                }
                'aviso' {
                    Add-TabLog $script:bkLog ([string]$evt.texto) 'WARN'
                }
                'verificado' {
                    if ([bool]$evt.ok) {
                        Add-TabLog $script:bkLog ('Comprobado {0}: {1} archivos en el destino (esperados {2}).' -f $evt.origen, $evt.archivos, $evt.esperados) 'OK'
                    } else {
                        Add-TabLog $script:bkLog ('La comprobación de {0} no coincide: {1} archivos en destino, {2} esperados.' -f $evt.origen, $evt.archivos, $evt.esperados) 'WARN'
                    }
                }
                'linea' {
                    Add-TabLog $script:bkLog ([string]$evt.texto)
                }
                'resultado' {
                    $script:bkSawResult = $true
                    $script:bkResultOk = [bool]$evt.ok
                    if ($null -ne $evt.segundos) {
                        try { $script:bkStarted = (Get-Date).AddSeconds(-1 * [double]$evt.segundos) } catch { }
                    }
                    if ([string]$evt.modo -eq 'image') {
                        if ($script:bkResultOk) {
                            Add-TabLog $script:bkLog ('Imagen creada en {0}.' -f $evt.destino) 'OK'
                        } else {
                            Add-TabLog $script:bkLog ('No se pudo crear la imagen: {0}.' -f $evt.texto) 'ERROR'
                            $script:bkErrors++
                        }
                    } else {
                        if ($script:bkResultOk) {
                            Add-TabLog $script:bkLog ('Copia terminada: {0} archivos procesados.' -f $evt.procesados) 'OK'
                        } else {
                            Add-TabLog $script:bkLog ('Copia terminada con {0} error(es).' -f $evt.errores) 'WARN'
                            $script:bkErrors++
                        }
                    }
                }
                'fatal' {
                    $script:bkErrors++
                    Add-TabLog $script:bkLog ('Error: {0}' -f $evt.mensaje) 'ERROR'
                }
            }
        }
    } catch { }
}

function Complete-BackupJob {
    $script:bkBar.Style = 'Blocks'
    $ok = ($script:bkResultOk -and $script:bkSawResult)
    if (-not $script:bkSawResult) {
        Add-TabLog $script:bkLog 'La copia terminó sin dar un resultado. Revisa el registro.' 'ERROR'
    }
    if ($ok) {
        $script:bkBar.Value = 100
        $script:statusLabel.Text = 'Copia terminada correctamente'
    } else {
        $script:statusLabel.Text = 'Copia terminada con errores'
    }
    $minutos = 0
    if ($script:bkStarted) {
        try { $minutos = [math]::Round(((Get-Date) - $script:bkStarted).TotalMinutes, 1) } catch { }
    }
    $estado = 'con errores'
    if ($ok) { $estado = 'correcta' }
    Add-TabLog $script:bkLog ('=== Fin: {0} | tiempo {1} min ===' -f $estado, $minutos) 'STEP'
    Update-BackupButtons
    if ($ok -and $script:bkOpenAfter) {
        Open-BackupDestination
    }
    if (-not $UiSmokeTest) {
        $texto = 'Copia terminada.' + "`n`n"
        if ($ok) { $texto += 'Todo correcto.' } else { $texto += 'Ha habido errores; revisa el registro.' }
        $texto += "`n`nDestino: " + $script:bkDestFinal
        $icono = 'Information'
        if (-not $ok) { $icono = 'Warning' }
        [void][System.Windows.Forms.MessageBox]::Show($texto, "$script:AppName - copias", 'OK', $icono)
    }
}

function Step-BackupJob {
    $proc = $script:bkProcess
    if (-not $proc) { return }

    Read-BackupEvents

    $terminado = $false
    try { $terminado = $proc.HasExited } catch { $terminado = $true }

    if (-not $terminado) {
        if ($script:bkStarted -and ((Get-Date) - $script:bkStarted).TotalHours -gt 6) {
            try { & "$env:SystemRoot\System32\taskkill.exe" /PID $proc.Id /T /F 2>&1 | Out-Null } catch { }
            try { $proc.Dispose() } catch { }
            $script:bkProcess = $null
            $script:bkTimer.Stop()
            Clear-BackupTempFiles
            $script:bkBar.Style = 'Blocks'
            Add-TabLog $script:bkLog 'La copia superó 6 horas y se ha cancelado.' 'WARN'
            $script:statusLabel.Text = 'Copia cancelada'
            Update-BackupButtons
            return
        }
        if ($script:bkRunMode -eq 'image') {
            $min = 0
            if ($script:bkStarted) { $min = [int]((Get-Date) - $script:bkStarted).TotalMinutes }
            $script:statusLabel.Text = ('Creando imagen del sistema... {0} min' -f $min)
        } else {
            $script:statusLabel.Text = ('Copiando... {0} archivos procesados' -f $script:bkProcessed)
        }
        return
    }

    Read-BackupEvents
    try { $proc.Dispose() } catch { }
    $script:bkProcess = $null
    $script:bkTimer.Stop()
    Clear-BackupTempFiles
    Complete-BackupJob
}

function Stop-BackupJob {
    if ($script:bkProcess) {
        try {
            if (-not $script:bkProcess.HasExited) {
                & "$env:SystemRoot\System32\taskkill.exe" /PID $script:bkProcess.Id /T /F 2>&1 | Out-Null
            }
        } catch {
            try { $script:bkProcess.Kill() } catch { }
        }
        try { $script:bkProcess.Dispose() } catch { }
        Add-TabLog $script:bkLog 'Copia detenida por el usuario.' 'WARN'
    }
    $script:bkProcess = $null
    $script:bkTimer.Stop()
    Clear-BackupTempFiles
    $script:bkBar.Style = 'Blocks'
    $script:statusLabel.Text = 'Copia detenida'
    Update-BackupButtons
}

function Clear-BackupTempFiles {
    foreach ($f in @($script:bkOutFile, $script:bkScript, $script:bkJobFile)) {
        if ($f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
    }
    $script:bkOutFile = $null
    $script:bkScript  = $null
    $script:bkJobFile = $null
}

function Open-BackupDestination {
    $dest = $script:bkDestFinal
    if (-not $dest) { $dest = $script:bkDest.Text.Trim() }
    if ($script:bkRunMode -eq 'image' -and $dest) {
        try {
            $posible = Join-Path $dest 'WindowsImageBackup'
            if (Test-Path -LiteralPath $posible) { $dest = $posible }
        } catch { }
    }
    if ($dest -and (Test-Path -LiteralPath $dest)) {
        try { Start-Process -FilePath (Join-Path $env:SystemRoot 'explorer.exe') -ArgumentList ('"{0}"' -f $dest) | Out-Null } catch { }
    } else {
        [void][System.Windows.Forms.MessageBox]::Show(
            'Todavía no hay una carpeta de destino que abrir.', "$script:AppName - copias", 'OK', 'Information')
    }
}

function Show-BackupDrivePicker {
    $unidades = @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction SilentlyContinue |
        Where-Object { $_.DeviceID -ne $env:SystemDrive } |
        Sort-Object FreeSpace -Descending)
    if ($unidades.Count -eq 0) {
        [void][System.Windows.Forms.MessageBox]::Show(
            "No hay otra unidad disponible.`n`nConecta un disco externo o una segunda unidad para guardar la imagen del sistema.",
            "$script:AppName - copias", 'OK', 'Warning')
        return ''
    }

    $form = New-Object System.Windows.Forms.Form
    try { $form.Icon = Get-AppIcon } catch { }
    $form.Text = 'Unidad para la imagen del sistema'
    $form.Size = New-Object System.Drawing.Size(480, 330)
    $form.StartPosition = 'CenterParent'
    $form.FormBorderStyle = 'FixedDialog'
    $form.MaximizeBox = $false
    $form.MinimizeBox = $false
    $form.Font = $script:uiFont

    $lista = New-Object System.Windows.Forms.ListView
    $lista.Dock = 'Fill'
    $lista.View = 'Details'
    $lista.FullRowSelect = $true
    $lista.MultiSelect = $false
    $lista.HideSelection = $false
    $lista.Font = $script:uiFont
    [void]$lista.Columns.Add('Unidad', 80)
    [void]$lista.Columns.Add('Nombre', 150)
    [void]$lista.Columns.Add('Libre (GB)', 100)
    [void]$lista.Columns.Add('Total (GB)', 100)
    foreach ($u in $unidades) {
        $item = New-Object System.Windows.Forms.ListViewItem([string]$u.DeviceID)
        [void]$item.SubItems.Add([string]$u.VolumeName)
        [void]$item.SubItems.Add([string]([math]::Round([double]$u.FreeSpace / 1GB, 1)))
        [void]$item.SubItems.Add([string]([math]::Round([double]$u.Size / 1GB, 1)))
        $item.Tag = ([string]$u.DeviceID + '\')
        [void]$lista.Items.Add($item)
    }
    if ($lista.Items.Count -gt 0) { $lista.Items[0].Selected = $true }

    $botones = New-Object System.Windows.Forms.FlowLayoutPanel
    $botones.Dock = 'Bottom'
    $botones.FlowDirection = 'RightToLeft'
    $botones.Height = 46
    $botones.Padding = New-Object System.Windows.Forms.Padding(0, 8, 8, 0)
    $ok = New-Object System.Windows.Forms.Button
    $ok.Text = 'Usar esta unidad'
    $ok.AutoSize = $true
    $ok.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $cancelar = New-Object System.Windows.Forms.Button
    $cancelar.Text = 'Cancelar'
    $cancelar.AutoSize = $true
    $cancelar.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $botones.Controls.Add($cancelar)
    $botones.Controls.Add($ok)
    $form.Controls.Add($lista)
    $form.Controls.Add($botones)
    $form.AcceptButton = $ok
    $form.CancelButton = $cancelar

    $elegida = ''
    $resultado = $form.ShowDialog()
    if ($resultado -eq [System.Windows.Forms.DialogResult]::OK -and $lista.SelectedItems.Count -gt 0) {
        $elegida = [string]$lista.SelectedItems[0].Tag
    }
    $form.Dispose()
    return $elegida
}

