# Valores iniciales de la pestaña
$otraUnidad = Get-BackupOtherDriveRoot
if ($otraUnidad) {
    $script:bkDest.Text = Join-Path $otraUnidad 'Copia-WinTaller'
} else {
    $script:bkDest.Text = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'Copias'
}
Initialize-BackupFolderList
Set-BackupMode 'files'
Update-BackupDestinationInfo
Update-BackupButtons

$script:rbBkFolders.add_CheckedChanged({
    if ($script:bkChangingMode) { return }
    if ($script:rbBkFolders.Checked) { Set-BackupMode 'files' }
})

$script:rbBkImage.add_CheckedChanged({
    if ($script:bkChangingMode) { return }
    if ($script:rbBkImage.Checked) { Set-BackupMode 'image' }
})

$script:bkDest.add_Leave({ Update-BackupDestinationInfo })

$script:btnBkBrowse.add_Click({
    if ($script:bkProcess) { return }
    if ($script:bkMode -eq 'image') {
        $unidad = Show-BackupDrivePicker
        if ($unidad) {
            $script:bkDest.Text = $unidad
            Update-BackupDestinationInfo
        }
        return
    }
    $dialogo = New-Object System.Windows.Forms.FolderBrowserDialog
    $dialogo.Description = 'Selecciona la carpeta de destino para la copia'
    $dialogo.ShowNewFolderButton = $true
    try {
        $inicial = [System.IO.Path]::GetPathRoot($script:bkDest.Text.Trim())
        if ($inicial) { $dialogo.SelectedPath = $inicial }
    } catch { }
    if ($dialogo.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        $script:bkDest.Text = $dialogo.SelectedPath
        Update-BackupDestinationInfo
    }
})

$script:btnBkAdd.add_Click({
    if ($script:bkProcess -or $script:bkMode -eq 'image') { return }
    $dialogo = New-Object System.Windows.Forms.FolderBrowserDialog
    $dialogo.Description = 'Selecciona la carpeta que quieres copiar'
    $dialogo.ShowNewFolderButton = $false
    if ($dialogo.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        Add-BackupFolderItem $dialogo.SelectedPath
    }
})

$script:btnBkRemove.add_Click({
    if ($script:bkProcess -or $script:bkMode -eq 'image') { return }
    $indices = @($script:bkList.CheckedIndices)
    [array]::Sort($indices)
    [array]::Reverse($indices)
    foreach ($i in $indices) {
        $nombre = [string]$script:bkList.Items[$i]
        if ($script:bkPathByName.ContainsKey($nombre)) { $script:bkPathByName.Remove($nombre) }
        $script:bkList.Items.RemoveAt($i)
    }
})

$script:btnBkCommon.add_Click({
    if ($script:bkProcess -or $script:bkMode -eq 'image') { return }
    for ($i = 0; $i -lt $script:bkList.Items.Count; $i++) {
        $script:bkList.SetItemChecked($i, $true)
    }
})

$script:btnBkNone.add_Click({
    if ($script:bkProcess -or $script:bkMode -eq 'image') { return }
    for ($i = 0; $i -lt $script:bkList.Items.Count; $i++) {
        $script:bkList.SetItemChecked($i, $false)
    }
})

$script:btnBkStart.add_Click({
    if ($script:bkProcess) { return }
    Start-BackupJob -Mode $script:bkMode
})

$script:btnBkStop.add_Click({
    if (-not $script:bkProcess) { return }
    $respuesta = [System.Windows.Forms.MessageBox]::Show(
        'Se detendrá la copia en curso. Lo que ya se ha copiado se conserva. Continuar?',
        "$script:AppName - confirmar", 'YesNo', 'Question')
    if ($respuesta -eq 'Yes') { Stop-BackupJob }
})

$script:btnBkOpen.add_Click({ Open-BackupDestination })

$btnBkSave.add_Click({ Save-LogBox $script:bkLog 'copias' })

$btnBkClear.add_Click({
    $script:bkLog.Clear()
    Add-TabLog $script:bkLog 'Registro limpiado.'
})

