# ---------------------------------------------------------------------------
# Funciones de la pestaña Seguridad
# ---------------------------------------------------------------------------

# Ruta de MpCmdRun.exe: primero la plataforma más reciente de Defender
# (ProgramData, solo escribible por SYSTEM) y si no, la de Program Files.
function Get-MpCmdRunPath {
    $candidatos = @()
    $plataforma = Join-Path $env:ProgramData 'Microsoft\Windows Defender\Platform'
    if (Test-Path -LiteralPath $plataforma) {
        $carpetas = @(Get-ChildItem -LiteralPath $plataforma -Directory -ErrorAction SilentlyContinue)
        $ordenadas = $carpetas | Sort-Object -Descending -Property @{ Expression = {
            $v = [version]'0.0'
            try { $v = [version](($_.Name -split '-')[0]) } catch { }
            $v
        } }
        foreach ($c in $ordenadas) { $candidatos += (Join-Path $c.FullName 'MpCmdRun.exe') }
    }
    $candidatos += (Join-Path $env:ProgramFiles 'Windows Defender\MpCmdRun.exe')
    foreach ($c in $candidatos) {
        if (Test-Path -LiteralPath $c) { return $c }
    }
    return $null
}

# Entrecomilla un argumento para la línea de comandos. Las barras finales se
# duplican para que "E:\" no se convierta en una comilla escapada.
function ConvertTo-QuotedArgument {
    param([string]$Value)
    $v = $Value -replace '(\\+)$', '$1$1'
    return ('"' + $v + '"')
}

# Antivirus registrados en el Centro de seguridad de Windows.
function Get-AntivirusProducts {
    $lista = @()
    try {
        $productos = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName 'AntiVirusProduct' -ErrorAction Stop)
        foreach ($p in $productos) {
            $hex = '{0:X6}' -f [int]$p.productState
            if ($hex.Length -gt 6) { $hex = $hex.Substring($hex.Length - 6) }
            $lista += [pscustomobject]@{
                Name       = [string]$p.displayName
                Enabled    = (@('10', '11') -contains $hex.Substring(2, 2))
                UpToDate   = ($hex.Substring(4, 2) -eq '00')
                IsDefender = ([string]$p.displayName -match 'Defender')
            }
        }
    } catch { }
    return $lista
}

function Get-ExecutableFromCommand {
    param([string]$Command)
    $c = [Environment]::ExpandEnvironmentVariables([string]$Command).Trim()
    if (-not $c) { return '' }
    if ($c -match '^"([^"]+)"') { return $Matches[1] }
    if ($c -match '^(.+?\.(exe|com|bat|cmd|vbs|js|ps1|scr))(\s|$)') { return $Matches[1] }
    return ($c -split '\s+')[0]
}

# Programas que arrancan con Windows (claves Run y carpetas Inicio), su firma
# y si están habilitados. El estado se guarda en las claves StartupApproved,
# las mismas que usa la pestaña Inicio del Administrador de tareas: deshabilitar
# no borra nada y se puede deshacer desde aquí o desde el Administrador.
$script:StartupApprovedHKCU = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved'
$script:StartupApprovedHKLM = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved'

function Test-StartupApprovedEnabled {
    param([string]$Key, [string]$Name)
    $valor = $null
    try { $valor = (Get-ItemProperty -LiteralPath $Key -Name $Name -ErrorAction Stop).$Name } catch { return $true }
    $bytes = [byte[]]@($valor)
    if ($bytes.Length -eq 0) { return $true }
    # 02/06 = habilitado; 03/07 = deshabilitado (bit 0 a 1)
    return (($bytes[0] -band 1) -eq 0)
}

function Set-StartupApproved {
    param([string]$Key, [string]$Name, [bool]$Enabled)
    if (-not (Test-Path -LiteralPath $Key)) { New-Item -Path $Key -Force -ErrorAction Stop | Out-Null }
    $bytes = New-Object byte[] 12
    if ($Enabled) {
        $bytes[0] = 2
    } else {
        $bytes[0] = 3
        $marca = [BitConverter]::GetBytes([int64](Get-Date).ToFileTime())
        [Array]::Copy($marca, 0, $bytes, 4, 8)
    }
    New-ItemProperty -LiteralPath $Key -Name $Name -Value $bytes -PropertyType Binary -Force -ErrorAction Stop | Out-Null
}

function Get-StartupEntries {
    $entradas = @()
    $claves = @(
        @{ Ruta = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'; Origen = 'Registro (tu usuario)'; Aprobado = (Join-Path $script:StartupApprovedHKCU 'Run'); Admin = $false },
        @{ Ruta = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'; Origen = 'Registro (todos los usuarios)'; Aprobado = (Join-Path $script:StartupApprovedHKLM 'Run'); Admin = $true },
        @{ Ruta = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'; Origen = 'Registro (todos los usuarios, 32 bits)'; Aprobado = (Join-Path $script:StartupApprovedHKLM 'Run32'); Admin = $true }
    )
    foreach ($clave in $claves) {
        try {
            $props = Get-ItemProperty -LiteralPath $clave.Ruta -ErrorAction Stop
            foreach ($p in $props.PSObject.Properties) {
                if ($p.Name -like 'PS*') { continue }
                $entradas += [pscustomobject]@{
                    Name         = $p.Name
                    Command      = [string]$p.Value
                    Origin       = $clave.Origen
                    Location     = ('{0}  ->  {1}' -f $clave.Ruta, $p.Name)
                    ApprovedKey  = $clave.Aprobado
                    ApprovedName = $p.Name
                    NeedsAdmin   = $clave.Admin
                    FilePath     = ''
                }
            }
        } catch { }
    }
    $shell = $null
    $carpetas = @(
        @{ Ruta = [Environment]::GetFolderPath('Startup'); Origen = 'Carpeta Inicio (tu usuario)'; Aprobado = (Join-Path $script:StartupApprovedHKCU 'StartupFolder'); Admin = $false },
        @{ Ruta = [Environment]::GetFolderPath('CommonStartup'); Origen = 'Carpeta Inicio (todos los usuarios)'; Aprobado = (Join-Path $script:StartupApprovedHKLM 'StartupFolder'); Admin = $true }
    )
    foreach ($carpeta in $carpetas) {
        if (-not $carpeta.Ruta -or -not (Test-Path -LiteralPath $carpeta.Ruta)) { continue }
        foreach ($f in @(Get-ChildItem -LiteralPath $carpeta.Ruta -File -Force -ErrorAction SilentlyContinue)) {
            if ($f.Name -eq 'desktop.ini') { continue }
            $comando = '"' + $f.FullName + '"'
            if ($f.Extension -eq '.lnk') {
                try {
                    if (-not $shell) { $shell = New-Object -ComObject WScript.Shell }
                    $acceso = $shell.CreateShortcut($f.FullName)
                    if ($acceso.TargetPath) { $comando = ('"{0}" {1}' -f $acceso.TargetPath, $acceso.Arguments).Trim() }
                } catch { }
            }
            $entradas += [pscustomobject]@{
                Name         = $f.BaseName
                Command      = $comando
                Origin       = $carpeta.Origen
                Location     = $f.FullName
                ApprovedKey  = $carpeta.Aprobado
                ApprovedName = $f.Name
                NeedsAdmin   = $carpeta.Admin
                FilePath     = $f.FullName
            }
        }
    }

    foreach ($e in $entradas) {
        $exe = Get-ExecutableFromCommand $e.Command
        $estado = 'Sin comprobar'
        $firmante = ''
        if ($exe -and -not [System.IO.Path]::IsPathRooted($exe)) {
            $enSistema = Join-Path $env:SystemRoot ('System32\' + $exe)
            if (Test-Path -LiteralPath $enSistema) { $exe = $enSistema }
        }
        if (-not $exe -or -not (Test-Path -LiteralPath $exe)) {
            $estado = 'Archivo no encontrado'
        } else {
            try {
                $firma = Get-AuthenticodeSignature -LiteralPath $exe -ErrorAction Stop
                $estado = [string]$firma.Status
                if ($firma.SignerCertificate) { $firmante = [string]$firma.SignerCertificate.GetNameInfo('SimpleName', $false) }
            } catch { $estado = 'Error al comprobar' }
        }
        $e | Add-Member -NotePropertyName Executable -NotePropertyValue $exe -Force
        $e | Add-Member -NotePropertyName Signature -NotePropertyValue $estado -Force
        $e | Add-Member -NotePropertyName Signer -NotePropertyValue $firmante -Force
        $e | Add-Member -NotePropertyName Enabled -NotePropertyValue (Test-StartupApprovedEnabled $e.ApprovedKey $e.ApprovedName) -Force
    }
    return $entradas
}

function New-SecurityCheck {
    param([string]$Group, [string]$Name, [string]$Value, [ValidateSet('OK','INFO','WARN','BAD')][string]$Level, [string]$Detail)
    return [pscustomobject]@{ Group = $Group; Name = $Name; Value = $Value; Level = $Level; Detail = $Detail }
}

function Format-SecurityAge {
    param($Fecha)
    if (-not $Fecha) { return 'nunca' }
    $dias = [math]::Floor(((Get-Date) - [datetime]$Fecha).TotalDays)
    $texto = ([datetime]$Fecha).ToString('dd/MM/yyyy HH:mm')
    if ($dias -le 0) { return ('{0} (hoy)' -f $texto) }
    if ($dias -eq 1) { return ('{0} (ayer)' -f $texto) }
    return ('{0} (hace {1} días)' -f $texto, $dias)
}

# Revisión de seguridad. Solo lee información: no cambia ninguna configuración.
function Get-SecurityChecks {
    $c = New-Object System.Collections.ArrayList
    $soloAdmin = 'Abre el programa como administrador (Iniciar.bat) para comprobarlo.'

    # --- Antivirus -----------------------------------------------------------
    $productos = @(Get-AntivirusProducts)
    $activos = @($productos | Where-Object { $_.Enabled })
    $terceros = @($activos | Where-Object { -not $_.IsDefender })
    if ($productos.Count -eq 0) {
        [void]$c.Add((New-SecurityCheck 'Antivirus' 'Antivirus activo' 'No se pudo consultar el Centro de seguridad' 'INFO' 'Windows no ha devuelto la lista de antivirus (es habitual en Windows Server). Se comprueba Microsoft Defender directamente.'))
    } elseif ($activos.Count -eq 0) {
        [void]$c.Add((New-SecurityCheck 'Antivirus' 'Antivirus activo' 'NINGUNO' 'BAD' ("No hay ningún antivirus activo. Registrados: {0}.`r`n`r`nActiva Microsoft Defender en Seguridad de Windows o revisa el antivirus instalado." -f (($productos | ForEach-Object { $_.Name }) -join ', '))))
    } else {
        $nombres = ($activos | ForEach-Object { $_.Name }) -join ', '
        $nivel = 'OK'
        $detalle = "Antivirus activo según el Centro de seguridad de Windows: $nombres."
        $desfasados = @($activos | Where-Object { -not $_.UpToDate })
        if ($desfasados.Count -gt 0) {
            $nivel = 'WARN'
            $detalle += ("`r`n`r`nWindows indica que no está actualizado: {0}. Actualiza sus firmas." -f (($desfasados | ForEach-Object { $_.Name }) -join ', '))
        }
        if ($terceros.Count -gt 0) {
            $detalle += "`r`n`r`nCon otro antivirus activo, Microsoft Defender queda en modo pasivo: puede analizar bajo demanda, pero la protección en tiempo real la da el otro antivirus."
        }
        [void]$c.Add((New-SecurityCheck 'Antivirus' 'Antivirus activo' $nombres $nivel $detalle))
    }

    $mp = $null
    $script:secDefenderOk = $false
    try { $mp = Get-MpComputerStatus -ErrorAction Stop } catch { }
    if (-not $mp) {
        $nivel = 'BAD'
        if ($terceros.Count -gt 0) { $nivel = 'INFO' }
        [void]$c.Add((New-SecurityCheck 'Antivirus' 'Microsoft Defender' 'No disponible' $nivel 'No se puede consultar Microsoft Defender. Puede estar desactivado por otro antivirus, por una directiva o no estar instalado (Windows Server). Los análisis de esta pestaña no funcionarán.'))
    } else {
        $modo = [string]$mp.AMRunningMode
        if (-not $modo) { if ($mp.AntivirusEnabled) { $modo = 'Normal' } else { $modo = 'Desactivado' } }
        $pasivo = ($modo -match 'Passive|Pasivo')
        $script:secDefenderOk = [bool]$mp.AMServiceEnabled -and ($modo -notmatch 'Desactivado')
        switch -Regex ($modo) {
            '^Normal$'        { [void]$c.Add((New-SecurityCheck 'Antivirus' 'Modo de Defender' 'Normal (antivirus principal)' 'OK' 'Microsoft Defender es el antivirus principal del equipo y protege en tiempo real.')) }
            'Passive|Pasivo'  { [void]$c.Add((New-SecurityCheck 'Antivirus' 'Modo de Defender' 'Pasivo (hay otro antivirus)' 'INFO' 'Defender está en modo pasivo porque hay otro antivirus. Puede analizar bajo demanda, pero no bloquea amenazas en tiempo real ni las elimina automáticamente.')) }
            default           { [void]$c.Add((New-SecurityCheck 'Antivirus' 'Modo de Defender' $modo 'WARN' 'Defender no está en modo normal. Revisa Seguridad de Windows.')) }
        }

        if (-not $pasivo) {
            if ($mp.RealTimeProtectionEnabled) {
                [void]$c.Add((New-SecurityCheck 'Antivirus' 'Protección en tiempo real' 'Activada' 'OK' 'Defender analiza los archivos al abrirlos o descargarlos.'))
            } else {
                [void]$c.Add((New-SecurityCheck 'Antivirus' 'Protección en tiempo real' 'DESACTIVADA' 'BAD' "El equipo no está protegido en tiempo real.`r`n`r`nActívala en Seguridad de Windows > Protección antivirus y contra amenazas > Administrar la configuración. Si se desactiva sola, puede haber malware o una directiva que la bloquea."))
            }
        }

        $edadFirmas = [int]$mp.AntivirusSignatureAge
        $nivelFirmas = 'OK'
        if ($edadFirmas -gt 7) { $nivelFirmas = 'BAD' } elseif ($edadFirmas -gt 2) { $nivelFirmas = 'WARN' }
        [void]$c.Add((New-SecurityCheck 'Antivirus' 'Firmas de virus' ('{0} · versión {1}' -f (Format-SecurityAge $mp.AntivirusSignatureLastUpdated), $mp.AntivirusSignatureVersion) $nivelFirmas "Las firmas permiten reconocer el malware nuevo. Lo normal es que se actualicen varias veces al día.`r`n`r`nSi tienen más de 2 días, pulsa 'Actualizar firmas'."))

        $rapido = $mp.QuickScanEndTime
        $nivelRapido = 'OK'
        if (-not $rapido) { $nivelRapido = 'WARN' } elseif (((Get-Date) - [datetime]$rapido).TotalDays -gt 14) { $nivelRapido = 'WARN' }
        [void]$c.Add((New-SecurityCheck 'Antivirus' 'Último análisis rápido' (Format-SecurityAge $rapido) $nivelRapido 'Windows hace un análisis rápido automático cuando el equipo está inactivo. Si hace más de dos semanas, haz uno con el botón ''Análisis rápido''.'))

        $completo = $mp.FullScanEndTime
        $nivelCompleto = 'OK'
        if (-not $completo) { $nivelCompleto = 'INFO' } elseif (((Get-Date) - [datetime]$completo).TotalDays -gt 90) { $nivelCompleto = 'INFO' }
        [void]$c.Add((New-SecurityCheck 'Antivirus' 'Último análisis completo' (Format-SecurityAge $completo) $nivelCompleto 'El análisis completo revisa todos los archivos. Conviene hacerlo al recibir un equipo de un cliente o si se sospecha de una infección.'))

        if ($null -ne $mp.IsTamperProtected) {
            if ($mp.IsTamperProtected) {
                [void]$c.Add((New-SecurityCheck 'Antivirus' 'Protección contra alteraciones' 'Activada' 'OK' 'Impide que un programa malicioso desactive Defender.'))
            } elseif (-not $pasivo) {
                [void]$c.Add((New-SecurityCheck 'Antivirus' 'Protección contra alteraciones' 'Desactivada' 'WARN' "Un programa malicioso podría desactivar Defender.`r`n`r`nActívala en Seguridad de Windows > Protección antivirus y contra amenazas > Administrar la configuración > Protección contra alteraciones."))
            }
        }

        try {
            $pref = Get-MpPreference -ErrorAction Stop
            switch ([int]$pref.PUAProtection) {
                1       { [void]$c.Add((New-SecurityCheck 'Antivirus' 'Bloqueo de aplicaciones no deseadas' 'Activado' 'OK' 'Defender bloquea programas potencialmente no deseados (adware, barras de herramientas, minadores).')) }
                2       { [void]$c.Add((New-SecurityCheck 'Antivirus' 'Bloqueo de aplicaciones no deseadas' 'Solo auditoría' 'INFO' 'Defender detecta las aplicaciones no deseadas, pero no las bloquea.')) }
                default { [void]$c.Add((New-SecurityCheck 'Antivirus' 'Bloqueo de aplicaciones no deseadas' 'Desactivado' 'WARN' "Defender no bloquea adware ni programas potencialmente no deseados.`r`n`r`nSe activa en Seguridad de Windows > Control de aplicaciones y del explorador > Protección basada en la reputación > Bloqueo de aplicaciones potencialmente no deseadas.")) }
            }
        } catch { }
    }

    # --- Sistema ---------------------------------------------------------------
    try {
        $perfiles = @(Get-NetFirewallProfile -ErrorAction Stop)
        $apagados = @($perfiles | Where-Object { -not $_.Enabled } | ForEach-Object { [string]$_.Name })
        if ($apagados.Count -eq 0) {
            [void]$c.Add((New-SecurityCheck 'Sistema' 'Firewall de Windows' 'Activado en todos los perfiles' 'OK' 'El firewall está activado para las redes de dominio, privadas y públicas.'))
        } else {
            [void]$c.Add((New-SecurityCheck 'Sistema' 'Firewall de Windows' ('Desactivado: {0}' -f ($apagados -join ', ')) 'BAD' ("El firewall está desactivado en: {0}.`r`n`r`nSi no hay otro firewall instalado, actívalo en Seguridad de Windows > Firewall y protección de red." -f ($apagados -join ', '))))
        }
    } catch {
        [void]$c.Add((New-SecurityCheck 'Sistema' 'Firewall de Windows' 'No se pudo consultar' 'INFO' $_.Exception.Message))
    }

    try {
        $uac = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction Stop
        if ([int]$uac.EnableLUA -eq 0) {
            [void]$c.Add((New-SecurityCheck 'Sistema' 'Control de cuentas (UAC)' 'DESACTIVADO' 'BAD' 'Con el UAC desactivado, cualquier programa se ejecuta con permisos de administrador sin preguntar. Actívalo en Panel de control > Cuentas de usuario > Cambiar configuración de Control de cuentas de usuario.'))
        } elseif ([int]$uac.ConsentPromptBehaviorAdmin -eq 0) {
            [void]$c.Add((New-SecurityCheck 'Sistema' 'Control de cuentas (UAC)' 'No avisa nunca' 'WARN' 'El UAC está activado pero no pide confirmación: los programas se elevan sin avisar. Súbelo al nivel recomendado (el segundo empezando por arriba).'))
        } else {
            [void]$c.Add((New-SecurityCheck 'Sistema' 'Control de cuentas (UAC)' 'Activado' 'OK' 'Windows pide confirmación antes de dar permisos de administrador a un programa.'))
        }
    } catch { }

    $smbCliente = $false
    try {
        $mrx = Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\mrxsmb10' -ErrorAction Stop
        if ([int]$mrx.Start -ne 4) { $smbCliente = $true }
    } catch { }
    $smbServidor = $null
    try { $smbServidor = [bool](Get-SmbServerConfiguration -ErrorAction Stop).EnableSMB1Protocol } catch { }
    if ($smbCliente -or $smbServidor) {
        $donde = @()
        if ($smbCliente) { $donde += 'cliente' }
        if ($smbServidor) { $donde += 'servidor' }
        [void]$c.Add((New-SecurityCheck 'Sistema' 'SMBv1 (protocolo antiguo)' ('Activado ({0})' -f ($donde -join ' y ')) 'WARN' "SMBv1 es el protocolo que usaron WannaCry y NotPetya. Solo hace falta para NAS o impresoras muy antiguas.`r`n`r`nSe quita en Características de Windows > Compatibilidad con el protocolo para compartir archivos SMB 1.0/CIFS."))
    } else {
        [void]$c.Add((New-SecurityCheck 'Sistema' 'SMBv1 (protocolo antiguo)' 'Desactivado' 'OK' 'El protocolo SMB 1.0, vulnerable y obsoleto, no está activo.'))
    }

    if (Get-Command Get-BitLockerVolume -ErrorAction SilentlyContinue) {
        if ($script:IsAdmin) {
            try {
                $bl = Get-BitLockerVolume -MountPoint $env:SystemDrive -ErrorAction Stop
                $portatil = ($script:hardware -and $script:hardware.IsLaptop)
                if ([string]$bl.ProtectionStatus -eq 'On') {
                    [void]$c.Add((New-SecurityCheck 'Sistema' ('Cifrado BitLocker ({0})' -f $env:SystemDrive) 'Activado' 'OK' 'El disco del sistema está cifrado: si roban el equipo o el disco, no se pueden leer los datos. Guarda la clave de recuperación en un lugar seguro.'))
                } else {
                    $nivelBl = 'INFO'
                    if ($portatil) { $nivelBl = 'WARN' }
                    $estadoBl = switch ([string]$bl.VolumeStatus) {
                        'FullyDecrypted'       { 'sin cifrar' }
                        'FullyEncrypted'       { 'cifrado, protección suspendida' }
                        'EncryptionInProgress' { 'cifrando' }
                        'DecryptionInProgress' { 'descifrando' }
                        default                { [string]$bl.VolumeStatus }
                    }
                    [void]$c.Add((New-SecurityCheck 'Sistema' ('Cifrado BitLocker ({0})' -f $env:SystemDrive) ('Desactivado ({0})' -f $estadoBl) $nivelBl 'El disco del sistema no está cifrado. Es muy recomendable en portátiles: si se pierde el equipo, cualquiera puede leer los datos sacando el disco.'))
                }
            } catch {
                [void]$c.Add((New-SecurityCheck 'Sistema' ('Cifrado BitLocker ({0})' -f $env:SystemDrive) 'No disponible' 'INFO' $_.Exception.Message))
            }
        } else {
            [void]$c.Add((New-SecurityCheck 'Sistema' 'Cifrado BitLocker' 'Sin comprobar' 'INFO' $soloAdmin))
        }
    } else {
        [void]$c.Add((New-SecurityCheck 'Sistema' 'Cifrado BitLocker' 'No incluido en esta edición' 'INFO' 'Las ediciones Home no incluyen BitLocker. Algunos equipos ofrecen ''Cifrado de dispositivo'' en Configuración > Privacidad y seguridad.'))
    }

    if ($script:IsAdmin) {
        try {
            if (Confirm-SecureBootUEFI -ErrorAction Stop) {
                [void]$c.Add((New-SecurityCheck 'Sistema' 'Arranque seguro (Secure Boot)' 'Activado' 'OK' 'El equipo solo arranca sistemas firmados: protege contra bootkits.'))
            } else {
                [void]$c.Add((New-SecurityCheck 'Sistema' 'Arranque seguro (Secure Boot)' 'Desactivado' 'WARN' 'El equipo es UEFI pero el arranque seguro está desactivado. Se activa en la BIOS/UEFI. Windows 11 lo necesita.'))
            }
        } catch {
            [void]$c.Add((New-SecurityCheck 'Sistema' 'Arranque seguro (Secure Boot)' 'No compatible' 'INFO' 'El equipo arranca en modo BIOS heredado o no admite el arranque seguro.'))
        }
    } else {
        [void]$c.Add((New-SecurityCheck 'Sistema' 'Arranque seguro (Secure Boot)' 'Sin comprobar' 'INFO' $soloAdmin))
    }

    try {
        $parches = @(Get-HotFix -ErrorAction Stop | Where-Object { $_.InstalledOn } | Sort-Object InstalledOn -Descending)
        if ($parches.Count -gt 0) {
            $ultimo = $parches[0]
            $dias = [math]::Floor(((Get-Date) - [datetime]$ultimo.InstalledOn).TotalDays)
            $nivelWu = 'OK'
            if ($dias -gt 60) { $nivelWu = 'BAD' } elseif ($dias -gt 40) { $nivelWu = 'WARN' }
            [void]$c.Add((New-SecurityCheck 'Sistema' 'Última actualización de Windows' ('{0} ({1}, hace {2} días)' -f $ultimo.HotFixID, ([datetime]$ultimo.InstalledOn).ToString('dd/MM/yyyy'), $dias) $nivelWu 'Microsoft publica parches de seguridad cada mes (el segundo martes). Si la última actualización tiene más de 40 días, revisa Windows Update.'))
        }
    } catch { }
    if ((Test-Path -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') -or
        (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending')) {
        [void]$c.Add((New-SecurityCheck 'Sistema' 'Reinicio pendiente' 'Sí' 'WARN' 'Hay actualizaciones instaladas que no se aplican hasta reiniciar. Reinicia el equipo cuando puedas.'))
    }

    try {
        $ts = Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -ErrorAction Stop
        if ([int]$ts.fDenyTSConnections -eq 0) {
            $nla = 1
            try { $nla = [int](Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -ErrorAction Stop).UserAuthentication } catch { }
            if ($nla -eq 1) {
                [void]$c.Add((New-SecurityCheck 'Sistema' 'Escritorio remoto' 'Activado (con NLA)' 'INFO' 'El escritorio remoto está activado con autenticación a nivel de red. Si no lo usas, desactívalo. Nunca lo abras directamente a Internet (puerto 3389): usa una VPN.'))
            } else {
                [void]$c.Add((New-SecurityCheck 'Sistema' 'Escritorio remoto' 'Activado SIN NLA' 'BAD' 'El escritorio remoto acepta conexiones sin autenticación a nivel de red: más expuesto a ataques de fuerza bruta y vulnerabilidades. Activa NLA o desactiva el escritorio remoto.'))
            }
        } else {
            [void]$c.Add((New-SecurityCheck 'Sistema' 'Escritorio remoto' 'Desactivado' 'OK' 'El equipo no acepta conexiones de escritorio remoto.'))
        }
    } catch { }

    # --- Cuentas ----------------------------------------------------------------
    if (Get-Command Get-LocalUser -ErrorAction SilentlyContinue) {
        try {
            $usuarios = @(Get-LocalUser -ErrorAction Stop)
            $invitado = $usuarios | Where-Object { ([string]$_.SID).EndsWith('-501') } | Select-Object -First 1
            if ($invitado -and $invitado.Enabled) {
                [void]$c.Add((New-SecurityCheck 'Cuentas' 'Cuenta Invitado' 'Activada' 'WARN' 'La cuenta Invitado permite entrar sin contraseña. Desactívala: lusrmgr.msc > Usuarios > Invitado > La cuenta está deshabilitada.'))
            } else {
                [void]$c.Add((New-SecurityCheck 'Cuentas' 'Cuenta Invitado' 'Desactivada' 'OK' 'La cuenta Invitado no se puede usar.'))
            }
            $adminInt = $usuarios | Where-Object { ([string]$_.SID).EndsWith('-500') } | Select-Object -First 1
            if ($adminInt -and $adminInt.Enabled) {
                [void]$c.Add((New-SecurityCheck 'Cuentas' 'Administrador integrado' ('Activado ({0})' -f $adminInt.Name) 'WARN' 'La cuenta Administrador integrada está activada. No tiene UAC y es el objetivo habitual de los ataques de fuerza bruta. Desactívala si no la necesitas.'))
            }
            $sinClave = @($usuarios | Where-Object { $_.Enabled -and -not $_.PasswordRequired -and -not ([string]$_.SID).EndsWith('-501') } | ForEach-Object { $_.Name })
            if ($sinClave.Count -gt 0) {
                [void]$c.Add((New-SecurityCheck 'Cuentas' 'Cuentas que pueden no tener contraseña' ($sinClave -join ', ') 'INFO' 'Estas cuentas locales tienen permitido no usar contraseña. Comprueba que todas tienen una contraseña o PIN. (Las cuentas Microsoft usan la contraseña de la cuenta online.)'))
            }
        } catch { }
    }

    # --- Inicio -----------------------------------------------------------------
    try {
        $inicio = @(Get-StartupEntries)
        $sinFirma = @($inicio | Where-Object { $_.Enabled -and $_.Signature -ne 'Valid' -and $_.Signature -ne 'Archivo no encontrado' })
        $huerfanas = @($inicio | Where-Object { $_.Enabled -and $_.Signature -eq 'Archivo no encontrado' })
        $lineas = @()
        foreach ($e in $inicio) {
            $firma = $e.Signature
            if ($firma -eq 'Valid') { $firma = 'firmado' + $(if ($e.Signer) { ' por ' + $e.Signer } else { '' }) }
            $estadoInicio = ''
            if (-not $e.Enabled) { $estadoInicio = ', deshabilitado' }
            $lineas += ('- {0} [{1}{2}]: {3}' -f $e.Name, $firma, $estadoInicio, $e.Executable)
        }
        $detalleInicio = ("Programas que arrancan con Windows ({0}):`r`n`r`n{1}" -f $inicio.Count, ($lineas -join "`r`n"))
        if ($sinFirma.Count -gt 0) {
            $detalleInicio += "`r`n`r`nUn programa sin firma no tiene por qué ser malware, pero conviene revisarlo: el malware suele arrancar desde aquí. En Sistema > Inicio puedes deshabilitarlo o analizarlo con Defender."
            [void]$c.Add((New-SecurityCheck 'Inicio' 'Programas de inicio sin firma' ('{0} de {1}: {2}' -f $sinFirma.Count, $inicio.Count, (($sinFirma | ForEach-Object { $_.Name }) -join ', ')) 'WARN' $detalleInicio))
        } else {
            [void]$c.Add((New-SecurityCheck 'Inicio' 'Programas de inicio sin firma' ('Ninguno ({0} programas revisados)' -f $inicio.Count) 'OK' $detalleInicio))
        }
        if ($huerfanas.Count -gt 0) {
            [void]$c.Add((New-SecurityCheck 'Inicio' 'Entradas de inicio rotas' (($huerfanas | ForEach-Object { $_.Name }) -join ', ') 'INFO' 'Estas entradas apuntan a archivos que ya no existen (restos de programas desinstalados). No son peligrosas; se pueden deshabilitar en Sistema > Inicio.'))
        }
    } catch { }

    return $c.ToArray()
}

function Get-SecurityLevelColor {
    param([string]$Level)
    switch ($Level) {
        'OK'   { return [System.Drawing.Color]::FromArgb(0, 120, 0) }
        'WARN' { return [System.Drawing.Color]::FromArgb(180, 100, 0) }
        'BAD'  { return [System.Drawing.Color]::FromArgb(190, 30, 30) }
    }
    return [System.Drawing.Color]::FromArgb(60, 60, 60)
}

function Update-SecurityChecks {
    $script:form.UseWaitCursor = $true
    $script:statusLabel.Text = 'Revisando la seguridad del equipo...'
    [System.Windows.Forms.Application]::DoEvents()
    try {
        $script:secChecks = @(Get-SecurityChecks)
    } catch {
        $script:secChecks = @()
        Add-TabLog $script:secLog ('No se pudo completar la revisión: {0}' -f $_.Exception.Message) 'ERROR'
    } finally {
        $script:form.UseWaitCursor = $false
        $script:statusLabel.Text = 'Listo'
    }

    $script:secList.BeginUpdate()
    try {
        $script:secList.Items.Clear()
        $script:secList.Groups.Clear()
        $grupos = @{}
        foreach ($nombreGrupo in @('Antivirus', 'Sistema', 'Cuentas', 'Inicio')) {
            $g = New-Object System.Windows.Forms.ListViewGroup($nombreGrupo, $nombreGrupo)
            [void]$script:secList.Groups.Add($g)
            $grupos[$nombreGrupo] = $g
        }
        foreach ($chk in $script:secChecks) {
            $item = New-Object System.Windows.Forms.ListViewItem([string]$chk.Name)
            [void]$item.SubItems.Add([string]$chk.Value)
            $item.Tag = $chk
            $item.ToolTipText = [string]$chk.Value
            $item.UseItemStyleForSubItems = $true
            $item.ForeColor = Get-SecurityLevelColor $chk.Level
            if ($chk.Level -eq 'BAD') { $item.Font = $script:boldFont }
            if ($grupos.ContainsKey([string]$chk.Group)) { $item.Group = $grupos[[string]$chk.Group] }
            [void]$script:secList.Items.Add($item)
        }
    } finally {
        $script:secList.EndUpdate()
    }

    $graves = @($script:secChecks | Where-Object { $_.Level -eq 'BAD' }).Count
    $avisos = @($script:secChecks | Where-Object { $_.Level -eq 'WARN' }).Count
    if ($graves -gt 0) {
        $script:lblSecResumen.ForeColor = Get-SecurityLevelColor 'BAD'
        $script:lblSecResumen.Text = ('{0} problema(s) grave(s) y {1} aviso(s)' -f $graves, $avisos)
    } elseif ($avisos -gt 0) {
        $script:lblSecResumen.ForeColor = Get-SecurityLevelColor 'WARN'
        $script:lblSecResumen.Text = ('Sin problemas graves · {0} aviso(s)' -f $avisos)
    } else {
        $script:lblSecResumen.ForeColor = Get-SecurityLevelColor 'OK'
        $script:lblSecResumen.Text = 'Todo correcto'
    }
    Add-TabLog $script:secLog ('Revisión de seguridad: {0} comprobaciones, {1} grave(s), {2} aviso(s).' -f $script:secChecks.Count, $graves, $avisos) $(if ($graves -gt 0) { 'WARN' } else { 'OK' })
    foreach ($chk in @($script:secChecks | Where-Object { $_.Level -eq 'BAD' -or $_.Level -eq 'WARN' })) {
        Add-TabLog $script:secLog ('{0}: {1}' -f $chk.Name, $chk.Value) $(if ($chk.Level -eq 'BAD') { 'ERROR' } else { 'WARN' })
    }
}

function Get-ThreatStatusText {
    param([int]$Id)
    switch ($Id) {
        1   { return 'Desconocido' }
        2   { return 'Detectada' }
        3   { return 'Limpiada' }
        4   { return 'En cuarentena' }
        5   { return 'Eliminada' }
        6   { return 'Permitida' }
        7   { return 'Bloqueada' }
        102 { return 'Fallo al poner en cuarentena' }
        103 { return 'Fallo al eliminar' }
        104 { return 'Fallo al permitir' }
        105 { return 'Abandonada' }
        107 { return 'Fallo al bloquear' }
    }
    return ('Estado ' + $Id)
}

function Get-ThreatSeverityText {
    param([int]$Id)
    switch ($Id) {
        1 { return 'Baja' }
        2 { return 'Moderada' }
        4 { return 'Alta' }
        5 { return 'Grave' }
    }
    return 'Desconocida'
}

function Update-SecurityThreats {
    $script:secThreatList.BeginUpdate()
    $activas = 0
    try {
        $script:secThreatList.Items.Clear()
        if (-not (Get-Command Get-MpThreatDetection -ErrorAction SilentlyContinue)) { return }
        $detecciones = @()
        try { $detecciones = @(Get-MpThreatDetection -ErrorAction Stop) } catch { }
        $amenazas = @{}
        try {
            foreach ($t in @(Get-MpThreat -ErrorAction Stop)) { $amenazas[[string]$t.ThreatID] = $t }
        } catch { }
        $ordenadas = @($detecciones | Sort-Object InitialDetectionTime -Descending | Select-Object -First 100)
        foreach ($d in $ordenadas) {
            $t = $amenazas[[string]$d.ThreatID]
            $nombre = 'ID ' + $d.ThreatID
            $gravedad = 'Desconocida'
            $activa = $false
            if ($t) {
                $nombre = [string]$t.ThreatName
                $gravedad = Get-ThreatSeverityText ([int]$t.SeverityID)
                $activa = [bool]$t.IsActive
            }
            $fecha = ''
            if ($d.InitialDetectionTime) { $fecha = ([datetime]$d.InitialDetectionTime).ToString('dd/MM/yyyy HH:mm') }
            $estado = Get-ThreatStatusText ([int]$d.ThreatStatusID)
            if ($activa) { $estado = 'ACTIVA · ' + $estado; $activas++ }
            $item = New-Object System.Windows.Forms.ListViewItem($fecha)
            [void]$item.SubItems.Add($nombre)
            [void]$item.SubItems.Add($gravedad)
            [void]$item.SubItems.Add($estado)
            $item.Tag = [pscustomobject]@{
                Name      = $nombre
                Severity  = $gravedad
                Status    = $estado
                Date      = $fecha
                Active    = $activa
                Resources = @($d.Resources)
                Process   = [string]$d.ProcessName
                User      = [string]$d.DomainUser
            }
            if ($activa) {
                $item.ForeColor = Get-SecurityLevelColor 'BAD'
                $item.Font = $script:boldFont
            }
            [void]$script:secThreatList.Items.Add($item)
        }
        $grpSecThreats.Text = ('Amenazas detectadas por Defender ({0}, {1} activa(s))' -f $ordenadas.Count, $activas)
    } finally {
        $script:secThreatList.EndUpdate()
        $script:btnSecRemove.Enabled = ($activas -gt 0 -and -not $script:secProcess)
    }
}

function Update-SecurityTab {
    param([switch]$Force)
    if ($script:secLoaded -and -not $Force) { return }
    $script:secLoaded = $true
    $script:secMpCmdRun = Get-MpCmdRunPath
    Update-SecurityChecks
    Update-SecurityThreats
    Update-SecurityButtons
}

function Update-SecurityButtons {
    $libre = -not $script:secProcess
    $puede = $libre -and [bool]$script:secMpCmdRun -and $script:secDefenderOk
    $script:btnSecQuick.Enabled   = $puede
    $script:btnSecFull.Enabled    = $puede
    $script:btnSecCustom.Enabled  = $puede
    $script:btnSecUpdate.Enabled  = $libre -and [bool]$script:secMpCmdRun
    $script:btnSecOffline.Enabled = $libre -and $script:secDefenderOk
    $script:btnSecRefresh.Enabled = $libre
    $script:btnSecStop.Enabled    = -not $libre
}

function Show-SecurityDetail {
    param([ValidateSet('Check','Threat')][string]$Source)
    if ($Source -eq 'Check') {
        if ($script:secList.SelectedItems.Count -eq 0) { return }
        $chk = $script:secList.SelectedItems[0].Tag
        if (-not $chk) { return }
        $estado = switch ($chk.Level) { 'OK' { 'Correcto' } 'WARN' { 'Aviso' } 'BAD' { 'Problema grave' } default { 'Información' } }
        $script:secDetail.Text = ("{0}`r`nResultado: {1}`r`nValoración: {2}`r`n`r`n{3}" -f $chk.Name, $chk.Value, $estado, $chk.Detail)
        return
    }
    if ($script:secThreatList.SelectedItems.Count -eq 0) { return }
    $t = $script:secThreatList.SelectedItems[0].Tag
    if (-not $t) { return }
    $lineas = @(
        ('Amenaza: {0}' -f $t.Name),
        ('Gravedad: {0}' -f $t.Severity),
        ('Estado: {0}' -f $t.Status),
        ('Detectada: {0}' -f $t.Date)
    )
    if ($t.Process) { $lineas += ('Proceso: {0}' -f $t.Process) }
    if ($t.User) { $lineas += ('Usuario: {0}' -f $t.User) }
    if (@($t.Resources).Count -gt 0) {
        $lineas += ''
        $lineas += 'Archivos o ubicaciones afectados:'
        foreach ($r in @($t.Resources | Select-Object -First 15)) { $lineas += ('  ' + ([string]$r -replace '^file:_', '')) }
    }
    $lineas += ''
    if ($t.Active) {
        $lineas += 'La amenaza sigue ACTIVA. Pulsa "Eliminar amenazas activas" y después haz un análisis completo. Si vuelve a aparecer, usa el análisis sin conexión.'
    } else {
        $lineas += 'Defender ya actuó sobre esta amenaza. Si era un falso positivo, puedes restaurar el archivo desde "Abrir Seguridad de Windows" > Historial de protección.'
    }
    $script:secDetail.Text = ($lineas -join "`r`n")
}

function Test-OtherJobRunning {
    return ($script:wingetProcess -or $script:drvProcess -or $script:bkProcess -or $script:uninstProcess -or $script:busy)
}

# Lanza MpCmdRun.exe en segundo plano: análisis rápido, completo, personalizado
# o actualización de firmas. La ventana sigue respondiendo y se puede detener.
function Start-SecurityJob {
    param(
        [ValidateSet('quick', 'full', 'custom', 'update')][string]$Kind,
        [string]$Path = ''
    )
    if ($script:secProcess) { return }
    if (-not (Assert-Admin)) { return }
    if (-not $script:secMpCmdRun) { $script:secMpCmdRun = Get-MpCmdRunPath }
    if (-not $script:secMpCmdRun) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'No se encuentra MpCmdRun.exe (Microsoft Defender). Puede que Defender esté desinstalado o desactivado por otro antivirus.',
            "$script:AppName - seguridad", 'OK', 'Warning')
        return
    }

    switch ($Kind) {
        'quick'  { $argumentos = @('-Scan', '-ScanType', '1'); $titulo = 'Análisis rápido' }
        'full'   { $argumentos = @('-Scan', '-ScanType', '2'); $titulo = 'Análisis completo' }
        'custom' { $argumentos = @('-Scan', '-ScanType', '3', '-File', (ConvertTo-QuotedArgument $Path)); $titulo = ('Análisis de {0}' -f $Path) }
        'update' { $argumentos = @('-SignatureUpdate'); $titulo = 'Actualización de firmas' }
    }

    if ($Kind -eq 'full' -and -not $UiSmokeTest) {
        $r = [System.Windows.Forms.MessageBox]::Show(
            "El análisis completo revisa todos los archivos de todos los discos.`n`nPuede tardar una o varias horas y el equipo irá más lento mientras tanto. Puedes seguir usando el programa y detenerlo cuando quieras.`n`n¿Empezar?",
            "$script:AppName - análisis completo", 'YesNo', 'Question')
        if ($r -ne 'Yes') { return }
    }

    try {
        $dir = Get-WorkDir
        $script:secOutFile = Join-Path $dir ('wintaller_seguridad_{0}.txt' -f ([guid]::NewGuid().ToString('N')))
        $script:secErrFile = $script:secOutFile + '.err'
        $script:secProcess = Start-Process -FilePath $script:secMpCmdRun -ArgumentList $argumentos -PassThru -WindowStyle Hidden `
            -RedirectStandardOutput $script:secOutFile -RedirectStandardError $script:secErrFile
        # Igual que con winget: conserva el handle para poder leer el código de salida.
        $script:secProcess.EnableRaisingEvents = $true
    } catch {
        Add-TabLog $script:secLog ('No se pudo iniciar {0}: {1}' -f $titulo.ToLowerInvariant(), $_.Exception.Message) 'ERROR'
        $script:secProcess = $null
        Clear-SecurityTempFiles
        return
    }

    $script:secKind    = $Kind
    $script:secTarget  = $titulo
    $script:secStarted = Get-Date
    Add-TabLog $script:secLog ('{0} iniciado.' -f $titulo) 'STEP'
    if ($Kind -eq 'full') { Add-TabLog $script:secLog 'Puede tardar bastante. El progreso no se puede medir: la barra solo indica que sigue trabajando.' }
    $script:secBar.Style = 'Marquee'
    $script:secBar.Visible = $true
    Update-SecurityButtons
    $script:btnSecRemove.Enabled = $false
    $script:secTimer.Start()
}

function Clear-SecurityTempFiles {
    foreach ($f in @($script:secOutFile, $script:secErrFile)) {
        if ($f) { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue }
    }
    $script:secOutFile = $null
    $script:secErrFile = $null
}

function Step-SecurityJob {
    $proc = $script:secProcess
    if (-not $proc) { $script:secTimer.Stop(); return }

    $terminado = $false
    try { $terminado = $proc.HasExited } catch { $terminado = $true }
    $transcurrido = (Get-Date) - $script:secStarted

    if (-not $terminado) {
        $script:statusLabel.Text = ('{0}... {1:hh\:mm\:ss}' -f $script:secTarget, $transcurrido)
        $limite = 12 * 60
        if ($script:secKind -eq 'update') { $limite = 20 }
        if ($transcurrido.TotalMinutes -gt $limite) {
            Add-TabLog $script:secLog ('{0}: ha superado el tiempo máximo y se detiene.' -f $script:secTarget) 'WARN'
            Stop-SecurityJob -Silent
        }
        return
    }

    $codigo = -1
    try { $codigo = [int]$proc.ExitCode } catch { }
    try { $proc.Dispose() } catch { }
    $script:secProcess = $null
    $script:secTimer.Stop()
    $script:secBar.Visible = $false
    $script:secBar.Style = 'Blocks'

    $salida = @()
    foreach ($f in @($script:secOutFile, $script:secErrFile)) {
        if ($f -and (Test-Path -LiteralPath $f)) {
            try { $salida += @(Get-Content -LiteralPath $f -ErrorAction SilentlyContinue | ForEach-Object { ([string]$_).Trim() } | Where-Object { $_ }) } catch { }
        }
    }
    Clear-SecurityTempFiles
    foreach ($linea in @($salida | Select-Object -Last 12)) { Add-TabLog $script:secLog ('  ' + $linea) }

    $duracion = '{0:hh\:mm\:ss}' -f $transcurrido
    if ($script:secKind -eq 'update') {
        if ($codigo -eq 0) {
            Add-TabLog $script:secLog ('Firmas actualizadas ({0}).' -f $duracion) 'OK'
        } else {
            Add-TabLog $script:secLog ('La actualización de firmas terminó con el código {0}. Comprueba la conexión a Internet o usa Windows Update.' -f $codigo) 'WARN'
        }
        $script:statusLabel.Text = 'Actualización de firmas terminada'
        Update-SecurityChecks
        Update-SecurityButtons
        return
    }

    # Análisis: se cuentan las detecciones que Defender ha registrado desde que empezó.
    $nuevas = @()
    try {
        $desde = $script:secStarted.AddMinutes(-1)
        $nuevas = @(Get-MpThreatDetection -ErrorAction Stop | Where-Object { $_.InitialDetectionTime -and [datetime]$_.InitialDetectionTime -ge $desde })
    } catch { }

    if ($nuevas.Count -gt 0) {
        Add-TabLog $script:secLog ('{0} terminado en {1}: {2} amenaza(s) detectada(s). Revisa la lista de amenazas.' -f $script:secTarget, $duracion, $nuevas.Count) 'ERROR'
    } elseif ($codigo -eq 0) {
        Add-TabLog $script:secLog ('{0} terminado en {1}: no se han encontrado amenazas.' -f $script:secTarget, $duracion) 'OK'
    } elseif ($codigo -eq 2) {
        Add-TabLog $script:secLog ('{0} terminado en {1}: Defender indica que ha encontrado amenazas. Revisa la lista.' -f $script:secTarget, $duracion) 'ERROR'
    } else {
        Add-TabLog $script:secLog ('{0} terminó con el código {1} ({2}).' -f $script:secTarget, $codigo, $duracion) 'WARN'
    }
    $script:statusLabel.Text = ('{0} terminado' -f $script:secTarget)

    Update-SecurityChecks
    Update-SecurityThreats
    Update-SecurityButtons

    if (-not $UiSmokeTest) {
        if ($nuevas.Count -gt 0 -or $codigo -eq 2) {
            [void][System.Windows.Forms.MessageBox]::Show(
                ("{0} terminado.`n`nDefender ha detectado amenazas. Revisa la lista 'Amenazas detectadas' y pulsa 'Eliminar amenazas activas' si alguna sigue activa." -f $script:secTarget),
                "$script:AppName - seguridad", 'OK', 'Warning')
        } elseif ($codigo -eq 0) {
            [void][System.Windows.Forms.MessageBox]::Show(
                ("{0} terminado.`n`nNo se han encontrado amenazas." -f $script:secTarget),
                "$script:AppName - seguridad", 'OK', 'Information')
        }
    }
}

function Stop-SecurityJob {
    param([switch]$Silent)
    $proc = $script:secProcess
    if ($proc) {
        if ($script:secKind -ne 'update' -and $script:secMpCmdRun) {
            # Cancela el análisis en el motor de Defender, no solo el proceso cliente.
            try {
                $cancelar = Start-Process -FilePath $script:secMpCmdRun -ArgumentList @('-Scan', '-Cancel') -PassThru -WindowStyle Hidden
                [void]$cancelar.WaitForExit(15000)
            } catch { }
        }
        try {
            if (-not $proc.HasExited) { & "$env:SystemRoot\System32\taskkill.exe" /PID $proc.Id /T /F 2>&1 | Out-Null }
        } catch { }
        try { $proc.Dispose() } catch { }
        if (-not $Silent) { Add-TabLog $script:secLog ('{0} detenido por el usuario.' -f $script:secTarget) 'WARN' }
    }
    $script:secProcess = $null
    $script:secTimer.Stop()
    $script:secBar.Visible = $false
    $script:secBar.Style = 'Blocks'
    Clear-SecurityTempFiles
    $script:statusLabel.Text = 'Operación de seguridad detenida'
    Update-SecurityButtons
    try { Update-SecurityThreats } catch { }
}

function Start-SecurityCustomScan {
    $dialogo = New-Object System.Windows.Forms.FolderBrowserDialog
    $dialogo.Description = 'Elige la carpeta o la unidad (por ejemplo, un USB) que quieres analizar.'
    $dialogo.ShowNewFolderButton = $false
    if ($dialogo.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return }
    $ruta = $dialogo.SelectedPath
    if (-not $ruta -or -not (Test-Path -LiteralPath $ruta)) { return }
    Start-SecurityJob -Kind 'custom' -Path $ruta
}

function Start-SecurityOfflineScan {
    if (-not (Assert-Admin)) { return }
    if (-not (Get-Command Start-MpWDOScan -ErrorAction SilentlyContinue)) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'Este Windows no permite lanzar el análisis sin conexión desde aquí. Hazlo desde Seguridad de Windows > Protección antivirus y contra amenazas > Opciones de examen.',
            "$script:AppName - seguridad", 'OK', 'Information')
        return
    }
    if (Test-OtherJobRunning) {
        [void][System.Windows.Forms.MessageBox]::Show(
            'Hay otra operación en curso (instalación, drivers, copia o desinstalación). Espera a que termine: el análisis sin conexión reinicia el equipo.',
            "$script:AppName - seguridad", 'OK', 'Warning')
        return
    }
    $aviso = "El análisis sin conexión de Microsoft Defender REINICIA EL EQUIPO en unos segundos.`n`n- Guarda y cierra todo lo que tengas abierto antes de continuar.`n- El análisis dura unos 15 minutos y se hace antes de arrancar Windows.`n- Después Windows arranca normalmente. Los resultados aparecen en 'Amenazas detectadas'.`n`nSi el disco está cifrado con BitLocker, ten a mano la clave de recuperación por si la pide.`n`n¿Reiniciar ahora y analizar?"
    $r = [System.Windows.Forms.MessageBox]::Show($aviso, "$script:AppName - análisis sin conexión", 'YesNo', 'Warning', 'Button2')
    if ($r -ne 'Yes') { return }
    try {
        Add-TabLog $script:secLog 'Iniciando el análisis sin conexión. El equipo se reiniciará.' 'STEP'
        Start-MpWDOScan -ErrorAction Stop
    } catch {
        Add-TabLog $script:secLog ('No se pudo iniciar el análisis sin conexión: {0}' -f $_.Exception.Message) 'ERROR'
        [void][System.Windows.Forms.MessageBox]::Show(
            ('No se pudo iniciar el análisis sin conexión.' + "`n`n" + $_.Exception.Message),
            "$script:AppName - seguridad", 'OK', 'Warning')
    }
}

function Remove-SecurityActiveThreats {
    if (-not (Assert-Admin)) { return }
    $activas = @($script:secThreatList.Items | Where-Object { $_.Tag -and $_.Tag.Active })
    if ($activas.Count -eq 0) { return }
    $lista = ($activas | ForEach-Object { ' - ' + $_.Tag.Name }) -join "`n"
    $r = [System.Windows.Forms.MessageBox]::Show(
        ("Defender aplicará la acción recomendada (cuarentena o eliminación) a estas amenazas:`n`n{0}`n`nLos archivos en cuarentena se pueden restaurar desde Seguridad de Windows si fueran un falso positivo.`n`n¿Continuar?" -f $lista),
        "$script:AppName - eliminar amenazas", 'YesNo', 'Warning')
    if ($r -ne 'Yes') { return }
    $script:form.UseWaitCursor = $true
    [System.Windows.Forms.Application]::DoEvents()
    try {
        Remove-MpThreat -ErrorAction Stop
        Add-TabLog $script:secLog ('Se ha aplicado la acción de Defender a {0} amenaza(s) activa(s).' -f $activas.Count) 'OK'
    } catch {
        Add-TabLog $script:secLog ('No se pudieron eliminar las amenazas: {0}' -f $_.Exception.Message) 'ERROR'
    } finally {
        $script:form.UseWaitCursor = $false
    }
    Update-SecurityThreats
}

