function Get-StartupSignatureText {
    param($Entrada)
    switch ([string]$Entrada.Signature) {
        'Valid'                 { if ($Entrada.Signer) { return $Entrada.Signer } else { return 'Firmado' } }
        'NotSigned'             { return 'SIN FIRMA' }
        'Archivo no encontrado' { return 'Archivo no encontrado' }
        'HashMismatch'          { return 'FIRMA ALTERADA' }
        'NotTrusted'            { return 'Firma no fiable' }
        'UnknownError'          { return 'Firma no válida' }
    }
    return [string]$Entrada.Signature
}

function Update-StartupTab {
    $script:iniLoaded = $true
    $script:form.UseWaitCursor = $true
    $script:statusLabel.Text = 'Leyendo los programas de inicio...'
    [System.Windows.Forms.Application]::DoEvents()
    $entradas = @()
    try {
        $entradas = @(Get-StartupEntries | Sort-Object @{ Expression = { -not $_.Enabled } }, Name)
    } catch {
        Add-TabLog $script:iniLog ('No se pudo leer la lista de inicio: {0}' -f $_.Exception.Message) 'ERROR'
    } finally {
        $script:form.UseWaitCursor = $false
        $script:statusLabel.Text = 'Listo'
    }

    $script:iniList.BeginUpdate()
    try {
        $script:iniList.Items.Clear()
        foreach ($e in $entradas) {
            $item = New-Object System.Windows.Forms.ListViewItem([string]$e.Name)
            [void]$item.SubItems.Add($(if ($e.Enabled) { 'Habilitado' } else { 'Deshabilitado' }))
            [void]$item.SubItems.Add((Get-StartupSignatureText $e))
            [void]$item.SubItems.Add([string]$e.Origin)
            $item.Tag = $e
            $item.ToolTipText = [string]$e.Command
            if (-not $e.Enabled) {
                $item.ForeColor = [System.Drawing.Color]::FromArgb(140, 140, 140)
            } elseif ($e.Signature -eq 'Archivo no encontrado') {
                $item.ForeColor = [System.Drawing.Color]::FromArgb(140, 140, 140)
            } elseif ($e.Signature -ne 'Valid') {
                $item.ForeColor = [System.Drawing.Color]::FromArgb(180, 100, 0)
                $item.Font = $script:boldFont
            }
            [void]$script:iniList.Items.Add($item)
        }
    } finally {
        $script:iniList.EndUpdate()
    }

    $habilitados = @($entradas | Where-Object { $_.Enabled }).Count
    $sinFirma = @($entradas | Where-Object { $_.Enabled -and $_.Signature -ne 'Valid' -and $_.Signature -ne 'Archivo no encontrado' }).Count
    $texto = ('{0} programas · {1} habilitados · {2} deshabilitados' -f $entradas.Count, $habilitados, ($entradas.Count - $habilitados))
    if ($sinFirma -gt 0) {
        $texto += (' · {0} sin firma' -f $sinFirma)
        $script:lblIniResumen.ForeColor = [System.Drawing.Color]::FromArgb(180, 100, 0)
    } else {
        $script:lblIniResumen.ForeColor = [System.Drawing.Color]::FromArgb(90, 90, 90)
    }
    $script:lblIniResumen.Text = $texto
    Add-TabLog $script:iniLog ('Programas de inicio: {0}' -f $texto)
    Update-StartupButtons
}

function Get-SelectedStartupEntries {
    return @($script:iniList.SelectedItems | ForEach-Object { $_.Tag } | Where-Object { $_ })
}

function Update-StartupButtons {
    $sel = @(Get-SelectedStartupEntries)
    $script:btnIniDisable.Enabled = (@($sel | Where-Object { $_.Enabled }).Count -gt 0)
    $script:btnIniEnable.Enabled  = (@($sel | Where-Object { -not $_.Enabled }).Count -gt 0)
    $uno = ($sel.Count -eq 1 -and $sel[0].Executable -and (Test-Path -LiteralPath $sel[0].Executable))
    $script:btnIniOpen.Enabled = $uno
    $script:btnIniScan.Enabled = $uno
}

function Show-StartupDetail {
    $sel = @(Get-SelectedStartupEntries)
    if ($sel.Count -eq 0) { return }
    if ($sel.Count -gt 1) {
        $script:iniDetail.Text = ('{0} programas seleccionados:{1}{1}{2}' -f $sel.Count, "`r`n", (($sel | ForEach-Object { '- ' + $_.Name }) -join "`r`n"))
        return
    }
    $e = $sel[0]
    $lineas = @(
        $e.Name,
        ('Estado: {0}' -f $(if ($e.Enabled) { 'arranca con Windows' } else { 'deshabilitado (no arranca)' })),
        ('Origen: {0}' -f $e.Origin),
        ('Ubicación: {0}' -f $e.Location),
        ('Comando: {0}' -f $e.Command),
        ('Archivo: {0}' -f $(if ($e.Executable) { $e.Executable } else { '(no se pudo determinar)' })),
        ('Firma: {0}' -f (Get-StartupSignatureText $e))
    )
    $lineas += ''
    if ($e.Signature -eq 'Archivo no encontrado') {
        $lineas += 'El archivo ya no existe: es un resto de un programa desinstalado. Puedes deshabilitarlo sin problema.'
    } elseif ($e.Signature -ne 'Valid') {
        $lineas += 'No tiene una firma digital válida. No tiene por qué ser malware, pero si no lo reconoces, deshabilítalo y analízalo con Defender.'
    } else {
        $lineas += 'Programa firmado. Si no necesitas que arranque con Windows (actualizadores, asistentes, lanzadores de juegos...), puedes deshabilitarlo para que el equipo arranque antes.'
    }
    if ($e.NeedsAdmin) { $lineas += 'Para cambiarlo hacen falta permisos de administrador (afecta a todos los usuarios).' }
    $script:iniDetail.Text = ($lineas -join "`r`n")
}

function Set-SelectedStartupEnabled {
    param([bool]$Enabled)
    $sel = @(Get-SelectedStartupEntries | Where-Object { [bool]$_.Enabled -ne $Enabled })
    if ($sel.Count -eq 0) { return }
    if (@($sel | Where-Object { $_.NeedsAdmin }).Count -gt 0 -and -not (Assert-Admin)) { return }

    $nombres = ($sel | ForEach-Object { ' - ' + $_.Name }) -join "`n"
    if (-not $Enabled -and -not $UiSmokeTest) {
        $r = [System.Windows.Forms.MessageBox]::Show(
            ("Estos programas dejarán de arrancar con Windows:`n`n{0}`n`nNo se desinstalan ni se borra nada. Puedes volver a habilitarlos aquí o en el Administrador de tareas.`n`n¿Continuar?" -f $nombres),
            "$script:AppName - inicio", 'YesNo', 'Question')
        if ($r -ne 'Yes') { return }
    }
    $ok = 0
    foreach ($e in $sel) {
        try {
            Set-StartupApproved -Key $e.ApprovedKey -Name $e.ApprovedName -Enabled $Enabled
            Add-TabLog $script:iniLog ('{0}: {1}.' -f $e.Name, $(if ($Enabled) { 'habilitado' } else { 'deshabilitado' })) 'OK'
            $ok++
        } catch {
            Add-TabLog $script:iniLog ('{0}: no se pudo cambiar ({1}).' -f $e.Name, $_.Exception.Message) 'ERROR'
        }
    }
    if ($ok -gt 0 -and -not $Enabled) { Add-TabLog $script:iniLog 'El cambio se nota en el próximo inicio de sesión.' }
    Update-StartupTab
}

function Open-StartupLocation {
    $sel = @(Get-SelectedStartupEntries)
    if ($sel.Count -ne 1 -or -not $sel[0].Executable) { return }
    try { Start-Process -FilePath (Join-Path $env:SystemRoot 'explorer.exe') -ArgumentList ('/select,"{0}"' -f $sel[0].Executable) | Out-Null } catch { }
}

function Start-StartupScan {
    $sel = @(Get-SelectedStartupEntries)
    if ($sel.Count -ne 1 -or -not $sel[0].Executable) { return }
    $archivo = $sel[0].Executable
    Add-TabLog $script:iniLog ('Analizando {0} con Defender (el progreso se ve en Protección > Seguridad)...' -f $archivo) 'STEP'
    Select-AppTab $tabSeguridad
    Start-SecurityJob -Kind 'custom' -Path $archivo
}

$script:iniList.add_SelectedIndexChanged({
    Show-StartupDetail
    Update-StartupButtons
})
$script:btnIniDisable.add_Click({ Set-SelectedStartupEnabled -Enabled $false })
$script:btnIniEnable.add_Click({ Set-SelectedStartupEnabled -Enabled $true })
$script:btnIniOpen.add_Click({ Open-StartupLocation })
$script:btnIniScan.add_Click({ Start-StartupScan })
$btnIniRefresh.add_Click({ Update-StartupTab })
$btnIniTaskMgr.add_Click({ try { Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\taskmgr.exe') -ArgumentList '/0 /startup' | Out-Null } catch { } })
$btnIniSave.add_Click({ Save-LogBox $script:iniLog 'registro_inicio' })
$btnIniClear.add_Click({ $script:iniLog.Clear() })

