# TabPages.Insert no funciona antes de que el control exista en pantalla, así
# que el orden definitivo de las subpestañas se fija aquí con Clear + AddRange.
function Set-SubTabOrder {
    param($Control, [object[]]$Pages)
    $Control.SuspendLayout()
    try {
        $Control.TabPages.Clear()
        $Control.TabPages.AddRange([System.Windows.Forms.TabPage[]]$Pages)
        $Control.SelectedIndex = 0
    } finally {
        $Control.ResumeLayout()
    }
}
Set-SubTabOrder $script:subSistema    @($tabServices, $tabInicio, $tabDrivers)
Set-SubTabOrder $script:subOptim      @($tabOptimize, $tabEquipo)
Set-SubTabOrder $script:subProgramas  @($tabPrograms, $tabUninstall)
Set-SubTabOrder $script:subProteccion @($tabSeguridad, $tabPuertos, $tabPrivacidad, $tabCopias)

# Acciones al mostrar cada subpestaña (carga perezosa y tamaño de los paneles)
function Invoke-TabActivated {
    param($Page)
    if (-not $Page) { return }
    # Una subpestaña que aún no se ha mostrado puede tener el tamaño por defecto
    # (200x100): se ajusta al área de su control antes de colocar los paneles.
    try {
        $contenedor = $Page.Parent
        if ($contenedor -is [System.Windows.Forms.TabControl] -and $contenedor.IsHandleCreated) {
            $Page.Bounds = $contenedor.DisplayRectangle
            $Page.PerformLayout()
        }
    } catch { }
    if ($Page -eq $tabServices) {
        try {
            $script:split.Panel1MinSize = 330
            $script:split.Panel2MinSize = 380
            $script:split.SplitterDistance = 400
        } catch { }
        return
    }
    if ($Page -eq $tabUninstall) {
        try {
            $script:uninstSplit.Panel1MinSize = 520
            $script:uninstSplit.Panel2MinSize = 300
            $script:uninstSplit.SplitterDistance = 700
        } catch { }
        if (-not $script:uninstLoaded) {
            Update-UninstallList -Reload
        }
        return
    }

    if ($Page -eq $tabEquipo) {
        try {
            $script:eqSplit.Panel1MinSize = 560
            $script:eqSplit.Panel2MinSize = 380
            $script:eqSplit.SplitterDistance = 650
        } catch { }
        if ($script:equipoDetected) { return }
        $script:form.UseWaitCursor = $true
        $script:statusLabel.Text = 'Detectando el equipo...'
        [System.Windows.Forms.Application]::DoEvents()
        try {
            Update-EquipoTab
        } catch {
            Add-TabLog $script:eqLog ('No se pudo detectar el equipo: {0}' -f $_.Exception.Message) 'ERROR'
            Write-Diag ('ERROR detectando el equipo: ' + $_.Exception.ToString())
        } finally {
            $script:form.UseWaitCursor = $false
            $script:statusLabel.Text = 'Listo'
        }
        return
    }

    if ($Page -eq $tabPrograms) {
        try {
            $script:prgSplit.Panel1MinSize = 430
            $script:prgSplit.Panel2MinSize = 340
            $script:prgSplit.SplitterDistance = 650
        } catch { }
        return
    }

    if ($Page -eq $tabDrivers) {
        try {
            $script:drvSplit.Panel1MinSize = 330
            $script:drvSplit.Panel2MinSize = 380
            $script:drvSplit.SplitterDistance = 510
        } catch { }
        Update-DriverTab
        return
    }

    if ($Page -eq $tabCopias) {
        try {
            $script:bkSplit.Panel1MinSize = 360
            $script:bkSplit.Panel2MinSize = 340
            $script:bkSplit.SplitterDistance = 480
        } catch { }
        Update-BackupDestinationInfo
        Update-BackupButtons
        return
    }

    if ($Page -eq $tabPuertos) {
        try {
            $script:ptSplit.Panel1MinSize = 560
            $script:ptSplit.Panel2MinSize = 340
            $script:ptSplit.SplitterDistance = 700
        } catch { }
        if (-not $script:ptLoaded) {
            try { Update-PortsTab } catch {
                Add-TabLog $script:ptLog ('No se pudieron leer los puertos: {0}' -f $_.Exception.Message) 'ERROR'
                Write-Diag ('ERROR en la pestaña Puertos: ' + $_.Exception.ToString())
            }
        }
        return
    }

    if ($Page -eq $tabPrivacidad) {
        try {
            $script:pvSplit.Panel1MinSize = 560
            $script:pvSplit.Panel2MinSize = 340
            $script:pvSplit.SplitterDistance = 680
        } catch { }
        if (-not $script:pvLoaded) {
            try { Update-PrivacyTab } catch {
                Add-TabLog $script:pvLog ('No se pudo buscar la telemetría: {0}' -f $_.Exception.Message) 'ERROR'
                Write-Diag ('ERROR en la pestaña Privacidad: ' + $_.Exception.ToString())
            }
        }
        return
    }

    if ($Page -eq $tabSeguridad) {
        try {
            $script:secSplit.Panel1MinSize = 520
            $script:secSplit.Panel2MinSize = 340
            $script:secSplit.SplitterDistance = 640
        } catch { }
        if (-not $script:secLoaded) {
            try {
                Update-SecurityTab
            } catch {
                Add-TabLog $script:secLog ('No se pudo revisar la seguridad: {0}' -f $_.Exception.Message) 'ERROR'
                Write-Diag ('ERROR en la pestaña Seguridad: ' + $_.Exception.ToString())
            }
        }
    }

    if ($Page -eq $tabInicio) {
        try {
            $script:iniSplit.Panel1MinSize = 560
            $script:iniSplit.Panel2MinSize = 340
            $script:iniSplit.SplitterDistance = 700
        } catch { }
        if (-not $script:iniLoaded) {
            try { Update-StartupTab } catch {
                Add-TabLog $script:iniLog ('No se pudo leer el inicio: {0}' -f $_.Exception.Message) 'ERROR'
                Write-Diag ('ERROR en la pestaña Inicio: ' + $_.Exception.ToString())
            }
        }
    }
}

$script:tabs.add_SelectedIndexChanged({
    if ($script:tabSwitching) { return }
    Invoke-TabActivated (Get-CurrentSubTab)
})
foreach ($subControl in @($script:subSistema, $script:subOptim, $script:subProgramas, $script:subProteccion)) {
    $subControl.add_SelectedIndexChanged({
        if ($script:tabSwitching) { return }
        Invoke-TabActivated $this.SelectedTab
    })
}


# ---------------------------------------------------------------------------
# Inicio de la aplicación
# ---------------------------------------------------------------------------

$script:form.add_Shown({
    [System.Windows.Forms.Application]::DoEvents()
    try { Invoke-TabActivated (Get-CurrentSubTab) } catch { }

    # Traer la ventana al frente (útil cuando se lanza elevada desde una consola)
    try {
        $script:form.Activate()
        $script:form.BringToFront()
        $script:form.TopMost = $true
        $script:form.TopMost = $false
    } catch { }

    Write-Diag 'Ventana mostrada. Cargando servicios...'
    $script:statusLabel.Text = 'Cargando servicios...'
    [System.Windows.Forms.Application]::DoEvents()
    $script:form.UseWaitCursor = $true
    $cronometro = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        Update-ServiceGrid
        Update-SystemInfoLabel
    } catch {
        Write-Diag ('ERROR cargando servicios: ' + $_.Exception.ToString())
        [void][System.Windows.Forms.MessageBox]::Show(
            ("No se pudo cargar la lista de servicios:`n`n{0}`n`nDetalle en: {1}" -f $_.Exception.Message, $script:DiagFile),
            "$script:AppName - error", 'OK', 'Error')
    } finally {
        $script:form.UseWaitCursor = $false
        $cronometro.Stop()
        Write-Diag ('Carga de servicios completada en {0:N2} s.' -f $cronometro.Elapsed.TotalSeconds)
    }

    Write-Log ('{0} v{1} listo.' -f $script:AppName, $script:AppVersion) 'STEP'
    if ($script:IsAdmin) {
        Write-Log 'Modo de ejecución: Administrador.'
    } else {
        Write-Log 'Modo de ejecución: usuario limitado. No se podrán detener ni deshabilitar servicios.' 'WARN'
    }
    Write-Log $script:lblSystemInfo.Text
    Write-Log 'Pestaña Optimización: marca las tareas y pulsa "Ejecutar seleccionadas".'
    Write-Log 'Antes de cambiar nada, ejecuta la tarea "Crear punto de restauración".'
    $script:statusLabel.Text = 'Listo'

    Add-TabLog $script:uninstLog 'Pulsa "Actualizar lista" para leer los programas instalados.'
    Add-TabLog $script:uninstLog 'Los componentes de Windows aparecen en rojo y no se pueden quitar desde aquí.'
    Add-TabLog $script:uninstLog 'Marca los programas que quieras quitar y pulsa "Desinstalar seleccionados".'

    Add-TabLog $script:prgLog 'Marca los programas que quieras instalar y pulsa "Instalar seleccionados".'
    Add-TabLog $script:prgLog ('Programas disponibles en el catalogo: {0}' -f $script:appCatalog.Count)
    try {
        $script:statusLabel.Text = 'Comprobando winget...'
        [System.Windows.Forms.Application]::DoEvents()
        [void](Test-Winget)
        Update-WingetLabel
        if ($script:wingetReady) {
            Add-TabLog $script:prgLog ('winget {0} disponible' -f $script:wingetVersion) 'OK'
            if ($script:wingetPath) { Add-TabLog $script:prgLog ('Ruta: {0}' -f $script:wingetPath) }
        } else {
            Add-TabLog $script:prgLog 'winget no está disponible. Pulsa "Abrir Store" e instala "Instalador de aplicaciones" (App Installer).' 'WARN'
        }
    } catch {
        Add-TabLog $script:prgLog ('No se pudo comprobar winget: {0}' -f $_.Exception.Message) 'ERROR'
    }

    # La pestaña Equipo detecta el hardware cuando se abre por primera vez
    # (evita retrasar el arranque con consultas WMI que tardan varios segundos).
    Add-TabLog $script:drvLog 'Abre la pestaña "Drivers" para ver los componentes del equipo.'
    Add-TabLog $script:drvLog 'Desde ahi puedes buscar drivers en Windows Update, guardar una copia de los actuales o instalar un archivo .inf.'
    Add-TabLog $script:bkLog 'Elige las carpetas y el destino, y pulsa "Iniciar copia".'
    Add-TabLog $script:bkLog 'Para una imagen completa del sistema usa un disco externo o una segunda unidad.'
    Update-BackupDestinationInfo
    Update-BackupButtons
    $script:statusLabel.Text = 'Listo'
    Write-Diag 'Carga inicial completada.'
})

if ($UiSmokeTest) {
    $script:form.Show()
    for ($i = 0; $i -lt 20; $i++) {
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 50
    }
    Write-Host ('Ventana: {0}x{1} (cliente {2}x{3})' -f $script:form.Width, $script:form.Height, $script:form.ClientSize.Width, $script:form.ClientSize.Height)
    Write-Host ('Pestañas: {0}' -f (($tabs.TabPages | ForEach-Object { '{0} ({1})' -f $_.Text, (($_.Tag.TabPages | ForEach-Object { $_.Text }) -join ', ') }) -join ' | '))
    Write-Host ('Filas visibles en la tabla: {0} de {1} servicios' -f $script:grid.Rows.Count, $script:serviceTable.Rows.Count)
    Write-Host ('Columnas: {0}' -f $script:grid.Columns.Count)
    Write-Host ('Tareas en la lista: {0}' -f $script:taskList.Items.Count)
    Write-Host ('Split: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:split.SplitterDistance, $script:split.Panel1.Width, $script:split.Panel2.Width)
    Write-Host ('Tamaño del panel de tareas: {0}x{1}' -f $grpTasks.Width, $grpTasks.Height)
    Write-Host ('Tamaño del registro: {0}x{1}' -f $script:logBox.Width, $script:logBox.Height)
    Write-Host ('Etiqueta de info: {0}' -f $script:lblSystemInfo.Text)
    if ($script:SessionUser) {
        Write-Host ('Usuario del programa: {0} | usuario de la sesión: {1} | distinto: {2}' -f $script:SessionUser.Process, $script:SessionUser.Session, $script:SessionUser.Mismatch)
    } else {
        Write-Host 'Usuario de la sesión: sin comprobar (sin administrador)'
    }

    # Prueba del filtro de búsqueda
    $script:txtSearch.Text = 'Windows'
    [System.Windows.Forms.Application]::DoEvents()
    Write-Host ('Filtro "Windows": {0} resultados' -f $script:grid.Rows.Count)
    $script:txtSearch.Text = ''
    [System.Windows.Forms.Application]::DoEvents()
    Start-Sleep -Milliseconds 300
    [System.Windows.Forms.Application]::DoEvents()
    Write-Host ('Sin filtro: {0} resultados' -f $script:grid.Rows.Count)

    # Prueba de marcado de casillas
    try {
        if ($script:grid.Rows.Count -gt 0) {
            $cell = $script:grid.Rows[0].Cells['Sel']
            $cell.Value = $true
            Write-Host ('Valor de la casilla: {0}' -f $cell.Value)
            Write-Host ('Casillas marcadas detectadas: {0}' -f @(Get-CheckedRows).Count)
            $cell.Value = $false
        } else {
            Write-Host 'AVISO: no hay filas para probar la casilla'
        }
    } catch {
        Write-Host ('ERROR al probar la casilla: {0}' -f $_.Exception.Message)
    }

    # Comprobar que la barra de herramientas no se recorta
    try {
        $maxL = 0
        foreach ($c in $leftTools.Controls) { $r = $c.Right + $c.Margin.Right; if ($r -gt $maxL) { $maxL = $r } }
        $maxR = 0
        foreach ($c in $rightTools.Controls) { $r = $c.Right + $c.Margin.Right; if ($r -gt $maxR) { $maxR = $r } }
        Write-Host ('Barra: filtros {0} px (contenido {1}) | botones {2} px (contenido {3})' -f $leftTools.Width, $maxL, $rightTools.Width, $maxR)
        Write-Host ('Botón info: {0}x{1} en x={2}, y={3}' -f $btnInfo.Width, $btnInfo.Height, $btnInfo.Left, $btnInfo.Top)
    } catch {
        Write-Host ('ERROR al medir la barra: {0}' -f $_.Exception.Message)
    }

    # Prueba de la ficha de información y del filtro de consejo
    try {
        if ($script:grid.Rows.Count -gt 0) {
            $r = $script:grid.Rows[0]
            $adv = Get-ServiceAdvice ([pscustomobject]@{
                Name        = [string]$r.Cells['Nombre'].Value
                Description = [string]$r.Cells['Descripcion'].Value
                PathName    = [string]$r.Cells['Ruta'].Value
            })
            $info = New-ServiceInfoText -Name ([string]$r.Cells['Nombre'].Value) `
                -DisplayName ([string]$r.Cells['Mostrar'].Value) `
                -State ([string]$r.Cells['Estado'].Value) `
                -StartMode ([string]$r.Cells['Inicio'].Value) `
                -ProcessId ([int]$r.Cells['PID'].Value) `
                -Risk ([string]$r.Cells['Riesgo'].Value) `
                -Description ([string]$r.Cells['Descripcion'].Value) `
                -Advice $adv
            Write-Host ('Ficha de {0}: {1} caracteres | consejo: {2}' -f $r.Cells['Nombre'].Value, $info.Length, $adv.Consejo)
        }
        Write-Host ('Visibles con consejo "Quitar": {0}' -f @($script:grid.Rows | Where-Object { $_.Cells['Consejo'].Value -eq 'Quitar' }).Count)
        $script:chkRemovable.Checked = $true
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Filtro "solo se pueden quitar": {0} resultados' -f $script:grid.Rows.Count)
        $script:chkRemovable.Checked = $false
        [System.Windows.Forms.Application]::DoEvents()
    } catch {
        Write-Host ('ERROR al probar la ficha: {0}' -f $_.Exception.Message)
    }

    # Prueba visual de la ficha de información
    try {
        $dlg = New-ServiceInfoDialog -Row $script:grid.Rows[0]
        if ($dlg) {
            $dlg.Show()
            for ($i = 0; $i -lt 10; $i++) {
                [System.Windows.Forms.Application]::DoEvents()
                Start-Sleep -Milliseconds 30
            }
            $lblFicha = $null
            $txtFicha = $null
            $btnFicha = $null
            foreach ($c in $dlg.Controls[0].Controls) {
                if ($c -is [System.Windows.Forms.TextBox]) { $txtFicha = $c }
                if ($c -is [System.Windows.Forms.TableLayoutPanel]) {
                    foreach ($x in $c.Controls) {
                        if ($x -is [System.Windows.Forms.Label] -and $x.Font.Bold) { $lblFicha = $x }
                    }
                }
                if ($c -is [System.Windows.Forms.FlowLayoutPanel]) { $btnFicha = $c }
            }
            Write-Host ('Ficha: ventana {0}x{1}; texto {2}x{3}; botones {4}x{5}; veredicto: {6}' -f `
                $dlg.ClientSize.Width, $dlg.ClientSize.Height, `
                $txtFicha.Width, $txtFicha.Height, `
                $btnFicha.Width, $btnFicha.Height, `
                $lblFicha.Text)
            $bmpInfo = New-Object System.Drawing.Bitmap($dlg.Width, $dlg.Height)
            $dlg.DrawToBitmap($bmpInfo, (New-Object System.Drawing.Rectangle(0, 0, $dlg.Width, $dlg.Height)))
            $outInfo = Join-Path $env:TEMP 'wintaller_info.png'
            $bmpInfo.Save($outInfo, [System.Drawing.Imaging.ImageFormat]::Png)
            $bmpInfo.Dispose()
            Write-Host "Captura de la ficha: $outInfo"

            $btnMarcar = $null
            foreach ($b in $btnFicha.Controls) {
                if ($b -is [System.Windows.Forms.Button] -and $b.Text -like 'Marcar*') { $btnMarcar = $b }
            }
            if ($btnMarcar) {
                $antes = [bool]$script:grid.Rows[0].Cells['Sel'].Value
                $btnMarcar.PerformClick()
                [System.Windows.Forms.Application]::DoEvents()
                $despues = [bool]$script:grid.Rows[0].Cells['Sel'].Value
                Write-Host ('Botón "Marcar este servicio": casilla {0} -> {1}' -f $antes, $despues)
                $script:grid.Rows[0].Cells['Sel'].Value = $false
            }
            if (-not $dlg.IsDisposed) { $dlg.Close() }
            $dlg.Dispose()
        }
    } catch {
        Write-Host ('ERROR al probar la ficha visual: {0}' -f $_.Exception.Message)
    }

    # Pestaña Programas
    try {
        $recomendados = @($script:appCatalog | Where-Object { $_.Recommended }).Count
        Write-Host ('Programas en el catalogo: {0} (recomendados: {1})' -f $script:appList.Items.Count, $recomendados)
        Write-Host ('winget listo: {0} | etiqueta: {1}' -f $script:wingetReady, $script:lblWinget.Text)
        if ($script:wingetReady) {
            $ids = Get-WingetInstalledIds
            Write-Host ('Ids de programas instalados detectados: {0}' -f $ids.Count)
            $ya = @($script:appCatalog | Where-Object { $ids.ContainsKey($_.Id) })
            Write-Host ('Programas del catalogo ya instalados: {0} ({1})' -f $ya.Count, (($ya | ForEach-Object { $_.Name }) -join ', '))
        }
        Set-AllAppsChecked -Value $true -OnlyRecommended
        Write-Host ('Recomendados marcados: {0}' -f @($script:appList.CheckedItems).Count)
        Set-AllAppsChecked -Value $false
        Write-Host ('Marcas tras desmarcar: {0}' -f @($script:appList.CheckedItems).Count)

        # Prueba del buscador de programas
        $script:txtPrgSearch.Text = 'malware'
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Búsqueda "malware": {0} resultados ({1})' -f $script:appList.Items.Count, (($script:appList.Items | ForEach-Object { $_.Tag.Name }) -join ', '))
        $script:txtPrgSearch.Text = 'tinywall'
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Búsqueda "tinywall": {0} resultados ({1})' -f $script:appList.Items.Count, (($script:appList.Items | ForEach-Object { $_.Tag.Name }) -join ', '))
        $script:txtPrgSearch.Text = 'zzzznoexiste'
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Búsqueda sin resultados: {0} | etiqueta: {1}' -f $script:appList.Items.Count, $script:grpPrograms.Text)
        $script:txtPrgSearch.Text = ''
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Sin filtro: {0} programas | etiqueta: {1}' -f $script:appList.Items.Count, $script:grpPrograms.Text)

        # La selección se conserva al buscar y volver a limpiar
        $script:appCheckedById['Mozilla.Firefox'] = $true
        Update-AppList
        $script:txtPrgSearch.Text = 'malware'
        [System.Windows.Forms.Application]::DoEvents()
        $oculto = -not [bool](@($script:appList.Items | Where-Object { $_.Tag.Id -eq 'Mozilla.Firefox' }).Count)
        $script:txtPrgSearch.Text = ''
        [System.Windows.Forms.Application]::DoEvents()
        $visibleOtraVez = [bool](@($script:appList.Items | Where-Object { $_.Tag.Id -eq 'Mozilla.Firefox' -and $_.Checked }).Count)
        Write-Host ('Selección conservada al filtrar: oculto al buscar {0} | marcado al volver {1}' -f $oculto, $visibleOtraVez)
        $script:appCheckedById['Mozilla.Firefox'] = $false
        Update-AppList

        # Prueba de "Comprobar instalados": lee winget export y marca los que ya están
        Update-InstalledApps
        $estados = @($script:appList.Items | Where-Object { $_.SubItems[3].Text -eq 'Instalado' }).Count
        Write-Host ('Estado "Instalado" tras comprobar: {0}' -f $estados)

        # Prueba de la cola de instalación con un paquete que no existe (no instala nada)
        $falso = New-Object System.Windows.Forms.ListViewItem('Paquete de prueba')
        [void]$falso.SubItems.Add('Prueba')
        [void]$falso.SubItems.Add('Identificador inexistente para probar la cola')
        [void]$falso.SubItems.Add('')
        $falso.Tag = [pscustomobject]@{
            Name        = 'Paquete de prueba'
            Category    = 'Prueba'
            Id          = 'NoExiste.Prueba.123'
            Note        = 'Identificador inexistente'
            Recommended = $false
        }
        [void]$script:appList.Items.Add($falso)
        Start-WingetQueue @($falso)
        $relojCola = [System.Diagnostics.Stopwatch]::StartNew()
        while ($script:wingetProcess -and $relojCola.Elapsed.TotalSeconds -lt 60) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 100
        }
        Write-Host ('Cola de prueba: estado "{0}" | errores {1} | terminados {2}' -f $falso.SubItems[3].Text, $script:wingetErrors, $script:wingetDone)
        [void]$script:appList.Items.Remove($falso)

        Select-AppTab $tabPrograms
        for ($i = 0; $i -lt 10; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 40
        }
        Write-Host ('Split programas: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:prgSplit.SplitterDistance, $script:prgSplit.Panel1.Width, $script:prgSplit.Panel2.Width)
        $bmpPrg = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpPrg, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outPrg = Join-Path $env:TEMP 'wintaller_programas.png'
        $bmpPrg.Save($outPrg, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpPrg.Dispose()
        Write-Host "Captura de programas: $outPrg"
    } catch {
        Write-Host ('ERROR al probar la pestaña Programas: {0}' -f $_.Exception.Message)
    }

    # Pestaña Desinstalar
    try {
        Select-AppTab $tabUninstall
        for ($i = 0; $i -lt 15; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 60
        }
        $protegidos = @($script:uninstApps | Where-Object { $_.Protected }).Count
        $altos = @($script:uninstApps | Where-Object { $_.Risk -eq 'Alto' }).Count
        $usuarios = @($script:uninstApps | Where-Object { -not $_.Protected -and $_.Risk -eq 'Bajo' }).Count
        Write-Host ('Desinstalar: {0} programas | protegidos {1} | alto riesgo {2} | usuario {3}' -f $script:uninstApps.Count, $protegidos, $altos, $usuarios)
        Write-Host ('Split desinstalar: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:uninstSplit.SplitterDistance, $script:uninstSplit.Panel1.Width, $script:uninstSplit.Panel2.Width)

        $script:txtUninstSearch.Text = 'microsoft'
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Búsqueda "microsoft": {0} resultados' -f $script:uninstList.Items.Count)
        $script:txtUninstSearch.Text = ''
        [System.Windows.Forms.Application]::DoEvents()

        $script:cmbUninstFilter.SelectedIndex = 1
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Filtro solo del usuario: {0} resultados' -f $script:uninstList.Items.Count)
        $script:cmbUninstFilter.SelectedIndex = 2
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Filtro solo de Windows: {0} resultados' -f $script:uninstList.Items.Count)
        $script:cmbUninstFilter.SelectedIndex = 0
        [System.Windows.Forms.Application]::DoEvents()

        $script:btnUninstAll.PerformClick()
        [System.Windows.Forms.Application]::DoEvents()
        $marcadosTodos = @($script:uninstList.CheckedItems).Count
        $protegidosMarcados = @($script:uninstList.CheckedItems | Where-Object { $_.Tag -and $_.Tag.Protected }).Count
        Write-Host ('Seleccionar todos: {0} marcados | protegidos marcados: {1}' -f $marcadosTodos, $protegidosMarcados)
        $script:btnUninstAll.PerformClick()
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Tras desmarcar todos: {0} marcados' -f @($script:uninstList.CheckedItems).Count)

        $primero = @($script:uninstList.Items | Where-Object { $_.Tag -and -not $_.Tag.Protected } | Select-Object -First 1)
        if ($primero.Count -gt 0) {
            $primero[0].Selected = $true
            [System.Windows.Forms.Application]::DoEvents()
            Write-Host ('Detalle del programa 0: {0} caracteres' -f $script:uninstDetail.TextLength)
        }

        $bmpUn = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpUn, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outUn = Join-Path $env:TEMP 'wintaller_desinstalar.png'
        $bmpUn.Save($outUn, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpUn.Dispose()
        Write-Host "Captura de desinstalar: $outUn"
    } catch {
        Write-Host ('ERROR al probar la pestaña Desinstalar: {0}' -f $_.Exception.Message)
    }

    # Pestaña Optimización: cabecera, cultura, tareas y controles de progreso
    try {
        Select-AppTab $tabOptimize
        for ($i = 0; $i -lt 10; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 40
        }
        Write-Host ('Cultura actual: {0}' -f [System.Threading.Thread]::CurrentThread.CurrentCulture.Name)
        Write-Host ('Cabecera: {0}' -f $script:lblSystemInfo.Text)
        Write-Host ('Alturas cabecera: panel {0}, etiqueta {1}, fila0 {2}, fuente {3}' -f $infoPanel.Height, $script:lblSystemInfo.Height, $optLayout.GetRowHeights()[0], $script:lblSystemInfo.Font.Height)
        Write-Host ('Tareas de optimización: {0} | botón Cancelar: {1} | botón Revertir: {2}' -f $script:taskList.Items.Count, $script:btnOptCancel.Enabled, $script:btnRevert.Enabled)
        Write-Host ('Progreso: máximo {0}, valor {1}' -f $script:optProgress.Maximum, $script:optProgress.Value)
        $bmpOpt = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpOpt, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outOpt = Join-Path $env:TEMP 'wintaller_optimizacion.png'
        $bmpOpt.Save($outOpt, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpOpt.Dispose()
        Write-Host "Captura de optimización: $outOpt"
    } catch {
        Write-Host ('ERROR al probar la pestaña Optimización: {0}' -f $_.Exception.Message)
    }

    # Pestaña Equipo
    try {
        Select-AppTab $tabEquipo
        for ($i = 0; $i -lt 10; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 40
        }
        Write-Host ('Equipo: {0}' -f $script:lblEquipoTipo.Text)
        Write-Host ('Detalle: {0}' -f $script:lblEquipoDetalle.Text)
        Write-Host ('Ajustes para este equipo: {0} de {1}' -f $script:eqList.Items.Count, $script:equipoActions.Count)
        foreach ($it in $script:eqList.Items) {
            Write-Host ('  [{0}] {1}: {2}{3}' -f $(if ($it.Checked) { 'x' } else { ' ' }), $it.Text, $it.SubItems[1].Text, $(if ($it.Tag.Recommended) { ' (recomendado)' } else { '' }))
        }
        Write-Host ('Recomendados pendientes premarcados: {0}' -f @($script:eqList.Items | Where-Object { $_.Checked }).Count)

        # Exclusión de planes de energía: marcar dos planes deja solo el último
        $planes = @($script:eqList.Items | Where-Object { $_.Tag.Action.Exclusive -eq 'Plan' })
        if ($planes.Count -ge 2) {
            $antes = @($planes | ForEach-Object { $_.Checked })
            $planes[0].Checked = $true
            $planes[1].Checked = $true
            [System.Windows.Forms.Application]::DoEvents()
            Write-Host ('Planes marcados tras marcar dos: {0} (debe ser 1)' -f @($planes | Where-Object { $_.Checked }).Count)
            for ($i = 0; $i -lt $planes.Count; $i++) { $planes[$i].Checked = $antes[$i] }
        }

        $script:eqList.Items[0].Selected = $true
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Ficha del ajuste 0: {0} caracteres' -f $script:eqDetail.TextLength)

        Show-DiskHealth
        Show-CrashHistory
        $informe = New-EquipoReport
        Write-Host ('Informe del equipo: {0} | existe: {1}' -f $informe, $(if ($informe) { Test-Path -LiteralPath $informe } else { $false }))
        Write-Host ('Split equipo: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:eqSplit.SplitterDistance, $script:eqSplit.Panel1.Width, $script:eqSplit.Panel2.Width)
        $bmpEq = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpEq, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outEq = Join-Path $env:TEMP 'wintaller_equipo.png'
        $bmpEq.Save($outEq, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpEq.Dispose()
        Write-Host "Captura de equipo: $outEq"
    } catch {
        Write-Host ('ERROR al probar la pestaña Equipo: {0}' -f $_.Exception.Message)
    }

    # Pestaña Drivers
    try {
        Select-AppTab $tabDrivers
        for ($i = 0; $i -lt 10; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 40
        }
        Write-Host ('Drivers: {0}' -f $script:lblDrvEstado.Text)
        Write-Host ('Vista inicial: {0} | componentes listados: {1}' -f $script:drvView.Text, $script:drvList.Items.Count)
        $script:drvView.SelectedIndex = 1
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Todos los dispositivos: {0}' -f $script:drvList.Items.Count)
        Write-Host ('Split drivers: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:drvSplit.SplitterDistance, $script:drvSplit.Panel1.Width, $script:drvSplit.Panel2.Width)

        # La búsqueda real corre en un proceso hijo: esperamos a que termine
        Start-DriverSearch
        $relojBusqueda = [System.Diagnostics.Stopwatch]::StartNew()
        while ($script:drvProcess -and $relojBusqueda.Elapsed.TotalSeconds -lt 240) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 150
        }
        Write-Host ('Búsqueda en Windows Update: {0} s | proceso activo: {1}' -f [math]::Round($relojBusqueda.Elapsed.TotalSeconds, 1), [bool]$script:drvProcess)
        Write-Host ('Drivers en Windows Update: {0} | marcados: {1}' -f $script:drvUpdates.Count, @($script:drvList.CheckedItems).Count)
        $seleccionables = @($script:drvList.Items | Where-Object { $_.Tag -and -not $_.Tag.Installed }).Count
        $script:chkDrvAll.Checked = $true
        [System.Windows.Forms.Application]::DoEvents()
        $trasMarcar = @($script:drvList.CheckedItems).Count
        $estadoTodos = $script:chkDrvAll.Checked
        $script:chkDrvAll.Checked = $false
        [System.Windows.Forms.Application]::DoEvents()
        $trasDesmarcar = @($script:drvList.CheckedItems).Count
        Write-Host ('Seleccionar todos los drivers: {0} seleccionables -> {1} marcados (casilla {2}) -> {3} tras desmarcar' -f $seleccionables, $trasMarcar, $estadoTodos, $trasDesmarcar)
        $emparejados = @($script:drvUpdates | Where-Object { $_.Matched }).Count
        Write-Host ('Drivers que corresponden a componentes con problemas: {0}' -f $emparejados)
        if ($script:drvList.Items.Count -gt 0) {
            $script:drvList.Items[0].Selected = $true
            [System.Windows.Forms.Application]::DoEvents()
        }
        Write-Host ('Detalle del driver 0: {0} caracteres' -f $script:drvDetail.TextLength)

        # Cola con un identificador inexistente: prueba el proceso hijo sin instalar nada
        Start-DriverQueue -Ids @('00000000-0000-0000-0000-000000000000') -Testing
        $relojDrv = [System.Diagnostics.Stopwatch]::StartNew()
        while ($script:drvProcess -and $relojDrv.Elapsed.TotalSeconds -lt 180) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 150
        }
        Write-Host ('Cola de drivers de prueba: terminados {0} | errores {1} | proceso activo: {2}' -f $script:drvDone, $script:drvErrors, [bool]$script:drvProcess)

        $bmpDrv = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpDrv, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outDrv = Join-Path $env:TEMP 'wintaller_drivers.png'
        $bmpDrv.Save($outDrv, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpDrv.Dispose()
        Write-Host "Captura de drivers: $outDrv"
    } catch {
        Write-Host ('ERROR al probar la pestaña Drivers: {0}' -f $_.Exception.Message)
    }

    # Pestaña Copias
    try {
        Select-AppTab $tabCopias
        for ($i = 0; $i -lt 10; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 40
        }
        Write-Host ('Copias: modo {0} | carpetas en la lista {1} | marcadas {2}' -f $script:bkMode, $script:bkList.Items.Count, @($script:bkList.CheckedItems).Count)
        Write-Host ('Destino inicial: {0}' -f $script:bkDest.Text)
        Write-Host ('Espacio: {0}' -f $script:lblBkFree.Text)
        Write-Host ('Split copias: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:bkSplit.SplitterDistance, $script:bkSplit.Panel1.Width, $script:bkSplit.Panel2.Width)

        # Copia real de una carpeta temporal pequeña (no toca datos del usuario)
        $srcBk = Join-Path $env:TEMP ('wintaller_bk_src_' + [guid]::NewGuid().ToString('N').Substring(0, 6))
        $dstBk = Join-Path $env:TEMP ('wintaller_bk_dst_' + [guid]::NewGuid().ToString('N').Substring(0, 6))
        [void](New-Item -ItemType Directory -Path $srcBk -Force)
        [void](New-Item -ItemType Directory -Path (Join-Path $srcBk 'sub') -Force)
        Set-Content -LiteralPath (Join-Path $srcBk 'uno.txt') -Value 'prueba uno'
        Set-Content -LiteralPath (Join-Path $srcBk 'sub\dos.txt') -Value 'prueba dos'

        Start-BackupJob -Sources @($srcBk) -Destination $dstBk -Mode 'files' -Testing
        $relojBk = [System.Diagnostics.Stopwatch]::StartNew()
        while ($script:bkProcess -and $relojBk.Elapsed.TotalSeconds -lt 120) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 150
        }
        $archivosBk = @(Get-ChildItem -LiteralPath $dstBk -Recurse -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne '_registro-copia.txt' })
        $logBk = Test-Path -LiteralPath (Join-Path $dstBk '_registro-copia.txt')
        Write-Host ('Copia de prueba: {0} archivos | proceso activo {1} | errores {2} | resultado {3}' -f $archivosBk.Count, [bool]$script:bkProcess, $script:bkErrors, $script:bkResultOk)
        Write-Host ('Registro detallado creado: {0}' -f $logBk)

        $bmpBk = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpBk, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outBk = Join-Path $env:TEMP 'wintaller_copias.png'
        $bmpBk.Save($outBk, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpBk.Dispose()
        Write-Host "Captura de copias: $outBk"

        Remove-Item $srcBk, $dstBk -Recurse -Force -ErrorAction SilentlyContinue
    } catch {
        Write-Host ('ERROR al probar la pestaña Copias: {0}' -f $_.Exception.Message)
    }

    # Pestaña Seguridad (solo revisión; no lanza análisis)
    try {
        Select-AppTab $tabSeguridad
        for ($i = 0; $i -lt 10; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 40
        }
        Write-Host ('Seguridad: {0} comprobaciones | {1} amenazas en la lista | MpCmdRun: {2}' -f $script:secList.Items.Count, $script:secThreatList.Items.Count, $script:secMpCmdRun)
        Write-Host ('Resumen: {0}' -f $script:lblSecResumen.Text)
        foreach ($chk in $script:secChecks) { Write-Host ('  [{0}] {1}: {2}' -f $chk.Level, $chk.Name, $chk.Value) }
        Write-Host ('Split seguridad: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:secSplit.SplitterDistance, $script:secSplit.Panel1.Width, $script:secSplit.Panel2.Width)
        $bmpSec = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpSec, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outSec = Join-Path $env:TEMP 'wintaller_seguridad.png'
        $bmpSec.Save($outSec, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpSec.Dispose()
        Write-Host "Captura de seguridad: $outSec"
    } catch {
        Write-Host ('ERROR al probar la pestaña Seguridad: {0}' -f $_.Exception.Message)
    }

    # Subpestaña Inicio (solo lectura; no cambia nada)
    try {
        Select-AppTab $tabInicio
        for ($i = 0; $i -lt 10; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 40
        }
        Write-Host ('Inicio: {0}' -f $script:lblIniResumen.Text)
        foreach ($it in $script:iniList.Items) {
            Write-Host ('  {0} | {1} | {2} | {3}' -f $it.Text, $it.SubItems[1].Text, $it.SubItems[2].Text, $it.SubItems[3].Text)
        }
        if ($script:iniList.Items.Count -gt 0) {
            $script:iniList.Items[0].Selected = $true
            [System.Windows.Forms.Application]::DoEvents()
            Write-Host ('Detalle del programa 0: {0} caracteres | botones: deshabilitar {1}, habilitar {2}, ubicación {3}' -f $script:iniDetail.TextLength, $script:btnIniDisable.Enabled, $script:btnIniEnable.Enabled, $script:btnIniOpen.Enabled)
        }
        Write-Host ('Split inicio: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:iniSplit.SplitterDistance, $script:iniSplit.Panel1.Width, $script:iniSplit.Panel2.Width)
        $bmpIni = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpIni, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outIni = Join-Path $env:TEMP 'wintaller_inicio.png'
        $bmpIni.Save($outIni, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpIni.Dispose()
        Write-Host "Captura de inicio: $outIni"
    } catch {
        Write-Host ('ERROR al probar la pestaña Inicio: {0}' -f $_.Exception.Message)
    }

    # Subpestaña Puertos (solo lectura; no crea reglas en el cortafuegos)
    try {
        Select-AppTab $tabPuertos
        for ($i = 0; $i -lt 10; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 40
        }
        Write-Host ('Puertos: {0}' -f $script:lblPtResumen.Text)
        if ($script:ptFirewall) { Write-Host ('Cortafuegos: {0} | perfiles activos: {1}' -f $script:ptFirewall.Text, ($script:ptFirewall.Active -join ', ')) }
        Write-Host ('Reglas de entrada activas leídas: {0}' -f @(Get-FirewallInboundRules).Count)
        foreach ($e in @($script:ptEntries | Where-Object { -not $_.Local -and $_.Proto -eq 'TCP' } | Sort-Object Port)) {
            Write-Host ('  {0}/{1} | {2} | {3} | {4} | {5} | reglas: {6}' -f $e.Port, $e.Proto, $e.Known.Service, $e.Process, $e.Scope, $e.Level, (@($e.RuleIds) -join ', '))
        }
        $soloTcp = $script:ptList.Items.Count
        $script:chkPtUdp.Checked = $true
        [System.Windows.Forms.Application]::DoEvents()
        $conUdp = $script:ptList.Items.Count
        $script:chkPtNet.Checked = $true
        [System.Windows.Forms.Application]::DoEvents()
        $soloRed = $script:ptList.Items.Count
        $script:chkPtNet.Checked = $false
        $script:chkPtUdp.Checked = $false
        [System.Windows.Forms.Application]::DoEvents()
        Write-Host ('Filtros de puertos: solo TCP {0} | con UDP {1} | solo abiertos a la red {2}' -f $soloTcp, $conUdp, $soloRed)
        if ($script:ptList.Items.Count -gt 0) {
            $script:ptList.Items[0].Selected = $true
            [System.Windows.Forms.Application]::DoEvents()
            Write-Host ('Detalle del puerto 0: {0} caracteres | botones: bloquear {1}, quitar bloqueo {2}, ubicación {3}' -f $script:ptDetail.TextLength, $script:btnPtBlock.Enabled, $script:btnPtUnblock.Enabled, $script:btnPtOpen.Enabled)
        }
        Write-Host ('Split puertos: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:ptSplit.SplitterDistance, $script:ptSplit.Panel1.Width, $script:ptSplit.Panel2.Width)
        $maxPt = 0
        foreach ($c in $ptButtonsLeft.Controls) { $r = $c.Right + $c.Margin.Right; if ($r -gt $maxPt) { $maxPt = $r } }
        Write-Host ('Barra de puertos: {0} px (contenido {1})' -f $ptButtonsLeft.Width, $maxPt)
        $bmpPt = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpPt, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outPt = Join-Path $env:TEMP 'wintaller_puertos.png'
        $bmpPt.Save($outPt, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpPt.Dispose()
        Write-Host "Captura de puertos: $outPt"
    } catch {
        Write-Host ('ERROR al probar la pestaña Puertos: {0}' -f $_.Exception.Message)
    }

    # Subpestaña Privacidad (solo escaneo; no desactiva nada)
    try {
        Select-AppTab $tabPrivacidad
        for ($i = 0; $i -lt 10; $i++) {
            [System.Windows.Forms.Application]::DoEvents()
            Start-Sleep -Milliseconds 40
        }
        Write-Host ('Privacidad: {0}' -f $script:lblPvResumen.Text)
        Write-Host ('Catálogo de telemetría: {0} elementos | presentes en este equipo: {1}' -f $script:privCatalog.Count, $script:pvList.Items.Count)
        foreach ($it in $script:pvList.Items) {
            Write-Host ('  [{0}] {1} | {2} | {3}{4}' -f $(if ($it.Checked) { 'x' } else { ' ' }), $it.Text, $it.SubItems[1].Text, $it.SubItems[2].Text, $(if ($it.Tag.State.NeedsAdmin) { ' | admin' } else { '' }))
        }
        if ($script:pvList.Items.Count -gt 0) {
            $script:pvList.Items[0].Selected = $true
            [System.Windows.Forms.Application]::DoEvents()
            Write-Host ('Detalle del elemento 0: {0} caracteres' -f $script:pvDetail.TextLength)
        }
        $antesPv = @($script:pvList.CheckedItems).Count
        Set-PrivacyChecked -Value $false
        $sinMarcas = @($script:pvList.CheckedItems).Count
        Set-PrivacyChecked -Value $true -OnlyRecommended
        Write-Host ('Marcas de privacidad: iniciales {0} | tras quitar {1} | recomendados {2}' -f $antesPv, $sinMarcas, @($script:pvList.CheckedItems).Count)
        Write-Host ('Split privacidad: distancia {0}, panel1 {1} px, panel2 {2} px' -f $script:pvSplit.SplitterDistance, $script:pvSplit.Panel1.Width, $script:pvSplit.Panel2.Width)
        $maxPv = 0
        foreach ($c in $pvButtons.Controls) { $r = $c.Right + $c.Margin.Right; if ($r -gt $maxPv) { $maxPv = $r } }
        Write-Host ('Barra de privacidad: {0} px (contenido {1})' -f $pvButtons.Width, $maxPv)
        $bmpPv = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmpPv, (New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)))
        $outPv = Join-Path $env:TEMP 'wintaller_privacidad.png'
        $bmpPv.Save($outPv, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmpPv.Dispose()
        Write-Host "Captura de privacidad: $outPv"
    } catch {
        Write-Host ('ERROR al probar la pestaña Privacidad: {0}' -f $_.Exception.Message)
    }

    Select-AppTab $tabServices
    [System.Windows.Forms.Application]::DoEvents()

    try {
        $bmp = New-Object System.Drawing.Bitmap($script:form.Width, $script:form.Height)
        $rect = New-Object System.Drawing.Rectangle(0, 0, $script:form.Width, $script:form.Height)
        $script:form.DrawToBitmap($bmp, $rect)
        $out = Join-Path $env:TEMP 'wintaller_smoke.png'
        $bmp.Save($out, [System.Drawing.Imaging.ImageFormat]::Png)
        $bmp.Dispose()
        Write-Host "Captura: $out"
    } catch {
        Write-Host ('No se pudo capturar la ventana: {0}' -f $_.Exception.Message)
    }
    if ($script:logBox.TextLength -eq 0) { Write-Host 'AVISO: el registro esta vacio' }
    $script:form.Close()
    exit 0
}

Write-Diag 'Controles creados. Mostrando la ventana...'
[void]$script:form.ShowDialog()

Write-Diag 'La ventana se ha cerrado. Saliendo.'
$script:form.Dispose()
if ($script:instanceMutex) {
    try { $script:instanceMutex.ReleaseMutex() } catch { }
    $script:instanceMutex.Dispose()
}
} catch {
    Show-FatalError -Message $_.Exception.Message -Detail $_.Exception.ToString()
    exit 1
}